        .wr_data        ({m_axi_bid, m_axi_bresp, m_axi_buser}),
        .rd_ready       (s_axi_bready),
        .rd_valid       (s_axi_bvalid),
        .rd_data        ({s_axi_bid, s_axi_bresp, s_axi_buser})
    );

