//
// Module: axi4_dwidth_to_axil4_wr_chain
// Purpose: FUB-level chain wrapping axi4_dwidth_converter_wr (downsize)
//          directly connected to axi4_to_axil4_wr.
//
// Description:
//   Slave side: wide AXI4 (S_AXI_DATA_WIDTH).
//   axi4_dwidth_converter_wr downsizes the W beats to M_AXIL_DATA_WIDTH
//   and rewrites awlen/awsize so the downstream module sees a narrow
//   AXI4 burst of M_AXIL_DATA_WIDTH-wide beats.
//   axi4_to_axil4_wr then decomposes that narrow AXI4 burst into
//   single-beat AXIL4 writes on the master AXIL interface.
//
//   This chain is what real bridges instantiate when a wide master writes
//   to a narrow AXIL4 slave. It is the configuration that surfaces the
//   page-probe class of back-to-back boundary bugs at the bridge level,
//   so we exercise it at the FUB level here.
//
// Parameters:
//   S_AXI_DATA_WIDTH   - Slave wide AXI4 data width (must be > M_AXIL)
//   M_AXIL_DATA_WIDTH  - Master AXIL4 data width (narrow)
//   AXI_ID_WIDTH       - AXI4 ID width (fixed at 8 by convention)
//   AXI_ADDR_WIDTH     - Address width
//
// Author: RTL Design Sherpa
// Created: 2026-05-22

`timescale 1ns / 1ps

module axi4_dwidth_to_axil4_wr_chain #(
    parameter int S_AXI_DATA_WIDTH  = 64,
    parameter int M_AXIL_DATA_WIDTH = 32,
    parameter int AXI_ID_WIDTH      = 8,
    parameter int AXI_ADDR_WIDTH    = 32,
    parameter int AXI_USER_WIDTH    = 1,

    // Calculated
    localparam int S_STRB_WIDTH = S_AXI_DATA_WIDTH / 8,
    localparam int M_STRB_WIDTH = M_AXIL_DATA_WIDTH / 8
) (
    // Clock and Reset
    input  logic                          aclk,
    input  logic                          aresetn,

    //==========================================================================
    // Slave AXI4 Write Interface (wide)
    //==========================================================================
    input  logic [AXI_ID_WIDTH-1:0]       s_axi_awid,
    input  logic [AXI_ADDR_WIDTH-1:0]     s_axi_awaddr,
    input  logic [7:0]                    s_axi_awlen,
    input  logic [2:0]                    s_axi_awsize,
    input  logic [1:0]                    s_axi_awburst,
    input  logic                          s_axi_awlock,
    input  logic [3:0]                    s_axi_awcache,
    input  logic [2:0]                    s_axi_awprot,
    input  logic [3:0]                    s_axi_awqos,
    input  logic [3:0]                    s_axi_awregion,
    input  logic [AXI_USER_WIDTH-1:0]     s_axi_awuser,
    input  logic                          s_axi_awvalid,
    output logic                          s_axi_awready,

    input  logic [S_AXI_DATA_WIDTH-1:0]   s_axi_wdata,
    input  logic [S_STRB_WIDTH-1:0]       s_axi_wstrb,
    input  logic                          s_axi_wlast,
    input  logic [AXI_USER_WIDTH-1:0]     s_axi_wuser,
    input  logic                          s_axi_wvalid,
    output logic                          s_axi_wready,

    output logic [AXI_ID_WIDTH-1:0]       s_axi_bid,
    output logic [1:0]                    s_axi_bresp,
    output logic [AXI_USER_WIDTH-1:0]     s_axi_buser,
    output logic                          s_axi_bvalid,
    input  logic                          s_axi_bready,

    //==========================================================================
    // Master AXIL4 Write Interface (narrow)
    //==========================================================================
    output logic [AXI_ADDR_WIDTH-1:0]     m_axil_awaddr,
    output logic [2:0]                    m_axil_awprot,
    output logic                          m_axil_awvalid,
    input  logic                          m_axil_awready,

    output logic [M_AXIL_DATA_WIDTH-1:0]  m_axil_wdata,
    output logic [M_STRB_WIDTH-1:0]       m_axil_wstrb,
    output logic                          m_axil_wvalid,
    input  logic                          m_axil_wready,

    input  logic [1:0]                    m_axil_bresp,
    input  logic                          m_axil_bvalid,
    output logic                          m_axil_bready
);

    //==========================================================================
    // Boundary reset synchronization
    //==========================================================================
    // Boundary reset synchronizer (block input reset is async-assert,
    // synchronized internally; complete closure)
    //
    // The port aresetn is treated as an asynchronous-assert input of unknown
    // deassert quality: an N=3 reset_sync (rtl/cdc, formally proven) produces
    // the internal reset every block below sees.
    logic w_aresetn;
    reset_sync #(
        .N             (3),
        .KEEP_ATTRS    (1'b1),
        .IN_ACTIVE_LOW (1'b1),
        .OUT_ACTIVE_LOW(1'b1),
        .ASYNC_ASSERT  (1'b1)
    ) u_reset_sync (
        .clk        (aclk),
        .rst_n      (aresetn),
        .sync_rst_n (w_aresetn)
    );

    //==========================================================================
    // Internal narrow AXI4 (between dwidth converter and axil shim)
    //==========================================================================
    logic [AXI_ID_WIDTH-1:0]              int_awid;
    logic [AXI_ADDR_WIDTH-1:0]            int_awaddr;
    logic [7:0]                           int_awlen;
    logic [2:0]                           int_awsize;
    logic [1:0]                           int_awburst;
    logic                                 int_awlock;
    logic [3:0]                           int_awcache;
    logic [2:0]                           int_awprot;
    logic [3:0]                           int_awqos;
    logic [3:0]                           int_awregion;
    logic [AXI_USER_WIDTH-1:0]            int_awuser;
    logic                                 int_awvalid;
    logic                                 int_awready;

    logic [M_AXIL_DATA_WIDTH-1:0]         int_wdata;
    logic [M_STRB_WIDTH-1:0]              int_wstrb;
    logic                                 int_wlast;
    logic [AXI_USER_WIDTH-1:0]            int_wuser;
    logic                                 int_wvalid;
    logic                                 int_wready;

    logic [AXI_ID_WIDTH-1:0]              int_bid;
    logic [1:0]                           int_bresp;
    logic [AXI_USER_WIDTH-1:0]            int_buser;
    logic                                 int_bvalid;
    logic                                 int_bready;

    //==========================================================================
    // Wide AXI4 (slave) → Narrow AXI4 (internal)
    //==========================================================================
    axi4_dwidth_converter_wr #(
        .S_AXI_DATA_WIDTH (S_AXI_DATA_WIDTH),
        .M_AXI_DATA_WIDTH (M_AXIL_DATA_WIDTH),
        .AXI_ID_WIDTH     (AXI_ID_WIDTH),
        .AXI_ADDR_WIDTH   (AXI_ADDR_WIDTH),
        .AXI_USER_WIDTH   (AXI_USER_WIDTH)
    ) u_dwidth_wr (
        .aclk             (aclk),
        .aresetn          (w_aresetn),

        // Slave (wide)
        .s_axi_awid       (s_axi_awid),
        .s_axi_awaddr     (s_axi_awaddr),
        .s_axi_awlen      (s_axi_awlen),
        .s_axi_awsize     (s_axi_awsize),
        .s_axi_awburst    (s_axi_awburst),
        .s_axi_awlock     (s_axi_awlock),
        .s_axi_awcache    (s_axi_awcache),
        .s_axi_awprot     (s_axi_awprot),
        .s_axi_awqos      (s_axi_awqos),
        .s_axi_awregion   (s_axi_awregion),
        .s_axi_awuser     (s_axi_awuser),
        .s_axi_awvalid    (s_axi_awvalid),
        .s_axi_awready    (s_axi_awready),

        .s_axi_wdata      (s_axi_wdata),
        .s_axi_wstrb      (s_axi_wstrb),
        .s_axi_wlast      (s_axi_wlast),
        .s_axi_wuser      (s_axi_wuser),
        .s_axi_wvalid     (s_axi_wvalid),
        .s_axi_wready     (s_axi_wready),

        .s_axi_bid        (s_axi_bid),
        .s_axi_bresp      (s_axi_bresp),
        .s_axi_buser      (s_axi_buser),
        .s_axi_bvalid     (s_axi_bvalid),
        .s_axi_bready     (s_axi_bready),

        // Master (narrow) — feeds internal AXI4 between modules
        .m_axi_awid       (int_awid),
        .m_axi_awaddr     (int_awaddr),
        .m_axi_awlen      (int_awlen),
        .m_axi_awsize     (int_awsize),
        .m_axi_awburst    (int_awburst),
        .m_axi_awlock     (int_awlock),
        .m_axi_awcache    (int_awcache),
        .m_axi_awprot     (int_awprot),
        .m_axi_awqos      (int_awqos),
        .m_axi_awregion   (int_awregion),
        .m_axi_awuser     (int_awuser),
        .m_axi_awvalid    (int_awvalid),
        .m_axi_awready    (int_awready),

        .m_axi_wdata      (int_wdata),
        .m_axi_wstrb      (int_wstrb),
        .m_axi_wlast      (int_wlast),
        .m_axi_wuser      (int_wuser),
        .m_axi_wvalid     (int_wvalid),
        .m_axi_wready     (int_wready),

        .m_axi_bid        (int_bid),
        .m_axi_bresp      (int_bresp),
        .m_axi_buser      (int_buser),
        .m_axi_bvalid     (int_bvalid),
        .m_axi_bready     (int_bready)
    );

    //==========================================================================
    // Narrow AXI4 (internal) → AXIL4 (master)
    //==========================================================================
    axi4_to_axil4_wr #(
        .AXI_ID_WIDTH     (AXI_ID_WIDTH),
        .AXI_ADDR_WIDTH   (AXI_ADDR_WIDTH),
        .AXI_DATA_WIDTH   (M_AXIL_DATA_WIDTH),
        .AXI_USER_WIDTH   (AXI_USER_WIDTH)
    ) u_to_axil_wr (
        .aclk             (aclk),
        .aresetn          (w_aresetn),

        // Slave AXI4 (narrow) — accepts the dnsize'd burst
        .s_axi_awid       (int_awid),
        .s_axi_awaddr     (int_awaddr),
        .s_axi_awlen      (int_awlen),
        .s_axi_awsize     (int_awsize),
        .s_axi_awburst    (int_awburst),
        .s_axi_awlock     (int_awlock),
        .s_axi_awcache    (int_awcache),
        .s_axi_awprot     (int_awprot),
        .s_axi_awqos      (int_awqos),
        .s_axi_awregion   (int_awregion),
        .s_axi_awuser     (int_awuser),
        .s_axi_awvalid    (int_awvalid),
        .s_axi_awready    (int_awready),

        .s_axi_wdata      (int_wdata),
        .s_axi_wstrb      (int_wstrb),
        .s_axi_wlast      (int_wlast),
        .s_axi_wuser      (int_wuser),
        .s_axi_wvalid     (int_wvalid),
        .s_axi_wready     (int_wready),

        .s_axi_bid        (int_bid),
        .s_axi_bresp      (int_bresp),
        .s_axi_buser      (int_buser),
        .s_axi_bvalid     (int_bvalid),
        .s_axi_bready     (int_bready),

        // Master AXIL4 (narrow) — module output
        .m_axil_awaddr    (m_axil_awaddr),
        .m_axil_awprot    (m_axil_awprot),
        .m_axil_awvalid   (m_axil_awvalid),
        .m_axil_awready   (m_axil_awready),

        .m_axil_wdata     (m_axil_wdata),
        .m_axil_wstrb     (m_axil_wstrb),
        .m_axil_wvalid    (m_axil_wvalid),
        .m_axil_wready    (m_axil_wready),

        .m_axil_bresp     (m_axil_bresp),
        .m_axil_bvalid    (m_axil_bvalid),
        .m_axil_bready    (m_axil_bready)
    );

endmodule : axi4_dwidth_to_axil4_wr_chain

`timescale 1ns / 1ps

//==============================================================================
// Module: axi4_slave_rd_injector
//==============================================================================
//
// Protocol handling: the AXI channel logic is the standard `axi4_slave_rd`
// protocol module (instantiated below), with the pattern / CRC logic on its
// fub_axi_* user interface. Remaining TODO (task #78): move to the
// monitored `axi4_slave_rd_mon` variant.
//
// Description:
//   AXI4 read-only slave that generates pseudo-random patterns using LFSR
//   and computes CRC-32 for DMA validation. Combines axi4_slave_rd protocol
//   handler with LFSR pattern generator and CRC checker.
//
//   Per-channel mode (NUM_CHANNELS > 1): the slave maintains independent
//   LFSR + CRC state per channel, demuxed off the low bits of s_axi_arid,
//   or off s_axi_araddr[CH_ADDR_LSB +: CIW] when CH_SEL_ADDR = 1.
//   This makes the data each channel reads back independent of any other
//   channel's traffic, so a multi-channel test can verify integrity per
//   channel without ordering interleave at the shared AXI port corrupting
//   the running CRC.
//
// Parameters:
//   NUM_CHANNELS   - Number of independent LFSR/CRC contexts (default: 1)
//   SKID_DEPTH_AR  - AR channel skid buffer depth (default: 2)
//   SKID_DEPTH_R   - R channel skid buffer depth (default: 4)
//   AXI_ID_WIDTH   - AXI ID width (default: 8). Channel index is extracted
//                    from arid[CIW-1:0] where CIW = $clog2(NUM_CHANNELS).
//   AXI_ADDR_WIDTH - AXI address width (default: 32)
//   AXI_DATA_WIDTH - AXI data width (default: 64, can be wider)
//   AXI_USER_WIDTH - AXI user signal width (default: 1)
//   LFSR_SEED      - Base LFSR seed; channel N uses (LFSR_SEED ^ N) so
//                    each channel generates a distinct pseudo-random stream
//
// Per-channel outputs:
//   read_crc_value [NUM_CHANNELS][31:0]  - per-channel CRC values
//   read_crc_valid [NUM_CHANNELS]        - per-channel valid flags
//   read_beat_count[NUM_CHANNELS][31:0]  - per-channel beat counts
//
// Aggregate output (for harness timer):
//   read_beat_count_total [31:0]         - sum of per-channel beat counts
//
//==============================================================================

`include "reset_defs.svh"

module axi4_slave_rd_injector #(
    // AXI parameters
    parameter int NUM_CHANNELS  = 1,
    parameter int SKID_DEPTH_AR = 2,
    parameter int SKID_DEPTH_R  = 4,
    parameter int AXI_ID_WIDTH  = 8,
    parameter int AXI_ADDR_WIDTH = 32,
    parameter int AXI_DATA_WIDTH = 64,
    parameter int AXI_USER_WIDTH = 1,

    // LFSR parameters (32-bit fixed for simplicity and timing)
    parameter int LFSR_WIDTH = 32,
    parameter logic [31:0] LFSR_SEED = 32'hDEADBEEF,
    parameter logic [47:0] LFSR_TAPS = {12'd23, 12'd3, 12'd2, 12'd1},  // Maximal length

    // CRC parameters (fixed, MUST MATCH axi4_slave_wr_crc_check!)
    parameter int CRC_WIDTH      = 32,
    parameter int CRC_DATA_WIDTH = 32,  // Process 32-bit LFSR output only
    parameter logic [31:0] CRC_POLY    = 32'h04C11DB7,  // CRC-32 Ethernet
    parameter logic [31:0] CRC_INIT    = 32'hFFFFFFFF,
    parameter logic [31:0] CRC_XOROUT  = 32'hFFFFFFFF,
    parameter int CRC_REFIN  = 1,
    parameter int CRC_REFOUT = 1,

    // Derived parameters
    parameter int REPLICATION_FACTOR = (AXI_DATA_WIDTH + 31) / 32,
    parameter int CIW = (NUM_CHANNELS > 1) ? $clog2(NUM_CHANNELS) : 1,

    // Channel select. 0 (default): the channel is the low CIW bits of the
    // burst's ID (AR/AW), as every harness built so far drives it.
    // 1: the channel is the burst's address bits [CH_ADDR_LSB +: CIW] -- for a
    // fabric that does not carry the master's ID to its slaves (SmartConnect's
    // MI ID width is 0). Each channel then owns a 2^CH_ADDR_LSB-byte window;
    // the windows never overlap and a burst never crosses one (AXI bursts stop
    // at 4 KB, so CH_ADDR_LSB >= 12). CH_ADDR_LSB + CIW <= AXI_ADDR_WIDTH.
    parameter bit CH_SEL_ADDR = 1'b0,
    parameter int CH_ADDR_LSB = 16,

    // ERR_INJECT=1 (rapids TASK-020) builds the R-response error injector:
    // every beat of a chosen burst on a chosen channel answers cfg_err_resp
    // instead of OKAY, so a DUT's read-error path can be reached from a
    // harness. 0 (default) elaborates none of it and holds RRESP at OKAY --
    // identical to the pre-TASK-020 block, which is what STREAM's and the
    // RAPIDS-beats harnesses keep using.
    parameter bit ERR_INJECT = 1'b0
) (
    // Global Clock and Reset
    input  logic                        aclk,
    input  logic                        aresetn,

    // Test Control (from UART controller or test logic)
    input  logic                        crc_lfsr_reset,  // Pulse to reset LFSR and CRC

    // Per-channel CRC and Status Outputs
    output logic [NUM_CHANNELS-1:0][31:0] read_crc_value,
    output logic [NUM_CHANNELS-1:0]       read_crc_valid,
    output logic [NUM_CHANNELS-1:0][31:0] read_beat_count,
    // Aggregate beat count (sum across channels) for the harness stop trigger.
    output logic [31:0]                   read_beat_count_total,

    // AXI4 Slave Interface (Read-Only)
    // Read address channel (AR)
    input  logic [AXI_ID_WIDTH-1:0]     s_axi_arid,
    input  logic [AXI_ADDR_WIDTH-1:0]   s_axi_araddr,
    input  logic [7:0]                  s_axi_arlen,
    input  logic [2:0]                  s_axi_arsize,
    input  logic [1:0]                  s_axi_arburst,
    input  logic                        s_axi_arlock,
    input  logic [3:0]                  s_axi_arcache,
    input  logic [2:0]                  s_axi_arprot,
    input  logic [3:0]                  s_axi_arqos,
    input  logic [3:0]                  s_axi_arregion,
    input  logic [AXI_USER_WIDTH-1:0]   s_axi_aruser,
    input  logic                        s_axi_arvalid,
    output logic                        s_axi_arready,

    // Read data channel (R)
    output logic [AXI_ID_WIDTH-1:0]     s_axi_rid,
    output logic [AXI_DATA_WIDTH-1:0]   s_axi_rdata,
    output logic [1:0]                  s_axi_rresp,
    output logic                        s_axi_rlast,
    output logic [AXI_USER_WIDTH-1:0]   s_axi_ruser,
    output logic                        s_axi_rvalid,
    input  logic                        s_axi_rready,

    // Error-response injection config (rapids TASK-020).
    // Inert unless ERR_INJECT=1; tie off at 0 otherwise.
    input  logic                        cfg_err_enable,
    input  logic [CIW-1:0]              cfg_err_channel,
    input  logic [15:0]                 cfg_err_skip,
    input  logic [1:0]                  cfg_err_resp,
    input  logic                        cfg_err_oneshot,
    output logic                        err_injected,

    // Status Output
    output logic                        busy
);

    //==========================================================================
    // Boundary reset synchronization
    //==========================================================================
    // The port aresetn is treated as an asynchronous-assert input of unknown
    // deassert quality: an N=3 reset_sync produces the internal reset every
    // block below sees.
    logic w_aresetn;
    reset_sync #(
        .N             (3),
        .KEEP_ATTRS    (1'b1),
        .IN_ACTIVE_LOW (1'b1),
        .OUT_ACTIVE_LOW(1'b1),
        .ASYNC_ASSERT  (1'b1)
    ) u_reset_sync (
        .clk        (aclk),
        .rst_n      (aresetn),
        .sync_rst_n (w_aresetn)
    );

    //==========================================================================
    // Local Parameters
    //==========================================================================

    localparam int LFSR_TAP_INDEX_WIDTH = 12;
    localparam int LFSR_TAP_COUNT = 4;

    //==========================================================================
    // Internal Signals - FUB (Functional Unit Backend) Interface
    //==========================================================================

    // Internal interface between axi4_slave_rd and pattern generator
    logic [AXI_ID_WIDTH-1:0]     fub_axi_arid;
    logic [AXI_ADDR_WIDTH-1:0]   fub_axi_araddr;
    logic [7:0]                  fub_axi_arlen;
    logic [2:0]                  fub_axi_arsize;
    logic [1:0]                  fub_axi_arburst;
    logic                        fub_axi_arlock;
    logic [3:0]                  fub_axi_arcache;
    logic [2:0]                  fub_axi_arprot;
    logic [3:0]                  fub_axi_arqos;
    logic [3:0]                  fub_axi_arregion;
    logic [AXI_USER_WIDTH-1:0]   fub_axi_aruser;
    logic                        fub_axi_arvalid;
    logic                        fub_axi_arready;

    logic [AXI_ID_WIDTH-1:0]     fub_axi_rid;
    logic [AXI_DATA_WIDTH-1:0]   fub_axi_rdata;
    logic [1:0]                  fub_axi_rresp;
    logic                        fub_axi_rlast;
    logic [AXI_USER_WIDTH-1:0]   fub_axi_ruser;
    logic                        fub_axi_rvalid;
    logic                        fub_axi_rready;

    //==========================================================================
    // FUB Burst FSM — early forward-declarations (used by the per-channel
    // LFSR/CRC generate block below before the FSM body that drives them)
    //==========================================================================

    typedef enum logic [1:0] {
        RD_IDLE   = 2'b00,
        RD_BURST  = 2'b01
    } rd_state_t;

    rd_state_t r_rd_state;
    logic [AXI_ID_WIDTH-1:0]   r_rd_id;
    logic [AXI_USER_WIDTH-1:0] r_rd_user;
    logic [7:0]                r_rd_beats_remaining;

    // Channel of an AR at the handshake (CH_SEL_ADDR: from the ID or the
    // address), captured with the burst; the in-flight burst's channel.
    logic [CIW-1:0] w_ar_ch_sel;
    logic [CIW-1:0] r_rd_ch;
    assign w_ar_ch_sel = (NUM_CHANNELS == 1) ? '0
                       : CH_SEL_ADDR ? fub_axi_araddr[CH_ADDR_LSB +: CIW]
                                     : fub_axi_arid[CIW-1:0];
    logic [CIW-1:0] w_active_ch;
    assign w_active_ch = r_rd_ch;

    // R-beat handshake (one beat consumed per channel per cycle)
    wire w_r_beat = fub_axi_rvalid && fub_axi_rready;

    //==========================================================================
    // Per-channel LFSR Pattern Generators
    //==========================================================================
    // Each channel has its own LFSR seeded uniquely (LFSR_SEED ^ ch_index)
    // so its data stream is independent of other channels'. Only the channel
    // currently being served advances on each R beat; the others hold state.

    logic [31:0] lfsr_out_per_ch [NUM_CHANNELS];

    genvar gch;
    generate
        for (gch = 0; gch < NUM_CHANNELS; gch++) begin : gen_lfsr
            logic ch_enable;
            // LFSR advances on this channel's R beat, OR loads its seed on
            // the global crc_lfsr_reset pulse (the LFSR module accepts the
            // seed only when enable is also high during seed_load).
            assign ch_enable = (w_r_beat && (w_active_ch == gch[CIW-1:0]))
                            || crc_lfsr_reset;

            shifter_lfsr_fibonacci #(
                .WIDTH(LFSR_WIDTH),
                .TAP_INDEX_WIDTH(LFSR_TAP_INDEX_WIDTH),
                .TAP_COUNT(LFSR_TAP_COUNT)
            ) u_lfsr (
                .clk      (aclk),
                .rst_n    (w_aresetn),
                .enable   (ch_enable),
                .seed_load(crc_lfsr_reset),
                .seed_data(LFSR_SEED ^ 32'(gch)),  // unique seed per channel
                .taps     (LFSR_TAPS),
                .lfsr_out (lfsr_out_per_ch[gch]),
                .lfsr_done()
            );
        end
    endgenerate

    // Active channel's LFSR output drives the R data
    logic [31:0] lfsr_out;
    assign lfsr_out = lfsr_out_per_ch[w_active_ch];

    //==========================================================================
    // Pattern Data Replication (active channel feeds the AXI R bus)
    //==========================================================================

    logic [AXI_DATA_WIDTH-1:0] pattern_data;

    generate
        if (AXI_DATA_WIDTH == 32) begin : gen_no_replication
            assign pattern_data = lfsr_out;
        end else if (AXI_DATA_WIDTH % 32 == 0) begin : gen_aligned_replication
            assign pattern_data = {REPLICATION_FACTOR{lfsr_out}};
        end else begin : gen_unaligned_replication
            logic [(REPLICATION_FACTOR*32)-1:0] temp_pattern;
            assign temp_pattern = {REPLICATION_FACTOR{lfsr_out}};
            assign pattern_data = temp_pattern[AXI_DATA_WIDTH-1:0];
        end
    endgenerate

    //==========================================================================
    // Per-channel CRC-32 Calculators + beat counters
    //==========================================================================
    // Each channel has its own dataint_crc instance and beat counter.
    // The CRC for channel N updates only when the active R beat is for ch N.

    logic [31:0] crc_out_per_ch [NUM_CHANNELS];

    generate
        for (gch = 0; gch < NUM_CHANNELS; gch++) begin : gen_crc
            logic ch_load_from_cascade;
            logic r_ch_crc_valid;
            logic [31:0] r_ch_beat_count;

            // CRC accumulates only for this channel's beats
            assign ch_load_from_cascade = w_r_beat
                                       && (w_active_ch == gch[CIW-1:0]);

            dataint_crc #(
                .DATA_WIDTH(CRC_DATA_WIDTH),
                .CRC_WIDTH (CRC_WIDTH),
                .REFIN     (CRC_REFIN),
                .REFOUT    (CRC_REFOUT)
            ) u_crc (
                .POLY             (CRC_POLY),
                .POLY_INIT        (CRC_INIT),
                .XOROUT           (CRC_XOROUT),
                .clk              (aclk),
                .rst_n            (w_aresetn),
                .load_crc_start   (crc_lfsr_reset),
                .load_from_cascade(ch_load_from_cascade),
                .cascade_sel      (4'b1000),  // process all 4 bytes of 32-bit slice
                .data             (lfsr_out_per_ch[gch]),
                .crc              (crc_out_per_ch[gch])
            );

            // Per-channel CRC-valid + beat counter
            `ALWAYS_FF_RST(aclk, w_aresetn,
                if (`RST_ASSERTED(w_aresetn)) begin
                    r_ch_crc_valid  <= 1'b0;
                    r_ch_beat_count <= '0;
                end else begin
                    if (crc_lfsr_reset) begin
                        r_ch_crc_valid  <= 1'b0;
                        r_ch_beat_count <= '0;
                    end else if (ch_load_from_cascade) begin
                        r_ch_crc_valid  <= 1'b1;
                        r_ch_beat_count <= r_ch_beat_count + 1'b1;
                    end
                end
            )

            assign read_crc_value [gch] = crc_out_per_ch[gch];
            assign read_crc_valid [gch] = r_ch_crc_valid;
            assign read_beat_count[gch] = r_ch_beat_count;
        end
    endgenerate

    //==========================================================================
    // Aggregate beat count (sum across all channels) for the harness timer
    //==========================================================================

    always_comb begin
        read_beat_count_total = '0;
        for (int ch = 0; ch < NUM_CHANNELS; ch++) begin
            read_beat_count_total = read_beat_count_total + read_beat_count[ch];
        end
    end

    //==========================================================================
    // FUB Interface - Burst FSM
    //==========================================================================
    // Accepts AR requests, tracks burst beat count, generates R beats with
    // LFSR pattern data. Asserts rlast on final beat of each burst.

    // Accept AR when idle, OR on the last beat of the current burst so the
    // next burst follows with no dead cycle. The original (idle-only) accept
    // forced a 1-cycle RD_IDLE gap between every burst (rvalid=0), which showed
    // up as ~1 starvation cycle per burst (16-beat burst -> 16/17 = 94%) on the
    // master's R channel -- a *slave-model* artifact, not a DUT limitation.
    // Accepting the AR back-to-back on rlast keeps rvalid continuously high.
    wire w_rd_last_beat = (r_rd_state == RD_BURST) && fub_axi_rvalid &&
                          fub_axi_rready && (r_rd_beats_remaining == 8'd0);
    assign fub_axi_arready = (r_rd_state == RD_IDLE) || w_rd_last_beat;

    // R channel outputs
    assign fub_axi_rid   = r_rd_id;
    assign fub_axi_rdata = pattern_data;

    //==========================================================================
    // R-response error injection (rapids TASK-020)
    //==========================================================================
    // Counts ACCEPTED ARs on cfg_err_channel while armed; the burst whose
    // index equals cfg_err_skip answers cfg_err_resp on every one of its
    // beats. The decision is latched at AR acceptance, so it follows that
    // burst even though arready accepts the next AR on the last R beat.
    // One-shot disarms afterwards, so a sequence can prove recovery.
    generate
        if (ERR_INJECT) begin : gen_err_inject
            logic [15:0] r_err_count;
            logic        r_err_done;
            logic [1:0]  r_rd_resp;

            wire w_ar_accept = fub_axi_arvalid && fub_axi_arready;
            wire [CIW-1:0] w_ar_ch = w_ar_ch_sel;
            wire w_err_arm_ch = (NUM_CHANNELS == 1) ? 1'b1
                                                    : (w_ar_ch == cfg_err_channel);
            wire w_err_hit    = cfg_err_enable && !r_err_done && w_err_arm_ch &&
                                (r_err_count == cfg_err_skip);

            assign fub_axi_rresp = r_rd_resp;

            `ALWAYS_FF_RST(aclk, w_aresetn,
                if (`RST_ASSERTED(w_aresetn)) begin
                    r_err_count  <= '0;
                    r_err_done   <= 1'b0;
                    r_rd_resp    <= 2'b00;
                    err_injected <= 1'b0;
                end else begin
                    if (crc_lfsr_reset || !cfg_err_enable) begin
                        r_err_count <= '0;
                        r_err_done  <= 1'b0;
                    end else if (w_ar_accept && w_err_arm_ch) begin
                        if (w_err_hit) begin
                            if (cfg_err_oneshot) r_err_done  <= 1'b1;
                            else                 r_err_count <= '0;
                        end else begin
                            r_err_count <= r_err_count + 16'd1;
                        end
                    end

                    // The accepted burst carries its own response for all
                    // of its beats; it reverts on the next acceptance.
                    if (w_ar_accept) begin
                        r_rd_resp <= w_err_hit ? cfg_err_resp : 2'b00;
                    end

                    if (crc_lfsr_reset) begin
                        err_injected <= 1'b0;
                    end else if (w_ar_accept && w_err_hit) begin
                        err_injected <= 1'b1;
                    end
                end
            )
        end else begin : gen_no_err_inject
            assign fub_axi_rresp = 2'b00;  // OKAY
            assign err_injected  = 1'b0;
        end
    endgenerate
    assign fub_axi_ruser = r_rd_user;
    assign fub_axi_rlast = (r_rd_state == RD_BURST) && (r_rd_beats_remaining == 8'd0);
    assign fub_axi_rvalid = (r_rd_state == RD_BURST);

    `ALWAYS_FF_RST(aclk, w_aresetn,
        if (`RST_ASSERTED(w_aresetn)) begin
            r_rd_state <= RD_IDLE;
            r_rd_id <= '0;
            r_rd_ch <= '0;
            r_rd_user <= '0;
            r_rd_beats_remaining <= '0;
        end else begin
            case (r_rd_state)
                RD_IDLE: begin
                    if (fub_axi_arvalid && fub_axi_arready) begin
                        r_rd_state <= RD_BURST;
                        r_rd_id <= fub_axi_arid;
                        r_rd_ch <= w_ar_ch_sel;
                        r_rd_user <= fub_axi_aruser;
                        r_rd_beats_remaining <= fub_axi_arlen;  // arlen = beats - 1
                    end
                end

                RD_BURST: begin
                    if (fub_axi_rvalid && fub_axi_rready) begin
                        if (r_rd_beats_remaining == 8'd0) begin
                            // Last beat: if a new AR is already waiting, accept
                            // it now (arready is asserted via w_rd_last_beat) and
                            // reload, staying in RD_BURST so rvalid never drops.
                            // No beat is produced during the old idle cycle, so
                            // the per-channel LFSR sequence (and the write-side
                            // CRC) is unchanged -- only the dead cycle is removed.
                            if (fub_axi_arvalid) begin
                                r_rd_id <= fub_axi_arid;
                                r_rd_ch <= w_ar_ch_sel;
                                r_rd_user <= fub_axi_aruser;
                                r_rd_beats_remaining <= fub_axi_arlen;
                            end else begin
                                r_rd_state <= RD_IDLE;
                            end
                        end else begin
                            r_rd_beats_remaining <= r_rd_beats_remaining - 8'd1;
                        end
                    end
                end

                default: r_rd_state <= RD_IDLE;
            endcase
        end
    )

    //==========================================================================
    // AXI4 Slave Read Protocol Handler
    //==========================================================================

    axi4_slave_rd #(
        .SKID_DEPTH_AR      (SKID_DEPTH_AR),
        .SKID_DEPTH_R       (SKID_DEPTH_R),
        .AXI_ID_WIDTH       (AXI_ID_WIDTH),
        .AXI_ADDR_WIDTH     (AXI_ADDR_WIDTH),
        .AXI_DATA_WIDTH     (AXI_DATA_WIDTH),
        .AXI_USER_WIDTH     (AXI_USER_WIDTH)
    ) u_axi4_slave_rd (
        .aclk               (aclk),
        .aresetn            (w_aresetn),

        .s_axi_arid         (s_axi_arid),
        .s_axi_araddr       (s_axi_araddr),
        .s_axi_arlen        (s_axi_arlen),
        .s_axi_arsize       (s_axi_arsize),
        .s_axi_arburst      (s_axi_arburst),
        .s_axi_arlock       (s_axi_arlock),
        .s_axi_arcache      (s_axi_arcache),
        .s_axi_arprot       (s_axi_arprot),
        .s_axi_arqos        (s_axi_arqos),
        .s_axi_arregion     (s_axi_arregion),
        .s_axi_aruser       (s_axi_aruser),
        .s_axi_arvalid      (s_axi_arvalid),
        .s_axi_arready      (s_axi_arready),

        .s_axi_rid          (s_axi_rid),
        .s_axi_rdata        (s_axi_rdata),
        .s_axi_rresp        (s_axi_rresp),
        .s_axi_rlast        (s_axi_rlast),
        .s_axi_ruser        (s_axi_ruser),
        .s_axi_rvalid       (s_axi_rvalid),
        .s_axi_rready       (s_axi_rready),

        .fub_axi_arid       (fub_axi_arid),
        .fub_axi_araddr     (fub_axi_araddr),
        .fub_axi_arlen      (fub_axi_arlen),
        .fub_axi_arsize     (fub_axi_arsize),
        .fub_axi_arburst    (fub_axi_arburst),
        .fub_axi_arlock     (fub_axi_arlock),
        .fub_axi_arcache    (fub_axi_arcache),
        .fub_axi_arprot     (fub_axi_arprot),
        .fub_axi_arqos      (fub_axi_arqos),
        .fub_axi_arregion   (fub_axi_arregion),
        .fub_axi_aruser     (fub_axi_aruser),
        .fub_axi_arvalid    (fub_axi_arvalid),
        .fub_axi_arready    (fub_axi_arready),

        .fub_axi_rid        (fub_axi_rid),
        .fub_axi_rdata      (fub_axi_rdata),
        .fub_axi_rresp      (fub_axi_rresp),
        .fub_axi_rlast      (fub_axi_rlast),
        .fub_axi_ruser      (fub_axi_ruser),
        .fub_axi_rvalid     (fub_axi_rvalid),
        .fub_axi_rready     (fub_axi_rready),

        .busy               (busy)
    );

endmodule : axi4_slave_rd_injector

`timescale 1ns / 1ps

//==============================================================================
// Module: axi4_slave_rom
//==============================================================================
// Description:
//   AXI4 read-only memory slave wrapper. Combines axi4_slave_rd protocol
//   handler with simple_rom storage backend to provide AXI4-compliant ROM
//   interface. Useful for boot code, configuration data, lookup tables, etc.
//
// Parameters:
//   SKID_DEPTH_AR  - AR channel skid buffer depth (default: 2)
//   SKID_DEPTH_R   - R channel skid buffer depth (default: 4)
//   AXI_ID_WIDTH   - AXI ID width (default: 8)
//   AXI_ADDR_WIDTH - AXI address width (default: 32)
//   AXI_DATA_WIDTH - AXI data width (default: 64)
//   AXI_USER_WIDTH - AXI user signal width (default: 1)
//   ROM_INIT_FILE  - ROM initialization file path (default: "none")
//
// Interfaces:
//   aclk, aresetn     - Clock and reset
//   s_axi_ar*         - AXI4 read address channel (slave)
//   s_axi_r*          - AXI4 read data channel (slave)
//   busy              - Status output (active transactions)
//
// Notes:
//   - Read-only interface (no write channels)
//   - Single-cycle ROM access latency
//   - FPGA block RAM inference for ROM storage
//   - Supports bursts via AXI4 slave read handler
//   - ROM address is byte-aligned AXI address shifted by data width
//
//==============================================================================

module axi4_slave_rom
#(
    parameter int SKID_DEPTH_AR     = 2,                    // AR channel buffer depth
    parameter int SKID_DEPTH_R      = 4,                    // R channel buffer depth
    parameter int AXI_ID_WIDTH      = 8,                    // AXI ID width
    parameter int AXI_ADDR_WIDTH    = 32,                   // AXI address width
    parameter int AXI_DATA_WIDTH    = 64,                   // AXI data width
    parameter int AXI_USER_WIDTH    = 1,                    // AXI user width
    parameter int ROM_ADDR_WIDTH    = 12,                   // ROM depth = 2**ROM_ADDR_WIDTH words
    parameter string ROM_INIT_FILE  = "none"                // ROM initialization file
)
(
    // Global Clock and Reset
    input  logic                        aclk,               // AXI clock
    input  logic                        aresetn,            // AXI reset (active-low)

    // AXI4 Slave Interface (Read-Only)
    // Read address channel (AR)
    input  logic [AXI_ID_WIDTH-1:0]     s_axi_arid,         // Read address ID
    input  logic [AXI_ADDR_WIDTH-1:0]   s_axi_araddr,       // Read address
    input  logic [7:0]                  s_axi_arlen,        // Burst length
    input  logic [2:0]                  s_axi_arsize,       // Burst size
    input  logic [1:0]                  s_axi_arburst,      // Burst type
    input  logic                        s_axi_arlock,       // Lock type
    input  logic [3:0]                  s_axi_arcache,      // Cache type
    input  logic [2:0]                  s_axi_arprot,       // Protection type
    input  logic [3:0]                  s_axi_arqos,        // QoS identifier
    input  logic [3:0]                  s_axi_arregion,     // Region identifier
    input  logic [AXI_USER_WIDTH-1:0]   s_axi_aruser,       // User signal
    input  logic                        s_axi_arvalid,      // Read address valid
    output logic                        s_axi_arready,      // Read address ready

    // Read data channel (R)
    output logic [AXI_ID_WIDTH-1:0]     s_axi_rid,          // Read data ID
    output logic [AXI_DATA_WIDTH-1:0]   s_axi_rdata,        // Read data
    output logic [1:0]                  s_axi_rresp,        // Read response
    output logic                        s_axi_rlast,        // Read last
    output logic [AXI_USER_WIDTH-1:0]   s_axi_ruser,        // User signal
    output logic                        s_axi_rvalid,       // Read data valid
    input  logic                        s_axi_rready,       // Read data ready

    // Status Output
    output logic                        busy                // Busy indicator
);

    //==========================================================================
    // Local Parameters
    //==========================================================================

    localparam int BYTES_PER_WORD = AXI_DATA_WIDTH / 8;
    localparam int ADDR_LSB       = $clog2(BYTES_PER_WORD);

    // Boundary reset synchronization. The port aresetn is treated as an
    // asynchronous-assert input of unknown deassert quality: an N=3
    // reset_sync (rtl/cdc, formally proven) produces the internal reset
    // every block below sees.
    logic w_aresetn;
    reset_sync #(
        .N             (3),
        .KEEP_ATTRS    (1'b1),
        .IN_ACTIVE_LOW (1'b1),
        .OUT_ACTIVE_LOW(1'b1),
        .ASYNC_ASSERT  (1'b1)
    ) u_reset_sync (
        .clk        (aclk),
        .rst_n      (aresetn),
        .sync_rst_n (w_aresetn)
    );

    //==========================================================================
    // Internal Signals - FUB (Functional Unit Backend) Interface
    //==========================================================================

    // Internal interface between axi4_slave_rd and ROM
    logic [AXI_ID_WIDTH-1:0]     fub_axi_arid;
    logic [AXI_ADDR_WIDTH-1:0]   fub_axi_araddr;
    logic [7:0]                  fub_axi_arlen;
    logic [2:0]                  fub_axi_arsize;
    logic [1:0]                  fub_axi_arburst;
    logic                        fub_axi_arlock;
    logic [3:0]                  fub_axi_arcache;
    logic [2:0]                  fub_axi_arprot;
    logic [3:0]                  fub_axi_arqos;
    logic [3:0]                  fub_axi_arregion;
    logic [AXI_USER_WIDTH-1:0]   fub_axi_aruser;
    logic                        fub_axi_arvalid;
    logic                        fub_axi_arready;

    logic [AXI_ID_WIDTH-1:0]     fub_axi_rid;
    logic [AXI_DATA_WIDTH-1:0]   fub_axi_rdata;
    logic [1:0]                  fub_axi_rresp;
    logic                        fub_axi_rlast;
    logic [AXI_USER_WIDTH-1:0]   fub_axi_ruser;
    logic                        fub_axi_rvalid;
    logic                        fub_axi_rready;

    //==========================================================================
    // Glue Logic - ROM Interface Conversion
    //==========================================================================

    // Convert byte-aligned AXI address to word-aligned ROM address
    logic [ROM_ADDR_WIDTH-1:0] rom_addr;
    assign rom_addr = fub_axi_araddr[ADDR_LSB +: ROM_ADDR_WIDTH];

    // ROM enable: active when valid address transaction
    logic rom_en;
    assign rom_en = fub_axi_arvalid;

    // ROM read data
    logic [AXI_DATA_WIDTH-1:0] rom_data;

    // FUB AR channel ready (ROM always ready for single-cycle access)
    assign fub_axi_arready = 1'b1;

    // FUB R channel - ROM read data and control
    assign fub_axi_rid     = fub_axi_arid;      // Pass through ID
    assign fub_axi_rdata   = rom_data;          // ROM data
    assign fub_axi_rresp   = 2'b00;             // OKAY response (no errors in ROM)
    assign fub_axi_rlast   = 1'b1;              // Single-beat response (burst handled by slave_rd)
    assign fub_axi_ruser   = '0;                // User signal unused
    assign fub_axi_rvalid  = fub_axi_arvalid;   // Valid when AR valid (single-cycle)
    assign fub_axi_rready  = 1'b1;              // Always ready (no backpressure from ROM)

    //==========================================================================
    // AXI4 Slave Read Protocol Handler
    //==========================================================================

    axi4_slave_rd #(
        .SKID_DEPTH_AR      (SKID_DEPTH_AR),
        .SKID_DEPTH_R       (SKID_DEPTH_R),
        .AXI_ID_WIDTH       (AXI_ID_WIDTH),
        .AXI_ADDR_WIDTH     (AXI_ADDR_WIDTH),
        .AXI_DATA_WIDTH     (AXI_DATA_WIDTH),
        .AXI_USER_WIDTH     (AXI_USER_WIDTH)
    ) u_axi4_slave_rd (
        // Clock and Reset
        .aclk               (aclk),
        .aresetn            (w_aresetn),

        // Slave AXI Interface (External)
        .s_axi_arid         (s_axi_arid),
        .s_axi_araddr       (s_axi_araddr),
        .s_axi_arlen        (s_axi_arlen),
        .s_axi_arsize       (s_axi_arsize),
        .s_axi_arburst      (s_axi_arburst),
        .s_axi_arlock       (s_axi_arlock),
        .s_axi_arcache      (s_axi_arcache),
        .s_axi_arprot       (s_axi_arprot),
        .s_axi_arqos        (s_axi_arqos),
        .s_axi_arregion     (s_axi_arregion),
        .s_axi_aruser       (s_axi_aruser),
        .s_axi_arvalid      (s_axi_arvalid),
        .s_axi_arready      (s_axi_arready),

        .s_axi_rid          (s_axi_rid),
        .s_axi_rdata        (s_axi_rdata),
        .s_axi_rresp        (s_axi_rresp),
        .s_axi_rlast        (s_axi_rlast),
        .s_axi_ruser        (s_axi_ruser),
        .s_axi_rvalid       (s_axi_rvalid),
        .s_axi_rready       (s_axi_rready),

        // Master AXI Interface (Internal to ROM)
        .fub_axi_arid       (fub_axi_arid),
        .fub_axi_araddr     (fub_axi_araddr),
        .fub_axi_arlen      (fub_axi_arlen),
        .fub_axi_arsize     (fub_axi_arsize),
        .fub_axi_arburst    (fub_axi_arburst),
        .fub_axi_arlock     (fub_axi_arlock),
        .fub_axi_arcache    (fub_axi_arcache),
        .fub_axi_arprot     (fub_axi_arprot),
        .fub_axi_arqos      (fub_axi_arqos),
        .fub_axi_arregion   (fub_axi_arregion),
        .fub_axi_aruser     (fub_axi_aruser),
        .fub_axi_arvalid    (fub_axi_arvalid),
        .fub_axi_arready    (fub_axi_arready),

        .fub_axi_rid        (fub_axi_rid),
        .fub_axi_rdata      (fub_axi_rdata),
        .fub_axi_rresp      (fub_axi_rresp),
        .fub_axi_rlast      (fub_axi_rlast),
        .fub_axi_ruser      (fub_axi_ruser),
        .fub_axi_rvalid     (fub_axi_rvalid),
        .fub_axi_rready     (fub_axi_rready),

        // Status Output
        .busy               (busy)
    );

    //==========================================================================
    // Simple ROM Storage Backend
    //==========================================================================

    simple_rom #(
        .ADDR_WIDTH         (ROM_ADDR_WIDTH),
        .DATA_WIDTH         (AXI_DATA_WIDTH),
        .INIT_FILE          (ROM_INIT_FILE)
    ) u_simple_rom (
        .clk                (aclk),
        .en                 (rom_en),
        .addr               (rom_addr),
        .data               (rom_data)
    );

endmodule : axi4_slave_rom

`timescale 1ns / 1ps

//==============================================================================
// Module: axi4_slave_wr_crc_check
//==============================================================================
//
// Protocol handling: the AXI channel logic is the standard `axi4_slave_wr`
// protocol module (instantiated below), with the pattern / CRC logic on its
// fub_axi_* user interface. Remaining TODO (task #79): move to the
// monitored `axi4_slave_wr_mon` variant.
//
// Description:
//   AXI4 write-only slave that computes CRC-32 on received data for DMA
//   validation. Combines axi4_slave_wr protocol handler with CRC checker.
//
//   Per-channel mode (NUM_CHANNELS > 1): the slave maintains independent
//   CRC state per channel, demuxed off the low bits of the W-side wuser
//   (which the STREAM master drives with the burst's channel index). The
//   AW FSM accepts one burst at a time and W beats are in-order with AW,
//   so the channel captured with the AW is the active channel during W: the
//   low CIW bits of awid, or awaddr[CH_ADDR_LSB +: CIW] when CH_SEL_ADDR = 1.
//
// Per-channel outputs:
//   write_crc_value [NUM_CHANNELS][31:0] - per-channel CRC values
//   write_crc_valid [NUM_CHANNELS]       - per-channel valid flags
//   write_beat_count[NUM_CHANNELS][31:0] - per-channel beat counts
//
// Aggregate output (for harness timer):
//   write_beat_count_total [31:0]        - sum of per-channel beat counts
//
//==============================================================================

`include "reset_defs.svh"

module axi4_slave_wr_crc_check #(
    // AXI parameters
    parameter int NUM_CHANNELS  = 1,
    parameter int SKID_DEPTH_AW = 2,
    parameter int SKID_DEPTH_W  = 4,
    parameter int SKID_DEPTH_B  = 2,
    parameter int AXI_ID_WIDTH  = 8,
    parameter int AXI_ADDR_WIDTH = 32,
    parameter int AXI_DATA_WIDTH = 64,
    parameter int AXI_USER_WIDTH = 1,

    // CRC parameters (MUST MATCH axi4_slave_rd_injector!)
    parameter int CRC_WIDTH      = 32,
    parameter int CRC_DATA_WIDTH = 32,
    parameter logic [31:0] CRC_POLY    = 32'h04C11DB7,
    parameter logic [31:0] CRC_INIT    = 32'hFFFFFFFF,
    parameter logic [31:0] CRC_XOROUT  = 32'hFFFFFFFF,
    parameter int CRC_REFIN  = 1,
    parameter int CRC_REFOUT = 1,

    // Which 32-bit slice to CRC from AXI_DATA_WIDTH
    parameter int CRC_SLICE_OFFSET = 0,
    // BYTE_CRC=1 (byte-granular RAPIDS, rapids TASK-019): the per-channel CRC
    // runs over the STROBED bytes of every W beat in lane order, four per
    // cycle through cascade_sel, with wready held low while a beat is fed.
    // 0: the CRC_SLICE_OFFSET 32-bit slice of every beat (STREAM's harness).
    parameter bit BYTE_CRC = 1'b0,

    // Channel select. 0 (default): the channel is the low CIW bits of the
    // burst's ID (AR/AW), as every harness built so far drives it.
    // 1: the channel is the burst's address bits [CH_ADDR_LSB +: CIW] -- for a
    // fabric that does not carry the master's ID to its slaves (SmartConnect's
    // MI ID width is 0). Each channel then owns a 2^CH_ADDR_LSB-byte window;
    // the windows never overlap and a burst never crosses one (AXI bursts stop
    // at 4 KB, so CH_ADDR_LSB >= 12). CH_ADDR_LSB + CIW <= AXI_ADDR_WIDTH.
    parameter bit CH_SEL_ADDR = 1'b0,
    parameter int CH_ADDR_LSB = 16,

    // ERR_INJECT=1 (rapids TASK-020) builds the B-response error injector:
    // a chosen burst on a chosen channel answers cfg_err_resp instead of
    // OKAY, so a DUT's write-error path can be reached from a harness.
    // 0 (default) elaborates none of it and holds BRESP at OKAY -- the block
    // is then identical to its pre-TASK-020 behaviour, which is what
    // STREAM's and the RAPIDS-beats harnesses keep using.
    parameter bit ERR_INJECT = 1'b0,

    // Derived
    parameter int CIW = (NUM_CHANNELS > 1) ? $clog2(NUM_CHANNELS) : 1
) (
    // Global Clock and Reset
    input  logic                        aclk,
    input  logic                        aresetn,

    // Test Control
    input  logic                        crc_reset,

    // Per-channel CRC and Status Outputs
    output logic [NUM_CHANNELS-1:0][31:0] write_crc_value,
    output logic [NUM_CHANNELS-1:0]       write_crc_valid,
    output logic [NUM_CHANNELS-1:0][31:0] write_beat_count,
    // Aggregate beat count (sum across channels) for the harness stop trigger.
    output logic [31:0]                   write_beat_count_total,

    // AXI4 Slave Interface (Write-Only)
    // Write address channel (AW)
    input  logic [AXI_ID_WIDTH-1:0]     s_axi_awid,
    input  logic [AXI_ADDR_WIDTH-1:0]   s_axi_awaddr,
    input  logic [7:0]                  s_axi_awlen,
    input  logic [2:0]                  s_axi_awsize,
    input  logic [1:0]                  s_axi_awburst,
    input  logic                        s_axi_awlock,
    input  logic [3:0]                  s_axi_awcache,
    input  logic [2:0]                  s_axi_awprot,
    input  logic [3:0]                  s_axi_awqos,
    input  logic [3:0]                  s_axi_awregion,
    input  logic [AXI_USER_WIDTH-1:0]   s_axi_awuser,
    input  logic                        s_axi_awvalid,
    output logic                        s_axi_awready,

    // Write data channel (W)
    input  logic [AXI_DATA_WIDTH-1:0]   s_axi_wdata,
    input  logic [AXI_DATA_WIDTH/8-1:0] s_axi_wstrb,
    input  logic                        s_axi_wlast,
    input  logic [AXI_USER_WIDTH-1:0]   s_axi_wuser,
    input  logic                        s_axi_wvalid,
    output logic                        s_axi_wready,

    // Write response channel (B)
    output logic [AXI_ID_WIDTH-1:0]     s_axi_bid,
    output logic [1:0]                  s_axi_bresp,
    output logic [AXI_USER_WIDTH-1:0]   s_axi_buser,
    output logic                        s_axi_bvalid,
    input  logic                        s_axi_bready,

    // Error-response injection config (rapids TASK-020).
    // Inert unless ERR_INJECT=1; tie off at 0 otherwise.
    input  logic                        cfg_err_enable,
    input  logic [CIW-1:0]              cfg_err_channel,
    input  logic [15:0]                 cfg_err_skip,
    input  logic [1:0]                  cfg_err_resp,
    input  logic                        cfg_err_oneshot,
    output logic                        err_injected,

    // Status Output
    output logic                        busy
);

    //==========================================================================
    // Internal Signals - FUB (Functional Unit Backend) Interface
    //==========================================================================

    logic [AXI_ID_WIDTH-1:0]     fub_axi_awid;
    logic [AXI_ADDR_WIDTH-1:0]   fub_axi_awaddr;
    logic [7:0]                  fub_axi_awlen;
    logic [2:0]                  fub_axi_awsize;
    logic [1:0]                  fub_axi_awburst;
    logic                        fub_axi_awlock;
    logic [3:0]                  fub_axi_awcache;
    logic [2:0]                  fub_axi_awprot;
    logic [3:0]                  fub_axi_awqos;
    logic [3:0]                  fub_axi_awregion;
    logic [AXI_USER_WIDTH-1:0]   fub_axi_awuser;
    logic                        fub_axi_awvalid;
    logic                        fub_axi_awready;

    logic [AXI_DATA_WIDTH-1:0]   fub_axi_wdata;
    logic [AXI_DATA_WIDTH/8-1:0] fub_axi_wstrb;
    logic                        fub_axi_wlast;
    logic [AXI_USER_WIDTH-1:0]   fub_axi_wuser;
    logic                        fub_axi_wvalid;
    logic                        fub_axi_wready;

    logic [AXI_ID_WIDTH-1:0]     fub_axi_bid;
    logic [1:0]                  fub_axi_bresp;
    logic [AXI_USER_WIDTH-1:0]   fub_axi_buser;
    logic                        fub_axi_bvalid;
    logic                        fub_axi_bready;

    //==========================================================================
    // Boundary reset synchronization
    //==========================================================================
    // The port aresetn is treated as an asynchronous-assert input of unknown
    // deassert quality: an N=3 reset_sync produces the internal reset every
    // block below sees.
    logic w_aresetn;
    reset_sync #(
        .N             (3),
        .KEEP_ATTRS    (1'b1),
        .IN_ACTIVE_LOW (1'b1),
        .OUT_ACTIVE_LOW(1'b1),
        .ASYNC_ASSERT  (1'b1)
    ) u_reset_sync (
        .clk        (aclk),
        .rst_n      (aresetn),
        .sync_rst_n (w_aresetn)
    );

    //==========================================================================
    // Extract 32-bit Slice from AXI Data
    //==========================================================================

    logic [31:0] data_slice;

    generate
        if (AXI_DATA_WIDTH == 32) begin : gen_no_slice
            assign data_slice = fub_axi_wdata;
        end else begin : gen_slice
            localparam int SLICE_LSB = CRC_SLICE_OFFSET * 32;
            localparam int SLICE_MSB = SLICE_LSB + 31;

            initial begin
                if (SLICE_MSB >= AXI_DATA_WIDTH) begin
                    $error("CRC_SLICE_OFFSET=%0d out of range for AXI_DATA_WIDTH=%0d",
                           CRC_SLICE_OFFSET, AXI_DATA_WIDTH);
                end
            end

            assign data_slice = fub_axi_wdata[SLICE_MSB:SLICE_LSB];
        end
    endgenerate

    //==========================================================================
    // FUB burst state (declared early — used by per-channel CRC gating)
    //==========================================================================

    logic [AXI_ID_WIDTH-1:0]   r_wr_id;
    logic [AXI_USER_WIDTH-1:0] r_wr_user;
    logic                      r_wr_active;
    // B responses are queued in a small FIFO (see below): with 8 channels issuing
    // gapless back-to-back bursts (and a trailing 1-beat burst), two WLASTs can
    // land within the B-drain window. The old single r_b_pending bit dropped the
    // new B whenever a WLAST coincided with a B consume -> ~1 dropped B per
    // channel -> the DUT's write-commit counter stalled and the channel never
    // returned to idle. The module comment already called for a B FIFO here.

    // Active channel index for the in-flight burst (low bits of captured AW ID).
    // Channel of an AW at the handshake (CH_SEL_ADDR: from the ID or the
    // address), captured with the burst; the in-flight burst's channel.
    logic [CIW-1:0] w_aw_ch_sel;
    logic [CIW-1:0] r_wr_ch;
    assign w_aw_ch_sel = (NUM_CHANNELS == 1) ? '0
                       : CH_SEL_ADDR ? fub_axi_awaddr[CH_ADDR_LSB +: CIW]
                                     : fub_axi_awid[CIW-1:0];
    logic [CIW-1:0] w_active_ch;
    assign w_active_ch = r_wr_ch;

    // Single accepted-W-beat strobe; per-channel CRC instances gate on this.
    wire w_w_beat = fub_axi_wvalid && fub_axi_wready && r_wr_active;

    //==========================================================================
    // Byte-granular CRC feed (BYTE_CRC)
    //==========================================================================
    // The strobed bytes of an accepted W beat are shifted down to lane 0 and
    // fed to the burst's channel CRC four bytes per cycle (cascade_sel picks
    // 1..4), so the CRC is over the bytes written, in address order.
    logic                        r_bc_busy;
    logic [AXI_DATA_WIDTH-1:0]   r_bc_data;
    logic [7:0]                  r_bc_left;
    logic [CIW-1:0]              r_bc_ch;
    logic [7:0]                  w_strb_bytes;
    logic [7:0]                  w_first_lane;
    logic [7:0]                  w_bc_take;
    logic [3:0]                  w_bc_sel;
    always_comb begin
        w_strb_bytes = '0;
        w_first_lane = '0;
        for (int b = AXI_DATA_WIDTH/8 - 1; b >= 0; b--) begin
            w_strb_bytes = w_strb_bytes + 8'(fub_axi_wstrb[b]);
            if (fub_axi_wstrb[b]) w_first_lane = 8'(b);
        end
    end
    assign w_bc_take = (r_bc_left > 8'd4) ? 8'd4 : r_bc_left;
    assign w_bc_sel  = 4'(4'b0001 << (w_bc_take - 8'd1));
    `ALWAYS_FF_RST(aclk, w_aresetn,
        if (`RST_ASSERTED(w_aresetn)) begin
            r_bc_busy <= 1'b0;
            r_bc_data <= '0;
            r_bc_left <= '0;
            r_bc_ch   <= '0;
        end else if (BYTE_CRC) begin
            if (r_bc_busy) begin
                r_bc_data <= r_bc_data >> 32;
                r_bc_left <= r_bc_left - w_bc_take;
                if (r_bc_left <= 8'd4) r_bc_busy <= 1'b0;
            end else if (w_w_beat && (w_strb_bytes != 8'd0)) begin
                r_bc_busy <= 1'b1;
                r_bc_data <= fub_axi_wdata >> (w_first_lane * 8);
                r_bc_left <= w_strb_bytes;
                r_bc_ch   <= w_active_ch;
            end
        end
    )

    //==========================================================================
    // Per-channel CRC-32 Calculators + beat counters
    //==========================================================================

    logic [31:0] crc_out_per_ch [NUM_CHANNELS];

    genvar gch;
    generate
        for (gch = 0; gch < NUM_CHANNELS; gch++) begin : gen_crc
            logic ch_load_from_cascade;
            logic r_ch_crc_valid;
            logic [31:0] r_ch_beat_count;

            // CRC accumulates only when the active burst belongs to this channel
            assign ch_load_from_cascade = w_w_beat
                                       && (w_active_ch == gch[CIW-1:0]);

            dataint_crc #(
                .DATA_WIDTH(CRC_DATA_WIDTH),
                .CRC_WIDTH (CRC_WIDTH),
                .REFIN     (CRC_REFIN),
                .REFOUT    (CRC_REFOUT)
            ) u_crc (
                .POLY             (CRC_POLY),
                .POLY_INIT        (CRC_INIT),
                .XOROUT           (CRC_XOROUT),
                .clk              (aclk),
                .rst_n            (w_aresetn),
                .load_crc_start   (crc_reset),
                .load_from_cascade(BYTE_CRC ? (r_bc_busy && (r_bc_ch == gch[CIW-1:0])) : ch_load_from_cascade),
                .cascade_sel      (BYTE_CRC ? w_bc_sel : 4'b1000),
                .data             (BYTE_CRC ? r_bc_data[31:0] : data_slice),
                .crc              (crc_out_per_ch[gch])
            );

            `ALWAYS_FF_RST(aclk, w_aresetn,
                if (`RST_ASSERTED(w_aresetn)) begin
                    r_ch_crc_valid  <= 1'b0;
                    r_ch_beat_count <= '0;
                end else begin
                    if (crc_reset) begin
                        r_ch_crc_valid  <= 1'b0;
                        r_ch_beat_count <= '0;
                    end else if (ch_load_from_cascade) begin
                        r_ch_crc_valid  <= 1'b1;
                        r_ch_beat_count <= r_ch_beat_count + 1'b1;
                    end
                end
            )

            assign write_crc_value [gch] = crc_out_per_ch[gch];
            assign write_crc_valid [gch] = r_ch_crc_valid;
            assign write_beat_count[gch] = r_ch_beat_count;
        end
    endgenerate

    //==========================================================================
    // Aggregate beat count (sum across all channels) for the harness timer
    //==========================================================================

    always_comb begin
        write_beat_count_total = '0;
        for (int ch = 0; ch < NUM_CHANNELS; ch++) begin
            write_beat_count_total = write_beat_count_total + write_beat_count[ch];
        end
    end

    //==========================================================================
    // FUB Interface - Burst FSM for Write Acceptance
    //==========================================================================

    // Accept AW when idle, OR on the last W beat of the current burst so the
    // next burst's W beats follow with no dead cycle. The original (idle-only)
    // accept forced a 1-cycle !active gap between bursts (wready=0); once the
    // read slave feeds the SRAM gaplessly this would become the write-side
    // limiter (~1 starvation cycle per burst). Mirrors the read-slave fix.
    wire w_wr_last_beat = r_wr_active && fub_axi_wvalid && fub_axi_wready &&
                          fub_axi_wlast;
    assign fub_axi_awready = !r_wr_active || w_wr_last_beat;
    assign fub_axi_wready  = r_wr_active && !r_bc_busy;   // BYTE_CRC: hold W while a beat is fed
    // fub_axi_bresp is driven by the error injector below (OKAY when
    // ERR_INJECT=0, which is every build but the byte-RAPIDS harness).

    // B-response FIFO (inline, self-contained): push {user,id} of the completing
    // burst on every WLAST, pop on the B handshake. Holds multiple outstanding B's
    // so gapless multi-channel bursts never drop one (the single r_b_pending bit
    // did). Kept inline (no gaxi_fifo_sync dependency) so this shared test-infra
    // slave pulls no extra modules into any consumer's filelist.
    localparam int BFIFO_W     = AXI_USER_WIDTH + AXI_ID_WIDTH;
    localparam int BFIFO_DEPTH = 16;
    localparam int BFIFO_AW    = $clog2(BFIFO_DEPTH);

    logic [BFIFO_W-1:0] r_bfifo_mem [BFIFO_DEPTH];
    logic [BFIFO_AW-1:0] r_bfifo_wptr, r_bfifo_rptr;
    logic [BFIFO_AW:0]   r_bfifo_count;

    wire   w_bfifo_din_valid = w_wr_last_beat;             // push
    wire   w_bfifo_rd_valid  = (r_bfifo_count != '0);      // not empty
    wire   w_bfifo_pop       = w_bfifo_rd_valid && fub_axi_bready;
    wire [BFIFO_W-1:0] w_bfifo_din = {r_wr_user, r_wr_id};

    //==========================================================================
    // B-response error injection (rapids TASK-020)
    //==========================================================================
    // Counts completing bursts on cfg_err_channel while armed; the burst whose
    // index equals cfg_err_skip answers cfg_err_resp. One-shot disarms after
    // it, so a sequence can prove recovery on the next burst. The resp travels
    // WITH its burst through the B FIFO rather than being muxed onto whatever
    // B happens to be presented -- with several bursts outstanding those are
    // different things, and only the former is addressable from a test.
    generate
        if (ERR_INJECT) begin : gen_err_inject
            logic [15:0] r_err_count;
            logic        r_err_done;
            logic [1:0]  r_bfifo_resp [BFIFO_DEPTH];

            wire w_err_arm_ch = (NUM_CHANNELS == 1) ? 1'b1
                                                    : (w_active_ch == cfg_err_channel);
            wire w_err_hit    = cfg_err_enable && !r_err_done && w_err_arm_ch &&
                                (r_err_count == cfg_err_skip);

            assign fub_axi_bresp = r_bfifo_resp[r_bfifo_rptr];

            `ALWAYS_FF_RST(aclk, w_aresetn,
                if (`RST_ASSERTED(w_aresetn)) begin
                    r_err_count  <= '0;
                    r_err_done   <= 1'b0;
                    err_injected <= 1'b0;
                    for (int i = 0; i < BFIFO_DEPTH; i++) begin
                        r_bfifo_resp[i] <= 2'b00;
                    end
                end else begin
                    if (crc_reset || !cfg_err_enable) begin
                        r_err_count <= '0;
                        r_err_done  <= 1'b0;
                    end else if (w_wr_last_beat && w_err_arm_ch) begin
                        if (w_err_hit) begin
                            if (cfg_err_oneshot) r_err_done  <= 1'b1;
                            else                 r_err_count <= '0;
                        end else begin
                            r_err_count <= r_err_count + 16'd1;
                        end
                    end

                    if (crc_reset) begin
                        err_injected <= 1'b0;
                    end else if (w_wr_last_beat && w_err_hit) begin
                        err_injected <= 1'b1;
                    end

                    // Every completing burst pushes its own response code.
                    if (w_bfifo_din_valid) begin
                        r_bfifo_resp[r_bfifo_wptr] <= w_err_hit ? cfg_err_resp : 2'b00;
                    end
                end
            )
        end else begin : gen_no_err_inject
            assign fub_axi_bresp = 2'b00;  // OKAY
            assign err_injected  = 1'b0;
        end
    endgenerate

    assign fub_axi_bvalid = w_bfifo_rd_valid;
    assign {fub_axi_buser, fub_axi_bid} = r_bfifo_mem[r_bfifo_rptr];

    `ALWAYS_FF_RST(aclk, w_aresetn,
        if (`RST_ASSERTED(w_aresetn)) begin
            r_bfifo_wptr  <= '0;
            r_bfifo_rptr  <= '0;
            r_bfifo_count <= '0;
        end else begin
            if (w_bfifo_din_valid) begin
                r_bfifo_mem[r_bfifo_wptr] <= w_bfifo_din;
                r_bfifo_wptr <= r_bfifo_wptr + 1'b1;
            end
            if (w_bfifo_pop) begin
                r_bfifo_rptr <= r_bfifo_rptr + 1'b1;
            end
            case ({w_bfifo_din_valid, w_bfifo_pop})
                2'b10:   r_bfifo_count <= r_bfifo_count + 1'b1;
                2'b01:   r_bfifo_count <= r_bfifo_count - 1'b1;
                default: r_bfifo_count <= r_bfifo_count;
            endcase
        end
    )

    `ALWAYS_FF_RST(aclk, w_aresetn,
        if (`RST_ASSERTED(w_aresetn)) begin
            r_wr_active <= 1'b0;
            r_wr_id <= '0;
            r_wr_ch <= '0;
            r_wr_user <= '0;
        end else begin
            // AW acceptance — start a new burst from idle.
            if (fub_axi_awvalid && fub_axi_awready && !r_wr_active) begin
                r_wr_active <= 1'b1;
                r_wr_id <= fub_axi_awid;
                r_wr_ch <= w_aw_ch_sel;
                r_wr_user <= fub_axi_awuser;
            end

            // W last beat — complete the burst: its {user,id} is pushed to the B
            // FIFO (above) so no B is ever dropped; accept the next AW back-to-back
            // if one is waiting (stay active so wready never drops).
            if (w_wr_last_beat) begin
                if (fub_axi_awvalid) begin
                    r_wr_id   <= fub_axi_awid;
                    r_wr_ch   <= w_aw_ch_sel;
                    r_wr_user <= fub_axi_awuser;
                    // r_wr_active stays 1 -> gapless
                end else begin
                    r_wr_active <= 1'b0;
                end
            end
        end
    )

    //==========================================================================
    // AXI4 Slave Write Protocol Handler
    //==========================================================================

    axi4_slave_wr #(
        .SKID_DEPTH_AW      (SKID_DEPTH_AW),
        .SKID_DEPTH_W       (SKID_DEPTH_W),
        .SKID_DEPTH_B       (SKID_DEPTH_B),
        .AXI_ID_WIDTH       (AXI_ID_WIDTH),
        .AXI_ADDR_WIDTH     (AXI_ADDR_WIDTH),
        .AXI_DATA_WIDTH     (AXI_DATA_WIDTH),
        .AXI_USER_WIDTH     (AXI_USER_WIDTH)
    ) u_axi4_slave_wr (
        .aclk               (aclk),
        .aresetn            (w_aresetn),

        .s_axi_awid         (s_axi_awid),
        .s_axi_awaddr       (s_axi_awaddr),
        .s_axi_awlen        (s_axi_awlen),
        .s_axi_awsize       (s_axi_awsize),
        .s_axi_awburst      (s_axi_awburst),
        .s_axi_awlock       (s_axi_awlock),
        .s_axi_awcache      (s_axi_awcache),
        .s_axi_awprot       (s_axi_awprot),
        .s_axi_awqos        (s_axi_awqos),
        .s_axi_awregion     (s_axi_awregion),
        .s_axi_awuser       (s_axi_awuser),
        .s_axi_awvalid      (s_axi_awvalid),
        .s_axi_awready      (s_axi_awready),

        .s_axi_wdata        (s_axi_wdata),
        .s_axi_wstrb        (s_axi_wstrb),
        .s_axi_wlast        (s_axi_wlast),
        .s_axi_wuser        (s_axi_wuser),
        .s_axi_wvalid       (s_axi_wvalid),
        .s_axi_wready       (s_axi_wready),

        .s_axi_bid          (s_axi_bid),
        .s_axi_bresp        (s_axi_bresp),
        .s_axi_buser        (s_axi_buser),
        .s_axi_bvalid       (s_axi_bvalid),
        .s_axi_bready       (s_axi_bready),

        .fub_axi_awid       (fub_axi_awid),
        .fub_axi_awaddr     (fub_axi_awaddr),
        .fub_axi_awlen      (fub_axi_awlen),
        .fub_axi_awsize     (fub_axi_awsize),
        .fub_axi_awburst    (fub_axi_awburst),
        .fub_axi_awlock     (fub_axi_awlock),
        .fub_axi_awcache    (fub_axi_awcache),
        .fub_axi_awprot     (fub_axi_awprot),
        .fub_axi_awqos      (fub_axi_awqos),
        .fub_axi_awregion   (fub_axi_awregion),
        .fub_axi_awuser     (fub_axi_awuser),
        .fub_axi_awvalid    (fub_axi_awvalid),
        .fub_axi_awready    (fub_axi_awready),

        .fub_axi_wdata      (fub_axi_wdata),
        .fub_axi_wstrb      (fub_axi_wstrb),
        .fub_axi_wlast      (fub_axi_wlast),
        .fub_axi_wuser      (fub_axi_wuser),
        .fub_axi_wvalid     (fub_axi_wvalid),
        .fub_axi_wready     (fub_axi_wready),

        .fub_axi_bid        (fub_axi_bid),
        .fub_axi_bresp      (fub_axi_bresp),
        .fub_axi_buser      (fub_axi_buser),
        .fub_axi_bvalid     (fub_axi_bvalid),
        .fub_axi_bready     (fub_axi_bready),

        .busy               (busy)
    );

endmodule : axi4_slave_wr_crc_check

