//                              the transfers on the bus
//   SIDE_DEPTH               - core direction queue (>= CMD_DEPTH + RSP_DEPTH)
//   CLASSIC                  - 0 = B4 pipelined, 1 = B4 standard (classic)
//   RTY_RESP                 - AXI response for a Wishbone RTY (SLVERR)
//
//------------------------------------------------------------------------------
// Test:
//------------------------------------------------------------------------------
//   Location: projects/components/utility-ip/converters/dv/tests/test_axil4_to_wb4.py
//==============================================================================

`timescale 1ns / 1ps

module axil4_to_wb4 #(
    parameter int ADDR_WIDTH    = 32,
    parameter int DATA_WIDTH    = 32,
    parameter int SKID_DEPTH_AW = 2,
    parameter int SKID_DEPTH_W  = 2,
    parameter int SKID_DEPTH_B  = 2,
    parameter int SKID_DEPTH_AR = 2,
    parameter int SKID_DEPTH_R  = 2,
    parameter int CMD_DEPTH     = 4,
    parameter int RSP_DEPTH     = 4,
    parameter int SIDE_DEPTH    = 8,
    parameter int CLASSIC       = 0,
    parameter logic [1:0] RTY_RESP = 2'b10,
    // Short params
    parameter int AW = ADDR_WIDTH,
    parameter int DW = DATA_WIDTH,
    parameter int SW = DW/8
)
(
    input  logic              aclk,
    input  logic              aresetn,

    // AXI4-Lite slave
    input  logic [AW-1:0]     s_axil_awaddr,
    input  logic [2:0]        s_axil_awprot,
    input  logic              s_axil_awvalid,
    output logic              s_axil_awready,
    input  logic [DW-1:0]     s_axil_wdata,
    input  logic [SW-1:0]     s_axil_wstrb,
    input  logic              s_axil_wvalid,
    output logic              s_axil_wready,
    output logic [1:0]        s_axil_bresp,
    output logic              s_axil_bvalid,
    input  logic              s_axil_bready,
    input  logic [AW-1:0]     s_axil_araddr,
    input  logic [2:0]        s_axil_arprot,
    input  logic              s_axil_arvalid,
    output logic              s_axil_arready,
    output logic [DW-1:0]     s_axil_rdata,
    output logic [1:0]        s_axil_rresp,
    output logic              s_axil_rvalid,
    input  logic              s_axil_rready,

    // Wishbone B4 master
    output logic              m_wb_CYC,
    output logic              m_wb_STB,
    output logic              m_wb_WE,
    output logic [AW-1:0]     m_wb_ADR,
    output logic [DW-1:0]     m_wb_DAT_W,
    output logic [SW-1:0]     m_wb_SEL,
    output logic [wb4_pkg::WB4_CTI_WIDTH-1:0] m_wb_CTI,
    output logic [wb4_pkg::WB4_BTE_WIDTH-1:0] m_wb_BTE,
    input  logic              m_wb_STALL,
    input  logic              m_wb_ACK,
    input  logic              m_wb_ERR,
    input  logic              m_wb_RTY,
    input  logic [DW-1:0]     m_wb_DAT_R,

    output logic              busy
);

    //==========================================================================
    // Boundary reset synchronization
    //==========================================================================
    // Boundary reset synchronizer (block input reset is async-assert,
    // synchronized internally; complete closure)
    //
    // The port aresetn is treated as an asynchronous-assert input of unknown
    // deassert quality: an N=3 reset_sync (rtl/cdc, formally proven) produces
    // the internal reset every block below sees.
    logic w_aresetn;
    reset_sync #(
        .N             (3),
        .KEEP_ATTRS    (1'b1),
        .IN_ACTIVE_LOW (1'b1),
        .OUT_ACTIVE_LOW(1'b1),
        .ASYNC_ASSERT  (1'b1)
    ) u_reset_sync (
        .clk        (aclk),
        .rst_n      (aresetn),
        .sync_rst_n (w_aresetn)
    );

    // AXI4-Lite channels after the skids
    logic [AW-1:0] w_fub_awaddr, w_fub_araddr;
    logic [2:0]    w_fub_awprot, w_fub_arprot;
    logic          w_fub_awvalid, w_fub_awready, w_fub_wvalid, w_fub_wready;
    logic          w_fub_bvalid, w_fub_bready, w_fub_arvalid, w_fub_arready;
    logic          w_fub_rvalid, w_fub_rready;
    logic [DW-1:0] w_fub_wdata, w_fub_rdata;
    logic [SW-1:0] w_fub_wstrb;
    logic [1:0]    w_fub_bresp, w_fub_rresp;
    logic          w_busy_wr, w_busy_rd;

    // Command / response queues
    logic          w_cmd_valid, w_cmd_ready, w_cmd_we;
    logic [AW-1:0] w_cmd_adr;
    logic [DW-1:0] w_cmd_dat, w_rsp_dat;
    logic [SW-1:0] w_cmd_sel;
    logic          w_rsp_valid, w_rsp_ready;
    logic [1:0]    w_rsp_status;

    axil4_slave_wr #(
        .AXIL_ADDR_WIDTH (AW),
        .AXIL_DATA_WIDTH (DW),
        .SKID_DEPTH_AW   (SKID_DEPTH_AW),
        .SKID_DEPTH_W    (SKID_DEPTH_W),
        .SKID_DEPTH_B    (SKID_DEPTH_B)
    ) u_slave_wr (
        .aclk           (aclk),
        .aresetn        (w_aresetn),
        .s_axil_awaddr  (s_axil_awaddr),
        .s_axil_awprot  (s_axil_awprot),
        .s_axil_awvalid (s_axil_awvalid),
        .s_axil_awready (s_axil_awready),
        .s_axil_wdata   (s_axil_wdata),
        .s_axil_wstrb   (s_axil_wstrb),
        .s_axil_wvalid  (s_axil_wvalid),
        .s_axil_wready  (s_axil_wready),
        .s_axil_bresp   (s_axil_bresp),
        .s_axil_bvalid  (s_axil_bvalid),
        .s_axil_bready  (s_axil_bready),
        .fub_awaddr     (w_fub_awaddr),
        .fub_awprot     (w_fub_awprot),
        .fub_awvalid    (w_fub_awvalid),
        .fub_awready    (w_fub_awready),
        .fub_wdata      (w_fub_wdata),
        .fub_wstrb      (w_fub_wstrb),
        .fub_wvalid     (w_fub_wvalid),
        .fub_wready     (w_fub_wready),
        .fub_bresp      (w_fub_bresp),
        .fub_bvalid     (w_fub_bvalid),
        .fub_bready     (w_fub_bready),
        .busy           (w_busy_wr)
    );

    axil4_slave_rd #(
        .AXIL_ADDR_WIDTH (AW),
        .AXIL_DATA_WIDTH (DW),
        .SKID_DEPTH_AR   (SKID_DEPTH_AR),
        .SKID_DEPTH_R    (SKID_DEPTH_R)
    ) u_slave_rd (
        .aclk           (aclk),
        .aresetn        (w_aresetn),
        .s_axil_araddr  (s_axil_araddr),
        .s_axil_arprot  (s_axil_arprot),
        .s_axil_arvalid (s_axil_arvalid),
        .s_axil_arready (s_axil_arready),
        .s_axil_rdata   (s_axil_rdata),
        .s_axil_rresp   (s_axil_rresp),
        .s_axil_rvalid  (s_axil_rvalid),
        .s_axil_rready  (s_axil_rready),
        .fub_araddr     (w_fub_araddr),
        .fub_arprot     (w_fub_arprot),
        .fub_arvalid    (w_fub_arvalid),
        .fub_arready    (w_fub_arready),
        .fub_rdata      (w_fub_rdata),
        .fub_rresp      (w_fub_rresp),
        .fub_rvalid     (w_fub_rvalid),
        .fub_rready     (w_fub_rready),
        .busy           (w_busy_rd)
    );

    axil4_to_wb4_core #(
        .ADDR_WIDTH (AW),
        .DATA_WIDTH (DW),
        .SIDE_DEPTH (SIDE_DEPTH),
        .RTY_RESP   (RTY_RESP)
    ) u_core (
        .aclk        (aclk),
        .aresetn     (w_aresetn),
        .fub_awaddr  (w_fub_awaddr),
        .fub_awprot  (w_fub_awprot),
        .fub_awvalid (w_fub_awvalid),
        .fub_awready (w_fub_awready),
        .fub_wdata   (w_fub_wdata),
        .fub_wstrb   (w_fub_wstrb),
        .fub_wvalid  (w_fub_wvalid),
        .fub_wready  (w_fub_wready),
        .fub_bresp   (w_fub_bresp),
        .fub_bvalid  (w_fub_bvalid),
        .fub_bready  (w_fub_bready),
        .fub_araddr  (w_fub_araddr),
        .fub_arprot  (w_fub_arprot),
        .fub_arvalid (w_fub_arvalid),
        .fub_arready (w_fub_arready),
        .fub_rdata   (w_fub_rdata),
        .fub_rresp   (w_fub_rresp),
        .fub_rvalid  (w_fub_rvalid),
        .fub_rready  (w_fub_rready),
        .cmd_valid   (w_cmd_valid),
        .cmd_ready   (w_cmd_ready),
        .cmd_we      (w_cmd_we),
        .cmd_adr     (w_cmd_adr),
        .cmd_dat     (w_cmd_dat),
        .cmd_sel     (w_cmd_sel),
        .rsp_valid   (w_rsp_valid),
        .rsp_ready   (w_rsp_ready),
        .rsp_status  (w_rsp_status),
        .rsp_dat     (w_rsp_dat)
    );

    wb4_master #(
        .ADDR_WIDTH (AW),
        .DATA_WIDTH (DW),
        .CMD_DEPTH  (CMD_DEPTH),
        .RSP_DEPTH  (RSP_DEPTH),
        .CLASSIC    (CLASSIC)
    ) u_wb_master (
        .clk        (aclk),
        .aresetn    (w_aresetn),
        .m_wb_CYC   (m_wb_CYC),
        .m_wb_STB   (m_wb_STB),
        .m_wb_WE    (m_wb_WE),
        .m_wb_ADR   (m_wb_ADR),
        .m_wb_DAT_W (m_wb_DAT_W),
        .m_wb_SEL   (m_wb_SEL),
        .m_wb_CTI   (m_wb_CTI),
        .m_wb_BTE   (m_wb_BTE),
        .m_wb_STALL (m_wb_STALL),
        .m_wb_ACK   (m_wb_ACK),
        .m_wb_ERR   (m_wb_ERR),
        .m_wb_RTY   (m_wb_RTY),
        .m_wb_DAT_R (m_wb_DAT_R),
        .cmd_valid  (w_cmd_valid),
        .cmd_ready  (w_cmd_ready),
        .cmd_we     (w_cmd_we),
        .cmd_adr    (w_cmd_adr),
        .cmd_dat    (w_cmd_dat),
        .cmd_sel    (w_cmd_sel),
        // AXI4-Lite is single-beat and has no burst concept, so there is
        // nothing to map onto CTI/BTE. The master is left at its default
        // USE_BURST_HINTS=0, which drives CLASSIC/LINEAR on the wires.
        .cmd_cti    (wb4_pkg::WB4_CTI_WIDTH'(wb4_pkg::WB4_CTI_CLASSIC)),
        .cmd_bte    (wb4_pkg::WB4_BTE_WIDTH'(wb4_pkg::WB4_BTE_LINEAR)),
        .rsp_valid  (w_rsp_valid),
        .rsp_ready  (w_rsp_ready),
        .rsp_status (w_rsp_status),
        .rsp_dat    (w_rsp_dat)
    );

    assign busy = w_busy_wr || w_busy_rd || m_wb_CYC;

endmodule : axil4_to_wb4

// SPDX-License-Identifier: MIT
// SPDX-FileCopyrightText: 2026 sean galloway
//
// Module: axil_to_axi4_wide_align_rd
// Purpose: Drop-in replacement for axi4_dwidth_converter_rd when the
//          slave-side master is effectively AXIL (single-beat, narrow).
//
// Mirror of axil_to_axi4_wide_align_wr — for sub-row narrow reads
// from a wider slave, the wide R beat has the requested slot at byte
// offset (araddr & wide_mask)*8. The generic narrow→wide dnsize
// emits multiple narrow beats by beat counter, not the slot the
// master asked for. This module:
//   - Accepts one AXI4 single-beat narrow AR (awlen/awsize ignored).
//   - Emits one wide AXI4 single-beat AR at the row-aligned address.
//   - On the wide R beat, extracts the narrow slot via araddr's low
//     bits and returns it as the narrow R.

`timescale 1ns / 1ps

`include "reset_defs.svh"

module axil_to_axi4_wide_align_rd #(
    parameter int S_AXI_DATA_WIDTH  = 32,
    parameter int M_AXI_DATA_WIDTH  = 256,
    parameter int AXI_ID_WIDTH      = 8,
    parameter int AXI_ADDR_WIDTH    = 32,
    parameter int AXI_USER_WIDTH    = 1,
    parameter int SKID_DEPTH_AR     = 2,
    parameter int SKID_DEPTH_R      = 4
) (
    input  logic                                  aclk,
    input  logic                                  aresetn,

    // -------- AXI4 slave (from master via wrapper) --------
    input  logic [AXI_ID_WIDTH-1:0]               s_axi_arid,
    input  logic [AXI_ADDR_WIDTH-1:0]             s_axi_araddr,
    input  logic [7:0]                            s_axi_arlen,
    input  logic [2:0]                            s_axi_arsize,
    input  logic [1:0]                            s_axi_arburst,
    input  logic                                  s_axi_arlock,
    input  logic [3:0]                            s_axi_arcache,
    input  logic [2:0]                            s_axi_arprot,
    input  logic [3:0]                            s_axi_arqos,
    input  logic [3:0]                            s_axi_arregion,
    input  logic [AXI_USER_WIDTH-1:0]             s_axi_aruser,
    input  logic                                  s_axi_arvalid,
    output logic                                  s_axi_arready,

    output logic [AXI_ID_WIDTH-1:0]               s_axi_rid,
    output logic [S_AXI_DATA_WIDTH-1:0]           s_axi_rdata,
    output logic [1:0]                            s_axi_rresp,
    output logic                                  s_axi_rlast,
    output logic [AXI_USER_WIDTH-1:0]             s_axi_ruser,
    output logic                                  s_axi_rvalid,
    input  logic                                  s_axi_rready,

    // -------- AXI4 master (to crossbar / wide slave) --------
    output logic [AXI_ID_WIDTH-1:0]               m_axi_arid,
    output logic [AXI_ADDR_WIDTH-1:0]             m_axi_araddr,
    output logic [7:0]                            m_axi_arlen,
    output logic [2:0]                            m_axi_arsize,
    output logic [1:0]                            m_axi_arburst,
    output logic                                  m_axi_arlock,
    output logic [3:0]                            m_axi_arcache,
    output logic [2:0]                            m_axi_arprot,
    output logic [3:0]                            m_axi_arqos,
    output logic [3:0]                            m_axi_arregion,
    output logic [AXI_USER_WIDTH-1:0]             m_axi_aruser,
    output logic                                  m_axi_arvalid,
    input  logic                                  m_axi_arready,

    input  logic [AXI_ID_WIDTH-1:0]               m_axi_rid,
    input  logic [M_AXI_DATA_WIDTH-1:0]           m_axi_rdata,
    input  logic [1:0]                            m_axi_rresp,
    input  logic                                  m_axi_rlast,
    input  logic [AXI_USER_WIDTH-1:0]             m_axi_ruser,
    input  logic                                  m_axi_rvalid,
    output logic                                  m_axi_rready
);

    // Boundary reset synchronizer (block input reset is async-assert,
    // synchronized internally; complete closure)
    //
    // The port aresetn is treated as an asynchronous-assert input of unknown
    // deassert quality: an N=3 reset_sync (rtl/cdc, formally proven) produces
    // the internal reset every block below sees.
    logic w_aresetn;
    reset_sync #(
        .N             (3),
        .KEEP_ATTRS    (1'b1),
        .IN_ACTIVE_LOW (1'b1),
        .OUT_ACTIVE_LOW(1'b1),
        .ASYNC_ASSERT  (1'b1)
    ) u_reset_sync (
        .clk        (aclk),
        .rst_n      (aresetn),
        .sync_rst_n (w_aresetn)
    );

    localparam int M_STRB_W       = M_AXI_DATA_WIDTH / 8;
    localparam int S_STRB_W       = S_AXI_DATA_WIDTH / 8;
    localparam int RATIO          = M_AXI_DATA_WIDTH / S_AXI_DATA_WIDTH;
    localparam int SLOT_W         = $clog2(RATIO);
    localparam int ROW_LSB        = $clog2(M_STRB_W);
    localparam int SLOT_LSB       = $clog2(S_STRB_W);
    localparam int WIDE_SIZE_LOG2 = $clog2(M_STRB_W);

    // ----------------------------------------------------------------
    // 1-deep AR latch
    // ----------------------------------------------------------------
    logic [AXI_ID_WIDTH-1:0]      r_ar_id;
    logic [AXI_ADDR_WIDTH-1:0]    r_ar_addr;
    logic [2:0]                   r_ar_prot;
    logic [3:0]                   r_ar_cache;
    logic [AXI_USER_WIDTH-1:0]    r_ar_user;
    logic                         r_ar_full;
    logic                         consume_ar;

    assign s_axi_arready = !r_ar_full;

    `ALWAYS_FF_RST(aclk, w_aresetn,
        if (`RST_ASSERTED(w_aresetn)) begin
            r_ar_full  <= 1'b0;
            r_ar_id    <= '0;
            r_ar_addr  <= '0;
            r_ar_prot  <= '0;
            r_ar_cache <= '0;
            r_ar_user  <= '0;
        end else begin
            if (s_axi_arvalid && s_axi_arready) begin
                r_ar_full  <= 1'b1;
                r_ar_id    <= s_axi_arid;
                r_ar_addr  <= s_axi_araddr;
                r_ar_prot  <= s_axi_arprot;
                r_ar_cache <= s_axi_arcache;
                r_ar_user  <= s_axi_aruser;
            end else if (consume_ar) begin
                r_ar_full <= 1'b0;
            end
        end
    )

    // ----------------------------------------------------------------
    // Forwarder FSM
    //   IDLE → AR: latch ready → emit wide AR
    //   AR   → R:  m_axi_arvalid/arready done
    //   R    → S:  wide R captured → drive narrow R
    //   S    → IDLE: narrow R handshake completes
    // ----------------------------------------------------------------
    typedef enum logic [1:0] {
        S_IDLE = 2'd0,
        S_AR   = 2'd1,
        S_R    = 2'd2,
        S_S    = 2'd3
    } state_e;

    state_e r_state, w_next_state;

    always_comb begin
        w_next_state = r_state;
        consume_ar   = 1'b0;
        case (r_state)
            S_IDLE: if (r_ar_full) begin
                consume_ar   = 1'b1;
                w_next_state = S_AR;
            end
            S_AR: if (m_axi_arvalid && m_axi_arready) w_next_state = S_R;
            S_R:  if (m_axi_rvalid  && m_axi_rready)  w_next_state = S_S;
            S_S:  if (s_axi_rvalid  && s_axi_rready)  w_next_state = S_IDLE;
            default: w_next_state = S_IDLE;
        endcase
    end

    `ALWAYS_FF_RST(aclk, w_aresetn,
        if (`RST_ASSERTED(w_aresetn)) begin
            r_state <= S_IDLE;
        end else begin
            r_state <= w_next_state;
        end
    )

    // ----------------------------------------------------------------
    // Held AR + the wide R beat we just got back.
    // ----------------------------------------------------------------
    logic [AXI_ID_WIDTH-1:0]      r_held_id;
    logic [AXI_ADDR_WIDTH-1:0]    r_held_addr;
    logic [2:0]                   r_held_prot;
    logic [3:0]                   r_held_cache;
    logic [AXI_USER_WIDTH-1:0]    r_held_aruser;
    logic [M_AXI_DATA_WIDTH-1:0]  r_wide_rdata;
    logic [1:0]                   r_wide_rresp;
    logic [AXI_USER_WIDTH-1:0]    r_wide_ruser;

    `ALWAYS_FF_RST(aclk, w_aresetn,
        if (`RST_ASSERTED(w_aresetn)) begin
            r_held_id     <= '0;
            r_held_addr   <= '0;
            r_held_prot   <= '0;
            r_held_cache  <= '0;
            r_held_aruser <= '0;
            r_wide_rdata  <= '0;
            r_wide_rresp  <= 2'b00;
            r_wide_ruser  <= '0;
        end else begin
            if (consume_ar) begin
                r_held_id     <= r_ar_id;
                r_held_addr   <= r_ar_addr;
                r_held_prot   <= r_ar_prot;
                r_held_cache  <= r_ar_cache;
                r_held_aruser <= r_ar_user;
            end
            if (r_state == S_R && m_axi_rvalid && m_axi_rready) begin
                r_wide_rdata <= m_axi_rdata;
                r_wide_rresp <= m_axi_rresp;
                r_wide_ruser <= m_axi_ruser;
            end
        end
    )

    wire [SLOT_W-1:0]         held_slot = r_held_addr[SLOT_LSB +: SLOT_W];
    wire [AXI_ADDR_WIDTH-1:0] row_addr_mask =
        ~({{(AXI_ADDR_WIDTH-ROW_LSB){1'b0}}, {ROW_LSB{1'b1}}});

    // ----------------------------------------------------------------
    // Wide-side AXI4 master drives
    // ----------------------------------------------------------------
    assign m_axi_arid     = r_held_id;
    assign m_axi_araddr   = r_held_addr & row_addr_mask;
    assign m_axi_arlen    = 8'd0;
    assign m_axi_arsize   = WIDE_SIZE_LOG2[2:0];
    assign m_axi_arburst  = 2'b01;
    assign m_axi_arlock   = 1'b0;
    assign m_axi_arcache  = r_held_cache;
    assign m_axi_arprot   = r_held_prot;
    assign m_axi_arqos    = 4'b0;
    assign m_axi_arregion = 4'b0;
    assign m_axi_aruser   = r_held_aruser;
    assign m_axi_arvalid  = (r_state == S_AR);
    assign m_axi_rready   = (r_state == S_R);

    // ----------------------------------------------------------------
    // Narrow R: extract the slot from the wide R data.
    // ----------------------------------------------------------------
    assign s_axi_rid    = r_held_id;
    assign s_axi_rdata  = r_wide_rdata[held_slot * S_AXI_DATA_WIDTH
                                       +: S_AXI_DATA_WIDTH];
    assign s_axi_rresp  = r_wide_rresp;
    assign s_axi_rlast  = (r_state == S_S);   // single beat → last on the only beat
    assign s_axi_ruser  = r_wide_ruser;
    assign s_axi_rvalid = (r_state == S_S);

    /* verilator lint_off UNUSED */
    wire _unused = &{1'b0, s_axi_arlen, s_axi_arsize, s_axi_arburst,
                     s_axi_arlock, s_axi_arqos, s_axi_arregion,
                     m_axi_rid, m_axi_rlast,
                     SKID_DEPTH_AR, SKID_DEPTH_R};
    /* verilator lint_on UNUSED */

endmodule : axil_to_axi4_wide_align_rd

// SPDX-License-Identifier: MIT
// SPDX-FileCopyrightText: 2026 sean galloway
//
// Module: axil_to_axi4_wide_align_wr
// Purpose: Drop-in replacement for axi4_dwidth_converter_wr when the
//          slave-side master is effectively AXIL (single-beat, narrow).
//
// Why this exists:
//   The narrow→wide upsize converter `axi_data_upsize` aggregates N
//   narrow beats into one wide beat by beat counter. For an AXIL
//   master (every transfer is single-beat at a sub-row address),
//   every beat lands at lane 0 of the wide bus regardless of awaddr.
//   The bridge generator wraps AXIL masters with `axi4_slave_wr`
//   which presents fub_axi_* with awlen=0/awsize=narrow/awburst=01 —
//   and this module replaces the buggy upsize in that path.
//
//   Per AXI4 spec for single-beat narrow writes on a wide bus:
//     - awaddr's low bits identify the byte offset within the wide row
//     - wstrb[b]=1 enables wdata[8*b +: 8] (byte lane b carries data)
//   So the master is responsible for placing its narrow data and
//   strobes at the correct byte lanes. This module does that
//   master-side alignment.
//
// Interface: AXI4 slave (matches axi4_dwidth_converter_wr's slave
// port) on the master-side; emits a single-beat wide AXI4 write.
// awlen/awsize on the slave side are ignored (always treated as
// single-beat narrow → single-beat wide aligned).

`timescale 1ns / 1ps

`include "reset_defs.svh"

module axil_to_axi4_wide_align_wr #(
    parameter int S_AXI_DATA_WIDTH  = 32,
    parameter int M_AXI_DATA_WIDTH  = 256,
    parameter int AXI_ID_WIDTH      = 8,
    parameter int AXI_ADDR_WIDTH    = 32,
    parameter int AXI_USER_WIDTH    = 1,
    parameter int SKID_DEPTH_AW     = 2,   // accepted for API parity
    parameter int SKID_DEPTH_W      = 2,
    parameter int SKID_DEPTH_B      = 2
) (
    input  logic                                  aclk,
    input  logic                                  aresetn,

    // -------- AXI4 slave (from master via wrapper) --------
    input  logic [AXI_ID_WIDTH-1:0]               s_axi_awid,
    input  logic [AXI_ADDR_WIDTH-1:0]             s_axi_awaddr,
    input  logic [7:0]                            s_axi_awlen,
    input  logic [2:0]                            s_axi_awsize,
    input  logic [1:0]                            s_axi_awburst,
    input  logic                                  s_axi_awlock,
    input  logic [3:0]                            s_axi_awcache,
    input  logic [2:0]                            s_axi_awprot,
    input  logic [3:0]                            s_axi_awqos,
    input  logic [3:0]                            s_axi_awregion,
    input  logic [AXI_USER_WIDTH-1:0]             s_axi_awuser,
    input  logic                                  s_axi_awvalid,
    output logic                                  s_axi_awready,

    input  logic [S_AXI_DATA_WIDTH-1:0]           s_axi_wdata,
    input  logic [S_AXI_DATA_WIDTH/8-1:0]         s_axi_wstrb,
    input  logic                                  s_axi_wlast,
    input  logic [AXI_USER_WIDTH-1:0]             s_axi_wuser,
    input  logic                                  s_axi_wvalid,
    output logic                                  s_axi_wready,

    output logic [AXI_ID_WIDTH-1:0]               s_axi_bid,
    output logic [1:0]                            s_axi_bresp,
    output logic [AXI_USER_WIDTH-1:0]             s_axi_buser,
    output logic                                  s_axi_bvalid,
    input  logic                                  s_axi_bready,

    // -------- AXI4 master (to crossbar / wide slave) --------
    output logic [AXI_ID_WIDTH-1:0]               m_axi_awid,
    output logic [AXI_ADDR_WIDTH-1:0]             m_axi_awaddr,
    output logic [7:0]                            m_axi_awlen,
    output logic [2:0]                            m_axi_awsize,
    output logic [1:0]                            m_axi_awburst,
    output logic                                  m_axi_awlock,
    output logic [3:0]                            m_axi_awcache,
    output logic [2:0]                            m_axi_awprot,
    output logic [3:0]                            m_axi_awqos,
    output logic [3:0]                            m_axi_awregion,
    output logic [AXI_USER_WIDTH-1:0]             m_axi_awuser,
    output logic                                  m_axi_awvalid,
    input  logic                                  m_axi_awready,

    output logic [M_AXI_DATA_WIDTH-1:0]           m_axi_wdata,
    output logic [M_AXI_DATA_WIDTH/8-1:0]         m_axi_wstrb,
    output logic                                  m_axi_wlast,
    output logic [AXI_USER_WIDTH-1:0]             m_axi_wuser,
    output logic                                  m_axi_wvalid,
    input  logic                                  m_axi_wready,

    input  logic [AXI_ID_WIDTH-1:0]               m_axi_bid,
    input  logic [1:0]                            m_axi_bresp,
    input  logic [AXI_USER_WIDTH-1:0]             m_axi_buser,
    input  logic                                  m_axi_bvalid,
    output logic                                  m_axi_bready
);

    // Boundary reset synchronizer (block input reset is async-assert,
    // synchronized internally; complete closure)
    //
    // The port aresetn is treated as an asynchronous-assert input of unknown
    // deassert quality: an N=3 reset_sync (rtl/cdc, formally proven) produces
    // the internal reset every block below sees.
    logic w_aresetn;
    reset_sync #(
        .N             (3),
        .KEEP_ATTRS    (1'b1),
        .IN_ACTIVE_LOW (1'b1),
        .OUT_ACTIVE_LOW(1'b1),
        .ASYNC_ASSERT  (1'b1)
    ) u_reset_sync (
        .clk        (aclk),
        .rst_n      (aresetn),
        .sync_rst_n (w_aresetn)
    );

    localparam int M_STRB_W       = M_AXI_DATA_WIDTH / 8;
    localparam int S_STRB_W       = S_AXI_DATA_WIDTH / 8;
    localparam int RATIO          = M_AXI_DATA_WIDTH / S_AXI_DATA_WIDTH;
    localparam int SLOT_W         = $clog2(RATIO);
    localparam int ROW_LSB        = $clog2(M_STRB_W);
    localparam int SLOT_LSB       = $clog2(S_STRB_W);
    localparam int WIDE_SIZE_LOG2 = $clog2(M_STRB_W);

    // ----------------------------------------------------------------
    // 1-deep independent AW and W latches.
    // ----------------------------------------------------------------
    logic [AXI_ID_WIDTH-1:0]       r_aw_id;
    logic [AXI_ADDR_WIDTH-1:0]     r_aw_addr;
    logic [2:0]                    r_aw_prot;
    logic [3:0]                    r_aw_cache;
    logic [AXI_USER_WIDTH-1:0]     r_aw_user;
    logic                          r_aw_full;
    logic [S_AXI_DATA_WIDTH-1:0]   r_w_data;
    logic [S_STRB_W-1:0]           r_w_strb;
    logic [AXI_USER_WIDTH-1:0]     r_w_user;
    logic                          r_w_full;

    logic consume_beat;
    wire  beat_pair_ready = r_aw_full && r_w_full;

    assign s_axi_awready = !r_aw_full;
    assign s_axi_wready  = !r_w_full;

    `ALWAYS_FF_RST(aclk, w_aresetn,
        if (`RST_ASSERTED(w_aresetn)) begin
            r_aw_full  <= 1'b0;
            r_aw_id    <= '0;
            r_aw_addr  <= '0;
            r_aw_prot  <= '0;
            r_aw_cache <= '0;
            r_aw_user  <= '0;
            r_w_full   <= 1'b0;
            r_w_data   <= '0;
            r_w_strb   <= '0;
            r_w_user   <= '0;
        end else begin
            if (s_axi_awvalid && s_axi_awready) begin
                r_aw_full  <= 1'b1;
                r_aw_id    <= s_axi_awid;
                r_aw_addr  <= s_axi_awaddr;
                r_aw_prot  <= s_axi_awprot;
                r_aw_cache <= s_axi_awcache;
                r_aw_user  <= s_axi_awuser;
            end else if (consume_beat) begin
                r_aw_full <= 1'b0;
            end

            if (s_axi_wvalid && s_axi_wready) begin
                r_w_full <= 1'b1;
                r_w_data <= s_axi_wdata;
                r_w_strb <= s_axi_wstrb;
                r_w_user <= s_axi_wuser;
            end else if (consume_beat) begin
                r_w_full <= 1'b0;
            end
        end
    )

    // ----------------------------------------------------------------
    // Forwarder FSM
    // ----------------------------------------------------------------
    // S_REQ presents AW and W TOGETHER and leaves once both have handshaken,
    // in either order or in one cycle. A3.3.1: a manager must not wait for
    // AWREADY before asserting WVALID, because a slave may wait for WVALID
    // before asserting AWREADY. This FSM used to be S_AW then S_W -- W only
    // after the AW handshake -- which deadlocked against such a slave (found
    // by the Genesys 2 bridge stress model's w_first profile on
    // bridge_bs_mixed_b: every AXI-Lite / WB4 master writing to a wider
    // slave, and every other master's writes behind it).
    typedef enum logic [1:0] {
        S_IDLE = 2'd0,
        S_REQ  = 2'd1,
        S_B    = 2'd3
    } state_e;

    state_e r_state, w_next_state;
    logic   r_aw_done, r_w_done;     // this beat's AW / W already taken
    logic   w_aw_now, w_w_now;
    assign w_aw_now = r_aw_done || (m_axi_awvalid && m_axi_awready);
    assign w_w_now  = r_w_done  || (m_axi_wvalid  && m_axi_wready);

    always_comb begin
        w_next_state = r_state;
        consume_beat = 1'b0;
        case (r_state)
            S_IDLE: if (beat_pair_ready) begin
                consume_beat = 1'b1;
                w_next_state = S_REQ;
            end
            S_REQ: if (w_aw_now && w_w_now) w_next_state = S_B;
            S_B:  if (m_axi_bvalid  && m_axi_bready)  w_next_state = S_IDLE;
            default: w_next_state = S_IDLE;
        endcase
    end

    `ALWAYS_FF_RST(aclk, w_aresetn,
        if (`RST_ASSERTED(w_aresetn)) begin
            r_state   <= S_IDLE;
            r_aw_done <= 1'b0;
            r_w_done  <= 1'b0;
        end else begin
            r_state <= w_next_state;
            if (r_state != S_REQ || w_next_state != S_REQ) begin
                r_aw_done <= 1'b0;          // a new beat starts with neither taken
                r_w_done  <= 1'b0;
            end else begin
                if (m_axi_awvalid && m_axi_awready) r_aw_done <= 1'b1;
                if (m_axi_wvalid  && m_axi_wready)  r_w_done  <= 1'b1;
            end
        end
    )

    // ----------------------------------------------------------------
    // Held (matched) beat — drives m_axi_* through multi-cycle handshakes.
    // ----------------------------------------------------------------
    logic [AXI_ID_WIDTH-1:0]     r_held_id;
    logic [AXI_ADDR_WIDTH-1:0]   r_held_addr;
    logic [2:0]                  r_held_prot;
    logic [3:0]                  r_held_cache;
    logic [AXI_USER_WIDTH-1:0]   r_held_awuser;
    logic [S_AXI_DATA_WIDTH-1:0] r_held_data;
    logic [S_STRB_W-1:0]         r_held_strb;
    logic [AXI_USER_WIDTH-1:0]   r_held_wuser;

    `ALWAYS_FF_RST(aclk, w_aresetn,
        if (`RST_ASSERTED(w_aresetn)) begin
            r_held_id     <= '0;
            r_held_addr   <= '0;
            r_held_prot   <= '0;
            r_held_cache  <= '0;
            r_held_awuser <= '0;
            r_held_data   <= '0;
            r_held_strb   <= '0;
            r_held_wuser  <= '0;
        end else if (consume_beat) begin
            r_held_id     <= r_aw_id;
            r_held_addr   <= r_aw_addr;
            r_held_prot   <= r_aw_prot;
            r_held_cache  <= r_aw_cache;
            r_held_awuser <= r_aw_user;
            r_held_data   <= r_w_data;
            r_held_strb   <= r_w_strb;
            r_held_wuser  <= r_w_user;
        end
    )

    // ----------------------------------------------------------------
    // Alignment — slot = held_addr[SLOT_LSB +: SLOT_W]
    //   m_axi_wdata: place S_AXI_DATA_WIDTH bits at slot*S_AXI_DATA_WIDTH
    //   m_axi_wstrb: place S_STRB_W bits at slot*S_STRB_W
    //   m_axi_awaddr: row-aligned (addr & ~(M_STRB_W-1))
    // ----------------------------------------------------------------
    wire [SLOT_W-1:0]         held_slot = r_held_addr[SLOT_LSB +: SLOT_W];
    wire [AXI_ADDR_WIDTH-1:0] row_addr_mask =
        ~({{(AXI_ADDR_WIDTH-ROW_LSB){1'b0}}, {ROW_LSB{1'b1}}});

    logic [M_AXI_DATA_WIDTH-1:0] aligned_wdata;
    logic [M_STRB_W-1:0]         aligned_wstrb;
    always_comb begin
        aligned_wdata = '0;
        aligned_wstrb = '0;
        aligned_wdata[held_slot * S_AXI_DATA_WIDTH +: S_AXI_DATA_WIDTH]
            = r_held_data;
        aligned_wstrb[held_slot * S_STRB_W +: S_STRB_W]
            = r_held_strb;
    end

    // ----------------------------------------------------------------
    // Wide-side master drives
    // ----------------------------------------------------------------
    assign m_axi_awid     = r_held_id;
    assign m_axi_awaddr   = r_held_addr & row_addr_mask;
    assign m_axi_awlen    = 8'd0;                       // single beat
    assign m_axi_awsize   = WIDE_SIZE_LOG2[2:0];
    assign m_axi_awburst  = 2'b01;                      // INCR
    assign m_axi_awlock   = 1'b0;
    assign m_axi_awcache  = r_held_cache;
    assign m_axi_awprot   = r_held_prot;
    assign m_axi_awqos    = 4'b0;
    assign m_axi_awregion = 4'b0;
    assign m_axi_awuser   = r_held_awuser;
    assign m_axi_awvalid  = (r_state == S_REQ) && !r_aw_done;
    assign m_axi_wdata    = aligned_wdata;
    assign m_axi_wstrb    = aligned_wstrb;
    assign m_axi_wlast    = 1'b1;
    assign m_axi_wuser    = r_held_wuser;
    assign m_axi_wvalid   = (r_state == S_REQ) && !r_w_done;
    // m_axi_bready: below, with the B register it guards.

    // ----------------------------------------------------------------
    // B response back to slave-side. Forward bid/bresp/buser.
    // ----------------------------------------------------------------
    logic                       r_s_bvalid;
    logic [AXI_ID_WIDTH-1:0]    r_s_bid;
    logic [1:0]                 r_s_bresp;
    logic [AXI_USER_WIDTH-1:0]  r_s_buser;
    `ALWAYS_FF_RST(aclk, w_aresetn,
        if (`RST_ASSERTED(w_aresetn)) begin
            r_s_bvalid <= 1'b0;
            r_s_bid    <= '0;
            r_s_bresp  <= 2'b00;
            r_s_buser  <= '0;
        end else begin
            if (r_state == S_B && m_axi_bvalid && m_axi_bready) begin
                r_s_bvalid <= 1'b1;
                r_s_bid    <= m_axi_bid;
                r_s_bresp  <= m_axi_bresp;
                r_s_buser  <= m_axi_buser;
            end else if (r_s_bvalid && s_axi_bready) begin
                r_s_bvalid <= 1'b0;
            end
        end
    )
    // The FSM returns to S_IDLE without waiting for the master to take this
    // B, so the next write can reach S_B while it is still held. Take a new
    // B only when the register is empty or drains this cycle; taking it
    // unconditionally overwrote the held one and lost that response (bridge
    // BUG-025).
    assign m_axi_bready = (r_state == S_B) && (!r_s_bvalid || s_axi_bready);

    assign s_axi_bvalid = r_s_bvalid;
    assign s_axi_bid    = r_s_bid;
    assign s_axi_bresp  = r_s_bresp;
    assign s_axi_buser  = r_s_buser;

    /* verilator lint_off UNUSED */
    wire _unused = &{1'b0, s_axi_awlen, s_axi_awsize, s_axi_awburst,
                     s_axi_awlock, s_axi_awqos, s_axi_awregion,
                     s_axi_wlast,
                     SKID_DEPTH_AW, SKID_DEPTH_W, SKID_DEPTH_B};
    /* verilator lint_on UNUSED */

endmodule : axil_to_axi4_wide_align_wr

// SPDX-License-Identifier: MIT
// SPDX-FileCopyrightText: 2024-2025 sean galloway
//
// RTL Design Sherpa - Industry-Standard RTL Design and Verification
// https://github.com/sean-galloway/RTLDesignSherpa
//
// Module: axis4_master_injector
// Purpose: AXI-Stream master that emits a deterministic, PER-CHANNEL LFSR data
//          pattern for characterization/verification. This is the AXIS SINK
//          stimulus for the RAPIDS characterization harness and is
//          pattern/CRC-CONSISTENT with axi4_slave_rd_injector /
//          axi4_slave_wr_crc_check: the per-channel 32-bit CRC-32 it computes
//          is bit-identical to what axi4_slave_wr_crc_check produces for the
//          same emitted stream (sink self-check: axis_gen -> m_axi_wr ->
//          wr_crc_check).
//
// Description:
//   On cfg_start the block streams cfg_num_beats beats PER CHANNEL for every
//   channel selected in cfg_channel_mask (mask == 0 => all NUM_CHANNELS active),
//   scheduled sequentially (finish one channel, then the next) so each
//   channel's LFSR sequence is contiguous -- or, with cfg_interleave set,
//   round-robin beat by beat across the active channels so every active
//   channel holds data in the DUT at once (the aggregate-window case). Each
//   channel N maintains an
//   independent LFSR seeded (seed ^ N) -- IDENTICAL to axi4_slave_rd_injector
//   -- and its own dataint_crc-32 instance. Each beat:
//     - m_axis_tid   = channel index
//     - m_axis_tdata = {REP{lfsr_out[ch]}}  (32-bit LFSR replicated to fill bus)
//     - the active channel's LFSR + CRC advance on the accepted beat only
//     - tlast asserted every cfg_beats_per_pkt beats (0 => tlast on each
//       channel's final beat only), and always on each channel's final beat.
//   Because the LFSR advances only on accepted beats, beat N of channel C is a
//   deterministic function of (seed ^ C, N), independent of tready stalls and
//   of the scheduling mode: the per-channel data, CRC and packet boundaries
//   are identical in sequential and interleaved runs; only the order in which
//   channels take the bus differs.
//
//   The per-channel expected CRC is exported continuously (o_expected_crc[ch],
//   o_expected_crc_valid[ch]) mirroring axi4_slave_rd_injector's
//   read_crc_value / read_crc_valid semantics -- NOT the old XOR-fold signature.
//
// CRC bit-consistency (copied VERBATIM from the axi4 blocks):
//   - shifter_lfsr_fibonacci #(WIDTH=32, TAP_INDEX_WIDTH=12, TAP_COUNT=4),
//     seed_data = (seed ^ ch), enable = (accepted-beat-for-ch || load),
//     seed_load = load.
//   - dataint_crc #(DATA_WIDTH=32, CRC_WIDTH=32, REFIN=1, REFOUT=1) with
//     POLY=0x04C11DB7, POLY_INIT=0xFFFFFFFF, XOROUT=0xFFFFFFFF,
//     cascade_sel=4'b1000, data=lfsr_out[ch], load_crc_start=load,
//     load_from_cascade=accepted-beat-for-ch.
//
// Notes:
//   - AXIS_DATA_WIDTH must be a multiple of LFSR_WIDTH (tdata = REP x lfsr_out).
//   - No address channel (pure stream): simpler than the AXI4 pattern gen.
//
// Documentation: vault/tracking/projects/components/dma-ip/rapids/CONTROL_ENGINE_INTEGRATION.md (harness)
// Subsystem: amba/shared

`timescale 1ns / 1ps

`include "reset_defs.svh"

module axis4_master_injector #(
    parameter int          NUM_CHANNELS     = 1,
    parameter int          AXIS_DATA_WIDTH  = 512,
    parameter int          AXIS_ID_WIDTH    = 8,
    parameter int          AXIS_DEST_WIDTH  = 4,
    parameter int          AXIS_USER_WIDTH  = 1,

    // LFSR parameters (32-bit fixed; MUST MATCH axi4_slave_rd_injector!)
    parameter int          LFSR_WIDTH       = 32,
    parameter logic [31:0] LFSR_SEED        = 32'hDEADBEEF,
    parameter logic [47:0] LFSR_TAPS        = {12'd23, 12'd3, 12'd2, 12'd1},

    // CRC parameters (fixed; MUST MATCH axi4_slave_rd_injector /
    // axi4_slave_wr_crc_check!)
    parameter int          CRC_WIDTH        = 32,
    parameter int          CRC_DATA_WIDTH   = 32,   // process 32-bit LFSR output only
    parameter logic [31:0] CRC_POLY         = 32'h04C11DB7,  // CRC-32 Ethernet
    parameter logic [31:0] CRC_INIT         = 32'hFFFFFFFF,
    parameter logic [31:0] CRC_XOROUT       = 32'hFFFFFFFF,
    parameter int          CRC_REFIN        = 1,
    parameter int          CRC_REFOUT       = 1,

    parameter int          BEAT_COUNT_WIDTH = 32,
    // Derived
    parameter int          STRB_WIDTH       = AXIS_DATA_WIDTH / 8,
    parameter int          REP              = AXIS_DATA_WIDTH / LFSR_WIDTH,
    parameter int          CIW              = (NUM_CHANNELS > 1) ? $clog2(NUM_CHANNELS) : 1
) (
    input  logic                          clk,
    input  logic                          rst_n,

    // Configuration / control
    input  logic                          cfg_start,          // pulse: begin a run
    input  logic [LFSR_WIDTH-1:0]         cfg_lfsr_seed,      // 0 => use LFSR_SEED param
    input  logic [NUM_CHANNELS-1:0]       cfg_channel_mask,   // active channels (0 => all)
    input  logic [BEAT_COUNT_WIDTH-1:0]   cfg_num_beats,      // beats to send PER CHANNEL
    input  logic [BEAT_COUNT_WIDTH-1:0]   cfg_beats_per_pkt,  // tlast cadence (0 => 1 pkt/channel)
    input  logic                          cfg_interleave,     // 1: round-robin active channels per beat
    input  logic [AXIS_DEST_WIDTH-1:0]    cfg_tdest,
    // Byte-granular packets (rapids TASK-019): bytes strobed on every tlast
    // beat, contiguous from lane 0. 0 (or >= STRB_WIDTH) keeps every lane,
    // which is the beat-granular behaviour.
    input  logic [7:0]                    cfg_last_bytes,
    output logic                          cfg_busy,
    output logic                          cfg_done,           // 1-cycle pulse at end of run

    // Per-channel expected CRC (mirrors axi4_slave_rd_injector.read_crc_value)
    output logic [NUM_CHANNELS-1:0][31:0] o_expected_crc,
    output logic [NUM_CHANNELS-1:0]       o_expected_crc_valid,
    output logic [NUM_CHANNELS-1:0][31:0] o_beat_count,       // per-channel beats emitted
    output logic [31:0]                   o_beat_count_total, // sum across channels

    // AXI-Stream master
    output logic                          m_axis_tvalid,
    input  logic                          m_axis_tready,
    output logic [AXIS_DATA_WIDTH-1:0]    m_axis_tdata,
    output logic [STRB_WIDTH-1:0]         m_axis_tstrb,
    output logic                          m_axis_tlast,
    output logic [AXIS_ID_WIDTH-1:0]      m_axis_tid,
    output logic [AXIS_DEST_WIDTH-1:0]    m_axis_tdest,
    output logic [AXIS_USER_WIDTH-1:0]    m_axis_tuser
);

    localparam int LFSR_TAP_INDEX_WIDTH = 12;
    localparam int LFSR_TAP_COUNT       = 4;

    typedef enum logic [1:0] { IDLE, RUN, DONE } state_t;
    state_t r_state;

    logic [CIW-1:0]              r_ch;               // channel currently streaming
    logic [BEAT_COUNT_WIDTH-1:0] r_beats_remaining;  // beats left for current channel (sequential)
                                                     // or rounds left (interleaved)
    logic [BEAT_COUNT_WIDTH-1:0] r_pkt_cnt;          // tlast cadence counter (per channel; in the
                                                     // interleaved mode every channel shares it)
    logic [NUM_CHANNELS-1:0]     r_channel_mask;     // latched active-channel mask
    logic [BEAT_COUNT_WIDTH-1:0] r_num_beats;        // latched beats-per-channel
    logic [BEAT_COUNT_WIDTH-1:0] r_beats_per_pkt;    // latched tlast cadence
    logic [7:0]                  r_last_bytes;       // latched tlast strobe count (0 = all)
    logic                        r_interleave;       // latched scheduling mode

    logic                        w_load;
    logic                        w_beat;
    logic                        w_ch_last_beat;
    logic                        w_pkt_last;
    logic [LFSR_WIDTH-1:0]       w_seed;
    logic [LFSR_WIDTH-1:0]       w_active_lfsr;

    logic [31:0] lfsr_out_per_ch [NUM_CHANNELS];
    logic [31:0] crc_out_per_ch  [NUM_CHANNELS];

    //==========================================================================
    // Boundary reset synchronization
    //==========================================================================
    // The port rst_n is treated as an asynchronous-assert input of unknown
    // deassert quality: an N=3 reset_sync produces the internal reset every
    // block below sees.
    logic w_rst_n;
    reset_sync #(
        .N             (3),
        .KEEP_ATTRS    (1'b1),
        .IN_ACTIVE_LOW (1'b1),
        .OUT_ACTIVE_LOW(1'b1),
        .ASYNC_ASSERT  (1'b1)
    ) u_reset_sync (
        .clk        (clk),
        .rst_n      (rst_n),
        .sync_rst_n (w_rst_n)
    );

    assign w_load = (r_state == IDLE) && cfg_start;
    assign w_seed = (cfg_lfsr_seed == '0) ? LFSR_SEED[LFSR_WIDTH-1:0] : cfg_lfsr_seed;
    assign w_beat = m_axis_tvalid && m_axis_tready;

    //==========================================================================
    // Next-active-channel search (sequential per-channel scheduling)
    //==========================================================================
    // Returns {found, idx} for the lowest active (masked) channel index strictly
    // greater than after_idx. after_idx = -1 => first active channel.

    function automatic logic [CIW:0] f_next_active_after(
        input logic [NUM_CHANNELS-1:0] mask,
        input int                      after_idx
    );
        logic           found;
        logic [CIW-1:0] idx;
        found = 1'b0;
        idx   = '0;
        for (int i = 0; i < NUM_CHANNELS; i++) begin
            if (!found && (i > after_idx) && mask[i]) begin
                found = 1'b1;
                idx   = CIW'(i);
            end
        end
        return {found, idx};
    endfunction

    logic [NUM_CHANNELS-1:0] w_eff_mask;
    assign w_eff_mask = (cfg_channel_mask == '0) ? {NUM_CHANNELS{1'b1}} : cfg_channel_mask;

    logic [CIW:0] w_first_res, w_next_res, w_wrap_res;
    assign w_first_res = f_next_active_after(w_eff_mask, -1);
    assign w_next_res  = f_next_active_after(r_channel_mask, int'(r_ch));
    assign w_wrap_res  = f_next_active_after(r_channel_mask, -1);   // round-robin wrap target

    logic           w_first_found, w_next_found;
    logic [CIW-1:0] w_first_idx,   w_next_idx, w_wrap_idx;
    assign w_first_found = w_first_res[CIW];
    assign w_first_idx   = w_first_res[CIW-1:0];
    assign w_next_found  = w_next_res[CIW];
    assign w_next_idx    = w_next_res[CIW-1:0];
    assign w_wrap_idx    = w_wrap_res[CIW-1:0];

    logic unused_wrap_found;
    assign unused_wrap_found = w_wrap_res[CIW];   // the latched mask is never empty in RUN

    //==========================================================================
    // Per-channel LFSR pattern generators + CRC-32 calculators
    //==========================================================================
    // seed/taps/replication/CRC instantiation + gating are copied VERBATIM from
    // axi4_slave_rd_injector so the per-channel 32-bit CRC is bit-identical.

    genvar gch;
    generate
        for (gch = 0; gch < NUM_CHANNELS; gch++) begin : gen_ch
            logic ch_beat;
            logic r_ch_crc_valid;
            logic [31:0] r_ch_beat_count;

            // The active channel advances on its accepted beat; all channels
            // (re)load their seed on the global load pulse.
            assign ch_beat = w_beat && (r_ch == gch[CIW-1:0]);

            shifter_lfsr_fibonacci #(
                .WIDTH          (LFSR_WIDTH),
                .TAP_INDEX_WIDTH(LFSR_TAP_INDEX_WIDTH),
                .TAP_COUNT      (LFSR_TAP_COUNT)
            ) u_lfsr (
                .clk      (clk),
                .rst_n    (w_rst_n),
                .enable   (ch_beat || w_load),
                .seed_load(w_load),
                .seed_data(w_seed ^ 32'(gch)),   // unique seed per channel
                .taps     (LFSR_TAPS),
                .lfsr_out (lfsr_out_per_ch[gch]),
                .lfsr_done()
            );

            dataint_crc #(
                .DATA_WIDTH(CRC_DATA_WIDTH),
                .CRC_WIDTH (CRC_WIDTH),
                .REFIN     (CRC_REFIN),
                .REFOUT    (CRC_REFOUT)
            ) u_crc (
                .POLY             (CRC_POLY),
                .POLY_INIT        (CRC_INIT),
                .XOROUT           (CRC_XOROUT),
                .clk              (clk),
                .rst_n            (w_rst_n),
                .load_crc_start   (w_load),
                .load_from_cascade(ch_beat),
                .cascade_sel      (4'b1000),          // process all 4 bytes of 32-bit slice
                .data             (lfsr_out_per_ch[gch]),
                .crc              (crc_out_per_ch[gch])
            );

            `ALWAYS_FF_RST(clk, w_rst_n,
                if (`RST_ASSERTED(w_rst_n)) begin
                    r_ch_crc_valid  <= 1'b0;
                    r_ch_beat_count <= '0;
                end else if (w_load) begin
                    r_ch_crc_valid  <= 1'b0;
                    r_ch_beat_count <= '0;
                end else if (ch_beat) begin
                    r_ch_crc_valid  <= 1'b1;
                    r_ch_beat_count <= r_ch_beat_count + 1'b1;
                end
            )

            assign o_expected_crc      [gch] = crc_out_per_ch[gch];
            assign o_expected_crc_valid[gch] = r_ch_crc_valid;
            assign o_beat_count        [gch] = r_ch_beat_count;
        end
    endgenerate

    // Aggregate beat count (sum across channels) for the harness stop trigger.
    always_comb begin
        o_beat_count_total = '0;
        for (int ch = 0; ch < NUM_CHANNELS; ch++) begin
            o_beat_count_total = o_beat_count_total + o_beat_count[ch];
        end
    end

    //==========================================================================
    // Stream outputs
    //==========================================================================

    assign w_active_lfsr  = lfsr_out_per_ch[r_ch];
    assign w_ch_last_beat = (r_beats_remaining == {{(BEAT_COUNT_WIDTH-1){1'b0}}, 1'b1});
    assign w_pkt_last     = w_ch_last_beat ||
                            ((r_beats_per_pkt != '0) &&
                             (r_pkt_cnt == r_beats_per_pkt - 1'b1));

    assign m_axis_tvalid = (r_state == RUN);
    assign m_axis_tdata  = {REP{w_active_lfsr}};
    // The tlast beat carries r_last_bytes valid bytes from lane 0 (TASK-019)
    logic [STRB_WIDTH-1:0] w_last_strb;
    assign w_last_strb   = ((r_last_bytes == 8'd0) || (r_last_bytes >= 8'(STRB_WIDTH)))
                         ? {STRB_WIDTH{1'b1}} : ~({STRB_WIDTH{1'b1}} << r_last_bytes);
    assign m_axis_tstrb  = w_pkt_last ? w_last_strb : {STRB_WIDTH{1'b1}};
    assign m_axis_tlast  = w_pkt_last;
    assign m_axis_tid    = AXIS_ID_WIDTH'(r_ch);
    assign m_axis_tdest  = cfg_tdest;
    assign m_axis_tuser  = '0;
    assign cfg_busy      = (r_state != IDLE);

    //==========================================================================
    // Scheduling FSM
    //==========================================================================

    `ALWAYS_FF_RST(clk, w_rst_n,
        if (`RST_ASSERTED(w_rst_n)) begin
            r_state           <= IDLE;
            r_ch              <= '0;
            r_beats_remaining <= '0;
            r_pkt_cnt         <= '0;
            r_channel_mask    <= '0;
            r_num_beats       <= '0;
            r_beats_per_pkt   <= '0;
            r_last_bytes      <= '0;
            r_interleave      <= 1'b0;
            cfg_done          <= 1'b0;
        end else begin
            cfg_done <= 1'b0;   // default: single-cycle pulse
            case (r_state)
                IDLE: begin
                    if (cfg_start) begin
                        r_channel_mask  <= w_eff_mask;
                        r_num_beats     <= cfg_num_beats;
                        r_beats_per_pkt <= cfg_beats_per_pkt;
                        r_last_bytes    <= cfg_last_bytes;
                        r_interleave    <= cfg_interleave;
                        r_pkt_cnt       <= '0;
                        if ((cfg_num_beats == '0) || !w_first_found) begin
                            r_state <= DONE;
                        end else begin
                            r_ch              <= w_first_idx;
                            r_beats_remaining <= cfg_num_beats;
                            r_state           <= RUN;
                        end
                    end
                end

                RUN: begin
                    if (w_beat && r_interleave) begin
                        // Round-robin: every accepted beat hands the bus to the
                        // next active channel. The round -- and the beat/packet
                        // counters, which every channel shares because each gets
                        // exactly one beat per round -- advances when the last
                        // active channel has taken its beat.
                        if (w_next_found) begin
                            r_ch <= w_next_idx;
                        end else if (w_ch_last_beat) begin
                            r_state <= DONE;
                        end else begin
                            r_ch              <= w_wrap_idx;
                            r_beats_remaining <= r_beats_remaining - 1'b1;
                            r_pkt_cnt         <= w_pkt_last ? '0 : (r_pkt_cnt + 1'b1);
                        end
                    end else if (w_beat) begin
                        r_pkt_cnt <= w_pkt_last ? '0 : (r_pkt_cnt + 1'b1);
                        if (w_ch_last_beat) begin
                            // Finished this channel -> advance to the next active
                            // channel (its LFSR/CRC state is untouched), or finish.
                            if (w_next_found) begin
                                r_ch              <= w_next_idx;
                                r_beats_remaining <= r_num_beats;
                                r_pkt_cnt         <= '0;
                            end else begin
                                r_state <= DONE;
                            end
                        end else begin
                            r_beats_remaining <= r_beats_remaining - 1'b1;
                        end
                    end
                end

                DONE: begin
                    cfg_done <= 1'b1;
                    r_state  <= IDLE;
                end

                default: r_state <= IDLE;
            endcase
        end
    )

endmodule : axis4_master_injector

// SPDX-License-Identifier: MIT
// SPDX-FileCopyrightText: 2024-2025 sean galloway
//
// RTL Design Sherpa - Industry-Standard RTL Design and Verification
// https://github.com/sean-galloway/RTLDesignSherpa
//
// Module: axis4_slave_pattern_check
// Purpose: AXI-Stream slave that checks a deterministic, PER-CHANNEL LFSR data
//          pattern. This is the AXIS SOURCE checker for the RAPIDS
//          characterization harness and is pattern/CRC-CONSISTENT with
//          axi4_slave_rd_injector: the per-channel 32-bit CRC-32 it computes
//          is bit-identical to axi4_slave_rd_injector.read_crc_value for the
//          same stream (source self-check: rd_gen -> m_axis -> axis_check).
//
// Description:
//   On cfg_start every channel's LFSR is seeded identically to the generator
//   (seed ^ ch). Incoming beats are DEMUXed by s_axis_tid[CIW-1:0] into the
//   matching channel context. On each accepted beat for channel ch:
//     - the received tdata is compared against the locally-regenerated pattern
//       {REP{lfsr_out[ch]}}; any mismatch latches o_data_error (sticky);
//     - that channel's LFSR + dataint_crc-32 advance (fed the 32-bit
//       lfsr_out[ch], exactly like axi4_slave_rd_injector).
//   The LFSR advances only on accepted beats, so the check is independent of
//   upstream stalls / interleave order across channels.
//
//   Per-channel CRC (o_actual_crc[ch]/o_actual_crc_valid[ch]) mirrors
//   axi4_slave_rd_injector.read_crc_value semantics -- NOT the old XOR-fold.
//
// CRC bit-consistency (copied VERBATIM from the axi4 blocks): identical LFSR
//   (WIDTH=32, TAP_INDEX_WIDTH=12, TAP_COUNT=4, seed ^ ch) + identical
//   dataint_crc (DATA_WIDTH=32, CRC_WIDTH=32, POLY=0x04C11DB7,
//   POLY_INIT=0xFFFFFFFF, XOROUT=0xFFFFFFFF, REFIN=1, REFOUT=1,
//   cascade_sel=4'b1000, data=lfsr_out[ch]) with the same gating
//   (load_crc_start=cfg_start, load_from_cascade=accepted-beat-for-ch).
//
// Notes:
//   - AXIS_DATA_WIDTH must be a multiple of LFSR_WIDTH.
//   - s_axis_tready = ready_en (pure sink; deassert to model backpressure).
//
// Documentation: vault/tracking/projects/components/dma-ip/rapids/CONTROL_ENGINE_INTEGRATION.md (harness)
// Subsystem: amba/shared

`timescale 1ns / 1ps

`include "reset_defs.svh"

module axis4_slave_pattern_check #(
    parameter int          NUM_CHANNELS     = 1,
    parameter int          AXIS_DATA_WIDTH  = 512,
    parameter int          AXIS_ID_WIDTH    = 8,
    parameter int          AXIS_DEST_WIDTH  = 4,
    parameter int          AXIS_USER_WIDTH  = 1,

    // LFSR parameters (32-bit fixed; MUST MATCH axi4_slave_rd_injector!)
    parameter int          LFSR_WIDTH       = 32,
    parameter logic [31:0] LFSR_SEED        = 32'hDEADBEEF,
    parameter logic [47:0] LFSR_TAPS        = {12'd23, 12'd3, 12'd2, 12'd1},

    // CRC parameters (fixed; MUST MATCH axi4_slave_rd_injector!)
    parameter int          CRC_WIDTH        = 32,
    parameter int          CRC_DATA_WIDTH   = 32,
    parameter logic [31:0] CRC_POLY         = 32'h04C11DB7,
    parameter logic [31:0] CRC_INIT         = 32'hFFFFFFFF,
    parameter logic [31:0] CRC_XOROUT       = 32'hFFFFFFFF,
    parameter int          CRC_REFIN        = 1,
    parameter int          CRC_REFOUT       = 1,

    parameter int          BEAT_COUNT_WIDTH = 32,
    // BYTE_CRC=1 (byte-granular RAPIDS, rapids TASK-019): the per-channel CRC
    // runs over the strobed bytes of every beat, four per cycle through
    // cascade_sel, with tready held low while a beat is fed; the word compare
    // is replaced by a tstrb-contiguity check. 0: the LFSR word CRC + compare.
    parameter bit          BYTE_CRC         = 1'b0,
    // Derived
    parameter int          STRB_WIDTH       = AXIS_DATA_WIDTH / 8,
    parameter int          REP              = AXIS_DATA_WIDTH / LFSR_WIDTH,
    parameter int          CIW              = (NUM_CHANNELS > 1) ? $clog2(NUM_CHANNELS) : 1
) (
    input  logic                          clk,
    input  logic                          rst_n,

    // Configuration / control
    input  logic                          cfg_start,          // pulse: arm + seed all channels
    input  logic [LFSR_WIDTH-1:0]         cfg_lfsr_seed,      // 0 => use LFSR_SEED param
    input  logic                          ready_en,           // s_axis_tready = ready_en

    // Per-channel actual CRC (mirrors axi4_slave_rd_injector.read_crc_value)
    output logic [NUM_CHANNELS-1:0][31:0] o_actual_crc,
    output logic [NUM_CHANNELS-1:0]       o_actual_crc_valid,
    output logic                          o_data_error,       // sticky: any beat mismatch
    output logic [NUM_CHANNELS-1:0][31:0] o_beat_count,       // per-channel beats received
    output logic [31:0]                   o_beat_count_total, // sum across channels
    output logic [BEAT_COUNT_WIDTH-1:0]   o_pkt_count,        // tlast beats received (aggregate)

    // AXI-Stream slave
    input  logic                          s_axis_tvalid,
    output logic                          s_axis_tready,
    input  logic [AXIS_DATA_WIDTH-1:0]    s_axis_tdata,
    input  logic [STRB_WIDTH-1:0]         s_axis_tstrb,
    input  logic                          s_axis_tlast,
    input  logic [AXIS_ID_WIDTH-1:0]      s_axis_tid,
    input  logic [AXIS_DEST_WIDTH-1:0]    s_axis_tdest,
    input  logic [AXIS_USER_WIDTH-1:0]    s_axis_tuser
);

    localparam int LFSR_TAP_INDEX_WIDTH = 12;
    localparam int LFSR_TAP_COUNT       = 4;

    logic                       w_load;
    logic                       w_beat;
    logic [CIW-1:0]             w_ch;
    logic [LFSR_WIDTH-1:0]      w_seed;

    logic [31:0]                lfsr_out_per_ch      [NUM_CHANNELS];
    logic [31:0]                crc_out_per_ch       [NUM_CHANNELS];
    logic [AXIS_DATA_WIDTH-1:0] expected_data_per_ch [NUM_CHANNELS];

    //==========================================================================
    // Boundary reset synchronization
    //==========================================================================
    // The port rst_n is treated as an asynchronous-assert input of unknown
    // deassert quality: an N=3 reset_sync produces the internal reset every
    // block below sees.
    logic w_rst_n;
    reset_sync #(
        .N             (3),
        .KEEP_ATTRS    (1'b1),
        .IN_ACTIVE_LOW (1'b1),
        .OUT_ACTIVE_LOW(1'b1),
        .ASYNC_ASSERT  (1'b1)
    ) u_reset_sync (
        .clk        (clk),
        .rst_n      (rst_n),
        .sync_rst_n (w_rst_n)
    );

    //==========================================================================
    // Byte-granular CRC feed (BYTE_CRC)
    //==========================================================================
    // An accepted beat's strobed bytes (contiguous from lane 0) are captured
    // and fed to the channel's CRC four bytes per cycle, so the CRC is over
    // the byte stream exactly as the golden model computes it.
    logic                        r_bc_busy;
    logic [AXIS_DATA_WIDTH-1:0]  r_bc_data;
    logic [7:0]                  r_bc_left;
    logic [CIW-1:0]              r_bc_ch;
    logic [7:0]                  w_strb_bytes;
    logic                        w_strb_contig;
    logic [7:0]                  w_bc_take;
    logic [3:0]                  w_bc_sel;
    always_comb begin
        w_strb_bytes = '0;
        for (int b = 0; b < STRB_WIDTH; b++) w_strb_bytes = w_strb_bytes + 8'(s_axis_tstrb[b]);
    end
    assign w_strb_contig = (s_axis_tstrb == ~({STRB_WIDTH{1'b1}} << w_strb_bytes));
    assign w_bc_take = (r_bc_left > 8'd4) ? 8'd4 : r_bc_left;
    assign w_bc_sel  = 4'(4'b0001 << (w_bc_take - 8'd1));
    `ALWAYS_FF_RST(clk, w_rst_n,
        if (`RST_ASSERTED(w_rst_n)) begin
            r_bc_busy <= 1'b0;
            r_bc_data <= '0;
            r_bc_left <= '0;
            r_bc_ch   <= '0;
        end else if (BYTE_CRC) begin
            if (r_bc_busy) begin
                r_bc_data <= r_bc_data >> 32;
                r_bc_left <= r_bc_left - w_bc_take;
                if (r_bc_left <= 8'd4) r_bc_busy <= 1'b0;
            end else if (w_beat && (w_strb_bytes != 8'd0)) begin
                r_bc_busy <= 1'b1;
                r_bc_data <= s_axis_tdata;
                r_bc_left <= w_strb_bytes;
                r_bc_ch   <= w_ch;
            end
        end
    )
    // Sink readiness driven by ready_en (tie high for a pure sink; deassert to
    // model backpressure). Drives the SAME handshake the upstream sees, so both
    // sides advance in lockstep. BYTE_CRC holds ready while a beat is fed.
    assign s_axis_tready = ready_en && !r_bc_busy;

    assign w_load = cfg_start;
    assign w_seed = (cfg_lfsr_seed == '0) ? LFSR_SEED[LFSR_WIDTH-1:0] : cfg_lfsr_seed;
    assign w_beat = s_axis_tvalid && s_axis_tready;
    assign w_ch   = (NUM_CHANNELS == 1) ? '0 : s_axis_tid[CIW-1:0];


    //==========================================================================
    // Per-channel LFSR pattern regenerators + CRC-32 calculators
    //==========================================================================
    // seed/taps/replication/CRC instantiation + gating are copied VERBATIM from
    // axi4_slave_rd_injector so the per-channel 32-bit CRC is bit-identical.

    genvar gch;
    generate
        for (gch = 0; gch < NUM_CHANNELS; gch++) begin : gen_ch
            logic ch_beat;
            logic r_ch_crc_valid;
            logic [31:0] r_ch_beat_count;

            // This channel advances only on an accepted beat carrying its tid;
            // all channels (re)load their seed on the arm pulse.
            assign ch_beat = w_beat && (w_ch == gch[CIW-1:0]);

            shifter_lfsr_fibonacci #(
                .WIDTH          (LFSR_WIDTH),
                .TAP_INDEX_WIDTH(LFSR_TAP_INDEX_WIDTH),
                .TAP_COUNT      (LFSR_TAP_COUNT)
            ) u_lfsr (
                .clk      (clk),
                .rst_n    (w_rst_n),
                .enable   (ch_beat || w_load),
                .seed_load(w_load),
                .seed_data(w_seed ^ 32'(gch)),   // unique seed per channel
                .taps     (LFSR_TAPS),
                .lfsr_out (lfsr_out_per_ch[gch]),
                .lfsr_done()
            );

            assign expected_data_per_ch[gch] = {REP{lfsr_out_per_ch[gch]}};

            dataint_crc #(
                .DATA_WIDTH(CRC_DATA_WIDTH),
                .CRC_WIDTH (CRC_WIDTH),
                .REFIN     (CRC_REFIN),
                .REFOUT    (CRC_REFOUT)
            ) u_crc (
                .POLY             (CRC_POLY),
                .POLY_INIT        (CRC_INIT),
                .XOROUT           (CRC_XOROUT),
                .clk              (clk),
                .rst_n            (w_rst_n),
                .load_crc_start   (w_load),
                .load_from_cascade(BYTE_CRC ? (r_bc_busy && (r_bc_ch == gch[CIW-1:0])) : ch_beat),
                .cascade_sel      (BYTE_CRC ? w_bc_sel : 4'b1000),   // word mode: all 4 bytes of the LFSR word
                .data             (BYTE_CRC ? r_bc_data[31:0] : lfsr_out_per_ch[gch]),
                .crc              (crc_out_per_ch[gch])
            );

            `ALWAYS_FF_RST(clk, w_rst_n,
                if (`RST_ASSERTED(w_rst_n)) begin
                    r_ch_crc_valid  <= 1'b0;
                    r_ch_beat_count <= '0;
                end else if (w_load) begin
                    r_ch_crc_valid  <= 1'b0;
                    r_ch_beat_count <= '0;
                end else if (ch_beat) begin
                    r_ch_crc_valid  <= 1'b1;
                    r_ch_beat_count <= r_ch_beat_count + 1'b1;
                end
            )

            assign o_actual_crc      [gch] = crc_out_per_ch[gch];
            assign o_actual_crc_valid[gch] = r_ch_crc_valid;
            assign o_beat_count      [gch] = r_ch_beat_count;
        end
    endgenerate

    // Aggregate beat count (sum across channels) for the harness timer.
    always_comb begin
        o_beat_count_total = '0;
        for (int ch = 0; ch < NUM_CHANNELS; ch++) begin
            o_beat_count_total = o_beat_count_total + o_beat_count[ch];
        end
    end

    //==========================================================================
    // Sticky data-error + aggregate packet counter
    //==========================================================================
    // Compare the received beat against the active channel's regenerated
    // expected data (current LFSR value, before it advances this same edge).

    logic w_data_mismatch;
    // BYTE_CRC: the CRC carries the data check; a beat whose tstrb is not
    // contiguous from lane 0 is the error.
    assign w_data_mismatch = w_beat && (BYTE_CRC ? !w_strb_contig
                                                 : (s_axis_tdata != expected_data_per_ch[w_ch]));

    `ALWAYS_FF_RST(clk, w_rst_n,
        if (`RST_ASSERTED(w_rst_n)) begin
            o_data_error <= 1'b0;
            o_pkt_count  <= '0;
        end else if (cfg_start) begin
            o_data_error <= 1'b0;
            o_pkt_count  <= '0;
        end else if (w_beat) begin
            if (w_data_mismatch)  o_data_error <= 1'b1;
            if (s_axis_tlast)     o_pkt_count  <= o_pkt_count + 1'b1;
        end
    )

endmodule : axis4_slave_pattern_check

// SPDX-License-Identifier: MIT
// SPDX-FileCopyrightText: 2026 sean galloway
//
// Module: axis_bus_meter
// Purpose: Per-cycle valid/ready bucket counter + byte/packet counters for one
//          AXI-Stream (AXIS) channel. The AXIS analogue of axi_bus_meter: same
//          4-bucket cycle classification, plus AXIS-native throughput counters
//          (bytes via tstrb, packets via tlast) that are WINDOW-INDEPENDENT.
//
// One instance per AXIS bus to be measured. Snoop tvalid/tready/tlast/tstrb/tid;
// the block is a pure observer (drives nothing back onto the bus).
//
// Cycle classification (identical to axi_bus_meter; see
// DMA_UTILIZATION_MEASUREMENT.md §3):
//
//   valid  ready    bucket           meaning
//   -----  -----    ------           -------
//     1      1      productive       beat transferred
//     1      0      backpressure     master wants to send, slave stalls
//     0      1      starvation       slave ready, master not producing
//     0      0      idle             both sides quiet
//
// AXIS-native counters (increment ONLY on a productive beat, valid&ready):
//   - o_agg_bytes   : += popcount(tstrb) each productive beat. This is the exact
//                     number of payload bytes moved, independent of how long the
//                     measurement window is held open -- so throughput =
//                     bytes / (busy_time) is robust to backpressure/idle padding
//                     that would distort a pure cycle-utilization figure.
//   - o_agg_beats   : += 1 each productive beat (== o_agg_productive; provided
//                     for convenience alongside bytes/packets).
//   - o_agg_packets : += 1 each productive beat with tlast (stream packets).
//
// Counters:
//   - Aggregate cycle buckets: 32-bit (42.9 s @ 100 MHz before wrap).
//   - Aggregate bytes: 64-bit (won't wrap in any realistic run).
//   - Aggregate beats/packets: 32-bit.
//   - Per-channel (by tid) cycle buckets: 16-bit x NUM_CHANNELS, with a
//     per-channel 4-bit overflow sticky (see axi_bus_meter for semantics).
//
// Control:
//   - i_clear  : synchronous one-cycle pulse; zeroes every counter + sticky.
//   - i_freeze : hold high to freeze the window (no counter moves). Drive from
//                the characterization window controller.

`timescale 1ns / 1ps

`include "reset_defs.svh"

module axis_bus_meter #(
    parameter int DATA_WIDTH   = 512,
    parameter int NUM_CHANNELS = 8,
    parameter int TID_WIDTH    = (NUM_CHANNELS > 1) ? $clog2(NUM_CHANNELS) : 1,
    parameter int SW           = DATA_WIDTH / 8,                    // tstrb width
    parameter int CW           = (NUM_CHANNELS > 1) ? $clog2(NUM_CHANNELS) : 1
) (
    input  logic                      aclk,
    input  logic                      aresetn,

    // Synchronous clear pulse (one cycle wide).
    input  logic                      i_clear,
    // Freeze: hold high to close the measurement window.
    input  logic                      i_freeze,

    // AXIS bus snoop. tid selects the per-channel bin (its low CW bits); for a
    // single-stream bus tie tid=0. tstrb counts payload bytes; if the stream has
    // no tstrb, tie it all-ones so bytes == beats * (DATA_WIDTH/8).
    input  logic                      i_tvalid,
    input  logic                      i_tready,
    input  logic                      i_tlast,
    input  logic [SW-1:0]             i_tstrb,
    input  logic [TID_WIDTH-1:0]      i_tid,

    // Aggregate cycle buckets
    output logic [31:0]               o_agg_productive,
    output logic [31:0]               o_agg_backpressure,
    output logic [31:0]               o_agg_starvation,
    output logic [31:0]               o_agg_idle,

    // Aggregate AXIS-native throughput counters (productive beats only)
    output logic [63:0]               o_agg_bytes,
    output logic [31:0]               o_agg_beats,
    output logic [31:0]               o_agg_packets,

    // Per-channel (by tid) cycle buckets
    output logic [15:0]               o_ch_productive   [NUM_CHANNELS],
    output logic [15:0]               o_ch_backpressure [NUM_CHANNELS],
    output logic [15:0]               o_ch_starvation   [NUM_CHANNELS],
    output logic [15:0]               o_ch_idle         [NUM_CHANNELS],

    // Per-channel overflow stickies, packed {prod, bp, starv, idle} per channel.
    output logic [NUM_CHANNELS*4-1:0] o_ch_overflow
);

    // =========================================================================
    // Boundary reset synchronization
    // =========================================================================
    // The port aresetn is treated as an asynchronous-assert input of unknown
    // deassert quality: an N=3 reset_sync produces the internal reset every
    // block below sees.
    logic w_aresetn;
    reset_sync #(
        .N             (3),
        .KEEP_ATTRS    (1'b1),
        .IN_ACTIVE_LOW (1'b1),
        .OUT_ACTIVE_LOW(1'b1),
        .ASYNC_ASSERT  (1'b1)
    ) u_reset_sync (
        .clk        (aclk),
        .rst_n      (aresetn),
        .sync_rst_n (w_aresetn)
    );

    // =========================================================================
    // Bucket selection + payload-byte popcount
    // =========================================================================
    logic w_prod, w_bp, w_starv, w_idle;
    assign w_prod  =  i_tvalid &&  i_tready;
    assign w_bp    =  i_tvalid && !i_tready;
    assign w_starv = !i_tvalid &&  i_tready;
    assign w_idle  = !i_tvalid && !i_tready;

    // Byte count of THIS beat = number of asserted tstrb lanes.
    logic [$clog2(SW+1)-1:0] w_beat_bytes;
    always_comb begin
        w_beat_bytes = '0;
        for (int b = 0; b < SW; b++) w_beat_bytes += ($clog2(SW+1))'(i_tstrb[b]);
    end

    // Channel bin index (low CW bits of tid).
    logic [CW-1:0] w_ch;
    assign w_ch = i_tid[CW-1:0];

    // =========================================================================
    // Aggregate cycle buckets
    // =========================================================================
    logic [31:0] r_agg_prod, r_agg_bp, r_agg_starv, r_agg_idle;
    `ALWAYS_FF_RST(aclk, w_aresetn,
        if (`RST_ASSERTED(w_aresetn)) begin
            r_agg_prod <= '0; r_agg_bp <= '0; r_agg_starv <= '0; r_agg_idle <= '0;
        end else if (i_clear) begin
            r_agg_prod <= '0; r_agg_bp <= '0; r_agg_starv <= '0; r_agg_idle <= '0;
        end else if (!i_freeze) begin
            if (w_prod)  r_agg_prod  <= r_agg_prod  + 32'd1;
            if (w_bp)    r_agg_bp    <= r_agg_bp    + 32'd1;
            if (w_starv) r_agg_starv <= r_agg_starv + 32'd1;
            if (w_idle)  r_agg_idle  <= r_agg_idle  + 32'd1;
        end
    )
    assign o_agg_productive   = r_agg_prod;
    assign o_agg_backpressure = r_agg_bp;
    assign o_agg_starvation   = r_agg_starv;
    assign o_agg_idle         = r_agg_idle;

    // =========================================================================
    // Aggregate AXIS-native throughput counters (productive beats only)
    // =========================================================================
    logic [63:0] r_agg_bytes;
    logic [31:0] r_agg_beats, r_agg_packets;
    `ALWAYS_FF_RST(aclk, w_aresetn,
        if (`RST_ASSERTED(w_aresetn)) begin
            r_agg_bytes <= '0; r_agg_beats <= '0; r_agg_packets <= '0;
        end else if (i_clear) begin
            r_agg_bytes <= '0; r_agg_beats <= '0; r_agg_packets <= '0;
        end else if (!i_freeze && w_prod) begin
            r_agg_bytes   <= r_agg_bytes   + 64'(w_beat_bytes);
            r_agg_beats   <= r_agg_beats   + 32'd1;
            if (i_tlast) r_agg_packets <= r_agg_packets + 32'd1;
        end
    )
    assign o_agg_bytes   = r_agg_bytes;
    assign o_agg_beats   = r_agg_beats;
    assign o_agg_packets = r_agg_packets;

    // =========================================================================
    // Per-channel cycle buckets + overflow stickies (binned by tid)
    // =========================================================================
    logic [15:0] r_ch_prod  [NUM_CHANNELS];
    logic [15:0] r_ch_bp    [NUM_CHANNELS];
    logic [15:0] r_ch_starv [NUM_CHANNELS];
    logic [15:0] r_ch_idle  [NUM_CHANNELS];
    logic [3:0]  r_ch_overflow [NUM_CHANNELS];  // {prod, bp, starv, idle}

    `ALWAYS_FF_RST(aclk, w_aresetn,
        if (`RST_ASSERTED(w_aresetn)) begin
            for (int c = 0; c < NUM_CHANNELS; c++) begin
                r_ch_prod[c] <= '0; r_ch_bp[c] <= '0; r_ch_starv[c] <= '0;
                r_ch_idle[c] <= '0; r_ch_overflow[c] <= '0;
            end
        end else if (i_clear) begin
            for (int c = 0; c < NUM_CHANNELS; c++) begin
                r_ch_prod[c] <= '0; r_ch_bp[c] <= '0; r_ch_starv[c] <= '0;
                r_ch_idle[c] <= '0; r_ch_overflow[c] <= '0;
            end
        end else if (!i_freeze) begin
            // AXIS carries tid on every valid cycle, so bin by tid whenever the
            // bus is active (valid or ready). Idle cycles (both low) are not
            // attributable to a channel and only land in the aggregate.
            if (w_prod) begin
                if (r_ch_prod [w_ch] == 16'hFFFF) r_ch_overflow[w_ch][3] <= 1'b1;
                r_ch_prod [w_ch] <= r_ch_prod [w_ch] + 16'd1;
            end
            if (w_bp) begin
                if (r_ch_bp   [w_ch] == 16'hFFFF) r_ch_overflow[w_ch][2] <= 1'b1;
                r_ch_bp   [w_ch] <= r_ch_bp   [w_ch] + 16'd1;
            end
            if (w_starv) begin
                if (r_ch_starv[w_ch] == 16'hFFFF) r_ch_overflow[w_ch][1] <= 1'b1;
                r_ch_starv[w_ch] <= r_ch_starv[w_ch] + 16'd1;
            end
        end
    )

    always_comb begin
        for (int c = 0; c < NUM_CHANNELS; c++) begin
            o_ch_productive  [c] = r_ch_prod [c];
            o_ch_backpressure[c] = r_ch_bp   [c];
            o_ch_starvation  [c] = r_ch_starv[c];
            o_ch_idle        [c] = r_ch_idle [c];
        end
    end
    always_comb begin
        o_ch_overflow = '0;
        for (int c = 0; c < NUM_CHANNELS; c++) o_ch_overflow[c*4 +: 4] = r_ch_overflow[c];
    end

endmodule : axis_bus_meter

// SPDX-License-Identifier: MIT
// SPDX-FileCopyrightText: 2026 sean galloway
//
// Module: bch_decoder_axi4
// Description: Binary BCH decoder as an AXI4 memory-to-memory job engine.
//
//   The AXI4 counterpart to bch_decoder_axis4 and the mirror of
//   bch_encoder_axi4: a job names a source address, a destination address and
//   a BLOCK COUNT, and the block reads one codeword per block, corrects it,
//   and writes the k recovered message bits out.
//
//   Per-block verdicts are accumulated into counters rather than only exposed
//   as a sideband pulse. A job covers many blocks and a host reads the result
//   once at the end, so the counters are what a CSR wants. The per-block
//   sideband is brought out too, for a consumer that wants to act on each
//   block.
//
// Parameters:
//   FIELD_DIM / PRIM_POLY / T_BITS / N_BITS / FIRST_ROOT
//                    the code, as bch_decoder_core takes them
//   DATA_WIDTH       AXI and stream width; also the BCH bits per beat
//   ADDR_WIDTH       AXI address width
//   ID_WIDTH         AXI id width
//   MAX_OUTSTANDING  requests in flight per direction
//
// Notes:
//   - A codeword is read as ceil(N/B) PACKED beats with any partial one last,
//     which is what bch_encoder_axi4 writes. This module reconstructs that
//     keep from the beat index, since the read engine deals in beats and
//     knows nothing about bits.
//   - The output is k bits per block and the write side writes whole beats;
//     a partial final beat's unused lanes carry whatever the core emitted.
//   - out_status_* are valid with the block's last output beat.
module bch_decoder_axi4
    import bch_pkg::bch_beats;
    import bch_pkg::bch_degree_g;
#(
    parameter int FIELD_DIM     = bch_pkg::FIELD_DIM,
    parameter int PRIM_POLY     = bch_pkg::PRIM_POLY,
    parameter int T_BITS        = bch_pkg::T_BITS,
    parameter int N_BITS        = bch_pkg::N_BITS,
    parameter int FIRST_ROOT    = bch_pkg::FIRST_ROOT,
    parameter int DATA_WIDTH    = bch_pkg::BITS_PER_BEAT,
    parameter int ADDR_WIDTH    = 32,
    parameter int ID_WIDTH      = 4,
    parameter int MAX_OUTSTANDING = 4,
    parameter int USER_WIDTH    = 1,
    // derived, exposed for the consumer's convenience
    parameter int K_BITS        = N_BITS - bch_degree_g(FIELD_DIM, PRIM_POLY, T_BITS, FIRST_ROOT),
    parameter int BITS_PER_BEAT = DATA_WIDTH,
    parameter int STATUS_W      = $clog2(T_BITS + 1)
) (
    input  logic                    aclk,
    input  logic                    aresetn,

    // -- job -----------------------------------------------------------------
    input  logic                    cfg_start,          // one-cycle pulse
    input  logic [ADDR_WIDTH-1:0]   cfg_src_addr,
    input  logic [ADDR_WIDTH-1:0]   cfg_dst_addr,
    input  logic [15:0]             cfg_blocks,
    input  logic [7:0]              cfg_burst_len,
    input  logic [ID_WIDTH-1:0]     cfg_axi_id,
    output logic                    cfg_done,
    output logic                    resp_err,           // sticky, either direction

    // -- per-block verdict, valid with the block's last output beat ----------
    output logic                    out_status_ok,
    output logic [STATUS_W-1:0]     out_status_corrected,
    output logic                    out_status_uncorrectable,
    output logic                    out_status_frame_err,

    // -- accumulated over the job, cleared by cfg_start ----------------------
    output logic [31:0]             stat_blocks_ok,
    output logic [31:0]             stat_blocks_corrected,
    output logic [31:0]             stat_blocks_uncorrectable,
    output logic [31:0]             stat_blocks_frame_err,
    output logic [31:0]             stat_bits_corrected,

    // -- AXI4 master: read channels ------------------------------------------
    output logic [ID_WIDTH-1:0]     m_axi_arid,
    output logic [ADDR_WIDTH-1:0]   m_axi_araddr,
    output logic [7:0]              m_axi_arlen,
    output logic [2:0]              m_axi_arsize,
    output logic [1:0]              m_axi_arburst,
    output logic                    m_axi_arlock,
    output logic [3:0]              m_axi_arcache,
    output logic [2:0]              m_axi_arprot,
    output logic [3:0]              m_axi_arqos,
    output logic [3:0]              m_axi_arregion,
    output logic [USER_WIDTH-1:0]   m_axi_aruser,
    output logic                    m_axi_arvalid,
    input  logic                    m_axi_arready,
    input  logic [ID_WIDTH-1:0]     m_axi_rid,
    input  logic [DATA_WIDTH-1:0]   m_axi_rdata,
    input  logic [1:0]              m_axi_rresp,
    input  logic                    m_axi_rlast,
    input  logic [USER_WIDTH-1:0]   m_axi_ruser,
    input  logic                    m_axi_rvalid,
    output logic                    m_axi_rready,

    // -- AXI4 master: write channels -----------------------------------------
    output logic [ID_WIDTH-1:0]     m_axi_awid,
    output logic [ADDR_WIDTH-1:0]   m_axi_awaddr,
    output logic [7:0]              m_axi_awlen,
    output logic [2:0]              m_axi_awsize,
    output logic [1:0]              m_axi_awburst,
    output logic                    m_axi_awlock,
    output logic [3:0]              m_axi_awcache,
    output logic [2:0]              m_axi_awprot,
    output logic [3:0]              m_axi_awqos,
    output logic [3:0]              m_axi_awregion,
    output logic [USER_WIDTH-1:0]   m_axi_awuser,
    output logic                    m_axi_awvalid,
    input  logic                    m_axi_awready,
    output logic [DATA_WIDTH-1:0]   m_axi_wdata,
    output logic [DATA_WIDTH/8-1:0] m_axi_wstrb,
    output logic                    m_axi_wlast,
    output logic [USER_WIDTH-1:0]   m_axi_wuser,
    output logic                    m_axi_wvalid,
    input  logic                    m_axi_wready,
    input  logic [ID_WIDTH-1:0]     m_axi_bid,
    input  logic [1:0]              m_axi_bresp,
    input  logic [USER_WIDTH-1:0]   m_axi_buser,
    input  logic                    m_axi_bvalid,
    output logic                    m_axi_bready
);

    localparam int B        = BITS_PER_BEAT;
    localparam int K_BEATS  = bch_beats(K_BITS, B);
    // The codeword in memory is PACKED by bch_encoder_axi4: ceil(N/B) beats
    // with any partial one last. That is this core's in_keep contract, so the
    // tail is N % B and it lands on the block's final beat.
    localparam int CW_BEATS = bch_beats(N_BITS, B);
    localparam int N_TAIL   = N_BITS % B;
    localparam int SIZE_B   = $clog2(DATA_WIDTH / 8);
    localparam int IBW      = (CW_BEATS > 1) ? $clog2(CW_BEATS) : 1;

    if (B < 1 || B > K_BITS) begin : g_check_b
        $fatal(1, "bch_decoder_axi4: BITS_PER_BEAT %0d out of range 1..K (%0d)", B, K_BITS);
    end

    if (DATA_WIDTH != B) begin : g_check_dw
        $fatal(1, "bch_decoder_axi4: DATA_WIDTH %0d must equal BITS_PER_BEAT %0d", DATA_WIDTH, B);
    end

    // Boundary reset synchronization. The port aresetn is treated as an
    // asynchronous-assert input of unknown deassert quality: an N=3
    // reset_sync (rtl/cdc, formally proven) produces the internal reset
    // every block below sees.
    logic w_aresetn;
    reset_sync #(
        .N             (3),
        .KEEP_ATTRS    (1'b1),
        .IN_ACTIVE_LOW (1'b1),
        .OUT_ACTIVE_LOW(1'b1),
        .ASYNC_ASSERT  (1'b1)
    ) u_reset_sync (
        .clk        (aclk),
        .rst_n      (aresetn),
        .sync_rst_n (w_aresetn)
    );

    // =========================================================================
    // source: one codeword per block
    // =========================================================================
    logic                  rd_valid, rd_ready, rd_last, rd_done, rd_err;
    logic [DATA_WIDTH-1:0] rd_data;

    rs_axi4_read_engine #(
        .ADDR_WIDTH(ADDR_WIDTH), .DATA_WIDTH(DATA_WIDTH), .ID_WIDTH(ID_WIDTH),
        .MAX_OUTSTANDING(MAX_OUTSTANDING), .USER_WIDTH(USER_WIDTH)
    ) u_rd (
        .aclk(aclk), .aresetn(w_aresetn),
        .cfg_start(cfg_start), .cfg_src_addr(cfg_src_addr),
        .cfg_beats(32'(cfg_blocks) * 32'(CW_BEATS)),
        .cfg_burst_len(cfg_burst_len), .cfg_beats_per_block(16'(CW_BEATS)),
        .cfg_axi_id(cfg_axi_id), .cfg_axi_size(3'(SIZE_B)),
        .cfg_done(rd_done), .resp_err(rd_err),
        .out_valid(rd_valid), .out_ready(rd_ready), .out_data(rd_data), .out_last(rd_last),
        .m_axi_arid(m_axi_arid), .m_axi_araddr(m_axi_araddr), .m_axi_arlen(m_axi_arlen),
        .m_axi_arsize(m_axi_arsize), .m_axi_arburst(m_axi_arburst),
        .m_axi_arlock(m_axi_arlock), .m_axi_arcache(m_axi_arcache),
        .m_axi_arprot(m_axi_arprot), .m_axi_arqos(m_axi_arqos),
        .m_axi_arregion(m_axi_arregion), .m_axi_aruser(m_axi_aruser),
        .m_axi_arvalid(m_axi_arvalid), .m_axi_arready(m_axi_arready),
        .m_axi_rid(m_axi_rid), .m_axi_rdata(m_axi_rdata), .m_axi_rresp(m_axi_rresp),
        .m_axi_rlast(m_axi_rlast), .m_axi_ruser(m_axi_ruser),
        .m_axi_rvalid(m_axi_rvalid), .m_axi_rready(m_axi_rready));

    // Reconstruct the keep pattern the encoder produced. The read engine
    // counts beats and knows nothing about bits, so the beat INDEX within
    // the block is what says whether this beat is the codeword's partial tail.
    logic [IBW-1:0] r_ibeat;
    logic [B-1:0]   w_in_keep;

    always_comb begin
        w_in_keep = {B{1'b1}};
        if ((N_TAIL != 0) && (r_ibeat == IBW'(CW_BEATS - 1)))
            w_in_keep = B'((1 << N_TAIL) - 1);
    end

    always_ff @(posedge aclk or negedge w_aresetn) begin
        if (!w_aresetn)                     r_ibeat <= '0;
        else if (cfg_start)                 r_ibeat <= '0;
        else if (rd_valid && rd_ready)      r_ibeat <= rd_last ? '0 : r_ibeat + IBW'(1);
    end

    // =========================================================================
    // the codec
    // =========================================================================
    logic                  dec_valid, dec_ready, dec_last;
    logic [DATA_WIDTH-1:0] dec_data;
    logic [B-1:0]          dec_keep;

    bch_decoder_core #(
        .FIELD_DIM(FIELD_DIM), .PRIM_POLY(PRIM_POLY), .T_BITS(T_BITS),
        .N_BITS(N_BITS), .BITS_PER_BEAT(B), .FIRST_ROOT(FIRST_ROOT),
        .K_BITS(K_BITS), .ENABLE_RECHECK(1)
    ) u_core (
        .aclk(aclk), .aresetn(w_aresetn),
        .in_valid(rd_valid), .in_ready(rd_ready), .in_data(rd_data),
        .in_keep(w_in_keep), .in_last(rd_last),
        .out_valid(dec_valid), .out_ready(dec_ready), .out_data(dec_data),
        .out_keep(dec_keep), .out_last(dec_last),
        .out_status_ok(out_status_ok), .out_status_corrected(out_status_corrected),
        .out_status_uncorrectable(out_status_uncorrectable),
        .out_status_frame_err(out_status_frame_err));

    // =========================================================================
    // destination: k message beats per block
    // =========================================================================
    logic wr_done, wr_err;

    rs_axi4_write_engine #(
        .ADDR_WIDTH(ADDR_WIDTH), .DATA_WIDTH(DATA_WIDTH), .ID_WIDTH(ID_WIDTH),
        .MAX_OUTSTANDING(MAX_OUTSTANDING), .USER_WIDTH(USER_WIDTH)
    ) u_wr (
        .aclk(aclk), .aresetn(w_aresetn),
        .cfg_start(cfg_start), .cfg_dst_addr(cfg_dst_addr),
        .cfg_beats(32'(cfg_blocks) * 32'(K_BEATS)),
        .cfg_burst_len(cfg_burst_len), .cfg_axi_id(cfg_axi_id),
        .cfg_axi_size(3'(SIZE_B)),
        .cfg_done(wr_done), .resp_err(wr_err),
        .in_valid(dec_valid), .in_ready(dec_ready), .in_data(dec_data), .in_last(dec_last),
        .m_axi_awid(m_axi_awid), .m_axi_awaddr(m_axi_awaddr), .m_axi_awlen(m_axi_awlen),
        .m_axi_awsize(m_axi_awsize), .m_axi_awburst(m_axi_awburst),
        .m_axi_awlock(m_axi_awlock), .m_axi_awcache(m_axi_awcache),
        .m_axi_awprot(m_axi_awprot), .m_axi_awqos(m_axi_awqos),
        .m_axi_awregion(m_axi_awregion), .m_axi_awuser(m_axi_awuser),
        .m_axi_awvalid(m_axi_awvalid), .m_axi_awready(m_axi_awready),
        .m_axi_wdata(m_axi_wdata), .m_axi_wstrb(m_axi_wstrb), .m_axi_wlast(m_axi_wlast),
        .m_axi_wuser(m_axi_wuser), .m_axi_wvalid(m_axi_wvalid), .m_axi_wready(m_axi_wready),
        .m_axi_bid(m_axi_bid), .m_axi_bresp(m_axi_bresp), .m_axi_buser(m_axi_buser),
        .m_axi_bvalid(m_axi_bvalid), .m_axi_bready(m_axi_bready));

    // =========================================================================
    // job status
    // =========================================================================
    assign cfg_done = rd_done && wr_done;
    assign resp_err = rd_err || wr_err;

    // One verdict per block, taken on the block's last output beat -- which is
    // where the core's contract says the status is valid.
    logic w_verdict;
    assign w_verdict = dec_valid && dec_ready && dec_last;

    always_ff @(posedge aclk or negedge w_aresetn) begin
        if (!w_aresetn || cfg_start) begin
            stat_blocks_ok            <= '0;
            stat_blocks_corrected     <= '0;
            stat_blocks_uncorrectable <= '0;
            stat_blocks_frame_err     <= '0;
            stat_bits_corrected       <= '0;
        end else if (w_verdict) begin
            if (out_status_frame_err)          stat_blocks_frame_err     <= stat_blocks_frame_err + 32'd1;
            else if (out_status_uncorrectable) stat_blocks_uncorrectable <= stat_blocks_uncorrectable + 32'd1;
            else if (out_status_ok)            stat_blocks_ok            <= stat_blocks_ok + 32'd1;
            else begin
                stat_blocks_corrected <= stat_blocks_corrected + 32'd1;
                stat_bits_corrected   <= stat_bits_corrected + 32'(out_status_corrected);
            end
        end
    end

    // the core reports keep on its output; the write side writes whole beats
    logic unused_d;
    assign unused_d = ^dec_keep;

endmodule

// SPDX-License-Identifier: MIT
// SPDX-FileCopyrightText: 2026 sean galloway
//
// Module: bch_decoder_axis4
// Description: Binary BCH decoder with AXI4-Stream interfaces.
//
//   The component's integration top (TASK-006), the counterpart to
//   `bch_encoder_axis4`. `bch_decoder_core` speaks a bare valid/ready/last
//   handshake plus a per-block verdict; this wraps the stream halves in the
//   house `axis4_slave` / `axis4_master` skid wrappers and leaves the verdict
//   as sideband.
//
// Parameters:
//   FIELD_DIM       GF(2^m) field dimension, m
//   PRIM_POLY       primitive polynomial of degree m, as an integer
//   T_BITS          t, correctable bit errors per block
//   N_BITS          n, codeword length in bits
//   FIRST_ROOT      b, must match the encoder
//   BITS_PER_BEAT   B, the AXI4-Stream beat width
//   SKID_DEPTH      depth of the two AXIS skid buffers, 2..8
//   AXIS_*_WIDTH    tid / tdest / tuser widths, captured and held per block
//
// Notes:
//   - tstrb vs keep: identical rule to `bch_encoder_axis4`. Byte-aligned
//     codes use tstrb; non-byte-aligned codes carry keep on tuser low bits.
//     Profile keep modes are listed in `bch_encoder_axis4.sv`.
//   - The decoder emits k corrected data bits per n-bit block; parity is
//     consumed, not forwarded. tid and tdest are captured from the block's
//     first accepted beat and held across the beats it produces.
//   - out_status_* are valid with THIS module's m_axis_tlast, not the core's
//     internal one. They are re-registered on the core's last output beat and
//     held, because the outlet skid delays the data past the point where the
//     core's status is still valid. A consumer sampling at m_axis_tlast gets
//     the verdict for the block that just ended.
module bch_decoder_axis4
    import bch_pkg::*;
#(
    parameter int FIELD_DIM     = bch_pkg::FIELD_DIM,
    parameter int PRIM_POLY     = bch_pkg::PRIM_POLY,
    parameter int T_BITS        = bch_pkg::T_BITS,
    parameter int N_BITS        = bch_pkg::N_BITS,
    parameter int FIRST_ROOT    = bch_pkg::FIRST_ROOT,
    parameter int BITS_PER_BEAT = bch_pkg::BITS_PER_BEAT,
    // derived, exposed for the consumer's convenience
    parameter int K_BITS        = N_BITS - bch_degree_g(FIELD_DIM, PRIM_POLY, T_BITS, FIRST_ROOT),
    parameter int SKID_DEPTH    = 2,
    parameter int AXIS_ID_WIDTH = 0,
    parameter int AXIS_DEST_WIDTH = 0,
    // Default is BITS_PER_BEAT so the package default (n=63, non-byte-aligned)
    // can carry per-bit keep on tuser without an explicit override.
    parameter int AXIS_USER_WIDTH = BITS_PER_BEAT,
    // zero-width AXIS sidebands still need a 1-bit wire
    parameter int IW            = (AXIS_ID_WIDTH   > 0) ? AXIS_ID_WIDTH   : 1,
    parameter int DESTW         = (AXIS_DEST_WIDTH > 0) ? AXIS_DEST_WIDTH : 1,
    parameter int UW            = (AXIS_USER_WIDTH > 0) ? AXIS_USER_WIDTH : 1
) (
    input  logic                       aclk,
    input  logic                       aresetn,

    // received codeword bits in
    input  logic [BITS_PER_BEAT-1:0]   s_axis_tdata,
    input  logic [BITS_PER_BEAT/8-1:0] s_axis_tstrb,
    input  logic                       s_axis_tlast,
    input  logic [IW-1:0]              s_axis_tid,
    input  logic [DESTW-1:0]           s_axis_tdest,
    input  logic [UW-1:0]              s_axis_tuser,
    input  logic                       s_axis_tvalid,
    output logic                       s_axis_tready,

    // corrected data bits out: k beats per block
    output logic [BITS_PER_BEAT-1:0]   m_axis_tdata,
    output logic [BITS_PER_BEAT/8-1:0] m_axis_tstrb,
    output logic                       m_axis_tlast,
    output logic [IW-1:0]              m_axis_tid,
    output logic [DESTW-1:0]           m_axis_tdest,
    output logic [UW-1:0]              m_axis_tuser,
    output logic                       m_axis_tvalid,
    input  logic                       m_axis_tready,

    // per-block verdict, valid with m_axis_tlast
    output logic                       out_status_ok,
    output logic [$clog2(T_BITS+1)-1:0] out_status_corrected,
    output logic                       out_status_uncorrectable,
    output logic                       out_status_frame_err
);

    localparam int B  = BITS_PER_BEAT;
    localparam int SW = BITS_PER_BEAT / 8;
    localparam int StatusW = $clog2(T_BITS + 1);

    // Byte-aligned codes can use tstrb; everything else needs per-bit keep.
    localparam bit KeepByteAligned = (K_BITS % 8 == 0) && (N_BITS % 8 == 0);

    initial begin : g_param_check
        if (B > K_BITS)
            $fatal(1, "bch_decoder_axis4: BITS_PER_BEAT %0d exceeds K_BITS %0d",
                   B, K_BITS);
        if (KeepByteAligned && (B % 8 != 0))
            $fatal(1, "bch_decoder_axis4: byte-aligned mode needs B multiple of 8 (%0d)", B);
        if (!KeepByteAligned && AXIS_USER_WIDTH < B)
            $fatal(1, "bch_decoder_axis4: tuser mode needs USER_WIDTH >= B (%0d/%0d)",
                   B, AXIS_USER_WIDTH);
    end

    // Boundary reset synchronization. The port aresetn is treated as an
    // asynchronous-assert input of unknown deassert quality: an N=3
    // reset_sync (rtl/cdc, formally proven) produces the internal reset
    // every block below sees.
    logic w_aresetn;
    reset_sync #(
        .N             (3),
        .KEEP_ATTRS    (1'b1),
        .IN_ACTIVE_LOW (1'b1),
        .OUT_ACTIVE_LOW(1'b1),
        .ASYNC_ASSERT  (1'b1)
    ) u_reset_sync (
        .clk        (aclk),
        .rst_n      (aresetn),
        .sync_rst_n (w_aresetn)
    );

    // -------------------------------------------------------------------------
    // intake skid
    // -------------------------------------------------------------------------
    logic [BITS_PER_BEAT-1:0] in_tdata;
    logic [SW-1:0]            in_tstrb;
    logic                     in_tlast, in_tvalid, in_tready;
    logic [IW-1:0]            in_tid;
    logic [DESTW-1:0]         in_tdest;
    logic [UW-1:0]            in_tuser;

    /* verilator lint_off PINCONNECTEMPTY */
    axis4_slave #(
        .SKID_DEPTH(SKID_DEPTH), .AXIS_DATA_WIDTH(BITS_PER_BEAT),
        .AXIS_ID_WIDTH(AXIS_ID_WIDTH), .AXIS_DEST_WIDTH(AXIS_DEST_WIDTH),
        .AXIS_USER_WIDTH(AXIS_USER_WIDTH)
    ) u_in (
        .aclk(aclk), .aresetn(w_aresetn),
        .s_axis_tdata(s_axis_tdata), .s_axis_tstrb(s_axis_tstrb),
        .s_axis_tlast(s_axis_tlast), .s_axis_tid(s_axis_tid),
        .s_axis_tdest(s_axis_tdest), .s_axis_tuser(s_axis_tuser),
        .s_axis_tvalid(s_axis_tvalid), .s_axis_tready(s_axis_tready),
        .fub_axis_tdata(in_tdata), .fub_axis_tstrb(in_tstrb),
        .fub_axis_tlast(in_tlast), .fub_axis_tid(in_tid),
        .fub_axis_tdest(in_tdest), .fub_axis_tuser(in_tuser),
        .fub_axis_tvalid(in_tvalid), .fub_axis_tready(in_tready),
        .busy());
    /* verilator lint_on PINCONNECTEMPTY */

    // -------------------------------------------------------------------------
    // keep mapping: AXI4-Stream sideband -> core per-bit keep
    // -------------------------------------------------------------------------
    logic [B-1:0] w_in_keep;

    if (KeepByteAligned) begin : g_keep_in_strb
        always_comb begin
            w_in_keep = '0;
            for (int u = 0; u < SW; u++) begin
                if (in_tstrb[u])
                    w_in_keep[u*8 +: 8] = {8{1'b1}};
            end
        end
    end else begin : g_keep_in_user
        assign w_in_keep = in_tuser[B-1:0];
    end

    // -------------------------------------------------------------------------
    // the decoder core
    // -------------------------------------------------------------------------
    logic [B-1:0]     core_data;
    logic [B-1:0]     core_keep;
    logic             core_last, core_valid, core_ready;
    logic             w_core_ok, w_core_unc, w_core_frame;
    logic [StatusW-1:0] w_core_corr;

    bch_decoder_core #(
        .FIELD_DIM(FIELD_DIM), .PRIM_POLY(PRIM_POLY), .T_BITS(T_BITS),
        .N_BITS(N_BITS), .BITS_PER_BEAT(BITS_PER_BEAT),
        .FIRST_ROOT(FIRST_ROOT), .K_BITS(K_BITS)
    ) u_core (
        .aclk(aclk), .aresetn(w_aresetn),
        .in_valid(in_tvalid), .in_ready(in_tready), .in_data(in_tdata),
        .in_keep(w_in_keep), .in_last(in_tlast),
        .out_valid(core_valid), .out_ready(core_ready), .out_data(core_data),
        .out_keep(core_keep), .out_last(core_last),
        .out_status_ok(w_core_ok), .out_status_corrected(w_core_corr),
        .out_status_uncorrectable(w_core_unc),
        .out_status_frame_err(w_core_frame));

    // Realign the verdict to THIS module's tlast.
    logic                  r_ok, r_unc, r_frame;
    logic [StatusW-1:0]   r_corr;

    always_ff @(posedge aclk or negedge w_aresetn) begin
        if (!w_aresetn) begin
            r_ok <= 1'b0; r_unc <= 1'b0; r_frame <= 1'b0; r_corr <= '0;
        end else if (core_valid && core_ready && core_last) begin
            r_ok    <= w_core_ok;
            r_unc   <= w_core_unc;
            r_frame <= w_core_frame;
            r_corr  <= w_core_corr;
        end
    end

    assign out_status_ok            = r_ok;
    assign out_status_corrected     = r_corr;
    assign out_status_uncorrectable = r_unc;
    assign out_status_frame_err     = r_frame;

    // -------------------------------------------------------------------------
    // id / dest passthrough: captured on the block's first accepted beat and
    // held until its last corrected beat leaves. A block enters as n beats and
    // leaves as k, so these cannot ride the datapath.
    // -------------------------------------------------------------------------
    logic [IW-1:0]    r_tid;
    logic [DESTW-1:0] r_tdest;
    logic             r_have;

    always_ff @(posedge aclk or negedge w_aresetn) begin
        if (!w_aresetn) begin
            r_tid <= '0; r_tdest <= '0; r_have <= 1'b0;
        end else begin
            if (in_tvalid && in_tready && !r_have) begin
                r_tid <= in_tid; r_tdest <= in_tdest; r_have <= 1'b1;
            end
            if (core_valid && core_ready && core_last) r_have <= 1'b0;
        end
    end

    // -------------------------------------------------------------------------
    // keep mapping: core per-bit keep -> AXI4-Stream sideband
    // -------------------------------------------------------------------------
    logic [SW-1:0] w_out_tstrb;
    logic [UW-1:0] w_out_tuser;

    if (KeepByteAligned) begin : g_keep_out_strb
        always_comb begin
            w_out_tuser = '0;
            w_out_tstrb = '0;
            for (int u = 0; u < SW; u++) begin
                w_out_tstrb[u] = &core_keep[u*8 +: 8];
            end
        end
    end else begin : g_keep_out_user
        always_comb begin
            w_out_tstrb = {SW{1'b1}};
            w_out_tuser = '0;
            w_out_tuser[B-1:0] = core_keep;
        end
    end

    // -------------------------------------------------------------------------
    // outlet skid
    // -------------------------------------------------------------------------
    /* verilator lint_off PINCONNECTEMPTY */
    axis4_master #(
        .SKID_DEPTH(SKID_DEPTH), .AXIS_DATA_WIDTH(BITS_PER_BEAT),
        .AXIS_ID_WIDTH(AXIS_ID_WIDTH), .AXIS_DEST_WIDTH(AXIS_DEST_WIDTH),
        .AXIS_USER_WIDTH(AXIS_USER_WIDTH)
    ) u_out (
        .aclk(aclk), .aresetn(w_aresetn),
        .fub_axis_tdata(core_data), .fub_axis_tstrb(w_out_tstrb),
        .fub_axis_tlast(core_last), .fub_axis_tid(r_tid),
        .fub_axis_tdest(r_tdest), .fub_axis_tuser(w_out_tuser),
        .fub_axis_tvalid(core_valid), .fub_axis_tready(core_ready),
        .m_axis_tdata(m_axis_tdata), .m_axis_tstrb(m_axis_tstrb),
        .m_axis_tlast(m_axis_tlast), .m_axis_tid(m_axis_tid),
        .m_axis_tdest(m_axis_tdest), .m_axis_tuser(m_axis_tuser),
        .m_axis_tvalid(m_axis_tvalid), .m_axis_tready(m_axis_tready),
        .busy());
    /* verilator lint_on PINCONNECTEMPTY */

endmodule

// SPDX-License-Identifier: MIT
// SPDX-FileCopyrightText: 2026 sean galloway
//
// Module: bch_encoder_axi4
// Description: Binary BCH encoder as an AXI4 memory-to-memory job engine.
//
//   The AXI4 counterpart to bch_encoder_axis4: a job names a source address,
//   a destination address and a BLOCK COUNT, and the block reads k data bits
//   per block, encodes, and writes the n-bit codewords out.
//
//   bch_axi4_read_engine feeds the core and bch_axi4_write_engine drains it,
//   both on the one AXI4 master port -- the read and write channel sets are
//   independent, so nothing arbitrates between them.
//
//   The job is in BLOCKS, not bytes. A codec's unit of work is a block; the
//   source and destination beat counts differ by construction (k in, n out).
//
// Parameters:
//   FIELD_DIM / PRIM_POLY / T_BITS / N_BITS / FIRST_ROOT
//                    the code, exactly as bch_encoder_core takes them
//   DATA_WIDTH       AXI and stream width; also the BCH bits per beat
//   ADDR_WIDTH       AXI address width
//   ID_WIDTH         AXI id width
//   MAX_OUTSTANDING  requests in flight per direction
//
// Notes:
//   - A codeword is written PACKED: exactly ceil(N/B) beats with any partial
//     one last, which is bch_decoder_core's in_keep contract. The core starts
//     parity on a fresh beat, so at K % B != 0 its output carries a partial
//     beat mid-codeword that a decoder flags as mis-framed. bch_beat_packer
//     closes that up, and is omitted when there is nothing to pack.
//   - in_keep is generated here, because the read engine deals in beats and
//     knows nothing about bits. Full on every beat except a block's last,
//     which carries K_TAIL bits when k does not fill its final beat.
//   - The write side writes whole beats. A partial final beat's unused lanes
//     carry whatever the core emitted; the consumer knows the bit count from
//     the profile and the block count.
//   - cfg_done is the WRITE engine's done ANDed with the read's.
module bch_encoder_axi4
    import bch_pkg::bch_beats;
    import bch_pkg::bch_degree_g;
#(
    parameter int FIELD_DIM     = bch_pkg::FIELD_DIM,
    parameter int PRIM_POLY     = bch_pkg::PRIM_POLY,
    parameter int T_BITS        = bch_pkg::T_BITS,
    parameter int N_BITS        = bch_pkg::N_BITS,
    parameter int FIRST_ROOT    = bch_pkg::FIRST_ROOT,
    parameter int DATA_WIDTH    = bch_pkg::BITS_PER_BEAT,
    parameter int ADDR_WIDTH    = 32,
    parameter int ID_WIDTH      = 4,
    parameter int MAX_OUTSTANDING = 4,
    parameter int USER_WIDTH    = 1,
    // derived, exposed for the consumer's convenience
    parameter int K_BITS        = N_BITS - bch_degree_g(FIELD_DIM, PRIM_POLY, T_BITS, FIRST_ROOT),
    parameter int BITS_PER_BEAT = DATA_WIDTH
) (
    input  logic                    aclk,
    input  logic                    aresetn,

    // -- job -----------------------------------------------------------------
    input  logic                    cfg_start,          // one-cycle pulse
    input  logic [ADDR_WIDTH-1:0]   cfg_src_addr,
    input  logic [ADDR_WIDTH-1:0]   cfg_dst_addr,
    input  logic [15:0]             cfg_blocks,
    input  logic [7:0]              cfg_burst_len,
    input  logic [ID_WIDTH-1:0]     cfg_axi_id,
    output logic                    cfg_done,
    output logic                    resp_err,           // sticky, either direction
    output logic                    frame_err,          // sticky: a short/long block

    // -- AXI4 master: read channels ------------------------------------------
    output logic [ID_WIDTH-1:0]     m_axi_arid,
    output logic [ADDR_WIDTH-1:0]   m_axi_araddr,
    output logic [7:0]              m_axi_arlen,
    output logic [2:0]              m_axi_arsize,
    output logic [1:0]              m_axi_arburst,
    output logic                    m_axi_arlock,
    output logic [3:0]              m_axi_arcache,
    output logic [2:0]              m_axi_arprot,
    output logic [3:0]              m_axi_arqos,
    output logic [3:0]              m_axi_arregion,
    output logic [USER_WIDTH-1:0]   m_axi_aruser,
    output logic                    m_axi_arvalid,
    input  logic                    m_axi_arready,
    input  logic [ID_WIDTH-1:0]     m_axi_rid,
    input  logic [DATA_WIDTH-1:0]   m_axi_rdata,
    input  logic [1:0]              m_axi_rresp,
    input  logic                    m_axi_rlast,
    input  logic [USER_WIDTH-1:0]   m_axi_ruser,
    input  logic                    m_axi_rvalid,
    output logic                    m_axi_rready,

    // -- AXI4 master: write channels -----------------------------------------
    output logic [ID_WIDTH-1:0]     m_axi_awid,
    output logic [ADDR_WIDTH-1:0]   m_axi_awaddr,
    output logic [7:0]              m_axi_awlen,
    output logic [2:0]              m_axi_awsize,
    output logic [1:0]              m_axi_awburst,
    output logic                    m_axi_awlock,
    output logic [3:0]              m_axi_awcache,
    output logic [2:0]              m_axi_awprot,
    output logic [3:0]              m_axi_awqos,
    output logic [3:0]              m_axi_awregion,
    output logic [USER_WIDTH-1:0]   m_axi_awuser,
    output logic                    m_axi_awvalid,
    input  logic                    m_axi_awready,
    output logic [DATA_WIDTH-1:0]   m_axi_wdata,
    output logic [DATA_WIDTH/8-1:0] m_axi_wstrb,
    output logic                    m_axi_wlast,
    output logic [USER_WIDTH-1:0]   m_axi_wuser,
    output logic                    m_axi_wvalid,
    input  logic                    m_axi_wready,
    input  logic [ID_WIDTH-1:0]     m_axi_bid,
    input  logic [1:0]              m_axi_bresp,
    input  logic [USER_WIDTH-1:0]   m_axi_buser,
    input  logic                    m_axi_bvalid,
    output logic                    m_axi_bready
);

    localparam int B        = BITS_PER_BEAT;
    localparam int K_BEATS  = bch_beats(K_BITS, B);
    localparam int K_TAIL   = K_BITS % B;             // 0 = the last data beat is full
    localparam int SIZE_B   = $clog2(DATA_WIDTH / 8); // AXI axsize

    // A codeword leaves this module PACKED: exactly ceil(N/B) beats, with any
    // partial one last. That is bch_decoder_core's in_keep contract.
    localparam int CW_BEATS = bch_beats(N_BITS, B);

    // The core emits its data phase then starts parity on a FRESH beat, so at
    // K % B != 0 its output carries a partial beat MID-codeword, which a
    // decoder rejects. bch_beat_packer closes that up.
    localparam bit NEED_PACK = (K_TAIL != 0);

    if (B < 1 || B > K_BITS) begin : g_check_b
        $fatal(1, "bch_encoder_axi4: BITS_PER_BEAT %0d out of range 1..K (%0d)", B, K_BITS);
    end

    if (DATA_WIDTH != B) begin : g_check_dw
        $fatal(1, "bch_encoder_axi4: DATA_WIDTH %0d must equal BITS_PER_BEAT %0d", DATA_WIDTH, B);
    end

    // Boundary reset synchronization. The port aresetn is treated as an
    // asynchronous-assert input of unknown deassert quality: an N=3
    // reset_sync (rtl/cdc, formally proven) produces the internal reset
    // every block below sees.
    logic w_aresetn;
    reset_sync #(
        .N             (3),
        .KEEP_ATTRS    (1'b1),
        .IN_ACTIVE_LOW (1'b1),
        .OUT_ACTIVE_LOW(1'b1),
        .ASYNC_ASSERT  (1'b1)
    ) u_reset_sync (
        .clk        (aclk),
        .rst_n      (aresetn),
        .sync_rst_n (w_aresetn)
    );

    // =========================================================================
    // source: k data beats per block
    // =========================================================================
    logic                  rd_valid, rd_ready, rd_last, rd_done, rd_err;
    logic [DATA_WIDTH-1:0] rd_data;

    rs_axi4_read_engine #(
        .ADDR_WIDTH(ADDR_WIDTH), .DATA_WIDTH(DATA_WIDTH), .ID_WIDTH(ID_WIDTH),
        .MAX_OUTSTANDING(MAX_OUTSTANDING), .USER_WIDTH(USER_WIDTH)
    ) u_rd (
        .aclk(aclk), .aresetn(w_aresetn),
        .cfg_start(cfg_start), .cfg_src_addr(cfg_src_addr),
        .cfg_beats(32'(cfg_blocks) * 32'(K_BEATS)),
        .cfg_burst_len(cfg_burst_len), .cfg_beats_per_block(16'(K_BEATS)),
        .cfg_axi_id(cfg_axi_id), .cfg_axi_size(3'(SIZE_B)),
        .cfg_done(rd_done), .resp_err(rd_err),
        .out_valid(rd_valid), .out_ready(rd_ready), .out_data(rd_data), .out_last(rd_last),
        .m_axi_arid(m_axi_arid), .m_axi_araddr(m_axi_araddr), .m_axi_arlen(m_axi_arlen),
        .m_axi_arsize(m_axi_arsize), .m_axi_arburst(m_axi_arburst),
        .m_axi_arlock(m_axi_arlock), .m_axi_arcache(m_axi_arcache),
        .m_axi_arprot(m_axi_arprot), .m_axi_arqos(m_axi_arqos),
        .m_axi_arregion(m_axi_arregion), .m_axi_aruser(m_axi_aruser),
        .m_axi_arvalid(m_axi_arvalid), .m_axi_arready(m_axi_arready),
        .m_axi_rid(m_axi_rid), .m_axi_rdata(m_axi_rdata), .m_axi_rresp(m_axi_rresp),
        .m_axi_rlast(m_axi_rlast), .m_axi_ruser(m_axi_ruser),
        .m_axi_rvalid(m_axi_rvalid), .m_axi_rready(m_axi_rready));

    // The read engine counts beats; bits are this module's business. Only a
    // block's LAST data beat can be partial, and only when k does not fill it.
    logic [B-1:0] w_in_keep;
    assign w_in_keep = (rd_last && (K_TAIL != 0)) ? B'((1 << K_TAIL) - 1) : {B{1'b1}};

    // =========================================================================
    // the codec
    // =========================================================================
    logic                  enc_valid, enc_ready, enc_last, w_frame_err;
    logic [DATA_WIDTH-1:0] enc_data;
    logic [B-1:0]          enc_keep;

    bch_encoder_core #(
        .FIELD_DIM(FIELD_DIM), .PRIM_POLY(PRIM_POLY), .T_BITS(T_BITS),
        .N_BITS(N_BITS), .BITS_PER_BEAT(B), .FIRST_ROOT(FIRST_ROOT),
        .K_BITS(K_BITS)
    ) u_core (
        .aclk(aclk), .aresetn(w_aresetn),
        .in_valid(rd_valid), .in_ready(rd_ready), .in_data(rd_data),
        .in_keep(w_in_keep), .in_last(rd_last),
        .out_valid(enc_valid), .out_ready(enc_ready), .out_data(enc_data),
        .out_keep(enc_keep), .out_last(enc_last),
        .frame_err(w_frame_err));

    // =========================================================================
    // repack, when the core's layout is not already decoder-legal
    // =========================================================================
    logic                  pk_valid, pk_ready, pk_last;
    logic [DATA_WIDTH-1:0] pk_data;
    logic [B-1:0]          pk_keep;

    if (NEED_PACK) begin : g_pack
        bch_beat_packer #(
            .BITS_PER_BEAT(B)
        ) u_pack (
            .aclk(aclk), .aresetn(w_aresetn),
            .in_valid(enc_valid), .in_ready(enc_ready), .in_data(enc_data),
            .in_keep(enc_keep), .in_last(enc_last),
            .out_valid(pk_valid), .out_ready(pk_ready), .out_data(pk_data),
            .out_keep(pk_keep), .out_last(pk_last));
    end else begin : g_no_pack
        assign pk_valid  = enc_valid;
        assign enc_ready = pk_ready;
        assign pk_data   = enc_data;
        assign pk_keep   = enc_keep;
        assign pk_last   = enc_last;
    end

    // =========================================================================
    // destination: a codeword per block
    // =========================================================================
    logic wr_done, wr_err;

    rs_axi4_write_engine #(
        .ADDR_WIDTH(ADDR_WIDTH), .DATA_WIDTH(DATA_WIDTH), .ID_WIDTH(ID_WIDTH),
        .MAX_OUTSTANDING(MAX_OUTSTANDING), .USER_WIDTH(USER_WIDTH)
    ) u_wr (
        .aclk(aclk), .aresetn(w_aresetn),
        .cfg_start(cfg_start), .cfg_dst_addr(cfg_dst_addr),
        .cfg_beats(32'(cfg_blocks) * 32'(CW_BEATS)),
        .cfg_burst_len(cfg_burst_len), .cfg_axi_id(cfg_axi_id),
        .cfg_axi_size(3'(SIZE_B)),
        .cfg_done(wr_done), .resp_err(wr_err),
        .in_valid(pk_valid), .in_ready(pk_ready), .in_data(pk_data), .in_last(pk_last),
        .m_axi_awid(m_axi_awid), .m_axi_awaddr(m_axi_awaddr), .m_axi_awlen(m_axi_awlen),
        .m_axi_awsize(m_axi_awsize), .m_axi_awburst(m_axi_awburst),
        .m_axi_awlock(m_axi_awlock), .m_axi_awcache(m_axi_awcache),
        .m_axi_awprot(m_axi_awprot), .m_axi_awqos(m_axi_awqos),
        .m_axi_awregion(m_axi_awregion), .m_axi_awuser(m_axi_awuser),
        .m_axi_awvalid(m_axi_awvalid), .m_axi_awready(m_axi_awready),
        .m_axi_wdata(m_axi_wdata), .m_axi_wstrb(m_axi_wstrb), .m_axi_wlast(m_axi_wlast),
        .m_axi_wuser(m_axi_wuser), .m_axi_wvalid(m_axi_wvalid), .m_axi_wready(m_axi_wready),
        .m_axi_bid(m_axi_bid), .m_axi_bresp(m_axi_bresp), .m_axi_buser(m_axi_buser),
        .m_axi_bvalid(m_axi_bvalid), .m_axi_bready(m_axi_bready));

    // =========================================================================
    // job status
    // =========================================================================
    assign cfg_done = rd_done && wr_done;
    assign resp_err = rd_err || wr_err;

    // frame_err is a pulse from the core; hold it for the job so a host that
    // polls after cfg_done still sees it
    always_ff @(posedge aclk or negedge w_aresetn) begin
        if (!w_aresetn)          frame_err <= 1'b0;
        else if (cfg_start)      frame_err <= 1'b0;
        else if (w_frame_err)    frame_err <= 1'b1;
    end

    // the packed stream reports keep; the write side writes whole beats
    logic unused_e;
    assign unused_e = ^pk_keep;

endmodule

// SPDX-License-Identifier: MIT
// SPDX-FileCopyrightText: 2026 sean galloway
//
// Module: bch_encoder_axis4
// Description: Binary BCH systematic encoder with AXI4-Stream interfaces.
//
//   This is the component's integration top (TASK-006). `bch_encoder_core`
//   speaks a bare valid/ready/last handshake, which is the right interface for
//   the algorithm but the wrong one for a fabric. This wraps it in the house
//   `axis4_slave` / `axis4_master` skid wrappers so a consumer connects a
//   stream, not ten renamed wires.
//
// Parameters:
//   FIELD_DIM       GF(2^m) field dimension, m
//   PRIM_POLY       primitive polynomial of degree m, as an integer
//   T_BITS          t, correctable bit errors per block
//   N_BITS          n, codeword length in bits
//   FIRST_ROOT      b in g(x) = lcm of minimal polynomials of alpha^b ..
//                   alpha^(b+2t-1)
//   BITS_PER_BEAT   B, the AXI4-Stream beat width; also the core's in_data/
//                   out_data width
//   SKID_DEPTH      depth of the two AXIS skid buffers, 2..8
//   AXIS_*_WIDTH    tid / tdest / tuser widths, captured and held per block
//
// Notes:
//   - tstrb vs keep. The core's `keep` is PER BIT; AXI4-Stream's tstrb is
//     PER BYTE. When K_BITS and N_BITS are both byte-aligned the core's keep
//     is guaranteed byte-aligned, so tstrb carries it (one strobe bit per byte,
//     high only when all eight keep bits in that byte are high). In that mode
//     tuser is driven to zero. When either K or N is not byte-aligned the keep
//     cannot be expressed per byte, so it rides the low BITS_PER_BEAT bits of
//     tuser and tstrb is driven all-ones -- the same rule the RS wrappers use
//     for non-byte-sized symbols.
//
//     Profile keep modes:
//       (m=6, n=63, k=56, B=8)  tuser mode  (63 is not byte-aligned)
//       (m=6, n=63, k=51, B=8)  tuser mode  (63 is not byte-aligned)
//       (m=13, n=4224, k=4120, B=8)  tstrb mode
//       (m=13, n=4224, k=4120, B=32) tstrb mode (k is not a multiple of B, so
//            the encoder emits a partial data-phase beat with tlast=0; the
//            keep is still byte-aligned and is carried faithfully by tstrb)
//   - No beat packer is instantiated. The BCH encoder core already places
//     partial beats only at the end of a phase (the final data beat and the
//     final parity beat). The wrapper preserves that beat layout and carries
//     the per-bit keep through the appropriate sideband.
//   - tid and tdest are captured from the block's FIRST accepted beat and held
//     until its last output beat leaves; parity beats carry the same id/dest.
module bch_encoder_axis4
    import bch_pkg::*;
#(
    parameter int FIELD_DIM     = bch_pkg::FIELD_DIM,
    parameter int PRIM_POLY     = bch_pkg::PRIM_POLY,
    parameter int T_BITS        = bch_pkg::T_BITS,
    parameter int N_BITS        = bch_pkg::N_BITS,
    parameter int FIRST_ROOT    = bch_pkg::FIRST_ROOT,
    parameter int BITS_PER_BEAT = bch_pkg::BITS_PER_BEAT,
    // derived, exposed for the consumer's convenience
    parameter int K_BITS        = N_BITS - bch_degree_g(FIELD_DIM, PRIM_POLY, T_BITS, FIRST_ROOT),
    parameter int SKID_DEPTH    = 2,
    parameter int AXIS_ID_WIDTH = 0,
    parameter int AXIS_DEST_WIDTH = 0,
    // Default is BITS_PER_BEAT so the package default (n=63, non-byte-aligned)
    // can carry per-bit keep on tuser without an explicit override.
    parameter int AXIS_USER_WIDTH = BITS_PER_BEAT,
    // zero-width AXIS sidebands still need a 1-bit wire
    parameter int IW            = (AXIS_ID_WIDTH   > 0) ? AXIS_ID_WIDTH   : 1,
    parameter int DESTW         = (AXIS_DEST_WIDTH > 0) ? AXIS_DEST_WIDTH : 1,
    parameter int UW            = (AXIS_USER_WIDTH > 0) ? AXIS_USER_WIDTH : 1
) (
    input  logic                       aclk,
    input  logic                       aresetn,

    // data bits in
    input  logic [BITS_PER_BEAT-1:0]   s_axis_tdata,
    input  logic [BITS_PER_BEAT/8-1:0] s_axis_tstrb,
    input  logic                       s_axis_tlast,
    input  logic [IW-1:0]              s_axis_tid,
    input  logic [DESTW-1:0]           s_axis_tdest,
    input  logic [UW-1:0]              s_axis_tuser,
    input  logic                       s_axis_tvalid,
    output logic                       s_axis_tready,

    // coded bits out: k data beats then the parity beats
    output logic [BITS_PER_BEAT-1:0]   m_axis_tdata,
    output logic [BITS_PER_BEAT/8-1:0] m_axis_tstrb,
    output logic                       m_axis_tlast,
    output logic [IW-1:0]              m_axis_tid,
    output logic [DESTW-1:0]           m_axis_tdest,
    output logic [UW-1:0]              m_axis_tuser,
    output logic                       m_axis_tvalid,
    input  logic                       m_axis_tready,

    // one-cycle pulse: a block ended with other than k data bits
    output logic                       frame_err
);

    localparam int B  = BITS_PER_BEAT;
    localparam int SW = BITS_PER_BEAT / 8;

    // Byte-aligned codes can use tstrb; everything else needs per-bit keep.
    localparam bit KeepByteAligned = (K_BITS % 8 == 0) && (N_BITS % 8 == 0);

    initial begin : g_param_check
        if (B > K_BITS)
            $fatal(1, "bch_encoder_axis4: BITS_PER_BEAT %0d exceeds K_BITS %0d",
                   B, K_BITS);
        if (KeepByteAligned && (B % 8 != 0))
            $fatal(1, "bch_encoder_axis4: byte-aligned mode needs B multiple of 8 (%0d)", B);
        if (!KeepByteAligned && AXIS_USER_WIDTH < B)
            $fatal(1, "bch_encoder_axis4: tuser mode needs USER_WIDTH >= B (%0d/%0d)",
                   B, AXIS_USER_WIDTH);
    end

    // Boundary reset synchronization. The port aresetn is treated as an
    // asynchronous-assert input of unknown deassert quality: an N=3
    // reset_sync (rtl/cdc, formally proven) produces the internal reset
    // every block below sees.
    logic w_aresetn;
    reset_sync #(
        .N             (3),
        .KEEP_ATTRS    (1'b1),
        .IN_ACTIVE_LOW (1'b1),
        .OUT_ACTIVE_LOW(1'b1),
        .ASYNC_ASSERT  (1'b1)
    ) u_reset_sync (
        .clk        (aclk),
        .rst_n      (aresetn),
        .sync_rst_n (w_aresetn)
    );

    // -------------------------------------------------------------------------
    // intake skid
    // -------------------------------------------------------------------------
    logic [BITS_PER_BEAT-1:0] in_tdata;
    logic [SW-1:0]            in_tstrb;
    logic                     in_tlast, in_tvalid, in_tready;
    logic [IW-1:0]            in_tid;
    logic [DESTW-1:0]         in_tdest;
    logic [UW-1:0]            in_tuser;

    /* verilator lint_off PINCONNECTEMPTY */
    axis4_slave #(
        .SKID_DEPTH(SKID_DEPTH), .AXIS_DATA_WIDTH(BITS_PER_BEAT),
        .AXIS_ID_WIDTH(AXIS_ID_WIDTH), .AXIS_DEST_WIDTH(AXIS_DEST_WIDTH),
        .AXIS_USER_WIDTH(AXIS_USER_WIDTH)
    ) u_in (
        .aclk(aclk), .aresetn(w_aresetn),
        .s_axis_tdata(s_axis_tdata), .s_axis_tstrb(s_axis_tstrb),
        .s_axis_tlast(s_axis_tlast), .s_axis_tid(s_axis_tid),
        .s_axis_tdest(s_axis_tdest), .s_axis_tuser(s_axis_tuser),
        .s_axis_tvalid(s_axis_tvalid), .s_axis_tready(s_axis_tready),
        .fub_axis_tdata(in_tdata), .fub_axis_tstrb(in_tstrb),
        .fub_axis_tlast(in_tlast), .fub_axis_tid(in_tid),
        .fub_axis_tdest(in_tdest), .fub_axis_tuser(in_tuser),
        .fub_axis_tvalid(in_tvalid), .fub_axis_tready(in_tready),
        .busy());
    /* verilator lint_on PINCONNECTEMPTY */

    // -------------------------------------------------------------------------
    // keep mapping: AXI4-Stream sideband -> core per-bit keep
    // -------------------------------------------------------------------------
    logic [B-1:0] w_in_keep;

    if (KeepByteAligned) begin : g_keep_in_strb
        always_comb begin
            w_in_keep = '0;
            for (int u = 0; u < SW; u++) begin
                if (in_tstrb[u])
                    w_in_keep[u*8 +: 8] = {8{1'b1}};
            end
        end
    end else begin : g_keep_in_user
        assign w_in_keep = in_tuser[B-1:0];
    end

    // -------------------------------------------------------------------------
    // the encoder core
    // -------------------------------------------------------------------------
    logic [B-1:0] core_data;
    logic [B-1:0] core_keep;
    logic         core_last, core_valid, core_ready;
    logic         core_frame_err;

    bch_encoder_core #(
        .FIELD_DIM(FIELD_DIM), .PRIM_POLY(PRIM_POLY), .T_BITS(T_BITS),
        .N_BITS(N_BITS), .BITS_PER_BEAT(BITS_PER_BEAT),
        .FIRST_ROOT(FIRST_ROOT), .K_BITS(K_BITS),
        .SKID_DEPTH(SKID_DEPTH)
    ) u_core (
        .aclk(aclk), .aresetn(w_aresetn),
        .in_valid(in_tvalid), .in_ready(in_tready), .in_data(in_tdata),
        .in_keep(w_in_keep), .in_last(in_tlast),
        .out_valid(core_valid), .out_ready(core_ready), .out_data(core_data),
        .out_keep(core_keep), .out_last(core_last),
        .frame_err(core_frame_err));

    assign frame_err = core_frame_err;

    // -------------------------------------------------------------------------
    // id / dest passthrough: captured on the block's first accepted beat and
    // held until its last output beat leaves. A block leaves as more beats
    // than it entered as, so these cannot ride the datapath.
    // -------------------------------------------------------------------------
    logic [IW-1:0]    r_tid;
    logic [DESTW-1:0] r_tdest;
    logic             r_have;

    always_ff @(posedge aclk or negedge w_aresetn) begin
        if (!w_aresetn) begin
            r_tid <= '0; r_tdest <= '0; r_have <= 1'b0;
        end else begin
            if (in_tvalid && in_tready && !r_have) begin
                r_tid <= in_tid; r_tdest <= in_tdest; r_have <= 1'b1;
            end
            if (core_valid && core_ready && core_last) r_have <= 1'b0;
        end
    end

    // -------------------------------------------------------------------------
    // keep mapping: core per-bit keep -> AXI4-Stream sideband
    // -------------------------------------------------------------------------
    logic [SW-1:0] w_out_tstrb;
    logic [UW-1:0] w_out_tuser;

    if (KeepByteAligned) begin : g_keep_out_strb
        always_comb begin
            w_out_tuser = '0;
            w_out_tstrb = '0;
            for (int u = 0; u < SW; u++) begin
                w_out_tstrb[u] = &core_keep[u*8 +: 8];
            end
        end
    end else begin : g_keep_out_user
        always_comb begin
            w_out_tstrb = {SW{1'b1}};
            w_out_tuser = '0;
            w_out_tuser[B-1:0] = core_keep;
        end
    end

    // -------------------------------------------------------------------------
    // outlet skid
    // -------------------------------------------------------------------------
    /* verilator lint_off PINCONNECTEMPTY */
    axis4_master #(
        .SKID_DEPTH(SKID_DEPTH), .AXIS_DATA_WIDTH(BITS_PER_BEAT),
        .AXIS_ID_WIDTH(AXIS_ID_WIDTH), .AXIS_DEST_WIDTH(AXIS_DEST_WIDTH),
        .AXIS_USER_WIDTH(AXIS_USER_WIDTH)
    ) u_out (
        .aclk(aclk), .aresetn(w_aresetn),
        .fub_axis_tdata(core_data), .fub_axis_tstrb(w_out_tstrb),
        .fub_axis_tlast(core_last), .fub_axis_tid(r_tid),
        .fub_axis_tdest(r_tdest), .fub_axis_tuser(w_out_tuser),
        .fub_axis_tvalid(core_valid), .fub_axis_tready(core_ready),
        .m_axis_tdata(m_axis_tdata), .m_axis_tstrb(m_axis_tstrb),
        .m_axis_tlast(m_axis_tlast), .m_axis_tid(m_axis_tid),
        .m_axis_tdest(m_axis_tdest), .m_axis_tuser(m_axis_tuser),
        .m_axis_tvalid(m_axis_tvalid), .m_axis_tready(m_axis_tready),
        .busy());
    /* verilator lint_on PINCONNECTEMPTY */

endmodule

