// RTL Design Sherpa - Industry-Standard RTL Design and Verification
// https://github.com/sean-galloway/RTLDesignSherpa
//
// Module: cdc_open_loop
// Purpose: Open-loop multi-bit CDC using valid/data stretching.
//
// The source asserts src_valid for one cycle. The module captures the data
// and stretches the valid signal for STRETCH_CYCLES source clock cycles,
// holding data stable throughout. A multi-stage synchronizer in the
// destination domain samples the stretched valid and latches the data on
// the rising edge.
//
// The source data bus must remain stable long enough for the
// synchronized enable to propagate through the destination sync
// chain and load the destination register. That gives:
//
//   STRETCH_CYCLES >= ceil((SYNC_STAGES + 1) * T_dst / T_src)
//
// where T_dst and T_src are the destination and source clock
// periods. (SYNC_STAGES + 1) counts the sync FFs plus the load edge.
// Example: a 1 GHz source crossing to 100 MHz with SYNC_STAGES=2
// needs STRETCH_CYCLES >= ceil(3 * 10/1) = 30. The 1.5*T_dst rule of
// thumb is enough to capture the valid pulse alone, but the multi-bit
// data bus needs the longer hold so r_src_data is still stable when
// the destination latches it.
//
// This is a true open-loop design: no return path, no handshake, no
// backpressure. The source is busy for exactly STRETCH_CYCLES and then
// free to send again. If the destination misses the stretched valid
// (because STRETCH_CYCLES is too short), the transfer is silently lost.
//
// Use when:
//   - Clock ratio is known and fixed (or bounded)
//   - Destination is always ready (no flow control needed)
//   - Minimum area/complexity is desired
//   - Config registers, status updates, infrequent events
//
// For unknown/variable clock ratios, use cdc_2_phase_handshake (closed-loop).
// For streaming data, use fifo_async or gaxi_fifo_async.
//
// Documentation: docs/markdown/rtl-cdc/cdc.md#cdc_open_loop
// Subsystem: cdc
//
// Author: sean galloway
// Created: 2026-04-21
//
// ===========================================================================
// REQUIRED SDC CONSTRAINTS
// ---------------------------------------------------------------------------
//   # 1. Stretched valid (single-bit, synchronized by destination)
//   set_max_delay -datapath_only \
//       -from [get_pins u_cdc/r_src_valid_stretch_reg/C] \
//       -to   [get_pins u_cdc/u_valid_sync/q_reg[0]/D] \
//       <dst_period_ns>
//
//   # 2. Data bus (quasi-static, held for STRETCH_CYCLES src clocks)
//   set_max_delay -datapath_only \
//       -from [get_pins u_cdc/r_src_data_reg[*]/C] \
//       -to   [get_pins u_cdc/r_dst_data_reg[*]/D] \
//       <dst_period_ns>
//
// ===========================================================================

`timescale 1ns / 1ps

`include "reset_defs.svh"

module cdc_open_loop #(
    parameter int DATA_WIDTH     = 8,    // Width of the data bus
    parameter int STRETCH_CYCLES = 8,    // Source clocks to hold valid+data (manual default)
    parameter int SYNC_STAGES    = 2,    // Destination synchronizer depth (2-4)

    // ---- Auto-compute STRETCH_CYCLES from clock periods (opt-in) ----
    //
    // The destination needs at least (SYNC_STAGES + 1) dst-clock periods
    // to safely capture a stretched pulse. Required hold time:
    //
    //     STRETCH * src_period >= (SYNC_STAGES + 1) * dst_period
    //
    // Solved for STRETCH:
    //
    //     STRETCH = ceil((SYNC_STAGES + 1) * SRC_CLK_HZ / DST_CLK_HZ)
    //
    // To turn this on, set AUTO_STRETCH = 1 and provide SRC_CLK_HZ (the
    // FASTEST source clock you want handled safely; sources above this
    // start dropping pulses) and DST_CLK_HZ. When AUTO_STRETCH = 0
    // (default), the STRETCH_CYCLES parameter above is used verbatim —
    // no breaking change for existing callers.
    parameter int AUTO_STRETCH = 0,   // 0 = use STRETCH_CYCLES; 1 = auto-compute
    parameter int SRC_CLK_HZ   = 25_000_000,
    parameter int DST_CLK_HZ   = 100_000_000
) (
    // Source clock domain
    input  logic                  clk_src,      // Source domain clock
    input  logic                  rst_src_n,    // Source domain async reset (active low)
    input  logic                  src_valid,    // Single-cycle pulse: data is valid NOW
    input  logic [DATA_WIDTH-1:0] src_data,     // Data from source domain
    output logic                  src_busy,     // High during stretch (blocks next valid)

    // Destination clock domain
    input  logic                  clk_dst,      // Destination domain clock
    input  logic                  rst_dst_n,    // Destination domain async reset (active low)
    output logic                  dst_valid,    // Single-cycle pulse: data latched
    output logic [DATA_WIDTH-1:0] dst_data      // Latched data (stable until next dst_valid)
);

    // Auto-compute (elaboration time; folds to a literal in synth).
    localparam int STRETCH_AUTO_VAL =
        ((SYNC_STAGES + 1) * SRC_CLK_HZ + DST_CLK_HZ - 1) / DST_CLK_HZ;
    localparam int STRETCH_RAW   = (AUTO_STRETCH != 0) ? STRETCH_AUTO_VAL : STRETCH_CYCLES;
    // Clamp >= 1: STRETCH=0 would assert valid for zero cycles.
    localparam int STRETCH_EFF   = (STRETCH_RAW > 0) ? STRETCH_RAW : 1;

    // Counter width to hold the effective STRETCH.
    localparam int CTR_WIDTH = $clog2(STRETCH_EFF + 1);

    //=========================================================================
    // Source domain: capture data and stretch valid
    //=========================================================================
    // On src_valid (when not busy), capture data and assert r_src_valid_stretch
    // for STRETCH_CYCLES. Both data and stretched valid cross to the destination
    // as quasi-static signals.

    logic [DATA_WIDTH-1:0] r_src_data;
    logic                  r_src_valid_stretch;
    logic [CTR_WIDTH-1:0]  r_stretch_count;

    assign src_busy = (r_stretch_count != '0);

    `ALWAYS_FF_RST(clk_src, rst_src_n,
        if (`RST_ASSERTED(rst_src_n)) begin
            r_src_data          <= '0;
            r_src_valid_stretch <= 1'b0;
            r_stretch_count     <= '0;
        end else begin
            if (src_valid && !src_busy) begin
                // New transfer: capture data, start stretching
                r_src_data          <= src_data;
                r_src_valid_stretch <= 1'b1;
                r_stretch_count     <= CTR_WIDTH'(STRETCH_EFF);
            end else if (r_stretch_count != '0) begin
                // Counting down
                r_stretch_count <= r_stretch_count - 1'b1;
                if (r_stretch_count == CTR_WIDTH'(1)) begin
                    // Last cycle -- deassert stretched valid
                    r_src_valid_stretch <= 1'b0;
                end
            end
        end
    )

    //=========================================================================
    // Destination domain: synchronize stretched valid, edge-detect, latch data
    //=========================================================================
    // The stretched valid is a level signal held for many source clocks.
    // The multi-stage synchronizer resolves metastability. We detect the
    // rising edge of the synchronized valid and latch data on that edge.

    logic w_valid_sync;

    glitch_free_n_dff_arn #(
        .FLOP_COUNT (SYNC_STAGES),
        .WIDTH      (1)
    ) u_valid_sync (
        .clk   (clk_dst),
        .rst_n (rst_dst_n),
        .d     (r_src_valid_stretch),
        .q     (w_valid_sync)
    );

    // Rising edge detect on synchronized valid
    logic r_valid_sync_prev;

    wire w_valid_rise = w_valid_sync && !r_valid_sync_prev;

    `ALWAYS_FF_RST(clk_dst, rst_dst_n,
        if (`RST_ASSERTED(rst_dst_n)) begin
            r_valid_sync_prev <= 1'b0;
            dst_data          <= '0;
            dst_valid         <= 1'b0;
        end else begin
            r_valid_sync_prev <= w_valid_sync;
            dst_valid         <= w_valid_rise;
            if (w_valid_rise) begin
                dst_data <= r_src_data;
            end
        end
    )

endmodule : cdc_open_loop

// SPDX-License-Identifier: MIT
// SPDX-FileCopyrightText: 2024-2025 sean galloway
//
// RTL Design Sherpa - Industry-Standard RTL Design and Verification
// https://github.com/sean-galloway/RTLDesignSherpa
//
// Module: cdc_synchronizer
// Purpose: Multi-bit synchronizer for clock domain crossing
//
// This module provides a simple CDC synchronizer interface that wraps
// the glitch_free_n_dff_arn module for consistent naming across the
// AMBA infrastructure.
//
// Documentation: docs/markdown/rtl-cdc/cdc.md#cdc_synchronizer
// Subsystem: cdc
//
// Author: sean galloway
// Created: 2025-12-23

`timescale 1ns / 1ps

module cdc_synchronizer #(
    parameter int WIDTH      = 1,   // Bus width to synchronize
    parameter int FLOP_COUNT = 3    // Number of synchronizer stages (2-5)
) (
    input  logic             clk,       // Destination clock
    input  logic             rst_n,     // Asynchronous active-low reset
    input  logic [WIDTH-1:0] async_in,  // Asynchronous input from source domain
    output logic [WIDTH-1:0] sync_out   // Synchronized output in destination domain
);

    // Use the glitch_free_n_dff_arn module for the actual synchronization
    glitch_free_n_dff_arn #(
        .FLOP_COUNT (FLOP_COUNT),
        .WIDTH      (WIDTH)
    ) u_sync (
        .clk   (clk),
        .rst_n (rst_n),
        .d     (async_in),
        .q     (sync_out)
    );

endmodule : cdc_synchronizer

// SPDX-License-Identifier: MIT
// SPDX-FileCopyrightText: 2026 sean galloway
//
// RTL Design Sherpa - Industry-Standard RTL Design and Verification
// https://github.com/sean-galloway/RTLDesignSherpa
//
// Module: chi_link_rx
// Purpose: RXLINKACTIVEACK controller for the receive direction of a CHI
//          port: one LINKACTIVE pair covers every RX channel (B14.5)
//
// Documentation: docs/markdown/rtl-amba/chi/README.md
// Subsystem: amba
//
// The state is the {RXLINKACTIVEREQ, RXLINKACTIVEACK} pair (Table B14.1).
// RXLINKACTIVEREQ comes from the other component; it crosses through
// glitch_free_n_dff_arn (LINKACTIVE_SYNC_STAGES flops) and 0 stages is
// allowed for a known-synchronous system.
//
//   - ACTIVATE -> RUN: raise ACK when REQ is seen and cfg_rx_enable is set.
//     Credits are granted only in RUN (o_grant_ok); the receiver "must
//     assert LINKACTIVEACK and move to the RUN state before sending credits"
//     (Table B14.2).
//   - DEACTIVATE -> STOP: stop granting once the synchronized REQ is seen
//     low (o_grant_ok low); because of the synchronizer and the registered
//     LCRDV in chi_rx_channel, up to LINKACTIVE_SYNC_STAGES + 1 grants can
//     still leave after the pin fell. Table B14.2 permits that ("the
//     Receiver is permitted, but not required, to send credits when first
//     entering this state"; B14.5.1.1: it "could take some time to react");
//     the transmitter returns them. Flits still in flight are accepted by
//     the channels; ACK drops only when every channel reports its credits
//     home (i_all_returned), so the transmitter never sees ACK low while
//     it holds a credit.
//
// B14.6.3.4 ordering with this port's TX direction: RXACK rises only after
// TXREQ has risen (i_tx_req high) and falls only after TXREQ has fallen
// (i_tx_req low). chi_link_tx raises TXREQ when this direction leaves
// STOP, so a remote activation completes without the Protocol layer
// doing anything.
//
// cfg_rx_enable gates the activation only: once in RUN, credits flow until
// the link deactivates (a receiver must grant "in a timely manner" while
// the link is active, B14.2.1.1). The port top gives the same input to
// chi_link_tx, which will not start a handshake this side cannot finish.
//
// LINKACTIVE_SYNC_STAGES is 0 (known-synchronous system) or >= 2; the port
// top rejects 1 at elaboration. TXLINKACTIVEACK is sampled once in
// chi_link_tx: the pair is synchronous to CLK unless a clock-domain
// crossing bridge sits between the components (B14.7.1 says the same of
// SACTIVE), and that bridge, not this block, owns the synchronization.
//
// With LINK_CTRL = 0 credits are granted whenever cfg_rx_enable is set and
// ACK is tied low.
//
// Author: sean galloway
// Created: 2026-10-30

`timescale 1ns / 1ps

`include "reset_defs.svh"

module chi_link_rx
    import chi_pkg::*;
#(
    parameter bit LINK_CTRL             = 1'b1,
    parameter int LINKACTIVE_SYNC_STAGES = 2
) (
    input  logic       aclk,
    input  logic       aresetn,

    // Configuration
    input  logic       cfg_rx_enable,     // 0 = never acknowledge an activation (so never RUN)

    // From the channels and the transmit direction
    input  logic       i_all_returned,    // every RX channel has its credits home
    input  logic       i_tx_req,          // TXLINKACTIVEREQ this port drives

    // LINKACTIVE pair
    input  logic       i_req,             // RXLINKACTIVEREQ
    output logic       o_ack,             // RXLINKACTIVEACK

    // Direction state for the channels
    output logic       o_req_s,           // REQ in this clock domain (for chi_link_tx)
    output logic       o_grant_ok,        // channels may grant credits (RUN)
    output logic [1:0] o_state            // {REQ sampled, ACK}
);

    logic w_req_s;
    logic w_ack;

    if (LINK_CTRL) begin : g_link
        logic r_ack;

        if (LINKACTIVE_SYNC_STAGES >= 2) begin : g_sync
            glitch_free_n_dff_arn #(
                .FLOP_COUNT (LINKACTIVE_SYNC_STAGES),
                .WIDTH      (1)
            ) u_req_sync (
                .clk   (aclk),
                .rst_n (aresetn),
                .d     (i_req),
                .q     (w_req_s)
            );
        end else begin : g_nosync
            assign w_req_s = i_req;
        end

        `ALWAYS_FF_RST(aclk, aresetn,
            if (`RST_ASSERTED(aresetn)) begin
                r_ack <= 1'b0;
            end else begin
                if (w_req_s && !r_ack && cfg_rx_enable && i_tx_req)
                    r_ack <= 1'b1;                                   // ACTIVATE -> RUN
                else if (!w_req_s && r_ack && i_all_returned && !i_tx_req)
                    r_ack <= 1'b0;                                   // DEACTIVATE -> STOP
            end
        )

        assign w_ack      = r_ack;
        assign o_grant_ok = w_req_s && r_ack;
    end else begin : g_no_link
        assign w_req_s    = 1'b0;
        assign w_ack      = 1'b0;
        assign o_grant_ok = cfg_rx_enable;

        /* verilator lint_off UNUSEDSIGNAL */
        logic unused_link;
        assign unused_link = ^{aclk, aresetn, i_req, i_all_returned, i_tx_req};
        /* verilator lint_on UNUSEDSIGNAL */
    end

    assign o_ack   = w_ack;
    assign o_req_s = w_req_s;
    // Without link control the direction IS in RUN; the pins stay low but the
    // status says what the channels see
    assign o_state = LINK_CTRL ? {w_req_s, w_ack} : CHI_LINK_RUN;

endmodule : chi_link_rx

// SPDX-License-Identifier: MIT
// SPDX-FileCopyrightText: 2026 sean galloway
//
// RTL Design Sherpa - Industry-Standard RTL Design and Verification
// https://github.com/sean-galloway/RTLDesignSherpa
//
// Module: cxs_slave
// Purpose: CXS Receiver endpoint (Arm IHI 0079, Issues A-D): a credited CXS
//          link in, FUB-side valid/ready flits out
//
// Documentation: docs/markdown/rtl-amba/cxs/cxs_slave.md
// Subsystem: amba
//
// The CXS counterpart of axis4_slave. Every credit is a promise of one FIFO
// slot (IHI 0079D 2.1.2: "the Receiver must guarantee that it can receive
// one flit of data for each credit that it grants"), so the receive FIFO is
// the credit pool:
//
//   r_out    credits granted and not yet spent (CXSVALID) or returned
//            (CXSCRDRTN), counting the grant on the wire this cycle
//   grant    another credit when, after this edge,
//              FIFO occupancy + r_out < RX_FIFO_DEPTH  and  r_out < CXS_MAX_CREDIT
//
// CXSCRDGNT is registered (r_crdgnt) from registered state and this cycle's
// VALID / CRDRTN / FUB pop, so a credit spent or returned in cycle t is
// granted again at t+1 at the earliest -- the reuse rule of 2.1.2 -- and no
// output depends combinationally on any input.
//
// Link control, CXS_LINK_CTRL = 1 (chapter 5). CXSACTIVEREQ "must be treated
// by the Receiver as an asynchronous signal" (5.5): it crosses through
// glitch_free_n_dff_arn (ACTIVEREQ_SYNC_STAGES flops, with its check bit) --
// 0 stages is allowed for a known-synchronous system.
//   - ACTIVATE -> RUN: raise CXSACTIVEACK when ACTIVEREQ is seen and
//     cfg_rx_enable is set. Credits are granted only in RUN.
//   - DEACTIVATE: stop granting; flits still in flight are accepted (5.4);
//     drop ACTIVEACK only when every credit is home (r_out reaches 0), so the
//     transmitter never sees ACK low while it holds a credit.
//   - CXSDEACTHINT is cfg_deact_hint, registered.
// With CXS_LINK_CTRL = 0 credits are granted whenever there is room and
// cfg_rx_enable is set, and CXSACTIVEACK / CXSDEACTHINT are tied low.
//
// Interface protection, CXS_CHECK = 1 (3.2): payload check signals are
// checked when CXSVALID is high, for the signals the interface has;
// CXSVALIDCHK, CXSCRDRTNCHK and CXSACTIVEREQCHK every cycle out of reset
// (ACTIVEREQCHK after the same synchronizer as ACTIVEREQ). A mismatch sets
// the sticky parity_error. CXSCRDGNTCHK and CXSACTIVEACKCHK are generated.
//
// Parameters: as cxs_master, plus
//   - RX_FIFO_DEPTH: receive FIFO depth = the credit pool; default
//     CXS_MAX_CREDIT. A depth below the credit round trip throttles the link
//     (2.1.2: the credit count must cover the credit latency for full rate)
//   - ACTIVEREQ_SYNC_STAGES: synchronizer flops on CXSACTIVEREQ, 0 or >= 2
//
// Author: sean galloway
// Created: 2026-10-15

`timescale 1ns / 1ps

`include "reset_defs.svh"

module cxs_slave
    import cxs_pkg::*;
#(
    parameter int CXS_ISSUE             = CXS_ISSUE_D,
    parameter int CXS_DATA_WIDTH        = 256,
    parameter int CXS_MAX_PKT_PER_FLIT  = 2,
    parameter int CXS_START_ALIGN       = 16,
    parameter bit CXS_HAS_LAST          = 1'b0,
    parameter bit CXS_HAS_PRCLTYPE      = 1'b0,
    parameter int CXS_SRCID_WIDTH       = 0,
    parameter int CXS_TGTID_WIDTH       = 0,
    parameter int CXS_USER_WIDTH        = 0,
    parameter int CXS_MAX_CREDIT        = 15,
    // Credit pool beyond the spec's CXS_MAX_CREDIT cap (63, or 15 before
    // Issue C): the one sanctioned departure, for a receiver whose buffer is
    // a whole SRAM. Both ends of the link must be built with it.
    parameter bit CXS_CREDIT_BEYOND_SPEC = 1'b0,
    // Per-stream packet tracking (IHI 0079D 2.5.2): the low bits of
    // CXSPRCLTYPE / CXSSRCID / CXSTGTID that tell interleaved streams apart.
    // 0/0/0 = the link is one stream (no interleave). See cxs_stream_key.
    parameter int CXS_STREAM_PRCL_BITS  = 0,
    parameter int CXS_STREAM_SRCID_BITS = 0,
    parameter int CXS_STREAM_TGTID_BITS = 0,
    parameter bit CXS_LINK_CTRL         = 1'b1,
    parameter bit CXS_CHECK             = 1'b0,
    parameter int RX_FIFO_DEPTH         = CXS_MAX_CREDIT,
    parameter int ACTIVEREQ_SYNC_STAGES = 2,

    // Short and calculated params
    parameter int DW        = CXS_DATA_WIDTH,
    parameter int N         = CXS_MAX_PKT_PER_FLIT,
    parameter int CNTL_W    = cntl_width(N, DW, CXS_START_ALIGN),
    parameter int CNTL_PW   = port_w(CNTL_W),
    parameter int SRCID_PW  = port_w(CXS_SRCID_WIDTH),
    parameter int TGTID_PW  = port_w(CXS_TGTID_WIDTH),
    parameter int USER_PW   = port_w(CXS_USER_WIDTH),
    parameter int DATACHK_W = chk_width(DW),
    parameter int CNTLCHK_W = port_w(chk_width(CNTL_W)),
    parameter int USERCHK_W = port_w(chk_width(CXS_USER_WIDTH)),
    parameter int CRW       = $clog2(CXS_MAX_CREDIT + 1)
) (
    // Global Clock and Reset
    input  logic                  aclk,
    input  logic                  aresetn,

    // Configuration
    input  logic                  cfg_rx_enable,     // 0 = never activate, never grant
    input  logic                  cfg_deact_hint,    // drives CXSDEACTHINT (registered)

    // CXS Receiver interface
    input  logic                  s_cxs_valid,
    input  logic [DW-1:0]         s_cxs_data,
    input  logic [CNTL_PW-1:0]    s_cxs_cntl,
    input  logic                  s_cxs_last,
    input  logic [2:0]            s_cxs_prcltype,
    input  logic [SRCID_PW-1:0]   s_cxs_srcid,
    input  logic [TGTID_PW-1:0]   s_cxs_tgtid,
    input  logic [USER_PW-1:0]    s_cxs_user,
    output logic                  s_cxs_crdgnt,
    input  logic                  s_cxs_crdrtn,
    input  logic                  s_cxs_activereq,
    output logic                  s_cxs_activeack,
    output logic                  s_cxs_deacthint,

    // CXS check signals (CXS_CHECK = 1)
    input  logic                  s_cxs_validchk,
    input  logic [DATACHK_W-1:0]  s_cxs_datachk,
    input  logic [CNTLCHK_W-1:0]  s_cxs_cntlchk,
    input  logic                  s_cxs_lastchk,
    input  logic                  s_cxs_prcltypechk,
    input  logic                  s_cxs_srcidchk,
    input  logic                  s_cxs_tgtidchk,
    input  logic [USERCHK_W-1:0]  s_cxs_userchk,
    output logic                  s_cxs_crdgntchk,
    input  logic                  s_cxs_crdrtnchk,
    input  logic                  s_cxs_activereqchk,
    output logic                  s_cxs_activeackchk,

    // FUB side (valid/ready flits out)
    output logic                  fub_cxs_valid,
    input  logic                  fub_cxs_ready,
    output logic [DW-1:0]         fub_cxs_data,
    output logic [CNTL_PW-1:0]    fub_cxs_cntl,
    output logic                  fub_cxs_last,
    output logic [2:0]            fub_cxs_prcltype,
    output logic [SRCID_PW-1:0]   fub_cxs_srcid,
    output logic [TGTID_PW-1:0]   fub_cxs_tgtid,
    output logic [USER_PW-1:0]    fub_cxs_user,

    // Status
    output logic                  busy,                // any work or link state that is not STOP
    output logic [CRW-1:0]        credits_outstanding, // granted, not yet spent or returned
    output logic [1:0]            link_state,          // {ACTIVEREQ synced, ACTIVEACK}
    output logic                  in_packet,           // a packet is open on the link
    output logic                  credit_starved,      // RUN, no credit out and none grantable: the FIFO holds every slot (the FUB is the bottleneck)
    output logic                  protocol_error,      // sticky: flit/return without a credit, VALID with CRDRTN, bad CXSCNTL, overflow
    output logic                  parity_error         // sticky: a received check signal mismatched
);

    // ------------------------------------------------------------------
    // Elaboration-time property check
    // ------------------------------------------------------------------
    localparam int CFG_ERR = config_error(CXS_ISSUE, DW, N, CXS_START_ALIGN,
                                          CXS_HAS_LAST, CXS_HAS_PRCLTYPE,
                                          CXS_SRCID_WIDTH, CXS_TGTID_WIDTH,
                                          CXS_USER_WIDTH, CXS_MAX_CREDIT,
                                          CXS_CREDIT_BEYOND_SPEC);
`ifndef SYNTHESIS
    initial begin : param_check
        if (CFG_ERR != 0)
            $fatal(1, "cxs_slave: illegal CXS property set for issue %0d (rule %0d, see cxs_pkg::config_error)",
                   CXS_ISSUE, CFG_ERR);
        if (RX_FIFO_DEPTH < 1)
            $fatal(1, "cxs_slave: RX_FIFO_DEPTH must be >= 1 (got %0d)", RX_FIFO_DEPTH);
        if (ACTIVEREQ_SYNC_STAGES == 1)
            $fatal(1, "cxs_slave: ACTIVEREQ_SYNC_STAGES is 0 (synchronous) or >= 2");
    end
`endif

    localparam int PKT_W = DW + CNTL_PW + 1 + 3 + SRCID_PW + TGTID_PW + USER_PW;
    // gaxi_fifo_sync needs DEPTH >= 2 (its counters go zero-width at 1), but
    // one credit with a one-flit buffer is a legal CXS receiver
    // (CXS_MAX_CREDIT = 1). The FIFO is built at least 2 deep; the credit
    // accounting below still uses RX_FIFO_DEPTH, so the spare slot is never
    // granted against.
    localparam int FIFO_D = (RX_FIFO_DEPTH < 2) ? 2 : RX_FIFO_DEPTH;
    localparam int AW     = $clog2(FIFO_D);
    localparam int OW    = ((AW + 1) > (CRW + 1)) ? (AW + 2) : (CRW + 2);   // sum width, no wrap

    // ------------------------------------------------------------------
    // Received fields: absent signals read as 0
    // ------------------------------------------------------------------
    logic [CNTL_PW-1:0]  w_cntl;
    logic                w_last;
    logic [2:0]          w_prcltype;
    logic [SRCID_PW-1:0] w_srcid;
    logic [TGTID_PW-1:0] w_tgtid;
    logic [USER_PW-1:0]  w_user;

    assign w_cntl     = (CNTL_W > 0)          ? s_cxs_cntl     : '0;
    assign w_last     = CXS_HAS_LAST          && s_cxs_last;
    assign w_prcltype = CXS_HAS_PRCLTYPE      ? s_cxs_prcltype : 3'b000;
    assign w_srcid    = (CXS_SRCID_WIDTH > 0) ? s_cxs_srcid    : '0;
    assign w_tgtid    = (CXS_TGTID_WIDTH > 0) ? s_cxs_tgtid    : '0;
    assign w_user     = (CXS_USER_WIDTH > 0)  ? s_cxs_user     : '0;

    // ------------------------------------------------------------------
    // Receive FIFO (the credit pool)
    // ------------------------------------------------------------------
    logic [AW:0]      w_fifo_count;
    logic             w_fifo_wr_ready;
    logic [PKT_W-1:0] w_fifo_rd_data;
    logic             w_push;
    logic             w_pop;

    assign w_push = s_cxs_valid;
    assign w_pop  = fub_cxs_valid && fub_cxs_ready;

    gaxi_fifo_sync #(
        .REGISTERED (0),
        .DATA_WIDTH (PKT_W),
        .DEPTH      (FIFO_D)
    ) u_rx_fifo (
        .axi_aclk    (aclk),
        .axi_aresetn (aresetn),
        .wr_valid    (w_push),
        .wr_ready    (w_fifo_wr_ready),
        .wr_data     ({s_cxs_data, w_cntl, w_last, w_prcltype, w_srcid, w_tgtid, w_user}),
        .rd_ready    (fub_cxs_ready),
        .count       (w_fifo_count),
        .rd_valid    (fub_cxs_valid),
        .rd_data     (w_fifo_rd_data)
    );

    assign {fub_cxs_data, fub_cxs_cntl, fub_cxs_last, fub_cxs_prcltype,
            fub_cxs_srcid, fub_cxs_tgtid, fub_cxs_user} = w_fifo_rd_data;

    // ------------------------------------------------------------------
    // Link control
    // ------------------------------------------------------------------
    logic w_req_s;       // CXSACTIVEREQ in this clock domain
    logic w_reqchk_s;    // CXSACTIVEREQCHK, same crossing
    logic r_ack;
    logic r_hint;
    logic w_grant_ok;

    logic [CRW-1:0] r_out;
    logic           r_crdgnt;
    logic [OW-1:0]  w_out_next;
    logic [OW-1:0]  w_occ_next;
    logic           w_can_grant;

    if (CXS_LINK_CTRL) begin : g_link
        if (ACTIVEREQ_SYNC_STAGES >= 2) begin : g_sync
            // The check bit crosses INVERTED: the flops reset to 0, and a
            // reset-low ACTIVEREQ's correct check is 1. Carried true, the
            // pair would read {0,0} -- a parity error -- for every cycle the
            // synchronizer is still flushing after reset.
            logic w_reqchk_n_s;
            glitch_free_n_dff_arn #(
                .FLOP_COUNT (ACTIVEREQ_SYNC_STAGES),
                .WIDTH      (2)
            ) u_req_sync (
                .clk   (aclk),
                .rst_n (aresetn),
                .d     ({s_cxs_activereq, ~s_cxs_activereqchk}),
                .q     ({w_req_s, w_reqchk_n_s})
            );
            assign w_reqchk_s = ~w_reqchk_n_s;
        end else begin : g_nosync
            assign w_req_s    = s_cxs_activereq;
            assign w_reqchk_s = s_cxs_activereqchk;
        end

        assign w_grant_ok = w_req_s && r_ack;

        `ALWAYS_FF_RST(aclk, aresetn,
            if (`RST_ASSERTED(aresetn)) begin
                r_ack  <= 1'b0;
                r_hint <= 1'b0;
            end else begin
                r_hint <= cfg_deact_hint;
                if (w_req_s && !r_ack && cfg_rx_enable)
                    r_ack <= 1'b1;                       // ACTIVATE -> RUN
                else if (!w_req_s && r_ack && (w_out_next == '0))
                    r_ack <= 1'b0;                       // DEACTIVATE -> STOP, all credits home
            end
        )
    end else begin : g_no_link
        assign w_req_s    = 1'b0;
        assign w_reqchk_s = 1'b1;
        assign w_grant_ok = cfg_rx_enable;

        always_comb begin
            r_ack  = 1'b0;
            r_hint = 1'b0;
        end

        /* verilator lint_off UNUSEDSIGNAL */
        logic unused_link;
        assign unused_link = ^{s_cxs_activereq, s_cxs_activereqchk, cfg_deact_hint};
        /* verilator lint_on UNUSEDSIGNAL */
    end

    // ------------------------------------------------------------------
    // Credits
    // ------------------------------------------------------------------
    // After this edge, before any new grant: the grant on the wire now has
    // joined r_out, a flit or a return has left it, and the FIFO has taken
    // the push and given up the pop.
    assign w_out_next = OW'(r_out) + OW'(r_crdgnt) - OW'(w_push) - OW'(s_cxs_crdrtn);
    assign w_occ_next = OW'(w_fifo_count) + OW'(w_push) - OW'(w_pop);

    // Underflow (a flit or return with no credit) wraps w_out_next high,
    // which also blocks a grant until reset; it is flagged below.
    assign w_can_grant = w_grant_ok &&
                         (w_out_next < OW'(CXS_MAX_CREDIT)) &&
                         ((w_occ_next + w_out_next) < OW'(RX_FIFO_DEPTH));

    `ALWAYS_FF_RST(aclk, aresetn,
        if (`RST_ASSERTED(aresetn)) begin
            r_out    <= '0;
            r_crdgnt <= 1'b0;
        end else begin
            r_crdgnt <= w_can_grant;
            if (w_out_next <= OW'(CXS_MAX_CREDIT))
                r_out <= CRW'(w_out_next);
        end
    )

    assign s_cxs_crdgnt    = r_crdgnt;
    assign s_cxs_activeack = r_ack;
    assign s_cxs_deacthint = r_hint;

    // ------------------------------------------------------------------
    // Packet tracking on the flits received
    // ------------------------------------------------------------------
    logic w_in_packet;
    logic w_cntl_err;

    localparam int SKEY_W  = CXS_STREAM_PRCL_BITS + CXS_STREAM_SRCID_BITS + CXS_STREAM_TGTID_BITS;
    localparam int SKEY_PW = (SKEY_W > 0) ? SKEY_W : 1;
    logic [SKEY_PW-1:0] w_stream_key;

    cxs_stream_key #(
        .PRCL_BITS  (CXS_STREAM_PRCL_BITS),
        .SRCID_BITS (CXS_STREAM_SRCID_BITS),
        .TGTID_BITS (CXS_STREAM_TGTID_BITS),
        .SRCID_PW   (SRCID_PW),
        .TGTID_PW   (TGTID_PW)
    ) u_stream_key (
        .i_prcltype (w_prcltype),
        .i_srcid    (w_srcid),
        .i_tgtid    (w_tgtid),
        .o_key      (w_stream_key)
    );

    cxs_cntl_track #(
        .N            (N),
        .CNTL_W       (CNTL_W),
        .END_LSB      (end_lsb(N, DW, CXS_START_ALIGN)),
        .ENDERROR_LSB (enderror_lsb(N, DW, CXS_START_ALIGN)),
        .KEY_W        (SKEY_W)
    ) u_track (
        .aclk        (aclk),
        .aresetn     (aresetn),
        .i_valid     (w_push),
        .i_cntl      (w_cntl),
        .i_key       (w_stream_key),
        .o_in_packet (w_in_packet),
        .o_cntl_err  (w_cntl_err)
    );

    // ------------------------------------------------------------------
    // Status and protocol errors
    // ------------------------------------------------------------------
    assign busy = s_cxs_valid || fub_cxs_valid || r_ack || w_req_s ||
                  (r_out != '0) || r_crdgnt;
    assign credits_outstanding = r_out;
    assign link_state          = {w_req_s, r_ack};
    assign in_packet           = w_in_packet;
    assign credit_starved      = w_grant_ok && (r_out == '0) && !r_crdgnt && !w_can_grant;

    logic w_proto_err;
    assign w_proto_err = (w_push && (r_out == '0)) ||
                         (s_cxs_crdrtn && (r_out == '0)) ||
                         (w_push && s_cxs_crdrtn) ||
                         (w_push && !w_fifo_wr_ready) ||
                         w_cntl_err;

    `ALWAYS_FF_RST(aclk, aresetn,
        if (`RST_ASSERTED(aresetn)) begin
            protocol_error <= 1'b0;
        end else if (w_proto_err) begin
            protocol_error <= 1'b1;
        end
    )

    // ------------------------------------------------------------------
    // Interface protection (Odd_Byte_Parity)
    // ------------------------------------------------------------------
    if (CXS_CHECK) begin : g_check
        logic w_data_err, w_cntl_chk_err, w_prcl_err, w_srcid_err, w_tgtid_err, w_user_err;
        logic w_payload_err, w_ctrl_err;

        /* verilator lint_off PINCONNECTEMPTY */
        cxs_odd_byte_parity #(.WIDTH(DW)) u_datachk (
            .data (s_cxs_data), .chk_in (s_cxs_datachk), .chk_out (), .chk_err (w_data_err));
        cxs_odd_byte_parity #(.WIDTH(CNTL_PW)) u_cntlchk (
            .data (s_cxs_cntl), .chk_in (s_cxs_cntlchk), .chk_out (), .chk_err (w_cntl_chk_err));
        cxs_odd_byte_parity #(.WIDTH(3)) u_prcltypechk (
            .data (s_cxs_prcltype), .chk_in (s_cxs_prcltypechk), .chk_out (), .chk_err (w_prcl_err));
        cxs_odd_byte_parity #(.WIDTH(SRCID_PW)) u_srcidchk (
            .data (s_cxs_srcid), .chk_in (s_cxs_srcidchk), .chk_out (), .chk_err (w_srcid_err));
        cxs_odd_byte_parity #(.WIDTH(TGTID_PW)) u_tgtidchk (
            .data (s_cxs_tgtid), .chk_in (s_cxs_tgtidchk), .chk_out (), .chk_err (w_tgtid_err));
        cxs_odd_byte_parity #(.WIDTH(USER_PW)) u_userchk (
            .data (s_cxs_user), .chk_in (s_cxs_userchk), .chk_out (), .chk_err (w_user_err));
        /* verilator lint_on PINCONNECTEMPTY */

        // Payload checks: Check enable = CXSVALID, only for signals present
        assign w_payload_err = s_cxs_valid && (
            w_data_err ||
            ((CNTL_W > 0)          && w_cntl_chk_err) ||
            (CXS_HAS_LAST          && (s_cxs_lastchk == s_cxs_last)) ||
            (CXS_HAS_PRCLTYPE      && w_prcl_err) ||
            ((CXS_SRCID_WIDTH > 0) && w_srcid_err) ||
            ((CXS_TGTID_WIDTH > 0) && w_tgtid_err) ||
            ((CXS_USER_WIDTH > 0)  && w_user_err));

        // Single-bit controls: Check enable = RESETn
        assign w_ctrl_err = (s_cxs_validchk == s_cxs_valid) ||
                            (CXS_LINK_CTRL && (s_cxs_crdrtnchk == s_cxs_crdrtn)) ||
                            (CXS_LINK_CTRL && (w_reqchk_s == w_req_s));

        `ALWAYS_FF_RST(aclk, aresetn,
            if (`RST_ASSERTED(aresetn)) begin
                parity_error <= 1'b0;
            end else if (w_payload_err || w_ctrl_err) begin
                parity_error <= 1'b1;
            end
        )

        assign s_cxs_crdgntchk    = ~s_cxs_crdgnt;
        assign s_cxs_activeackchk = ~s_cxs_activeack;
    end else begin : g_no_check
        assign parity_error       = 1'b0;
        assign s_cxs_crdgntchk    = 1'b0;
        assign s_cxs_activeackchk = 1'b0;

        /* verilator lint_off UNUSEDSIGNAL */
        logic unused_chk_inputs;
        assign unused_chk_inputs = ^{s_cxs_validchk, s_cxs_datachk, s_cxs_cntlchk,
                                     s_cxs_lastchk, s_cxs_prcltypechk, s_cxs_srcidchk,
                                     s_cxs_tgtidchk, s_cxs_userchk, s_cxs_crdrtnchk,
                                     w_reqchk_s};
        /* verilator lint_on UNUSEDSIGNAL */
    end

endmodule : cxs_slave

// SPDX-License-Identifier: MIT
// SPDX-FileCopyrightText: 2026 sean galloway
//
// RTL Design Sherpa - Industry-Standard RTL Design and Verification
// https://github.com/sean-galloway/RTLDesignSherpa
//
// Module: cxs_slave_cg
// Purpose: cxs_slave behind one amba_clock_gate_ctrl
//
// Documentation: docs/markdown/rtl-amba/cxs/cxs_slave_cg.md
// Subsystem: amba
//
// IHI 0079D 5.5 anticipates exactly this block: "It is common for the clock
// in the Receiver to stop during the STOP state ... The assertion of the
// CXSACTIVEREQ signal might be used to restart that clock."
//
// The core's `busy` covers every state in which a flit or a credit return
// can still arrive -- ACTIVEACK or the synchronized ACTIVEREQ high, or any
// credit outstanding -- plus a flit waiting on the FUB side. So the block
// gates only in STOP with every credit home and the FIFO empty, where the
// transmitter "must not send flits or credit returns" (5.2).
//
//   - CXS_LINK_CTRL = 1: gates in STOP; a rising CXSACTIVEREQ wakes it.
//   - CXS_LINK_CTRL = 0: credits stay outstanding indefinitely, `busy`
//     never falls, and this wrapper never gates (see cxs_master_cg).
//
// Activity terms (vault/handbook/design/clock-gating-activity-terms):
//   user_valid = core busy                       (includes fub_cxs_valid,
//                                                 the pending output)
//   axi_valid  = s_cxs_valid | s_cxs_crdrtn | ACTIVEREQ synchronized here
// CXSACTIVEREQ is asynchronous (5.5), so the wake term goes through its own
// glitch_free_n_dff_arn on the FREE-RUNNING aclk: a wake term must be in the
// gate's own clock domain, and the core's synchronizer sits on the gated
// clock and is frozen in STOP. Event outputs (CXSCRDGNT and its check bit,
// fub_cxs_valid) are masked with !cg_gating.
//
// Author: sean galloway
// Created: 2026-10-15

`timescale 1ns / 1ps

module cxs_slave_cg
    import cxs_pkg::*;
#(
    parameter int CXS_ISSUE             = CXS_ISSUE_D,
    parameter int CXS_DATA_WIDTH        = 256,
    parameter int CXS_MAX_PKT_PER_FLIT  = 2,
    parameter int CXS_START_ALIGN       = 16,
    parameter bit CXS_HAS_LAST          = 1'b0,
    parameter bit CXS_HAS_PRCLTYPE      = 1'b0,
    parameter int CXS_SRCID_WIDTH       = 0,
    parameter int CXS_TGTID_WIDTH       = 0,
    parameter int CXS_USER_WIDTH        = 0,
    parameter int CXS_MAX_CREDIT        = 15,
    parameter bit  CXS_CREDIT_BEYOND_SPEC = 1'b0,   // see cxs_master / cxs_slave
    parameter int  CXS_STREAM_PRCL_BITS   = 0,      // per-stream tracking key (cxs_stream_key)
    parameter int  CXS_STREAM_SRCID_BITS  = 0,
    parameter int  CXS_STREAM_TGTID_BITS  = 0,
    parameter bit CXS_LINK_CTRL         = 1'b1,
    parameter bit CXS_CHECK             = 1'b0,
    parameter int RX_FIFO_DEPTH         = CXS_MAX_CREDIT,
    parameter int ACTIVEREQ_SYNC_STAGES = 2,

    // Clock gating parameters
    parameter int CG_IDLE_COUNT_WIDTH   = 4,

    // Short and calculated params
    parameter int DW        = CXS_DATA_WIDTH,
    parameter int N         = CXS_MAX_PKT_PER_FLIT,
    parameter int CNTL_W    = cntl_width(N, DW, CXS_START_ALIGN),
    parameter int CNTL_PW   = port_w(CNTL_W),
    parameter int SRCID_PW  = port_w(CXS_SRCID_WIDTH),
    parameter int TGTID_PW  = port_w(CXS_TGTID_WIDTH),
    parameter int USER_PW   = port_w(CXS_USER_WIDTH),
    parameter int DATACHK_W = chk_width(DW),
    parameter int CNTLCHK_W = port_w(chk_width(CNTL_W)),
    parameter int USERCHK_W = port_w(chk_width(CXS_USER_WIDTH)),
    parameter int CRW       = $clog2(CXS_MAX_CREDIT + 1)
) (
    input  logic                           aclk,
    input  logic                           aresetn,

    // Clock gating configuration
    input  logic                           cfg_cg_enable,
    input  logic [CG_IDLE_COUNT_WIDTH-1:0] cfg_cg_idle_count,

    // Configuration
    input  logic                  cfg_rx_enable,
    input  logic                  cfg_deact_hint,

    // CXS Receiver interface
    input  logic                  s_cxs_valid,
    input  logic [DW-1:0]         s_cxs_data,
    input  logic [CNTL_PW-1:0]    s_cxs_cntl,
    input  logic                  s_cxs_last,
    input  logic [2:0]            s_cxs_prcltype,
    input  logic [SRCID_PW-1:0]   s_cxs_srcid,
    input  logic [TGTID_PW-1:0]   s_cxs_tgtid,
    input  logic [USER_PW-1:0]    s_cxs_user,
    output logic                  s_cxs_crdgnt,
    input  logic                  s_cxs_crdrtn,
    input  logic                  s_cxs_activereq,
    output logic                  s_cxs_activeack,
    output logic                  s_cxs_deacthint,

    // CXS check signals
    input  logic                  s_cxs_validchk,
    input  logic [DATACHK_W-1:0]  s_cxs_datachk,
    input  logic [CNTLCHK_W-1:0]  s_cxs_cntlchk,
    input  logic                  s_cxs_lastchk,
    input  logic                  s_cxs_prcltypechk,
    input  logic                  s_cxs_srcidchk,
    input  logic                  s_cxs_tgtidchk,
    input  logic [USERCHK_W-1:0]  s_cxs_userchk,
    output logic                  s_cxs_crdgntchk,
    input  logic                  s_cxs_crdrtnchk,
    input  logic                  s_cxs_activereqchk,
    output logic                  s_cxs_activeackchk,

    // FUB side
    output logic                  fub_cxs_valid,
    input  logic                  fub_cxs_ready,
    output logic [DW-1:0]         fub_cxs_data,
    output logic [CNTL_PW-1:0]    fub_cxs_cntl,
    output logic                  fub_cxs_last,
    output logic [2:0]            fub_cxs_prcltype,
    output logic [SRCID_PW-1:0]   fub_cxs_srcid,
    output logic [TGTID_PW-1:0]   fub_cxs_tgtid,
    output logic [USER_PW-1:0]    fub_cxs_user,

    // Status
    output logic [CRW-1:0]        credits_outstanding,
    output logic [1:0]            link_state,
    output logic                  in_packet,
    output logic                  credit_starved,
    output logic                  protocol_error,
    output logic                  parity_error,

    // Clock gating status
    output logic                  cg_gating,
    output logic                  cg_idle
);

    logic gated_aclk;
    logic int_busy;
    logic int_fub_valid;
    logic int_crdgnt;
    logic int_crdgntchk;
    logic w_req_wake;
    logic user_valid;
    logic axi_valid;

    // ACTIVEREQ wake term, synchronized on the free-running clock
    if (CXS_LINK_CTRL) begin : g_req_wake
        if (ACTIVEREQ_SYNC_STAGES >= 2) begin : g_sync
            glitch_free_n_dff_arn #(
                .FLOP_COUNT (ACTIVEREQ_SYNC_STAGES),
                .WIDTH      (1)
            ) u_req_wake_sync (
                .clk   (aclk),
                .rst_n (aresetn),
                .d     (s_cxs_activereq),
                .q     (w_req_wake)
            );
        end else begin : g_nosync
            assign w_req_wake = s_cxs_activereq;
        end
    end else begin : g_no_req_wake
        assign w_req_wake = 1'b0;
    end

    assign user_valid = int_busy;
    assign axi_valid  = s_cxs_valid || s_cxs_crdrtn || w_req_wake;

    amba_clock_gate_ctrl #(
        .CG_IDLE_COUNT_WIDTH (CG_IDLE_COUNT_WIDTH)
    ) i_amba_clock_gate_ctrl (
        .clk_in            (aclk),
        .aresetn           (aresetn),
        .cfg_cg_enable     (cfg_cg_enable),
        .cfg_cg_idle_count (cfg_cg_idle_count),
        .user_valid        (user_valid),
        .axi_valid         (axi_valid),
        .clk_out           (gated_aclk),
        .gating            (cg_gating),
        .idle              (cg_idle)
    );

    assign fub_cxs_valid   = cg_gating ? 1'b0 : int_fub_valid;
    assign s_cxs_crdgnt    = cg_gating ? 1'b0 : int_crdgnt;
    assign s_cxs_crdgntchk = (cg_gating && CXS_CHECK) ? 1'b1 : int_crdgntchk;

    cxs_slave #(
        .CXS_ISSUE             (CXS_ISSUE),
        .CXS_DATA_WIDTH        (CXS_DATA_WIDTH),
        .CXS_MAX_PKT_PER_FLIT  (CXS_MAX_PKT_PER_FLIT),
        .CXS_START_ALIGN       (CXS_START_ALIGN),
        .CXS_HAS_LAST          (CXS_HAS_LAST),
        .CXS_HAS_PRCLTYPE      (CXS_HAS_PRCLTYPE),
        .CXS_SRCID_WIDTH       (CXS_SRCID_WIDTH),
        .CXS_TGTID_WIDTH       (CXS_TGTID_WIDTH),
        .CXS_USER_WIDTH        (CXS_USER_WIDTH),
        .CXS_MAX_CREDIT        (CXS_MAX_CREDIT),
        .CXS_CREDIT_BEYOND_SPEC(CXS_CREDIT_BEYOND_SPEC),
        .CXS_STREAM_PRCL_BITS  (CXS_STREAM_PRCL_BITS),
        .CXS_STREAM_SRCID_BITS (CXS_STREAM_SRCID_BITS),
        .CXS_STREAM_TGTID_BITS (CXS_STREAM_TGTID_BITS),
        .CXS_LINK_CTRL         (CXS_LINK_CTRL),
        .CXS_CHECK             (CXS_CHECK),
        .RX_FIFO_DEPTH         (RX_FIFO_DEPTH),
        .ACTIVEREQ_SYNC_STAGES (ACTIVEREQ_SYNC_STAGES)
    ) i_cxs_slave (
        .aclk                (gated_aclk),
        .aresetn             (aresetn),
        .cfg_rx_enable       (cfg_rx_enable),
        .cfg_deact_hint      (cfg_deact_hint),
        .s_cxs_valid         (s_cxs_valid),
        .s_cxs_data          (s_cxs_data),
        .s_cxs_cntl          (s_cxs_cntl),
        .s_cxs_last          (s_cxs_last),
        .s_cxs_prcltype      (s_cxs_prcltype),
        .s_cxs_srcid         (s_cxs_srcid),
        .s_cxs_tgtid         (s_cxs_tgtid),
        .s_cxs_user          (s_cxs_user),
        .s_cxs_crdgnt        (int_crdgnt),
        .s_cxs_crdrtn        (s_cxs_crdrtn),
        .s_cxs_activereq     (s_cxs_activereq),
        .s_cxs_activeack     (s_cxs_activeack),
        .s_cxs_deacthint     (s_cxs_deacthint),
        .s_cxs_validchk      (s_cxs_validchk),
        .s_cxs_datachk       (s_cxs_datachk),
        .s_cxs_cntlchk       (s_cxs_cntlchk),
        .s_cxs_lastchk       (s_cxs_lastchk),
        .s_cxs_prcltypechk   (s_cxs_prcltypechk),
        .s_cxs_srcidchk      (s_cxs_srcidchk),
        .s_cxs_tgtidchk      (s_cxs_tgtidchk),
        .s_cxs_userchk       (s_cxs_userchk),
        .s_cxs_crdgntchk     (int_crdgntchk),
        .s_cxs_crdrtnchk     (s_cxs_crdrtnchk),
        .s_cxs_activereqchk  (s_cxs_activereqchk),
        .s_cxs_activeackchk  (s_cxs_activeackchk),
        .fub_cxs_valid       (int_fub_valid),
        .fub_cxs_ready       (fub_cxs_ready),
        .fub_cxs_data        (fub_cxs_data),
        .fub_cxs_cntl        (fub_cxs_cntl),
        .fub_cxs_last        (fub_cxs_last),
        .fub_cxs_prcltype    (fub_cxs_prcltype),
        .fub_cxs_srcid       (fub_cxs_srcid),
        .fub_cxs_tgtid       (fub_cxs_tgtid),
        .fub_cxs_user        (fub_cxs_user),
        .busy                (int_busy),
        .credits_outstanding (credits_outstanding),
        .link_state          (link_state),
        .in_packet           (in_packet),
        .credit_starved      (credit_starved),
        .protocol_error      (protocol_error),
        .parity_error        (parity_error)
    );

endmodule : cxs_slave_cg

// SPDX-License-Identifier: MIT
// SPDX-FileCopyrightText: 2026 sean galloway
//
// RTL Design Sherpa - Industry-Standard RTL Design and Verification
// https://github.com/sean-galloway/RTLDesignSherpa
//
// Module: error_injector
// Purpose:
//   Shared test stimulus: corrupts a coded valid/ready stream between an
//   encoder and a decoder under host control -- an exact number of errors per
//   block, a burst, an error rate, or random burst clusters.
//
// Documentation: projects/components/utility-ip/misc/README.md
// Subsystem: utility-ip/misc
//
// Author: sean galloway
// Created: 2026-10-04 (unified from bch_error_injector and rs_error_injector)

`timescale 1ns/1ps
`include "reset_defs.svh"

//==============================================================================
// Module: error_injector
//==============================================================================
// Description:
//   A three-stage valid/ready pipeline on the stream (data XORed with the
//   error pattern, keep/last untouched), so it sits anywhere on a coded
//   stream. Errors must be injected AFTER the encoder -- an error in the
//   generator's data is encoded faithfully and the code cannot see it --
//   which is why this is its own block and not a mode of the pattern
//   generator.
//
//   Granularity: SYMBOL_WIDTH = 1 makes it a bit injector (every hit XORs a
//   1, as binary BCH wants). SYMBOL_WIDTH = m makes it a symbol injector:
//   every hit XORs a random nonzero m-bit value into the symbol (a zero
//   would be no error), as Reed-Solomon wants. One module, both codecs.
//
//   Modes (cfg_mode):
//     0 NONE      pass through
//     1 COUNT     exactly cfg_count errors per block at uniformly random
//                 distinct positions, by selection sampling (Knuth's
//                 Algorithm S): symbol j of n is hit with probability
//                 e_left / (n - j), evaluated as r16 * (n - j) < e_left << 16
//                 with a 16-bit random r16; the last positions are hit with
//                 certainty when e_left catches up, so the count is exact
//                 whenever cfg_count <= n
//     2 BURST     cfg_count consecutive symbols from a random start
//     3 RATE      each symbol independently with probability cfg_rate / 65536
//     4 CLUSTERS  per block, draw N uniformly from [cfg_cnt_min, cfg_cnt_max],
//                 then per cluster draw a length uniformly from
//                 [cfg_len_min, cfg_len_max] and a uniform start in
//                 [0, N_SYMBOLS - length]; every symbol in a cluster range is
//                 hit. Overlapping clusters merge. Two dedicated xorshift
//                 streams draw the count/lengths and the starts, so cluster
//                 geometry is independent of the per-lane hit randoms.
//                 Presets model real media: small count and length ranges
//                 give DRAM multi-bit-upset patterns, larger ranges give
//                 flash disturbed pages.
//     5 LOCALIZED hits at cfg_rate density confined to one sub-window per
//                 block: the window width is drawn uniformly from
//                 [cfg_len_min, cfg_len_max] and its start uniformly from
//                 [0, N_SYMBOLS - width]. Models a damaged page region, a
//                 failed symbol column, or a half-plane failure -- real
//                 errors are often far more localized than uniform.
//     6 BADBLOCK  per block, with probability cfg_len_min / 65536 the block
//                 runs at the elevated rate cfg_len_max, otherwise at
//                 cfg_rate; models NAND retention tails and worn blocks --
//                 most of the stream is clean with a hard minority that is
//                 very bad, which uniform RATE cannot express.
//     7 DEBUG     deterministic walking errors: block b hits the symbols at
//                 ((b * step + j) mod N_SYMBOLS) for j < cfg_count, step =
//                 cfg_rate. No randoms on the hit path -- a counter and a
//                 subtract-compare -- so it is the hand-checkable bring-up
//                 mode whose timing closes by inspection. Every position is
//                 exercised over a campaign, at a configurable pace.
//
//   COUNT timing: exact selection sampling needs the running hit count --
//   each lane's threshold depends on how many lower lanes hit -- a prefix
//   recurrence that is ~111 logic levels when all lanes of a wide beat decide
//   in one cycle and cannot close at 100 MHz. Stage C therefore decides
//   GRP lanes per cycle (group-local 4-bit prefix, the group-start count
//   folded into per-lane thresholds in parallel), walking a wide beat over
//   N_GRP cycles while it waits in the B skid; the hit mask and count
//   accumulate in registers and release on the final group. GRP is 2 so the
//   conditional-increment ripple stays carry-chain shallow post-route; COUNT
//   mode on a 32-bit beat takes 16 cycles (~6 Mbit/s), far above any UART-fed
//   loop rate. A beat that has no errors left to place -- every count=0 beat,
//   and the tail of a block whose count is already placed -- shortcuts the
//   walk: e_left == 0 clamps every lane's capacity to zero, so the decision is
//   final after group 0 and clean beats stream at line rate (issue #89).
//   BURST, RATE and CLUSTERS are per-lane independent and stay
//   single-cycle, full rate.
//
//   Pipeline (each stage a register with valid/ready):
//     A  accept the beat, snapshot the lane generators (r16 draw + error
//        value), the block position, and -- on a block's first beat -- draw
//        the cluster table from the two stream generators
//     B  the per-lane products r16 * (n - pos - u) and the burst start, in
//        DSPs, from A's registers -- the multiply is the long path
//     C  the decisions and the error mask; the statistics update one cycle
//        later from the registered hit count; the configuration is
//        re-registered locally, so the CSR block is off every path.
//
//   Statistics for the host: total symbols injected (bits when
//   SYMBOL_WIDTH = 1), blocks with at least one injected symbol, blocks with
//   more than T_SYMBOLS injected (the ones a decoder must flag), and the
//   count injected into the most recent block. cfg_clear zeroes them;
//   cfg_seed_load reseeds every generator.
//
//   Erasure marking: with cfg_mark_erasure set, out_erasure carries the
//   beat's hit mask -- lane u flagged exactly where a symbol was corrupted.
//   Wired to a decoder's erasure sideband it turns any placement mode into an
//   erasure run: the positions the decoder is TOLD about are precisely the
//   ones that were hit, which is the information a RAID stripe map or an
//   MC's known-bad column has. With the bit clear out_erasure is all zero.
//
//------------------------------------------------------------------------------
// Parameters:
//------------------------------------------------------------------------------
//   SYMBOL_WIDTH:     1 = bit injector, m = symbol injector (GF(2^m) symbols
//   SYMBOLS_PER_BEAT: lanes per beat
//   N_SYMBOLS:        block length in symbols (<= 65535)
//   T_SYMBOLS:        correctable count, for the over-t statistic only
//   DATA_WIDTH:       SYMBOL_WIDTH * SYMBOLS_PER_BEAT
//
//==============================================================================

module error_injector #(
    parameter int SYMBOL_WIDTH     = 1,
    parameter int SYMBOLS_PER_BEAT = 8,
    parameter int N_SYMBOLS        = 8191,
    parameter int T_SYMBOLS        = 8,
    parameter int DATA_WIDTH       = SYMBOL_WIDTH * SYMBOLS_PER_BEAT
) (
    input  logic                        aclk,
    input  logic                        aresetn,

    input  logic                        in_valid,
    output logic                        in_ready,
    input  logic [DATA_WIDTH-1:0]       in_data,
    input  logic [SYMBOLS_PER_BEAT-1:0] in_keep,
    input  logic                        in_last,

    output logic                        out_valid,
    input  logic                        out_ready,
    output logic [DATA_WIDTH-1:0]       out_data,
    output logic [SYMBOLS_PER_BEAT-1:0] out_keep,
    output logic                        out_last,
    // the beat's hit mask when cfg_mark_erasure is set, else all zero
    output logic [SYMBOLS_PER_BEAT-1:0] out_erasure,

    input  logic [2:0]                  cfg_mode,
    input  logic [7:0]                  cfg_count,
    input  logic [15:0]                 cfg_rate,
    input  logic [31:0]                 cfg_seed,
    input  logic                        cfg_seed_load,
    input  logic                        cfg_clear,
    input  logic                        cfg_mark_erasure,
    input  logic [7:0]                  cfg_cnt_min,
    input  logic [7:0]                  cfg_cnt_max,
    input  logic [15:0]                 cfg_len_min,
    input  logic [15:0]                 cfg_len_max,

    output logic [31:0]                 o_inj_symbols,
    output logic [31:0]                 o_inj_blocks,
    output logic [31:0]                 o_inj_over_t,
    output logic [7:0]                  o_last_block_errors
);

    localparam int M     = SYMBOL_WIDTH;
    localparam int S     = SYMBOLS_PER_BEAT;
    localparam int N     = N_SYMBOLS;
    localparam int POS_W = 16;
    localparam int LW    = 32;
    localparam int MAXB  = 8;   // clusters per block in mode 4

    // Boundary reset synchronization. The port aresetn is treated as an
    // asynchronous-assert input of unknown deassert quality: an N=3
    // reset_sync (rtl/cdc, formally proven) produces the internal reset
    // every block below sees.
    logic w_aresetn;
    reset_sync #(
        .N             (3),
        .KEEP_ATTRS    (1'b1),
        .IN_ACTIVE_LOW (1'b1),
        .OUT_ACTIVE_LOW(1'b1),
        .ASYNC_ASSERT  (1'b1)
    ) u_reset_sync (
        .clk        (aclk),
        .rst_n      (aresetn),
        .sync_rst_n (w_aresetn)
    );

    // -------------------------------------------------------------------------
    // Configuration, re-registered locally: the values are static during a run
    // and the CSR block sits far away; the copy is one cycle late, which no
    // caller can observe.
    // -------------------------------------------------------------------------
    logic [2:0]  r_mode;
    logic [7:0]  r_count;
    logic [15:0] r_rate;
    logic        r_mark_erasure;
    logic [7:0]  r_cnt_min, r_cnt_max;
    logic [15:0] r_len_min, r_len_max;
    // range spans + 1, registered once per config change. Registering keeps
    // the quasi-static config out of the per-block draw multiplies: left
    // combinational, Vivado builds a PCIN cascade across the 17 draw DSPs and
    // the config ripples through the whole chain (12.7 ns path on Genesys 2)
    logic [31:0] r_span_cnt, r_span_len;
    `ALWAYS_FF_RST(aclk, w_aresetn,
        if (`RST_ASSERTED(w_aresetn)) begin
            r_mode <= '0; r_count <= '0; r_rate <= '0; r_mark_erasure <= 1'b0;
            r_cnt_min <= '0; r_cnt_max <= '0; r_len_min <= '0; r_len_max <= '0;
            r_span_cnt <= '0; r_span_len <= '0;
        end else begin
            r_mode <= cfg_mode; r_count <= cfg_count; r_rate <= cfg_rate;
            r_mark_erasure <= cfg_mark_erasure;
            r_cnt_min <= cfg_cnt_min; r_cnt_max <= cfg_cnt_max;
            r_len_min <= cfg_len_min; r_len_max <= cfg_len_max;
            r_span_cnt <= 32'(cfg_cnt_max) - 32'(cfg_cnt_min) + 32'd1;
            r_span_len <= 32'(cfg_len_max) - 32'(cfg_len_min) + 32'd1;
        end
    )

    // -------------------------------------------------------------------------
    // Stage C control declarations (before first use: the stage A handshakes
    // below gate on them, and lint-decl-order requires declare-before-use)
    // -------------------------------------------------------------------------
    localparam int GRP   = (S < 2) ? S : 2;     // lanes decided per cycle
    localparam int N_GRP = (S + GRP - 1) / GRP; // cycles per COUNT beat
    localparam int CYC_W = (N_GRP > 1) ? $clog2(N_GRP) : 1;

    logic             w_count_mode;
    logic [CYC_W-1:0] r_cyc;      // group being decided
    logic             r_dec_busy; // a multi-cycle COUNT decision owns stage C
    logic [7:0]       r_k_mid;    // within-beat count entering the current group
    logic [7:0]       r_hit_acc;  // hits accumulated across the groups of this beat
    logic [S-1:0]     r_mask_acc;

    logic [7:0]       w_start_k, w_k_next, w_grp_hits;
    logic             w_e_start_zero;   // COUNT beat with no errors left: 1-cycle decision
    logic [GRP-1:0]   w_ghit;
    logic [GRP-1:0]   w_gkeep;
    logic [7:0]       w_kp [GRP];         // group-local capacity; 0 = cannot hit
    logic             w_dec_step, w_dec_fire;
    logic             w_app_mode, w_draw_hold, w_draw_wait;
    logic             r_b_first;          // the beat in A/B opens a block
    logic             r_draw_busy, r_draw_done;

    // -------------------------------------------------------------------------
    // Stage A: accept a beat; one 32-bit xorshift generator per lane advances
    // with it, plus two stream generators for mode-4 cluster geometry.
    // -------------------------------------------------------------------------
    logic w_a_fire, w_b_fire, w_c_fire;
    logic r_a_v, r_b_v, r_c_v;
    logic w_a_ready, w_b_ready, w_c_ready;

    logic             r_first;      // lane 0 is a block's first beat (registered below)

    assign w_c_ready = (!r_c_v || out_ready) && !r_dec_busy && !w_draw_wait;
    // COUNT holds the beat in B for N_GRP decision cycles; in that mode B only
    // refills once empty, EXCEPT in the decision's release cycle -- the fire
    // consumes r_b_* combinationally, so A->B may transfer the next beat in
    // the same edge (issue #89: this bubble plus the vacuous walk below cost
    // three cycles per beat on clean characterization runs). BURST / RATE /
    // CLUSTERS keep the single-cycle overlap; the app modes also pause the
    // input for the draw walk and hold the block-start beat until the table
    // is complete.
    assign w_b_ready = !r_b_v || (w_c_ready && !w_count_mode)
                       || (w_count_mode && w_dec_fire);
    // A block-start beat accepted mid-walk (possible via the empty-A path
    // while a stale walk still runs -- snapshots fire for every mode, so a
    // non-app phase leaves the walk busy across the next app block's first
    // beat) used to let the stale walk's end-of-walk done pulse release the
    // held beat one cycle before the new walk's start branch cleared it, and
    // the block decided against the previous table (BUG-001, seed 33472).
    // Serialize instead: never accept a block-start beat while a walk runs,
    // so every snapshot lands at draw_busy==0 and the start branch's
    // invalidation is in force before the beat can reach stage B.  Steady
    // state is unaffected -- a block's own first beat already sits in A for
    // the whole walk, which blocks this path except in the race above.
    assign w_a_ready = (!r_a_v || (w_b_ready && !w_draw_hold))
                       && !(w_app_mode && r_draw_busy && r_first);
    assign in_ready  = w_a_ready;
    assign w_a_fire  = in_valid && w_a_ready;
    assign w_b_fire  = r_a_v && w_b_ready;
    assign w_c_fire  = r_b_v && w_c_ready;
    assign w_draw_hold = w_app_mode && r_draw_busy;
    assign w_draw_wait = w_app_mode && r_b_v && r_b_first && !r_draw_done;

    function automatic logic [LW-1:0] xorshift32(input logic [LW-1:0] x);
        logic [LW-1:0] y;
        y = x ^ (x << 13);
        y = y ^ (y >> 17);
        y = y ^ (y << 5);
        return y;
    endfunction

    // One xorshift32 generator per lane (x ^= x << 13; x ^= x >> 17; x ^= x << 5):
    // every bit of the state changes on every step, so consecutive beats draw
    // decorrelated numbers. A one-bit-per-step LFSR was tried first and its
    // 16-bit windows, each the previous one shifted by a bit, clustered the
    // RATE mode's hits (261 in a 204 +- 54 window at S = 1).
    logic [LW-1:0] r_rnd [S];
    logic [LW-1:0] w_rnd [S];
    always_comb begin
        for (int u = 0; u < S; u++) w_rnd[u] = xorshift32(r_rnd[u]);
    end

    // The two cluster-geometry streams (mode 4): stream A draws the cluster
    // count and the lengths, stream B draws the starts. Distinct seed mixes
    // keep them independent of each other and of the lane generators.
    logic [LW-1:0] r_rnd_a, r_rnd_b;
    logic [LW-1:0] w_rnd_a, w_rnd_b;
    assign w_rnd_a = xorshift32(r_rnd_a);
    assign w_rnd_b = xorshift32(r_rnd_b);

    `ALWAYS_FF_RST(aclk, w_aresetn,
        if (`RST_ASSERTED(w_aresetn)) begin
            for (int u = 0; u < S; u++) r_rnd[u] <= 32'h9E37_79B9 * 32'(u + 1);
            r_rnd_a <= (32'h9E37_79B9 * 32'd3);
            r_rnd_b <= (32'h9E37_79B9 * 32'd7);
        end else if (cfg_seed_load) begin
            // a zero state would stick at zero; the mix keeps every stream nonzero
            for (int u = 0; u < S; u++) r_rnd[u] <= (cfg_seed ^ (32'h9E37_79B9 * 32'(u + 1))) | 32'h1;
            r_rnd_a <= (cfg_seed ^ (32'h9E37_79B9 * 32'd3)) | 32'h1;
            r_rnd_b <= (cfg_seed ^ (32'h9E37_79B9 * 32'd7)) | 32'h1;
        end else if (w_a_fire) begin
            for (int u = 0; u < S; u++) r_rnd[u] <= w_rnd[u];
            r_rnd_a <= w_rnd_a;
            r_rnd_b <= w_rnd_b;
        end
    )

    // block position of lane 0 for the beat being accepted (r_first is
    // declared earlier: the stage-A ready term reads it)
    logic [POS_W-1:0] r_pos;

    // A registers
    logic [DATA_WIDTH-1:0] r_a_data;
    logic [S-1:0]          r_a_keep;
    logic                  r_a_last, r_a_first;
    logic [POS_W-1:0]      r_a_pos;
    logic [15:0]           r_a_r16 [S];
    logic [M-1:0]          r_a_val [S];
    logic [15:0]           r_a_rem [S];    // n - pos - u, the selection-sampling denominator
    logic [S-1:0]          r_a_inrange;    // pos + u < n
    logic [POS_W-1:0]      r_a_dbghold;    // 7 DEBUG: base snapshot at the block's first beat

    `ALWAYS_FF_RST(aclk, w_aresetn,
        if (`RST_ASSERTED(w_aresetn)) begin
            r_pos   <= '0;
            r_first <= 1'b1;
            r_a_v   <= 1'b0;
            r_a_data <= '0; r_a_keep <= '0; r_a_last <= 1'b0; r_a_first <= 1'b0; r_a_pos <= '0;
            r_a_dbghold <= '0;
            r_a_inrange <= '0;
            for (int u = 0; u < S; u++) begin
                r_a_r16[u] <= '0;
                r_a_val[u] <= '0;
                r_a_rem[u] <= '0;
            end
        end else begin
            if (w_a_fire) begin
                r_a_v     <= 1'b1;
                r_a_data  <= in_data;
                r_a_keep  <= in_keep;
                r_a_last  <= in_last;
                r_a_first <= r_first;
                r_a_pos   <= r_pos;
                for (int u = 0; u < S; u++) begin
                    r_a_r16[u]     <= w_rnd[u][15:0];
                    // the error value: raw register slice with zero remapped to
                    // one so every hit changes the symbol (M = 1 collapses to 1)
                    r_a_val[u]     <= (w_rnd[u][16 +: M] == '0) ? M'(1) : w_rnd[u][16 +: M];
                    r_a_rem[u]     <= POS_W'(N) - r_pos - POS_W'(u);
                    r_a_inrange[u] <= (r_pos + POS_W'(u)) < POS_W'(N);
                end
                r_pos   <= in_last ? '0 : r_pos + POS_W'(S);
                r_first <= in_last;
            end else if (w_b_fire) begin
                r_a_v <= 1'b0;
            end
        end
    )

    // -------------------------------------------------------------------------
    // Mode 4/5/6 block-start draw, SERIALIZED. The cluster/geometry values are
    // identical to the parallel form; only the timing differs. The streams are
    // walked one xorshift per cycle from a snapshot taken on the block's first
    // accepted beat, at most one multiply per cycle, because the parallel
    // unrolled draw -- 9 xorshifts plus 17 multiplies in one cycle -- mapped
    // into a PCIN-cascaded DSP blob and was the design's worst path twice
    // (~13 ns on Genesys 2). Validation hardware takes the backpressure: the
    // input pauses for the ~2*MAXB+2 cycle walk, and the block-start beat is
    // held at stage B until the table is complete.
    // -------------------------------------------------------------------------
    logic [POS_W-1:0] r_tab_start [MAXB];
    logic [15:0]      r_tab_len   [MAXB];
    logic [3:0]       r_n_burst;

    // per-block state for the application modes, filled by the draw walk
    // below; declared before first use (lint-decl-order), consumed in stage C
    logic [POS_W-1:0] r_loc_start, r_loc_wid;  // 5 LOCALIZED window
    logic             r_bad;                   // 6 BADBLOCK severity draw
    logic [15:0]      r_rate_eff;              // 6 BADBLOCK selected rate
    logic [POS_W-1:0] r_dbg_base;              // 7 DEBUG walk position

    logic [LW-1:0]    r_dxa, r_dxb;          // walking stream states
    logic [LW-1:0]    r_xa_hold, r_xb_hold;  // snapshot awaiting the walk
    logic             r_snap_pending;
    logic [4:0]       r_draw_cnt;
    logic [7:0]       w_fsm_n;
    logic [15:0]      w_fsm_l;
    logic [15:0]      w_fsm_li;
    logic [POS_W-1:0] w_fsm_s;
    logic [POS_W-1:0] w_fsm_s_loc;

    assign w_app_mode = (r_mode == 3'd4) || (r_mode == 3'd5) || (r_mode == 3'd6);

    // per-cycle draw step: at most one scale multiply on the registered
    // walking state, so no cascade and no long combinational chain. S_i uses
    // the L_i REGISTERED by the preceding odd count, not the live walking
    // state (which has already advanced past it).
    always_comb begin
        w_fsm_n = 8'(MAXB);
        if (r_cnt_max > r_cnt_min)
            w_fsm_n = r_cnt_min + 8'((32'(r_dxa[15:0]) * r_span_cnt) >> 16);
        else
            w_fsm_n = r_cnt_min;
        if (w_fsm_n > 8'(MAXB)) w_fsm_n = 8'(MAXB);
        if (r_len_max > r_len_min)
            w_fsm_l = r_len_min + 16'((32'(r_dxa[15:0]) * r_span_len) >> 16);
        else
            w_fsm_l = r_len_min;
        if (w_fsm_l > 16'(N)) w_fsm_l = 16'(N);
        w_fsm_li = r_tab_len[(int'(r_draw_cnt) >= 2) ? (int'(r_draw_cnt) - 2) / 2 : 0];
        w_fsm_s  = POS_W'((32'(r_dxb[15:0]) * (32'(N) - 32'(w_fsm_li) + 32'd1)) >> 16);
        // mode 5's window start must use the UNGATED width: r_loc_wid is
        // written without the (i < n_burst) cluster gate (mode 5 has no
        // cluster count), while r_tab_len is gated for mode 4 -- with a
        // zero/leftover cnt range the gated entry is 0 and would shift the
        // window start by drawing S against (N + 1) instead of (N - wid + 1)
        w_fsm_s_loc = POS_W'((32'(r_dxb[15:0]) * (32'(N) - 32'(r_loc_wid) + 32'd1)) >> 16);
    end

    `ALWAYS_FF_RST(aclk, w_aresetn,
        if (`RST_ASSERTED(w_aresetn)) begin
            r_n_burst <= '0;
            for (int i = 0; i < MAXB; i++) begin
                r_tab_start[i] <= '0;
                r_tab_len[i]   <= '0;
            end
            r_loc_start <= '0;
            r_loc_wid   <= '0;
            r_bad       <= 1'b0;
            r_rate_eff  <= '0;
            r_dbg_base  <= '0;
            r_dxa <= '0; r_dxb <= '0;
            r_xa_hold <= '0; r_xb_hold <= '0;
            r_snap_pending <= 1'b0; r_draw_busy <= 1'b0; r_draw_done <= 1'b0;
            r_draw_cnt <= '0;
        end else begin
            // snapshot the stream states on the block's first accepted beat;
            // 7 DEBUG advances its deterministic walk here too. The DEBUG
            // base is snapshotted BEFORE the advance: decisions run at stage
            // C, after the next block's first beat has already advanced the
            // live register -- a block deciding against the live base shifts
            // every hit one step and loses the hit whose position falls in
            // the block's last beats (issue #87).
            if (w_a_fire && r_first) begin
                r_xa_hold <= w_rnd_a;
                r_xb_hold <= w_rnd_b;
                r_snap_pending <= 1'b1;
                r_draw_done <= 1'b0;
                r_a_dbghold <= r_dbg_base;
                r_dbg_base <= (r_dbg_base + POS_W'(r_rate) >= POS_W'(N))
                              ? (r_dbg_base + POS_W'(r_rate) - POS_W'(N))
                              : (r_dbg_base + POS_W'(r_rate));
            end
            // start the walk once the previous one has finished; the table is
            // invalidated HERE (not at snapshot) so a previous walk's
            // end-of-walk done flag can never survive into the new block --
            // a block accepted mid-walk (non-app phases do not pause the
            // input) snapshots new state while the old walk is still running,
            // and only this ordering keeps done honest
            if (r_snap_pending && !r_draw_busy) begin
                r_snap_pending <= 1'b0;
                r_draw_busy    <= 1'b1;
                r_draw_done    <= 1'b0;
                r_draw_cnt     <= '0;
                r_dxa          <= r_xa_hold;
                r_dxb          <= r_xb_hold;
            end else if (r_draw_busy) begin
                r_draw_cnt <= r_draw_cnt + 1'b1;
                if (r_draw_cnt == 5'd0) begin
                    // N (and the 6 BADBLOCK severity draw) from the first value
                    r_n_burst  <= 4'(w_fsm_n);
                    r_bad      <= (r_dxa[15:0] < r_len_min);
                    r_rate_eff <= (r_dxa[15:0] < r_len_min) ? r_len_max : r_rate;
                    r_dxa      <= xorshift32(r_dxa);
                end else if (r_draw_cnt[0]) begin
                    // odd counts: L_i from the next stream-A value
                    automatic int li = (int'(r_draw_cnt) - 1) / 2;
                    if (li < MAXB) begin
                        r_tab_len[li] <= (li < int'(r_n_burst)) ? w_fsm_l : 16'd0;
                        if (li == 0) r_loc_wid <= w_fsm_l;   // 5 LOCALIZED window width
                    end
                    r_dxa <= xorshift32(r_dxa);
                end else begin
                    // even counts: S_i, using the L_i registered last cycle
                    automatic int si = (int'(r_draw_cnt) - 2) / 2;
                    r_tab_start[si] <= w_fsm_s;
                    if (si == 0) r_loc_start <= w_fsm_s_loc; // 5 LOCALIZED window start
                    r_dxb <= xorshift32(r_dxb);
                end
                if (r_draw_cnt == 5'(2 * MAXB + 1)) begin
                    r_draw_busy <= 1'b0;
                    r_draw_done <= 1'b1;
                end
            end
        end
    )

    // -------------------------------------------------------------------------
    // Stage B: the products, from A's registers -- a bare 16 x 16 multiply per
    // lane (one DSP). Only the high half matters: r16 * rem < e_left << 16 is
    // (r16 * rem) >> 16 < e_left, so the compare in C is 16 bits against 8.
    // -------------------------------------------------------------------------
    logic [31:0] w_lhs [S];       // r16 * (n - pos - u)
    logic [31:0] w_bprod;         // r16_0 * (n - e + 1), for the burst start
    logic [15:0] w_bspan;         // n - e + 1, the burst start's range
    always_comb begin
        for (int u = 0; u < S; u++) w_lhs[u] = 32'(r_a_r16[u]) * 32'(r_a_rem[u]);
        w_bspan = 16'(N) - 16'(r_count) + 16'd1;
        w_bprod = 32'(r_a_r16[0]) * 32'(w_bspan);
    end
    logic unused_frac;
    always_comb begin
        unused_frac = ^w_bprod[15:0];
        for (int u = 0; u < S; u++) unused_frac = unused_frac ^ (^w_lhs[u][15:0]);
    end

    logic [DATA_WIDTH-1:0] r_b_data;
    logic [S-1:0]          r_b_keep;
    logic                  r_b_last;
    logic [POS_W-1:0]      r_b_pos;
    logic [S-1:0]          r_b_inrange;
    logic [15:0]           r_b_lhs_hi [S];
    logic [15:0]           r_b_r16 [S];
    logic [M-1:0]          r_b_val [S];
    logic [POS_W-1:0]      r_b_bstart;
    logic [POS_W-1:0]      r_b_dbghold;   // 7 DEBUG base, block-aligned copy

    `ALWAYS_FF_RST(aclk, w_aresetn,
        if (`RST_ASSERTED(w_aresetn)) begin
            r_b_v <= 1'b0;
            r_b_data <= '0; r_b_keep <= '0; r_b_last <= 1'b0; r_b_first <= 1'b0; r_b_pos <= '0;
            r_b_bstart <= '0; r_b_inrange <= '0; r_b_dbghold <= '0;
            for (int u = 0; u < S; u++) begin
                r_b_lhs_hi[u] <= '0; r_b_r16[u] <= '0; r_b_val[u] <= '0;
            end
        end else begin
            if (w_b_fire) begin
                r_b_v      <= 1'b1;
                r_b_data   <= r_a_data;
                r_b_keep   <= r_a_keep;
                r_b_last   <= r_a_last;
                r_b_first  <= r_a_first;
                r_b_pos    <= r_a_pos;
                r_b_inrange <= r_a_inrange;
                r_b_bstart <= w_bprod[31:16];
                r_b_dbghold <= r_a_dbghold;
                for (int u = 0; u < S; u++) begin
                    r_b_lhs_hi[u] <= w_lhs[u][31:16];
                    r_b_r16[u] <= r_a_r16[u];
                    r_b_val[u] <= r_a_val[u];
                end
            end else if (w_dec_fire) begin
                r_b_v <= 1'b0;
            end
        end
    )

    // -------------------------------------------------------------------------
    // Stage C: decisions. Per-block state lives here.
    //
    // COUNT decides GRP lanes per cycle: the prefix recurrence (each lane's
    // threshold depends on how many lower lanes hit) is ~111 logic levels
    // across a wide single-cycle beat and cannot close at 100 MHz. The beat
    // waits in the B skid while a group counter walks the lanes; the hit mask
    // and count accumulate in registers and release on the final group. The
    // group-local prefix counter is 4 bits (0..GRP): the group-start count is
    // folded into per-lane capacity thresholds in parallel
    // (Kp' = clamp(Kp - k_start)), which halves the ripple a raw 8-bit
    // counter would pay. BURST / RATE / CLUSTERS are per-lane independent and
    // stay single-cycle.
    // -------------------------------------------------------------------------
    logic [7:0]       r_e_left;       // COUNT: errors still to place after the previous beat
    logic [7:0]       r_blk_errors;   // injected so far in this block
    logic [POS_W-1:0] r_burst_start;
    logic [POS_W-1:0] r_dbg_run;      // 7 DEBUG base, held across the block's beats

    logic [S-1:0]          w_hit;
    logic [DATA_WIDTH-1:0] w_mask;
    logic [7:0]            w_hits;
    logic [7:0]            w_e_after;

    assign w_count_mode = (r_mode == 3'd1);
    assign w_dec_step   = r_b_v && (w_c_fire || r_dec_busy);
    // A COUNT beat with no errors left to place cannot hit: every lane's
    // capacity is e_left - lhs_hi clamped at zero, so the group walk is
    // vacuous and the decision (all-zero mask, e_left unchanged) is final
    // after group 0. Fire it in one cycle and let clean blocks -- count=0
    // runs, blocks whose errors are already placed -- stream at line rate
    // instead of paying N_GRP+1 cycles per beat (issue #89). Blocks still
    // carrying errors take the full walk, unchanged.
    assign w_e_start_zero = w_count_mode && (r_b_first ? (r_count == 8'd0)
                                                       : (r_e_left == 8'd0));
    assign w_dec_fire   = w_dec_step && (!w_count_mode || (r_cyc == CYC_W'(N_GRP-1))
                                         || w_e_start_zero);

    always_comb begin
        logic [7:0]       e_left;
        logic [POS_W-1:0] pos;
        logic [POS_W-1:0] bstart;
        logic [POS_W-1:0] dbg_base;
        logic [7:0]       k;
        logic [16:0]      dpos;
        int               base;
        int               u;
        // defaults for every variable the mode branches assign conditionally;
        // the strict harness sim build treats inferred latches as errors
        e_left     = '0;
        pos        = '0;
        bstart     = '0;
        dbg_base   = '0;
        k          = '0;
        dpos       = '0;
        base       = 0;
        u          = 0;
        w_start_k  = '0;
        w_k_next   = '0;
        w_grp_hits = '0;
        w_hits     = '0;
        w_e_after  = '0;
        w_mask     = '0;
        for (int i = 0; i < GRP; i++) begin
            w_ghit[i]  = 1'b0;
            w_gkeep[i] = 1'b0;
            w_kp[i]    = '0;
        end
        e_left = r_b_first ? r_count : r_e_left;
        bstart = r_b_first ? r_b_bstart : r_burst_start;
        dbg_base = r_b_first ? r_b_dbghold : r_dbg_run;
        // BURST / RATE / CLUSTERS / LOCALIZED / BADBLOCK / DEBUG:
        // per-lane independent, single cycle
        w_hits = '0;
        for (int u = 0; u < S; u++) begin
            pos = r_b_pos + POS_W'(u);
            w_hit[u] = 1'b0;
            if (r_b_keep[u]) begin
                case (r_mode)
                    3'd2:    w_hit[u] = (pos >= bstart) && (pos < bstart + POS_W'(r_count));
                    3'd3:    w_hit[u] = (r_b_r16[u] < r_rate);
                    3'd4: begin
                        for (int i = 0; i < MAXB; i++) begin
                            if ((i < r_n_burst) && (pos >= r_tab_start[i])
                                && ({1'b0, pos} < (17'(r_tab_start[i]) + 17'(r_tab_len[i]))))
                                w_hit[u] = 1'b1;
                        end
                    end
                    3'd5:    w_hit[u] = (pos >= r_loc_start)
                                         && ({1'b0, pos} < (17'(r_loc_start) + 17'(r_loc_wid)))
                                         && (r_b_r16[u] < r_rate);
                    3'd6:    w_hit[u] = (r_b_r16[u] < r_rate_eff);
                    3'd7: begin
                        dpos = (pos >= dbg_base) ? (17'(pos) - 17'(dbg_base))
                                                 : (17'(pos) + 17'(N) - 17'(dbg_base));
                        w_hit[u] = (dpos < 17'(r_count));
                    end
                    default: w_hit[u] = 1'b0;
                endcase
            end
            w_mask[u*M +: M] = w_hit[u] ? r_b_val[u] : '0;
            w_hits    = w_hits + 8'(w_hit[u]);
        end
        w_e_after = e_left - w_hits;
        // COUNT: decide the r_cyc group, accumulate; release on the last group
        if (w_count_mode) begin
            base      = int'(r_cyc) * GRP;
            w_start_k = (r_cyc == '0) ? 8'd0 : r_k_mid;
            k         = '0;               // group-local prefix, 0..GRP
            for (int i = 0; i < GRP; i++) begin
                u = base + i;
                w_gkeep[i] = 1'b0;
                w_kp[i]    = '0;          // clamped group-local capacity
                if (u < S) begin
                    w_gkeep[i] = r_b_keep[u];
                    if (r_b_inrange[u] && (r_b_lhs_hi[u] < 16'(e_left))) begin
                        automatic logic [8:0] kp_full;
                        kp_full = 9'(e_left) - 9'(r_b_lhs_hi[u]);
                        if (kp_full > 9'(w_start_k)) begin
                            automatic logic [8:0] kp_loc;
                            kp_loc  = kp_full - 9'(w_start_k);
                            w_kp[i] = (kp_loc > 9'(GRP)) ? 8'(GRP + 1) : 8'(kp_loc);
                        end
                    end
                end
                w_ghit[i] = w_gkeep[i] && (k < w_kp[i]);
                k         = k + 8'(w_ghit[i]);
            end
            w_k_next   = w_start_k + k;
            w_grp_hits = k;
            w_hits     = r_hit_acc + w_grp_hits;
            w_e_after  = e_left - w_hits;
            for (int u = 0; u < S; u++) begin
                if ((u / GRP) == int'(r_cyc)) w_hit[u] = w_ghit[u % GRP];
                else                          w_hit[u] = r_mask_acc[u];
                w_mask[u*M +: M] = w_hit[u] ? r_b_val[u] : '0;
            end
        end
    end

    `ALWAYS_FF_RST(aclk, w_aresetn,
        if (`RST_ASSERTED(w_aresetn)) begin
            r_cyc      <= '0;
            r_dec_busy <= 1'b0;
            r_k_mid    <= '0;
            r_hit_acc  <= '0;
            r_mask_acc <= '0;
        end else begin
            if (w_dec_fire) begin
                r_cyc      <= '0;
                r_hit_acc  <= '0;
                r_mask_acc <= '0;
                r_dec_busy <= 1'b0;
            end else if (w_dec_step) begin
                r_cyc <= r_cyc + 1'b1;
            end
            if (w_c_fire && w_count_mode && (N_GRP > 1) && !w_e_start_zero) begin
                // a decision that completes this cycle (last group, or the
                // no-errors-left shortcut) must not set busy: it would survive
                // the fire above and make the NEXT beat walk phantom groups
                r_dec_busy <= 1'b1;
            end
            if (w_dec_step && !w_dec_fire) begin
                r_k_mid   <= w_k_next;
                r_hit_acc <= r_hit_acc + w_grp_hits;
                for (int u = 0; u < S; u++) begin
                    if ((u / GRP) == int'(r_cyc)) r_mask_acc[u] <= w_ghit[u % GRP];
                end
            end
        end
    )

    // C registers: the output beat, plus the beat's hit count and last flag for
    // the statistics stage a cycle later
    logic [DATA_WIDTH-1:0] r_c_data;
    logic [S-1:0]          r_c_keep;
    logic                  r_c_last;
    logic [S-1:0]          r_c_erasure;
    logic                  r_s_v, r_s_last;
    logic [7:0]            r_s_hits;
    logic [7:0]            w_blk_total;
    assign w_blk_total = r_blk_errors + r_s_hits;

    `ALWAYS_FF_RST(aclk, w_aresetn,
        if (`RST_ASSERTED(w_aresetn)) begin
            r_c_v <= 1'b0; r_c_data <= '0; r_c_keep <= '0; r_c_last <= 1'b0;
            r_c_erasure <= '0;
            r_s_v <= 1'b0; r_s_last <= 1'b0; r_s_hits <= '0;
            r_e_left            <= '0;
            r_blk_errors        <= '0;
            r_burst_start       <= '0;
            r_dbg_run           <= '0;
            o_inj_symbols       <= '0;
            o_inj_blocks        <= '0;
            o_inj_over_t        <= '0;
            o_last_block_errors <= '0;
        end else begin
            // the beat, released on the final decision group
            if (w_dec_fire) begin
                r_c_v    <= 1'b1;
                r_c_data <= r_b_data ^ w_mask;
                r_c_keep <= r_b_keep;
                r_c_last <= r_b_last;
                r_c_erasure <= r_mark_erasure ? w_hit : '0;
                if (r_b_first) r_burst_start <= r_b_bstart;
                if (r_b_first) r_dbg_run    <= r_b_dbghold;
                r_e_left <= w_e_after;
            end else if (out_valid && out_ready) begin
                r_c_v <= 1'b0;
            end
            // the statistics, one cycle behind the beat
            r_s_v    <= w_dec_fire;
            r_s_last <= r_b_last;
            r_s_hits <= w_hits;
            if (cfg_clear) begin
                o_inj_symbols       <= '0;
                o_inj_blocks        <= '0;
                o_inj_over_t        <= '0;
                o_last_block_errors <= '0;
                r_blk_errors        <= '0;
            end else if (r_s_v) begin
                o_inj_symbols <= o_inj_symbols + 32'(r_s_hits);
                if (r_s_last) begin
                    r_blk_errors        <= '0;
                    o_last_block_errors <= w_blk_total;
                    if (w_blk_total != 8'd0)         o_inj_blocks <= o_inj_blocks + 32'd1;
                    if (w_blk_total > 8'(T_SYMBOLS)) o_inj_over_t <= o_inj_over_t + 32'd1;
                end else begin
                    r_blk_errors <= w_blk_total;
                end
            end
        end
    )

    assign out_valid   = r_c_v;
    assign out_data    = r_c_data;
    assign out_keep    = r_c_keep;
    assign out_last    = r_c_last;
    assign out_erasure = r_c_erasure;

endmodule : error_injector

// SPDX-License-Identifier: MIT
// SPDX-FileCopyrightText: 2026 sean galloway
//
// Module: fb_endpoints
// Purpose: The fabric benchmark's LFSR source (S2) and CRC sink (S3) on their
//          own clock, behind CDC crossings, with their verdicts brought back.
//
// Documentation: projects/fpga-systems/Genesys2/fabric-benchmark/PRD.md
//                (DE10 PRD sections 4.1 and 5.3: fabric-only mode, clocks)
//
// Author: sean galloway
// Created: 2026-10-14
//
//==============================================================================
// Description:
//   Two slave ports on the FABRIC clock (aclk): s_rd_* is the LFSR source
//   window, s_wr_* the CRC sink window. Each crosses into the ENDPOINT clock
//   (ep_clk) through its own axi4_cdc_{rd,wr}, where one axi4_dma_slaves --
//   the same source/sink the Genesys 2 STREAM harness uses -- answers both.
//   Nothing here knows which fabric is upstream; both legs see this block
//   unchanged.
//
//   Why a separate clock: the endpoints accept a beat every cycle, and on a
//   clock at least as fast as the fabric's they cannot be what limits a run.
//   The slave-side observers sit on the s_* ports, upstream of the crossings,
//   so the crossings and endpoints fall out of the fabric's measured latency.
//
//   Status back to aclk. The CRCs and beat counts live in ep_clk. They return
//   as ONE coherent snapshot through cdc_2_phase_handshake, resent
//   continuously: the aclk side only ever sees a complete bundle, never a mix
//   of an old CRC and a new count. The cost is a lag of a few cycles of both
//   clocks per update -- identical in every leg, and outside the measurement
//   (the observers do the timing; the harness timer only stops the run).
//
//   The clear pulse goes the other way through sync_pulse. A clear issued
//   while beats are in flight is the host's error, as in the STREAM harness.
//
//------------------------------------------------------------------------------
// Parameters:
//------------------------------------------------------------------------------
//   NUM_CHANNELS   - STREAM channels (1..8)
//   CH_SEL_ADDR    - 1 (default): a burst's channel is its address bits
//                    [CH_ADDR_LSB +: log2(NUM_CHANNELS)] -- every leg, because
//                    SmartConnect (leg B2) carries no ID to its slaves and the
//                    endpoints must be identical in all legs. 0: the low ID
//                    bits, as in the STREAM harness.
//   CH_ADDR_LSB    - with CH_SEL_ADDR: each channel's window is 2^CH_ADDR_LSB
//                    bytes (default 16: channel N at window base + N * 64 KB);
//                    the host places each channel's buffers in its own window
//   AXI_ID_WIDTH   - slave-side ID width ({fabric slot, master id} on legs A and
//                    B1, 0-valued on B2); unused for channel selection by address
//   AXI_DATA_WIDTH - fabric data width
//   CDC_DEPTH      - async FIFO depth per AXI channel; 16 sustains a beat per
//                    cycle with the synchronizer round trip in flight
//   LFSR_SEED      - source seed (channel N uses LFSR_SEED ^ N); identical in
//                    every leg -- the legs are compared on the same data
//
//------------------------------------------------------------------------------
// Related Modules:
//------------------------------------------------------------------------------
//   axi4_dma_slaves, axi4_cdc_rd, axi4_cdc_wr, cdc_2_phase_handshake, sync_pulse
//==============================================================================

`timescale 1ns / 1ps

`include "reset_defs.svh"

module fb_endpoints #(
    parameter int          NUM_CHANNELS   = 8,
    parameter int          AXI_ID_WIDTH   = 10,
    parameter int          AXI_ADDR_WIDTH = 32,
    parameter int          AXI_DATA_WIDTH = 128,
    parameter int          CDC_DEPTH      = 16,
    parameter logic [31:0] LFSR_SEED      = 32'hDEADBEEF,
    parameter bit          CH_SEL_ADDR    = 1'b1,
    parameter int          CH_ADDR_LSB    = 16,
    // Short params
    parameter int IW = AXI_ID_WIDTH,
    parameter int AW = AXI_ADDR_WIDTH,
    parameter int DW = AXI_DATA_WIDTH,
    parameter int SW = DW / 8,
    parameter int NC = NUM_CHANNELS
) (
    // Fabric clock: the slave ports and every status output
    input  logic              aclk,
    input  logic              aresetn,
    // Endpoint clock
    input  logic              ep_clk,
    input  logic              ep_aresetn,

    // Clear both CRCs and beat counts (aclk pulse)
    input  logic              i_clear,

    // S2: LFSR source (read only)
    input  logic [IW-1:0]     s_rd_arid,
    input  logic [AW-1:0]     s_rd_araddr,
    input  logic [7:0]        s_rd_arlen,
    input  logic [2:0]        s_rd_arsize,
    input  logic [1:0]        s_rd_arburst,
    input  logic              s_rd_arlock,
    input  logic [3:0]        s_rd_arcache,
    input  logic [2:0]        s_rd_arprot,
    input  logic [3:0]        s_rd_arqos,
    input  logic              s_rd_arvalid,
    output logic              s_rd_arready,
    output logic [IW-1:0]     s_rd_rid,
    output logic [DW-1:0]     s_rd_rdata,
    output logic [1:0]        s_rd_rresp,
    output logic              s_rd_rlast,
    output logic              s_rd_rvalid,
    input  logic              s_rd_rready,

    // S3: CRC sink (write only)
    input  logic [IW-1:0]     s_wr_awid,
    input  logic [AW-1:0]     s_wr_awaddr,
    input  logic [7:0]        s_wr_awlen,
    input  logic [2:0]        s_wr_awsize,
    input  logic [1:0]        s_wr_awburst,
    input  logic              s_wr_awlock,
    input  logic [3:0]        s_wr_awcache,
    input  logic [2:0]        s_wr_awprot,
    input  logic [3:0]        s_wr_awqos,
    input  logic              s_wr_awvalid,
    output logic              s_wr_awready,
    input  logic [DW-1:0]     s_wr_wdata,
    input  logic [SW-1:0]     s_wr_wstrb,
    input  logic              s_wr_wlast,
    input  logic              s_wr_wvalid,
    output logic              s_wr_wready,
    output logic [IW-1:0]     s_wr_bid,
    output logic [1:0]        s_wr_bresp,
    output logic              s_wr_bvalid,
    input  logic              s_wr_bready,

    // Verdicts, aclk domain (one coherent snapshot, refreshed continuously)
    output logic [NC-1:0][31:0] o_read_crc_value,
    output logic [NC-1:0]       o_read_crc_valid,
    output logic [31:0]         o_read_beat_count,
    output logic [NC-1:0][31:0] o_write_crc_value,
    output logic [NC-1:0]       o_write_crc_valid,
    output logic [31:0]         o_write_beat_count
);

    // ------------------------------------------------------------------------
    // Crossings into ep_clk. The CDCs carry USER/REGION; the port set has
    // neither, so they ride as zero.
    // ------------------------------------------------------------------------
    logic [IW-1:0] e_arid, e_rid, e_awid, e_bid;
    logic [AW-1:0] e_araddr, e_awaddr;
    logic [7:0]    e_arlen, e_awlen;
    logic [2:0]    e_arsize, e_awsize, e_arprot, e_awprot;
    logic [1:0]    e_arburst, e_awburst, e_rresp, e_bresp;
    logic          e_arlock, e_awlock;
    logic [3:0]    e_arcache, e_awcache, e_arqos, e_awqos, e_arregion, e_awregion;
    logic          e_aruser, e_ruser, e_awuser, e_wuser, e_buser;
    logic          e_arvalid, e_arready, e_rvalid, e_rready, e_rlast;
    logic [DW-1:0] e_rdata, e_wdata;
    logic [SW-1:0] e_wstrb;
    logic          e_awvalid, e_awready, e_wvalid, e_wready, e_wlast, e_bvalid, e_bready;

    axi4_cdc_rd #(
        .AXI_ID_WIDTH(IW), .AXI_ADDR_WIDTH(AW), .AXI_DATA_WIDTH(DW),
        .AXI_USER_WIDTH(1), .CDC_DEPTH(CDC_DEPTH)
    ) u_cdc_rd (
        .s_aclk(aclk), .s_aresetn(aresetn),
        .s_axi_arid(s_rd_arid), .s_axi_araddr(s_rd_araddr), .s_axi_arlen(s_rd_arlen),
        .s_axi_arsize(s_rd_arsize), .s_axi_arburst(s_rd_arburst), .s_axi_arlock(s_rd_arlock),
        .s_axi_arcache(s_rd_arcache), .s_axi_arprot(s_rd_arprot), .s_axi_arqos(s_rd_arqos),
        .s_axi_arregion(4'b0), .s_axi_aruser(1'b0),
        .s_axi_arvalid(s_rd_arvalid), .s_axi_arready(s_rd_arready),
        .s_axi_rid(s_rd_rid), .s_axi_rdata(s_rd_rdata), .s_axi_rresp(s_rd_rresp),
        .s_axi_rlast(s_rd_rlast), .s_axi_ruser(), .s_axi_rvalid(s_rd_rvalid),
        .s_axi_rready(s_rd_rready),
        .m_aclk(ep_clk), .m_aresetn(ep_aresetn),
        .m_axi_arid(e_arid), .m_axi_araddr(e_araddr), .m_axi_arlen(e_arlen),
        .m_axi_arsize(e_arsize), .m_axi_arburst(e_arburst), .m_axi_arlock(e_arlock),
        .m_axi_arcache(e_arcache), .m_axi_arprot(e_arprot), .m_axi_arqos(e_arqos),
        .m_axi_arregion(e_arregion), .m_axi_aruser(e_aruser),
        .m_axi_arvalid(e_arvalid), .m_axi_arready(e_arready),
        .m_axi_rid(e_rid), .m_axi_rdata(e_rdata), .m_axi_rresp(e_rresp),
        .m_axi_rlast(e_rlast), .m_axi_ruser(e_ruser), .m_axi_rvalid(e_rvalid),
        .m_axi_rready(e_rready)
    );

    axi4_cdc_wr #(
        .AXI_ID_WIDTH(IW), .AXI_ADDR_WIDTH(AW), .AXI_DATA_WIDTH(DW),
        .AXI_USER_WIDTH(1), .CDC_DEPTH(CDC_DEPTH)
    ) u_cdc_wr (
        .s_aclk(aclk), .s_aresetn(aresetn),
        .s_axi_awid(s_wr_awid), .s_axi_awaddr(s_wr_awaddr), .s_axi_awlen(s_wr_awlen),
        .s_axi_awsize(s_wr_awsize), .s_axi_awburst(s_wr_awburst), .s_axi_awlock(s_wr_awlock),
        .s_axi_awcache(s_wr_awcache), .s_axi_awprot(s_wr_awprot), .s_axi_awqos(s_wr_awqos),
        .s_axi_awregion(4'b0), .s_axi_awuser(1'b0),
        .s_axi_awvalid(s_wr_awvalid), .s_axi_awready(s_wr_awready),
        .s_axi_wdata(s_wr_wdata), .s_axi_wstrb(s_wr_wstrb), .s_axi_wlast(s_wr_wlast),
        .s_axi_wuser(1'b0), .s_axi_wvalid(s_wr_wvalid), .s_axi_wready(s_wr_wready),
        .s_axi_bid(s_wr_bid), .s_axi_bresp(s_wr_bresp), .s_axi_buser(),
        .s_axi_bvalid(s_wr_bvalid), .s_axi_bready(s_wr_bready),
        .m_aclk(ep_clk), .m_aresetn(ep_aresetn),
        .m_axi_awid(e_awid), .m_axi_awaddr(e_awaddr), .m_axi_awlen(e_awlen),
        .m_axi_awsize(e_awsize), .m_axi_awburst(e_awburst), .m_axi_awlock(e_awlock),
        .m_axi_awcache(e_awcache), .m_axi_awprot(e_awprot), .m_axi_awqos(e_awqos),
        .m_axi_awregion(e_awregion), .m_axi_awuser(e_awuser),
        .m_axi_awvalid(e_awvalid), .m_axi_awready(e_awready),
        .m_axi_wdata(e_wdata), .m_axi_wstrb(e_wstrb), .m_axi_wlast(e_wlast),
        .m_axi_wuser(e_wuser), .m_axi_wvalid(e_wvalid), .m_axi_wready(e_wready),
        .m_axi_bid(e_bid), .m_axi_bresp(e_bresp), .m_axi_buser(e_buser),
        .m_axi_bvalid(e_bvalid), .m_axi_bready(e_bready)
    );

    // ------------------------------------------------------------------------
    // Clear into ep_clk
    // ------------------------------------------------------------------------
    logic w_ep_clear;
    sync_pulse u_clear_sync (
        .i_src_clk(aclk),   .i_src_rst_n(aresetn), .i_pulse(i_clear),
        .i_dst_clk(ep_clk), .i_dst_rst_n(ep_aresetn), .o_pulse(w_ep_clear)
    );

    // ------------------------------------------------------------------------
    // The source and sink, in ep_clk
    // ------------------------------------------------------------------------
    logic [NC-1:0][31:0] w_rd_crc, w_wr_crc;
    logic [NC-1:0]       w_rd_crc_v, w_wr_crc_v;
    logic [31:0]         w_rd_beats, w_wr_beats;

    axi4_dma_slaves #(
        .NUM_CHANNELS(NC), .AXI_ID_WIDTH(IW), .AXI_ADDR_WIDTH(AW),
        .AXI_DATA_WIDTH(DW), .AXI_USER_WIDTH(1), .LFSR_SEED(LFSR_SEED),
        .CH_SEL_ADDR(CH_SEL_ADDR), .CH_ADDR_LSB(CH_ADDR_LSB)
    ) u_slaves (
        .aclk(ep_clk), .aresetn(ep_aresetn),
        .read_lfsr_reset(w_ep_clear), .write_crc_reset(w_ep_clear),
        .read_crc_value(w_rd_crc), .read_crc_valid(w_rd_crc_v),
        .read_beat_count(), .read_beat_count_total(w_rd_beats),
        .write_crc_value(w_wr_crc), .write_crc_valid(w_wr_crc_v),
        .write_beat_count(), .write_beat_count_total(w_wr_beats),
        .s_axi_arid(e_arid), .s_axi_araddr(e_araddr), .s_axi_arlen(e_arlen),
        .s_axi_arsize(e_arsize), .s_axi_arburst(e_arburst), .s_axi_arlock(e_arlock),
        .s_axi_arcache(e_arcache), .s_axi_arprot(e_arprot), .s_axi_arqos(e_arqos),
        .s_axi_arregion(e_arregion), .s_axi_aruser(e_aruser),
        .s_axi_arvalid(e_arvalid), .s_axi_arready(e_arready),
        .s_axi_rid(e_rid), .s_axi_rdata(e_rdata), .s_axi_rresp(e_rresp),
        .s_axi_rlast(e_rlast), .s_axi_ruser(e_ruser), .s_axi_rvalid(e_rvalid),
        .s_axi_rready(e_rready),
        .s_axi_awid(e_awid), .s_axi_awaddr(e_awaddr), .s_axi_awlen(e_awlen),
        .s_axi_awsize(e_awsize), .s_axi_awburst(e_awburst), .s_axi_awlock(e_awlock),
        .s_axi_awcache(e_awcache), .s_axi_awprot(e_awprot), .s_axi_awqos(e_awqos),
        .s_axi_awregion(e_awregion), .s_axi_awuser(e_awuser),
        .s_axi_awvalid(e_awvalid), .s_axi_awready(e_awready),
        .s_axi_wdata(e_wdata), .s_axi_wstrb(e_wstrb), .s_axi_wlast(e_wlast),
        .s_axi_wuser(e_wuser), .s_axi_wvalid(e_wvalid), .s_axi_wready(e_wready),
        .s_axi_bid(e_bid), .s_axi_bresp(e_bresp), .s_axi_buser(e_buser),
        .s_axi_bvalid(e_bvalid), .s_axi_bready(e_bready),
        .busy_rd(), .busy_wr()
    );

    // ------------------------------------------------------------------------
    // Status snapshot back to aclk. The source side offers a fresh bundle
    // whenever the handshake is free, so the aclk copy trails ep_clk by one
    // round trip and is always internally consistent.
    // ------------------------------------------------------------------------
    localparam int SNAP_W = 2 * (NC * 32 + NC + 32);

    logic [SNAP_W-1:0] w_snap_src, w_snap_dst;
    logic              w_snap_dst_valid;

    assign w_snap_src = {w_rd_crc, w_rd_crc_v, w_rd_beats, w_wr_crc, w_wr_crc_v, w_wr_beats};

    cdc_2_phase_handshake #(
        .DATA_WIDTH(SNAP_W)
    ) u_status (
        .clk_src(ep_clk), .rst_src_n(ep_aresetn),
        .src_valid(1'b1), .src_ready(), .src_data(w_snap_src), .src_timeout(),
        .clk_dst(aclk), .rst_dst_n(aresetn),
        .dst_valid(w_snap_dst_valid), .dst_ready(1'b1), .dst_data(w_snap_dst)
    );

    `ALWAYS_FF_RST(aclk, aresetn,
        if (`RST_ASSERTED(aresetn)) begin
            o_read_crc_value   <= '0;
            o_read_crc_valid   <= '0;
            o_read_beat_count  <= '0;
            o_write_crc_value  <= '0;
            o_write_crc_valid  <= '0;
            o_write_beat_count <= '0;
        end else if (w_snap_dst_valid) begin
            {o_read_crc_value, o_read_crc_valid, o_read_beat_count,
             o_write_crc_value, o_write_crc_valid, o_write_beat_count} <= w_snap_dst;
        end
    )

endmodule : fb_endpoints

