`timescale 1ns / 1ps

//==============================================================================
// Module: reset_sync
//==============================================================================
// Description:
//   Multi-stage reset synchronizer for safe clock domain reset distribution.
//   Converts an asynchronous reset (typically active-low from POR or external
//   source) into a clean, clock-synchronous reset aligned to a destination
//   clock domain. Prevents metastability and ensures controlled reset
//   deassertion. Used per-clock-domain to safely fan out reset.
//
//------------------------------------------------------------------------------
// Key Enhancements (2025 Revision):
//------------------------------------------------------------------------------
//   - FPGA vs ASIC portable implementation (parametrized behavior)
//   - Optional vendor attributes for FPGA tool recognition
//   - Configurable polarity on input and output resets
//   - Optional purely synchronous style for ASIC methodology alignment
//   - Optional internal assertions (SVA) for timing and behavior checking
//
//------------------------------------------------------------------------------
// Features:
//------------------------------------------------------------------------------
//   - Parameterized synchronizer depth (N ≥ 2, default 3)
//   - Async assertion / sync deassertion (FPGA default)
//   - Optional fully synchronous reset (ASIC optional)
//   - Optional FPGA vendor attributes (ASYNC_REG, SHREG_EXTRACT, MLAB/M20K hints)
//   - Active-low I/O by default (matches typical FPGA and ASIC conventions)
//   - Built-in SVA option (RESET_SYNC_SVA)
//   - Elaboration-time guard against illegal N < 2
//
//------------------------------------------------------------------------------
// Parameters:
//------------------------------------------------------------------------------
//   N:
//     Description: Synchronizer depth (number of flip-flops)
//     Type: int
//     Range: 2 to 5
//     Default: 3
//     Notes: N=3 recommended (industry standard), N≥4 for extreme reliability
//
//   KEEP_ATTRS:
//     Description: Include FPGA vendor attributes for CDC inference
//     Type: bit
//     Default: 1
//     Notes: Set 0 for ASIC or pure Verilog synthesis
//
//   IN_ACTIVE_LOW:
//     Description: Input reset polarity (1=active-low, 0=active-high)
//     Type: bit
//     Default: 1
//
//   OUT_ACTIVE_LOW:
//     Description: Output reset polarity (1=active-low, 0=active-high)
//     Type: bit
//     Default: 1
//
//   ASYNC_ASSERT:
//     Description: Control reset assertion style
//     Type: bit
//     Default: 1
//     Notes:
//       1 = Asynchronous assert, synchronous deassert (FPGA default)
//       0 = Fully synchronous assert/deassert (ASIC optional)
//
//------------------------------------------------------------------------------
// Ports:
//------------------------------------------------------------------------------
//   Inputs:
//     clk:       Destination clock domain
//     rst_n:     Asynchronous reset input (default active-low)
//
//   Outputs:
//     sync_rst_n: Synchronized reset output (default active-low)
//                 Safe to use inside always_ff @(posedge clk)
//
//------------------------------------------------------------------------------
// Timing (FPGA default - ASYNC_ASSERT=1):
//------------------------------------------------------------------------------
//   Reset Assert:    Asynchronous (immediate)
//   Reset Deassert:  Synchronous, N-cycle latency
//   Latency:         N clock cycles for deassertion
//   MTBF:            Exponentially increases with N (3 → 10^12+ hours typical)
//
//------------------------------------------------------------------------------
// Behavior (FPGA default mode):
//------------------------------------------------------------------------------
//   - rst_n low immediately drives all synchronizer flops low
//   - On rising edge of clk after rst_n=1:
//       * Stage 0 captures 1'b1
//       * Subsequent stages shift 1'b1 toward MSB
//   - After N cycles, sync_rst_n deasserts (goes high)
//   - Prevents recovery/removal violations and metastability
//
//------------------------------------------------------------------------------
// Optional Behavior (ASIC mode, ASYNC_ASSERT=0):
//------------------------------------------------------------------------------
//   - Reset is sampled synchronously on clock edges
//   - Deassertion timing remains deterministic
//   - All stages deassert simultaneously without async event paths
//   - No asynchronous sensitivity list in the synchronizer itself
//
//------------------------------------------------------------------------------
// FPGA Usage Example (default - async assert / sync deassert):
//------------------------------------------------------------------------------
//
//   // 3-stage synchronizer with vendor attributes (default)
//   reset_sync #(
//       .N(3),
//       .KEEP_ATTRS(1),
//       .IN_ACTIVE_LOW(1),
//       .OUT_ACTIVE_LOW(1),
//       .ASYNC_ASSERT(1)     // Async assert, sync deassert (FPGA default)
//   ) u_rst_sync_fpga (
//       .clk        (clk_core),
//       .rst_n      (por_rst_n),   // Raw async reset (active-low)
//       .sync_rst_n (core_rst_n)   // Safe, clock-aligned reset (active-low)
//   );
//
//   // Usage in downstream logic
//   `ALWAYS_FF_RST(clk_core, core_rst_n, begin
//       if (`RST_ASSERTED(core_rst_n))
//           state <= IDLE;
//       else
//           state <= next_state;
//   end)
//
//------------------------------------------------------------------------------
// ASIC Usage Example (synchronous only):
//------------------------------------------------------------------------------
//
//   // Same ports, no vendor attributes, sync-only behavior
//   reset_sync #(
//       .N(2),
//       .KEEP_ATTRS(0),     // Remove FPGA-specific attributes
//       .ASYNC_ASSERT(0),   // Purely synchronous style (no async assert path)
//       .IN_ACTIVE_LOW(1),
//       .OUT_ACTIVE_LOW(1)
//   ) u_rst_sync_asic (
//       .clk        (clk_core),
//       .rst_n      (global_rst_n),
//       .sync_rst_n (core_rst_n)
//   );
//
//   // Downstream logic (identical reset handling)
//   `ALWAYS_FF_RST(clk_core, core_rst_n, begin
//       if (`RST_ASSERTED(core_rst_n))
//           r_ctrl <= '0;
//       else
//           r_ctrl <= next_ctrl;
//   end)
//
//------------------------------------------------------------------------------
// Comparative Notes (FPGA vs ASIC modes):
//------------------------------------------------------------------------------
//   Behavior Aspect        | FPGA Default (ASYNC_ASSERT=1)    | ASIC Mode (ASYNC_ASSERT=0)
//   ---------------------- | -------------------------------- | -----------------------------
//   Reset assertion        | Asynchronous (immediate)         | Synchronous (clocked)
//   Reset deassertion      | Synchronous, N cycles            | Synchronous, N cycles
//   Vendor attributes      | Included (`ASYNC_REG`, etc.)     | Removed
//   Input polarity         | Active-low (configurable)        | Active-low (configurable)
//   Output polarity        | Active-low (configurable)        | Active-low (configurable)
//   Use case               | FPGA/SoC RTL, external PORs      | ASIC, synchronous methodology
//   Synthesis tools        | Vivado, Quartus, Radiant         | DC, Genus, Yosys (ASIC flow)
//   Simulation behavior    | Same in both modes               | Same functional results
//
//------------------------------------------------------------------------------
// Notes:
//------------------------------------------------------------------------------
//   - Use one reset_sync per clock domain
//   - Never share a single sync_rst_n across multiple clocks
//   - N=3 is standard (3-stage metastability filtering)
//   - KEEP_ATTRS=1 enables dedicated synchronizer cell inference
//   - In ASIC mode, KEEP_ATTRS=0 for cleaner netlist
//   - Internal SVA (`RESET_SYNC_SVA`) checks deassert timing
//   - The sync chain initializes to '0, so with the default OUT_ACTIVE_LOW=1
//     the output powers up as sync_rst_n = ~0 = 1, i.e. DEASSERTED (released)
//   - Safe for any frequency ratio between reset source and clk
//   - Typical reset latency: N × Tclk
//   - Compatible with Verilator, VCS, Questa, and Xcelium
//
//------------------------------------------------------------------------------
// Related Modules:
//------------------------------------------------------------------------------
//   - sync_2ff.sv      : General data synchronizer (2-flop CDC)
//   - sync_pulse.sv    : Pulse synchronizer for one-shot transfers
//   - reset_sync_ah.sv : Active-high variant (if needed for legacy code)
//   - glitch_free_n_dff_arn.sv : Glitch-free mux with reset sync
//
//------------------------------------------------------------------------------
// Test:
//------------------------------------------------------------------------------
//   Location: val/cdc/test_reset_sync.py
//   Run: pytest val/cdc/test_reset_sync.py -v
//   Coverage: >95%
//   Key Test Scenarios:
//     - FPGA async-assert, N=2,3,4
//     - ASIC sync-only, N=2,3
//     - Metastability injection (force X on first stage)
//     - Back-to-back reset pulses
//     - Reset deassertion near clk edge
//
//==============================================================================
//
// Revision Summary (2025-10-21):
//   - Added polarity parameters (IN_ACTIVE_LOW, OUT_ACTIVE_LOW)
//   - Added ASYNC_ASSERT param for FPGA/ASIC flexibility
//   - Added KEEP_ATTRS to control vendor attributes
//   - Added detailed FPGA and ASIC instantiation examples
//   - Clarified behavioral equivalence and differences
//   - SVA properties generalized for both polarities
//==============================================================================

module reset_sync #(
    parameter int N               = 3,     // >=2 recommended
    parameter bit KEEP_ATTRS      = 1'b1,  // keep vendor attrs for FPGA
    // Polarity controls (no port changes needed)
    parameter bit IN_ACTIVE_LOW   = 1'b1,  // rst_n is active-low by default
    parameter bit OUT_ACTIVE_LOW  = 1'b1,  // sync output is active-low by default
    // Style control
    parameter bit ASYNC_ASSERT    = 1'b1   // 1: async-assert/sync-deassert (FPGA best practice)
) (
    input  logic clk,
    input  logic rst_n,          // async reset IN (name kept for compatibility)
    output logic sync_rst_n      // synced reset OUT (name kept for compatibility)
);

    // -----------------------------
    // Elaboration guards
    // -----------------------------
    if (N < 2) begin : g_illegal
        initial $error("reset_sync: N must be >= 2 (got %0d)", N);
    end

    // Normalize input to active-HIGH async reset
    wire rst_in_h = IN_ACTIVE_LOW ? ~rst_n : rst_n;

    // Synchronizer chain
    // Attributes help tools recognize CDC flops and avoid SRL extraction
    generate
        if (ASYNC_ASSERT) begin : g_async_assert
            if (KEEP_ATTRS) begin : g_attrd
                (* ASYNC_REG = "TRUE", SHREG_EXTRACT = "NO" *)
                (* altera_attribute = "-name SYNCHRONIZER_IDENTIFICATION FORCED" *)
                // The initialiser is the FPGA power-on value: the chain must come
                // up asserted on a device that has no reset before the first clock.
                // PROCASSINIT is the linter objecting to exactly that deliberate
                // combination, so the waiver is scoped to the declaration rather
                // than the file (RLB TASK-010, was RLB-010).
                /* verilator lint_off PROCASSINIT */
                logic [N-1:0] r_sync_reg = '0 /* synthesis syn_preserve = 1 */;
                /* verilator lint_on PROCASSINIT */

                // Async assert (posedge rst_in_h), sync deassert.
                //
                // THE ONE FILE IN rtl/ THAT DOES NOT USE `ALWAYS_FF_RST, and it
                // must not. The macro is asynchronous only when the build
                // defines USE_ASYNC_RESET; the default build makes it
                // synchronous. A reset synchroniser whose assert needs a clock
                // edge is not a reset synchroniser -- it is the thing that
                // produces the synchronous deassert everything else relies on,
                // so its own assert path has to be async unconditionally.
                // Active-HIGH here too, which the macro cannot express without
                // RESET_ACTIVE_HIGH set globally.
                always_ff @(posedge clk or posedge rst_in_h) begin
                    if (rst_in_h) r_sync_reg <= '1;                // hold asserted through chain
                    else          r_sync_reg <= {r_sync_reg[N-2:0], 1'b0};
                end

                // Active-HIGH internal form (asserted when MSB is 1)
                wire sync_rst_h = r_sync_reg[N-1];
                // Drive requested output polarity without changing port name
                always_comb begin
                    sync_rst_n = OUT_ACTIVE_LOW ? ~sync_rst_h : sync_rst_h;
                end
            end else begin : g_plain
                // The initialiser is the FPGA power-on value: the chain must come
                // up asserted on a device that has no reset before the first clock.
                // PROCASSINIT is the linter objecting to exactly that deliberate
                // combination, so the waiver is scoped to the declaration rather
                // than the file (RLB TASK-010, was RLB-010).
                /* verilator lint_off PROCASSINIT */
                logic [N-1:0] r_sync_reg = '0;
                /* verilator lint_on PROCASSINIT */

                always_ff @(posedge clk or posedge rst_in_h) begin
                    if (rst_in_h) r_sync_reg <= '1;
                    else          r_sync_reg <= {r_sync_reg[N-2:0], 1'b0};
                end

                wire sync_rst_h = r_sync_reg[N-1];
                always_comb begin
                    sync_rst_n = OUT_ACTIVE_LOW ? ~sync_rst_h : sync_rst_h;
                end
            end
        end else begin : g_sync_only
            // Purely synchronous reset style (rarely used for initial assert)
            if (KEEP_ATTRS) begin : g_attrd
                (* ASYNC_REG = "TRUE", SHREG_EXTRACT = "NO" *)
                (* altera_attribute = "-name SYNCHRONIZER_IDENTIFICATION FORCED" *)
                // The initialiser is the FPGA power-on value: the chain must come
                // up asserted on a device that has no reset before the first clock.
                // PROCASSINIT is the linter objecting to exactly that deliberate
                // combination, so the waiver is scoped to the declaration rather
                // than the file (RLB TASK-010, was RLB-010).
                /* verilator lint_off PROCASSINIT */
                logic [N-1:0] r_sync_reg = '0 /* synthesis syn_preserve = 1 */;
                /* verilator lint_on PROCASSINIT */

                always_ff @(posedge clk) begin
                    if (rst_in_h) r_sync_reg <= '1;
                    else          r_sync_reg <= {r_sync_reg[N-2:0], 1'b0};
                end

                wire sync_rst_h = r_sync_reg[N-1];
                always_comb begin
                    sync_rst_n = OUT_ACTIVE_LOW ? ~sync_rst_h : sync_rst_h;
                end
            end else begin : g_plain
                // The initialiser is the FPGA power-on value: the chain must come
                // up asserted on a device that has no reset before the first clock.
                // PROCASSINIT is the linter objecting to exactly that deliberate
                // combination, so the waiver is scoped to the declaration rather
                // than the file (RLB TASK-010, was RLB-010).
                /* verilator lint_off PROCASSINIT */
                logic [N-1:0] r_sync_reg = '0;
                /* verilator lint_on PROCASSINIT */

                always_ff @(posedge clk) begin
                    if (rst_in_h) r_sync_reg <= '1;
                    else          r_sync_reg <= {r_sync_reg[N-2:0], 1'b0};
                end

                wire sync_rst_h = r_sync_reg[N-1];
                always_comb begin
                    sync_rst_n = OUT_ACTIVE_LOW ? ~sync_rst_h : sync_rst_h;
                end
            end
        end
    endgenerate

`ifdef RESET_SYNC_SVA
    // Assertions in active-HIGH internal convention
    wire sync_rst_h_int = OUT_ACTIVE_LOW ? ~sync_rst_n : sync_rst_n;
    // When input asserted, output must be asserted
    property p_assert_holds;
        @(posedge clk) rst_in_h |-> sync_rst_h_int;
    endproperty
    assert property (p_assert_holds);

    // Deassert no earlier than N cycles after input deassert
    property p_deassert_after_N;
        @(posedge clk) disable iff (rst_in_h)
            $fell(rst_in_h) |-> (sync_rst_h_int)[*N-1] ##1 !sync_rst_h_int;
    endproperty
    assert property (p_deassert_after_N);
`endif

endmodule : reset_sync

// SPDX-License-Identifier: MIT
// SPDX-FileCopyrightText: 2026 sean galloway
//
// Module: rs_encoder_axi4
// Description: Reed-Solomon encoder as an AXI4 memory-to-memory job engine.
//
//   The AXI4 counterpart to rs_encoder_axis4 (PRD D9): a job names a source
//   address, a destination address and a BLOCK COUNT, and the block reads k
//   data symbols per block, encodes, and writes the n-symbol codewords out.
//   rs_axi4_read_engine feeds the core and rs_axi4_write_engine drains it,
//   both on the one AXI4 master port -- the read and write channel sets are
//   independent, so nothing arbitrates between them.
//
//   The job is in BLOCKS, not bytes. A codec's unit of work is a block, the
//   source and destination beat counts differ by construction (k in, n out),
//   and making the caller compute both from a byte count is how an off-by-one
//   becomes a framing error. The block count is the one number a caller has.
//
// Parameters:
//   SYMBOL_WIDTH / PRIM_POLY / T_SYMBOLS / N_SYMBOLS / FIRST_ROOT
//                    the code, exactly as rs_encoder_core takes them
//   DATA_WIDTH       AXI and stream width; a whole number of symbols
//   ADDR_WIDTH       AXI address width
//   ID_WIDTH         AXI id width
//   MAX_OUTSTANDING  requests in flight per direction
//
// Notes:
//   - A codeword is written PACKED: exactly ceil(N/S) beats with any partial
//     one last, which is rs_decoder_core's in_keep contract. The core itself
//     does not produce that -- it starts parity on a fresh beat, so at
//     K % S != 0 its output carries a partial beat mid-codeword that a decoder
//     flags as mis-framed. rs_beat_packer is generated in the output path to
//     close that up, and is omitted when there is nothing to pack.
//   - in_keep is generated here, because the read engine deals in beats and
//     knows nothing about symbols. Full on every beat except a block's last,
//     which carries K_TAIL symbols when k does not fill its final beat.
//   - The write side writes whole beats. A partial final beat's unused lanes
//     carry whatever the core emitted; the consumer knows the symbol count
//     from the profile and the block count. That is what lets the memory run
//     sdpram_core with USE_WSTRB = 0 and infer block RAM.
//   - cfg_done is the WRITE engine's done ANDed with the read's: the job is
//     finished when the codewords have been acknowledged by the destination,
//     not when the last source beat was fetched.
module rs_encoder_axi4
    import rs_pkg::*;
#(
    parameter int SYMBOL_WIDTH     = 8,
    parameter int PRIM_POLY        = 'h11D,
    parameter int T_SYMBOLS        = 8,
    parameter int N_SYMBOLS        = (1 << SYMBOL_WIDTH) - 1,
    parameter int FIRST_ROOT       = 0,
    parameter int DATA_WIDTH       = 32,
    parameter int ADDR_WIDTH       = 32,
    parameter int ID_WIDTH         = 4,
    parameter int MAX_OUTSTANDING  = 4,
    parameter int USER_WIDTH       = 1,
    // derived, exposed for the consumer's convenience
    parameter int K_SYMBOLS        = N_SYMBOLS - 2 * T_SYMBOLS,
    parameter int SYMBOLS_PER_BEAT = DATA_WIDTH / SYMBOL_WIDTH
) (
    input  logic                    aclk,
    input  logic                    aresetn,

    // -- job ---------------------------------------------------------------
    input  logic                    cfg_start,          // one-cycle pulse
    input  logic [ADDR_WIDTH-1:0]   cfg_src_addr,
    input  logic [ADDR_WIDTH-1:0]   cfg_dst_addr,
    input  logic [15:0]             cfg_blocks,
    input  logic [7:0]              cfg_burst_len,
    input  logic [ID_WIDTH-1:0]     cfg_axi_id,
    output logic                    cfg_done,
    output logic                    resp_err,           // sticky, either direction
    output logic                    frame_err,          // sticky: a short/long block

    // -- AXI4 master: read channels ----------------------------------------
    output logic [ID_WIDTH-1:0]     m_axi_arid,
    output logic [ADDR_WIDTH-1:0]   m_axi_araddr,
    output logic [7:0]              m_axi_arlen,
    output logic [2:0]              m_axi_arsize,
    output logic [1:0]              m_axi_arburst,
    output logic                    m_axi_arlock,
    output logic [3:0]              m_axi_arcache,
    output logic [2:0]              m_axi_arprot,
    output logic [3:0]              m_axi_arqos,
    output logic [3:0]              m_axi_arregion,
    output logic [USER_WIDTH-1:0]   m_axi_aruser,
    output logic                    m_axi_arvalid,
    input  logic                    m_axi_arready,
    input  logic [ID_WIDTH-1:0]     m_axi_rid,
    input  logic [DATA_WIDTH-1:0]   m_axi_rdata,
    input  logic [1:0]              m_axi_rresp,
    input  logic                    m_axi_rlast,
    input  logic [USER_WIDTH-1:0]   m_axi_ruser,
    input  logic                    m_axi_rvalid,
    output logic                    m_axi_rready,

    // -- AXI4 master: write channels ---------------------------------------
    output logic [ID_WIDTH-1:0]     m_axi_awid,
    output logic [ADDR_WIDTH-1:0]   m_axi_awaddr,
    output logic [7:0]              m_axi_awlen,
    output logic [2:0]              m_axi_awsize,
    output logic [1:0]              m_axi_awburst,
    output logic                    m_axi_awlock,
    output logic [3:0]              m_axi_awcache,
    output logic [2:0]              m_axi_awprot,
    output logic [3:0]              m_axi_awqos,
    output logic [3:0]              m_axi_awregion,
    output logic [USER_WIDTH-1:0]   m_axi_awuser,
    output logic                    m_axi_awvalid,
    input  logic                    m_axi_awready,
    output logic [DATA_WIDTH-1:0]   m_axi_wdata,
    output logic [DATA_WIDTH/8-1:0] m_axi_wstrb,
    output logic                    m_axi_wlast,
    output logic [USER_WIDTH-1:0]   m_axi_wuser,
    output logic                    m_axi_wvalid,
    input  logic                    m_axi_wready,
    input  logic [ID_WIDTH-1:0]     m_axi_bid,
    input  logic [1:0]              m_axi_bresp,
    input  logic [USER_WIDTH-1:0]   m_axi_buser,
    input  logic                    m_axi_bvalid,
    output logic                    m_axi_bready
);

    // Boundary reset synchronization. The port aresetn is treated as an
    // asynchronous-assert input of unknown deassert quality: an N=3
    // reset_sync (rtl/cdc, formally proven) produces the internal reset
    // every block below sees.
    logic w_aresetn;
    reset_sync #(
        .N             (3),
        .KEEP_ATTRS    (1'b1),
        .IN_ACTIVE_LOW (1'b1),
        .OUT_ACTIVE_LOW(1'b1),
        .ASYNC_ASSERT  (1'b1)
    ) u_reset_sync (
        .clk        (aclk),
        .rst_n      (aresetn),
        .sync_rst_n (w_aresetn)
    );

    localparam int S        = SYMBOLS_PER_BEAT;
    localparam int K_BEATS  = (K_SYMBOLS + S - 1) / S;
    localparam int K_TAIL   = K_SYMBOLS % S;          // 0 = the last data beat is full
    localparam int SIZE_B   = $clog2(DATA_WIDTH / 8); // AXI axsize

    // A codeword leaves this module PACKED: exactly ceil(N/S) beats, with any
    // partial one last. That is rs_decoder_core's in_keep contract.
    localparam int CW_BEATS = (N_SYMBOLS + S - 1) / S;

    // The core emits its data phase then starts parity on a FRESH beat, so at
    // K % S != 0 its output carries a partial beat MID-codeword, which a
    // decoder rejects. rs_beat_packer closes that up. At K % S == 0 there is
    // nothing to pack -- the core's own layout is already ceil(N/S) beats with
    // any partial last -- so the packer is not built and costs nothing.
    localparam bit NEED_PACK = rs_need_pack(K_SYMBOLS, S);

    if (DATA_WIDTH % SYMBOL_WIDTH != 0)
        $fatal(1, "rs_encoder_axi4: DATA_WIDTH %0d is not a whole number of %0d-bit symbols",
               DATA_WIDTH, SYMBOL_WIDTH);


    // =========================================================================
    // source: k data beats per block
    // =========================================================================
    logic                  rd_valid, rd_ready, rd_last, rd_done, rd_err;
    logic [DATA_WIDTH-1:0] rd_data;

    rs_axi4_read_engine #(
        .ADDR_WIDTH(ADDR_WIDTH), .DATA_WIDTH(DATA_WIDTH), .ID_WIDTH(ID_WIDTH),
        .MAX_OUTSTANDING(MAX_OUTSTANDING), .USER_WIDTH(USER_WIDTH)
    ) u_rd (
        .aclk(aclk), .aresetn(w_aresetn),
        .cfg_start(cfg_start), .cfg_src_addr(cfg_src_addr),
        .cfg_beats(32'(cfg_blocks) * 32'(K_BEATS)),
        .cfg_burst_len(cfg_burst_len), .cfg_beats_per_block(16'(K_BEATS)),
        .cfg_axi_id(cfg_axi_id), .cfg_axi_size(3'(SIZE_B)),
        .cfg_done(rd_done), .resp_err(rd_err),
        .out_valid(rd_valid), .out_ready(rd_ready), .out_data(rd_data), .out_last(rd_last),
        .m_axi_arid(m_axi_arid), .m_axi_araddr(m_axi_araddr), .m_axi_arlen(m_axi_arlen),
        .m_axi_arsize(m_axi_arsize), .m_axi_arburst(m_axi_arburst),
        .m_axi_arlock(m_axi_arlock), .m_axi_arcache(m_axi_arcache),
        .m_axi_arprot(m_axi_arprot), .m_axi_arqos(m_axi_arqos),
        .m_axi_arregion(m_axi_arregion), .m_axi_aruser(m_axi_aruser),
        .m_axi_arvalid(m_axi_arvalid), .m_axi_arready(m_axi_arready),
        .m_axi_rid(m_axi_rid), .m_axi_rdata(m_axi_rdata), .m_axi_rresp(m_axi_rresp),
        .m_axi_rlast(m_axi_rlast), .m_axi_ruser(m_axi_ruser),
        .m_axi_rvalid(m_axi_rvalid), .m_axi_rready(m_axi_rready));

    // The read engine counts beats; symbols are this module's business. Only a
    // block's LAST data beat can be partial, and only when k does not fill it.
    logic [S-1:0] w_in_keep;
    assign w_in_keep = (rd_last && (K_TAIL != 0)) ? S'((1 << K_TAIL) - 1) : {S{1'b1}};

    // =========================================================================
    // the codec
    // =========================================================================
    logic                  enc_valid, enc_ready, enc_last, w_frame_err;
    logic [DATA_WIDTH-1:0] enc_data;
    logic [S-1:0]          enc_keep;

    rs_encoder_core #(
        .SYMBOL_WIDTH(SYMBOL_WIDTH), .PRIM_POLY(PRIM_POLY), .T_SYMBOLS(T_SYMBOLS),
        .N_SYMBOLS(N_SYMBOLS), .FIRST_ROOT(FIRST_ROOT), .DATA_WIDTH(DATA_WIDTH)
    ) u_core (
        .aclk(aclk), .aresetn(w_aresetn),
        .in_valid(rd_valid), .in_ready(rd_ready), .in_data(rd_data),
        .in_keep(w_in_keep), .in_last(rd_last),
        .out_valid(enc_valid), .out_ready(enc_ready), .out_data(enc_data),
        .out_keep(enc_keep), .out_last(enc_last),
        .frame_err(w_frame_err));

    // =========================================================================
    // repack, when the core's layout is not already decoder-legal
    // =========================================================================
    logic                  pk_valid, pk_ready, pk_last;
    logic [DATA_WIDTH-1:0] pk_data;
    logic [S-1:0]          pk_keep;

    if (NEED_PACK) begin : g_pack
        rs_beat_packer #(
            .SYMBOL_WIDTH(SYMBOL_WIDTH), .SYMBOLS_PER_BEAT(S)
        ) u_pack (
            .aclk(aclk), .aresetn(w_aresetn),
            .in_valid(enc_valid), .in_ready(enc_ready), .in_data(enc_data),
            .in_keep(enc_keep), .in_last(enc_last),
            .out_valid(pk_valid), .out_ready(pk_ready), .out_data(pk_data),
            .out_keep(pk_keep), .out_last(pk_last));
    end else begin : g_no_pack
        assign pk_valid  = enc_valid;
        assign enc_ready = pk_ready;
        assign pk_data   = enc_data;
        assign pk_keep   = enc_keep;
        assign pk_last   = enc_last;
    end

    // =========================================================================
    // destination: a codeword per block
    // =========================================================================
    logic wr_done, wr_err;

    rs_axi4_write_engine #(
        .ADDR_WIDTH(ADDR_WIDTH), .DATA_WIDTH(DATA_WIDTH), .ID_WIDTH(ID_WIDTH),
        .MAX_OUTSTANDING(MAX_OUTSTANDING), .USER_WIDTH(USER_WIDTH)
    ) u_wr (
        .aclk(aclk), .aresetn(w_aresetn),
        .cfg_start(cfg_start), .cfg_dst_addr(cfg_dst_addr),
        .cfg_beats(32'(cfg_blocks) * 32'(CW_BEATS)),
        .cfg_burst_len(cfg_burst_len), .cfg_axi_id(cfg_axi_id),
        .cfg_axi_size(3'(SIZE_B)),
        .cfg_done(wr_done), .resp_err(wr_err),
        .in_valid(pk_valid), .in_ready(pk_ready), .in_data(pk_data), .in_last(pk_last),
        .m_axi_awid(m_axi_awid), .m_axi_awaddr(m_axi_awaddr), .m_axi_awlen(m_axi_awlen),
        .m_axi_awsize(m_axi_awsize), .m_axi_awburst(m_axi_awburst),
        .m_axi_awlock(m_axi_awlock), .m_axi_awcache(m_axi_awcache),
        .m_axi_awprot(m_axi_awprot), .m_axi_awqos(m_axi_awqos),
        .m_axi_awregion(m_axi_awregion), .m_axi_awuser(m_axi_awuser),
        .m_axi_awvalid(m_axi_awvalid), .m_axi_awready(m_axi_awready),
        .m_axi_wdata(m_axi_wdata), .m_axi_wstrb(m_axi_wstrb), .m_axi_wlast(m_axi_wlast),
        .m_axi_wuser(m_axi_wuser), .m_axi_wvalid(m_axi_wvalid), .m_axi_wready(m_axi_wready),
        .m_axi_bid(m_axi_bid), .m_axi_bresp(m_axi_bresp), .m_axi_buser(m_axi_buser),
        .m_axi_bvalid(m_axi_bvalid), .m_axi_bready(m_axi_bready));

    // =========================================================================
    // job status
    // =========================================================================
    assign cfg_done = rd_done && wr_done;
    assign resp_err = rd_err || wr_err;

    // frame_err is a pulse from the core; hold it for the job so a host that
    // polls after cfg_done still sees it
    always_ff @(posedge aclk or negedge w_aresetn) begin
        if (!w_aresetn)            frame_err <= 1'b0;
        else if (cfg_start)      frame_err <= 1'b0;
        else if (w_frame_err)    frame_err <= 1'b1;
    end

    // the packed stream reports keep; the write side writes whole beats
    logic unused_e;
    assign unused_e = ^pk_keep;

endmodule

// SPDX-License-Identifier: MIT
// SPDX-FileCopyrightText: 2026 sean galloway
//
// Module: rs_encoder_axis4
// Description: Reed-Solomon systematic encoder with AXI4-Stream interfaces.
//
//   This is the component's integration top (PRD D9). `rs_encoder_core` speaks
//   a bare valid/ready/last handshake, which is the right interface for the
//   algorithm but the wrong one for a fabric. This wraps it in the house
//   `axis4_slave` / `axis4_master` skid wrappers so a consumer connects a
//   stream, not eleven renamed wires.
//
//   Why this module exists at all: the Nexys A7 loop harness used to rename
//   the core's handshake onto its generator and checker signals inline, in the
//   BOARD area. That put an interface decision that belongs to the component
//   in a project that merely instantiates it, and every future consumer would
//   have had to repeat it. The adapter lives here now, once.
//
// Parameters:
//   SYMBOL_WIDTH      GF(2^m) symbol width, m. 8 is the common case.
//   PRIM_POLY         field polynomial, degree m, as an integer
//   T_SYMBOLS         correctable symbols per block; parity is 2t symbols
//   N_SYMBOLS         codeword length in symbols, <= 2^m - 1
//   FIRST_ROOT        b in g(x) = prod (x - alpha^(b+i))
//   DATA_WIDTH        stream width; must be a whole number of symbols
//   SKID_DEPTH        depth of the two AXIS skid buffers, 2..8
//   AXIS_*_WIDTH      tid / tdest / tuser widths, forwarded beat for beat
//
// Notes:
//   - tstrb vs keep. The core's `keep` is PER SYMBOL; AXI4-Stream's tstrb is
//     PER BYTE. At SYMBOL_WIDTH == 8 the two coincide and tstrb carries keep
//     directly. At any other m they do not, so keep rides the low
//     SYMBOLS_PER_BEAT bits of tuser and tstrb is driven all ones. The
//     elaboration guard below enforces a wide enough tuser for that case
//     rather than silently truncating the strobe.
//   - keep is low-aligned and may be partial only on a block's last beat,
//     which is the core's contract, not something this wrapper relaxes.
//   - tid and tdest are forwarded from the beat that ENTERS the encoder to the
//     beats that leave it, held for the whole codeword. Parity beats carry the
//     same id and dest as the block's data beats.
module rs_encoder_axis4
    import rs_pkg::*;
#(
    parameter int SYMBOL_WIDTH     = 8,
    parameter int PRIM_POLY        = 'h11D,
    parameter int T_SYMBOLS        = 8,
    parameter int N_SYMBOLS        = (1 << SYMBOL_WIDTH) - 1,
    parameter int FIRST_ROOT       = 0,
    parameter int DATA_WIDTH       = SYMBOL_WIDTH,
    parameter int SKID_DEPTH       = 2,
    parameter int AXIS_ID_WIDTH    = 0,
    parameter int AXIS_DEST_WIDTH  = 0,
    parameter int AXIS_USER_WIDTH  = 0,
    // derived, exposed for the consumer's convenience
    parameter int K_SYMBOLS        = N_SYMBOLS - 2 * T_SYMBOLS,
    parameter int SYMBOLS_PER_BEAT = DATA_WIDTH / SYMBOL_WIDTH,
    // zero-width AXIS sidebands still need a 1-bit wire; these are in the
    // parameter list rather than the body because the PORTS below use them
    parameter int IW               = (AXIS_ID_WIDTH   > 0) ? AXIS_ID_WIDTH   : 1,
    parameter int DESTW            = (AXIS_DEST_WIDTH > 0) ? AXIS_DEST_WIDTH : 1,
    parameter int UW               = (AXIS_USER_WIDTH > 0) ? AXIS_USER_WIDTH : 1
) (
    input  logic                       aclk,
    input  logic                       aresetn,

    // data symbols in
    input  logic [DATA_WIDTH-1:0]      s_axis_tdata,
    input  logic [DATA_WIDTH/8-1:0]    s_axis_tstrb,
    input  logic                       s_axis_tlast,
    input  logic [IW-1:0]              s_axis_tid,
    input  logic [DESTW-1:0]           s_axis_tdest,
    input  logic [UW-1:0]              s_axis_tuser,
    input  logic                       s_axis_tvalid,
    output logic                       s_axis_tready,

    // codeword symbols out: k data beats then the parity beats
    output logic [DATA_WIDTH-1:0]      m_axis_tdata,
    output logic [DATA_WIDTH/8-1:0]    m_axis_tstrb,
    output logic                       m_axis_tlast,
    output logic [IW-1:0]              m_axis_tid,
    output logic [DESTW-1:0]           m_axis_tdest,
    output logic [UW-1:0]              m_axis_tuser,
    output logic                       m_axis_tvalid,
    input  logic                       m_axis_tready,

    // one-cycle pulse: a block ended with other than k data symbols
    output logic                       frame_err
);

    // Boundary reset synchronization. The port aresetn is treated as an
    // asynchronous-assert input of unknown deassert quality: an N=3
    // reset_sync (rtl/cdc, formally proven) produces the internal reset
    // every block below sees.
    logic w_aresetn;
    reset_sync #(
        .N             (3),
        .KEEP_ATTRS    (1'b1),
        .IN_ACTIVE_LOW (1'b1),
        .OUT_ACTIVE_LOW(1'b1),
        .ASYNC_ASSERT  (1'b1)
    ) u_reset_sync (
        .clk        (aclk),
        .rst_n      (aresetn),
        .sync_rst_n (w_aresetn)
    );

    // -------------------------------------------------------------------------
    // widths
    // -------------------------------------------------------------------------
    localparam int S     = SYMBOLS_PER_BEAT;
    localparam int SW    = DATA_WIDTH / 8;

    // At m == 8 a byte IS a symbol, so tstrb and keep are the same vector.
    // Anywhere else they are not, and guessing would corrupt partial beats.
    localparam bit KEEP_ON_USER = (SYMBOL_WIDTH != 8);

    // rs_encoder_core finishes its data phase and starts parity on a FRESH
    // beat, so at K % S != 0 its output carries a partial beat MID-codeword.
    // That is poor AXI-Stream citizenship -- a partial TSTRB is expected on
    // TLAST and almost nowhere else, and an rs_decoder_core downstream flags
    // it as a mis-framed block outright (PRD D9b). rs_beat_packer closes it
    // up so a codeword leaves as ceil(N/S) beats with any partial one last.
    // At K % S == 0 there is nothing to pack and it is not built.
    localparam bit NEED_PACK = rs_need_pack(K_SYMBOLS, S);

    if (DATA_WIDTH % SYMBOL_WIDTH != 0)
        $fatal(1, "rs_encoder_axis4: DATA_WIDTH %0d is not a whole number of %0d-bit symbols",
               DATA_WIDTH, SYMBOL_WIDTH);
    if (KEEP_ON_USER && AXIS_USER_WIDTH < S)
        // SV has no adjacent string-literal concatenation; keep it one literal
        $fatal(1, "rs_encoder_axis4: SYMBOL_WIDTH %0d != 8 so keep rides tuser, needing AXIS_USER_WIDTH >= SYMBOLS_PER_BEAT (%0d), got %0d",
               SYMBOL_WIDTH, S, AXIS_USER_WIDTH);

    // -------------------------------------------------------------------------
    // intake skid
    // -------------------------------------------------------------------------
    logic [DATA_WIDTH-1:0] in_tdata;
    logic [SW-1:0]         in_tstrb;
    logic                  in_tlast, in_tvalid, in_tready;
    logic [IW-1:0]         in_tid;
    logic [DESTW-1:0]      in_tdest;
    logic [UW-1:0]         in_tuser;

    /* verilator lint_off PINCONNECTEMPTY */
    axis4_slave #(
        .SKID_DEPTH(SKID_DEPTH), .AXIS_DATA_WIDTH(DATA_WIDTH),
        .AXIS_ID_WIDTH(AXIS_ID_WIDTH), .AXIS_DEST_WIDTH(AXIS_DEST_WIDTH),
        .AXIS_USER_WIDTH(AXIS_USER_WIDTH)
    ) u_in (
        .aclk(aclk), .aresetn(w_aresetn),
        .s_axis_tdata(s_axis_tdata), .s_axis_tstrb(s_axis_tstrb),
        .s_axis_tlast(s_axis_tlast), .s_axis_tid(s_axis_tid),
        .s_axis_tdest(s_axis_tdest), .s_axis_tuser(s_axis_tuser),
        .s_axis_tvalid(s_axis_tvalid), .s_axis_tready(s_axis_tready),
        .fub_axis_tdata(in_tdata), .fub_axis_tstrb(in_tstrb),
        .fub_axis_tlast(in_tlast), .fub_axis_tid(in_tid),
        .fub_axis_tdest(in_tdest), .fub_axis_tuser(in_tuser),
        .fub_axis_tvalid(in_tvalid), .fub_axis_tready(in_tready),
        .busy());
    /* verilator lint_on PINCONNECTEMPTY */

    // -------------------------------------------------------------------------
    // the codec
    // -------------------------------------------------------------------------
    logic [S-1:0]          w_in_keep;
    logic [DATA_WIDTH-1:0] core_data;
    logic [S-1:0]          core_keep;
    logic                  core_last, core_valid, core_ready;

    // A ternary will not do here: both arms ELABORATE, so in_tuser[S-1:0]
    // is range-checked even when KEEP_ON_USER is constant 0 -- and tuser is
    // 1 bit wide in that configuration, which is the normal one. It has to be
    // a generate so only the live arm exists.
    if (KEEP_ON_USER) begin : g_keep_in_user
        assign w_in_keep = in_tuser[S-1:0];
    end else begin : g_keep_in_strb
        assign w_in_keep = in_tstrb[S-1:0];
    end

    rs_encoder_core #(
        .SYMBOL_WIDTH(SYMBOL_WIDTH), .PRIM_POLY(PRIM_POLY), .T_SYMBOLS(T_SYMBOLS),
        .N_SYMBOLS(N_SYMBOLS), .FIRST_ROOT(FIRST_ROOT), .DATA_WIDTH(DATA_WIDTH),
        .SKID_DEPTH(SKID_DEPTH)
    ) u_core (
        .aclk(aclk), .aresetn(w_aresetn),
        .in_valid(in_tvalid), .in_ready(in_tready), .in_data(in_tdata),
        .in_keep(w_in_keep), .in_last(in_tlast),
        .out_valid(core_valid), .out_ready(core_ready), .out_data(core_data),
        .out_keep(core_keep), .out_last(core_last),
        .frame_err(frame_err));

    // -------------------------------------------------------------------------
    // repack, when the core's layout would put a partial beat mid-codeword
    // -------------------------------------------------------------------------
    logic [DATA_WIDTH-1:0] pk_data;
    logic [S-1:0]          pk_keep;
    logic                  pk_last, pk_valid, pk_ready;

    if (NEED_PACK) begin : g_pack
        rs_beat_packer #(
            .SYMBOL_WIDTH(SYMBOL_WIDTH), .SYMBOLS_PER_BEAT(S)
        ) u_pack (
            .aclk(aclk), .aresetn(w_aresetn),
            .in_valid(core_valid), .in_ready(core_ready), .in_data(core_data),
            .in_keep(core_keep), .in_last(core_last),
            .out_valid(pk_valid), .out_ready(pk_ready), .out_data(pk_data),
            .out_keep(pk_keep), .out_last(pk_last));
    end else begin : g_no_pack
        assign pk_valid   = core_valid;
        assign core_ready = pk_ready;
        assign pk_data    = core_data;
        assign pk_keep    = core_keep;
        assign pk_last    = core_last;
    end

    // -------------------------------------------------------------------------
    // id / dest passthrough
    //
    // A codeword leaves as more beats than it entered as, so the id and dest
    // cannot ride the datapath -- they are captured from the block's FIRST
    // accepted beat and held until its last beat leaves.
    // -------------------------------------------------------------------------
    logic [IW-1:0]    r_tid;
    logic [DESTW-1:0] r_tdest;
    logic             r_have;

    always_ff @(posedge aclk or negedge w_aresetn) begin
        if (!w_aresetn) begin
            r_tid <= '0; r_tdest <= '0; r_have <= 1'b0;
        end else begin
            if (in_tvalid && in_tready && !r_have) begin
                r_tid <= in_tid; r_tdest <= in_tdest; r_have <= 1'b1;
            end
            if (pk_valid && pk_ready && pk_last) r_have <= 1'b0;
        end
    end

    // -------------------------------------------------------------------------
    // outlet skid
    // -------------------------------------------------------------------------
    logic [SW-1:0] w_out_tstrb;
    logic [UW-1:0] w_out_tuser;

    // Same reason as above: a generate, not a runtime branch.
    if (KEEP_ON_USER) begin : g_keep_out_user
        always_comb begin
            w_out_tstrb = {SW{1'b1}};
            w_out_tuser = '0;
            w_out_tuser[S-1:0] = pk_keep;
        end
    end else begin : g_keep_out_strb
        always_comb begin
            w_out_tuser = '0;
            w_out_tstrb = {SW{1'b1}};
            w_out_tstrb[S-1:0] = pk_keep;
        end
    end

    /* verilator lint_off PINCONNECTEMPTY */
    axis4_master #(
        .SKID_DEPTH(SKID_DEPTH), .AXIS_DATA_WIDTH(DATA_WIDTH),
        .AXIS_ID_WIDTH(AXIS_ID_WIDTH), .AXIS_DEST_WIDTH(AXIS_DEST_WIDTH),
        .AXIS_USER_WIDTH(AXIS_USER_WIDTH)
    ) u_out (
        .aclk(aclk), .aresetn(w_aresetn),
        .fub_axis_tdata(pk_data), .fub_axis_tstrb(w_out_tstrb),
        .fub_axis_tlast(pk_last), .fub_axis_tid(r_tid),
        .fub_axis_tdest(r_tdest), .fub_axis_tuser(w_out_tuser),
        .fub_axis_tvalid(pk_valid), .fub_axis_tready(pk_ready),
        .m_axis_tdata(m_axis_tdata), .m_axis_tstrb(m_axis_tstrb),
        .m_axis_tlast(m_axis_tlast), .m_axis_tid(m_axis_tid),
        .m_axis_tdest(m_axis_tdest), .m_axis_tuser(m_axis_tuser),
        .m_axis_tvalid(m_axis_tvalid), .m_axis_tready(m_axis_tready),
        .busy());
    /* verilator lint_on PINCONNECTEMPTY */

endmodule

