    output logic                       wrlvl_result_valid_o,
    output logic                       wrlvl_result_o,
    output logic [15:0]                wrlvl_attempts_o,
    output logic [15:0]                wrlvl_flips_o,
    output logic                       wrlvl_timeout_o,
