    ) u_sched_plane (
        .aclk               (aclk),
        .aresetn            (w_aresetn),
        .page_policy_i      (page_policy_i),
        .memtype_i          (memtype_i),
        .page_mode_i        (page_mode_i),
        .page_tr_init_i     (page_tr_init_i),
