// https://github.com/sean-galloway/RTLDesignSherpa
//
// Module: traffic_counter
// Purpose: Router tap synchronizer + 32-bit wrapping counter bank
//
// Documentation: projects/components/compute-eng-ip/hive-serv/docs/hive_mas/ch02_blocks/03_serv_monitor.md
// Subsystem: hive-serv
//
// Author: sean galloway
// Created: 2026-10-13

`timescale 1ns / 1ps

module traffic_counter #(
    parameter int IBUF_DEPTH = 8
)(
    input  logic        clk,
    input  logic        rst_n,

    // --- router tap (source domain is the tile router / delta_clk)
    input  logic [3:0]  tap_rx_stb,
    input  logic [3:0]  tap_tx_stb,
    input  logic [3:0]  tap_local_inject_stb,
    input  logic [3:0]  tap_local_consume_stb,
    input  logic [31:0] tap_occupancy,
    input  logic        tap_stall_stb,
    input  logic        tap_parity_err_stb,
    input  logic        tap_protocol_err_stb,
    input  logic        tap_overflow_stb,

    // --- counter bank outputs (serv_clk domain)
    output logic [31:0] pkt_rx_count [4],
    output logic [31:0] pkt_tx_count [4],
    output logic [31:0] pkt_local_inject,
    output logic [31:0] pkt_local_consume,
    output logic [31:0] buffer_overflow_count,
    output logic [31:0] stall_cycles,
    output logic [7:0]  buffer_occupancy [4],

    // --- synchronized error pulses (one cycle in serv_clk)
    output logic        parity_err_pulse,
    output logic        protocol_err_pulse,
    output logic        overflow_err_pulse,

    // --- control
    input  logic        clear_stats
);

    //--------------------------------------------------------------------------
    // Dual-flop synchronizers for all tap signals (2026-10-13 decision)
    //--------------------------------------------------------------------------
    logic [3:0] rx_stb_sync;
    logic [3:0] tx_stb_sync;
    logic [3:0] local_inject_stb_sync;
    logic [3:0] local_consume_stb_sync;
    logic [31:0] occupancy_sync;
    logic        stall_stb_sync;
    logic        parity_err_sync;
    logic        protocol_err_sync;
    logic        overflow_stb_sync;

    cdc_synchronizer #(.WIDTH(4),  .FLOP_COUNT(2)) u_rx_sync          (.clk, .rst_n, .async_in(tap_rx_stb),          .sync_out(rx_stb_sync));
    cdc_synchronizer #(.WIDTH(4),  .FLOP_COUNT(2)) u_tx_sync          (.clk, .rst_n, .async_in(tap_tx_stb),          .sync_out(tx_stb_sync));
    cdc_synchronizer #(.WIDTH(4),  .FLOP_COUNT(2)) u_local_inject_sync (.clk, .rst_n, .async_in(tap_local_inject_stb), .sync_out(local_inject_stb_sync));
    cdc_synchronizer #(.WIDTH(4),  .FLOP_COUNT(2)) u_local_consume_sync(.clk, .rst_n, .async_in(tap_local_consume_stb), .sync_out(local_consume_stb_sync));
    cdc_synchronizer #(.WIDTH(32), .FLOP_COUNT(2)) u_occupancy_sync   (.clk, .rst_n, .async_in(tap_occupancy),       .sync_out(occupancy_sync));
    cdc_synchronizer #(.WIDTH(1),  .FLOP_COUNT(2)) u_stall_sync       (.clk, .rst_n, .async_in(tap_stall_stb),       .sync_out(stall_stb_sync));
    cdc_synchronizer #(.WIDTH(1),  .FLOP_COUNT(2)) u_parity_sync      (.clk, .rst_n, .async_in(tap_parity_err_stb),  .sync_out(parity_err_sync));
    cdc_synchronizer #(.WIDTH(1),  .FLOP_COUNT(2)) u_protocol_sync    (.clk, .rst_n, .async_in(tap_protocol_err_stb), .sync_out(protocol_err_sync));
    cdc_synchronizer #(.WIDTH(1),  .FLOP_COUNT(2)) u_overflow_sync    (.clk, .rst_n, .async_in(tap_overflow_stb),    .sync_out(overflow_stb_sync));

    //--------------------------------------------------------------------------
    // Occupancy decode (8 bits per direction)
    //--------------------------------------------------------------------------
    genvar d;
    generate
        for (d = 0; d < 4; d++) begin : gen_occ
            assign buffer_occupancy[d] = occupancy_sync[d*8 +: 8];
        end
    endgenerate

    //--------------------------------------------------------------------------
    // Edge-detect counters for per-direction packet strobes
    //--------------------------------------------------------------------------
    logic [3:0] rx_stb_prev;
    logic [3:0] tx_stb_prev;
    logic [3:0] local_inject_stb_prev;
    logic [3:0] local_consume_stb_prev;
    logic       overflow_stb_prev;

    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            rx_stb_prev           <= '0;
            tx_stb_prev           <= '0;
            local_inject_stb_prev <= '0;
            local_consume_stb_prev<= '0;
            overflow_stb_prev     <= '0;
            for (int i = 0; i < 4; i++) begin
                pkt_rx_count[i]   <= '0;
                pkt_tx_count[i]   <= '0;
            end
            pkt_local_inject      <= '0;
            pkt_local_consume     <= '0;
            buffer_overflow_count <= '0;
            stall_cycles          <= '0;
        end else begin
            rx_stb_prev           <= rx_stb_sync;
            tx_stb_prev           <= tx_stb_sync;
            local_inject_stb_prev <= local_inject_stb_sync;
            local_consume_stb_prev<= local_consume_stb_sync;
            overflow_stb_prev     <= overflow_stb_sync;

            if (clear_stats) begin
                for (int i = 0; i < 4; i++) begin
                    pkt_rx_count[i]   <= '0;
                    pkt_tx_count[i]   <= '0;
                end
                pkt_local_inject      <= '0;
                pkt_local_consume     <= '0;
                buffer_overflow_count <= '0;
                stall_cycles          <= '0;
            end else begin
                for (int i = 0; i < 4; i++) begin
                    if (rx_stb_sync[i] && !rx_stb_prev[i])
                        pkt_rx_count[i] <= pkt_rx_count[i] + 32'd1;
                    if (tx_stb_sync[i] && !tx_stb_prev[i])
                        pkt_tx_count[i] <= pkt_tx_count[i] + 32'd1;
                end
                if (local_inject_stb_sync[0] && !local_inject_stb_prev[0])
                    pkt_local_inject <= pkt_local_inject + 32'd1;
                if (local_consume_stb_sync[0] && !local_consume_stb_prev[0])
                    pkt_local_consume <= pkt_local_consume + 32'd1;
                if (overflow_stb_sync && !overflow_stb_prev)
                    buffer_overflow_count <= buffer_overflow_count + 32'd1;
                if (stall_stb_sync)
                    stall_cycles <= stall_cycles + 32'd1;
            end
        end
    end

    //--------------------------------------------------------------------------
    // Synchronized error pulses
    //--------------------------------------------------------------------------
    logic parity_err_prev;
    logic protocol_err_prev;

    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            parity_err_prev   <= '0;
            protocol_err_prev <= '0;
        end else begin
            parity_err_prev   <= parity_err_sync;
            protocol_err_prev <= protocol_err_sync;
        end
    end

    assign parity_err_pulse   = parity_err_sync   && !parity_err_prev;
    assign protocol_err_pulse = protocol_err_sync && !protocol_err_prev;
    assign overflow_err_pulse = overflow_stb_sync && !overflow_stb_prev;

endmodule : traffic_counter

// SPDX-License-Identifier: MIT
// SPDX-FileCopyrightText: 2024-2025 sean galloway
//
// RTL Design Sherpa - Industry-Standard RTL Design and Verification
// https://github.com/sean-galloway/RTLDesignSherpa
//
// Module: uart_axil_bridge
// Purpose: UART to AXI4-Lite Master Bridge
//
// Parses UART commands and executes AXI4-Lite transactions with timing isolation
//
// Command Protocol:
//   Write: W <addr_hex> <data_hex>\n  -> Response: "OK\n"
//   Read:  R <addr_hex>\n             -> Response: "0xDEADBEEF\n"

`timescale 1ns / 1ps

`include "reset_defs.svh"

module uart_axil_bridge #(
    parameter int AXIL_ADDR_WIDTH = 32,
    parameter int AXIL_DATA_WIDTH = 32,
    parameter int CLKS_PER_BIT    = 868,  // 100MHz / 115200 baud
    parameter int SKID_DEPTH_AR   = 2,
    parameter int SKID_DEPTH_R    = 4,
    parameter int SKID_DEPTH_AW   = 2,
    parameter int SKID_DEPTH_W    = 4,
    parameter int SKID_DEPTH_B    = 2
)(
    input  logic                         aclk,
    input  logic                         aresetn,

    // UART interface
    input  logic                         i_uart_rx,
    output logic                         o_uart_tx,

    // AXI4-Lite Master interface (with timing isolation)
    output logic [AXIL_ADDR_WIDTH-1:0]   m_axil_awaddr,
    output logic [2:0]                   m_axil_awprot,
    output logic                         m_axil_awvalid,
    input  logic                         m_axil_awready,

    output logic [AXIL_DATA_WIDTH-1:0]   m_axil_wdata,
    output logic [AXIL_DATA_WIDTH/8-1:0] m_axil_wstrb,
    output logic                         m_axil_wvalid,
    input  logic                         m_axil_wready,

    input  logic [1:0]                   m_axil_bresp,
    input  logic                         m_axil_bvalid,
    output logic                         m_axil_bready,

    output logic [AXIL_ADDR_WIDTH-1:0]   m_axil_araddr,
    output logic [2:0]                   m_axil_arprot,
    output logic                         m_axil_arvalid,
    input  logic                         m_axil_arready,

    input  logic [AXIL_DATA_WIDTH-1:0]   m_axil_rdata,
    input  logic [1:0]                   m_axil_rresp,
    input  logic                         m_axil_rvalid,
    output logic                         m_axil_rready
);

    //==========================================================================
    // Boundary reset synchronization
    //==========================================================================
    // Boundary reset synchronizer (block input reset is async-assert,
    // synchronized internally; complete closure)
    //
    // The port aresetn is treated as an asynchronous-assert input of unknown
    // deassert quality: an N=3 reset_sync (rtl/cdc, formally proven) produces
    // the internal reset every block below sees.
    logic w_aresetn;
    reset_sync #(
        .N             (3),
        .KEEP_ATTRS    (1'b1),
        .IN_ACTIVE_LOW (1'b1),
        .OUT_ACTIVE_LOW(1'b1),
        .ASYNC_ASSERT  (1'b1)
    ) u_reset_sync (
        .clk        (aclk),
        .rst_n      (aresetn),
        .sync_rst_n (w_aresetn)
    );

    // UART signals
    logic [7:0] w_rx_data, w_tx_data;
    logic       w_rx_valid, w_rx_ready;
    logic       w_tx_valid, w_tx_ready;

    // Internal AXI4-Lite signals (before timing isolation)
    logic [AXIL_ADDR_WIDTH-1:0]   w_fub_awaddr;
    logic [2:0]                   w_fub_awprot;
    logic                         w_fub_awvalid;
    logic                         w_fub_awready;

    logic [AXIL_DATA_WIDTH-1:0]   w_fub_wdata;
    logic [AXIL_DATA_WIDTH/8-1:0] w_fub_wstrb;
    logic                         w_fub_wvalid;
    logic                         w_fub_wready;

    logic [1:0]                   w_fub_bresp;
    logic                         w_fub_bvalid;
    logic                         w_fub_bready;

    logic [AXIL_ADDR_WIDTH-1:0]   w_fub_araddr;
    logic [2:0]                   w_fub_arprot;
    logic                         w_fub_arvalid;
    logic                         w_fub_arready;

    logic [AXIL_DATA_WIDTH-1:0]   w_fub_rdata;
    logic [1:0]                   w_fub_rresp;
    logic                         w_fub_rvalid;
    logic                         w_fub_rready;

    // UART RX instance
    uart_rx #(
        .CLKS_PER_BIT(CLKS_PER_BIT)
    ) u_uart_rx (
        .i_clk      (aclk),
        .i_rst_n    (w_aresetn),
        .i_rx       (i_uart_rx),
        .o_rx_data  (w_rx_data),
        .o_rx_valid (w_rx_valid),
        .i_rx_ready (w_rx_ready)
    );

    // UART TX instance
    uart_tx #(
        .CLKS_PER_BIT(CLKS_PER_BIT)
    ) u_uart_tx (
        .i_clk      (aclk),
        .i_rst_n    (w_aresetn),
        .o_tx       (o_uart_tx),
        .i_tx_data  (w_tx_data),
        .i_tx_valid (w_tx_valid),
        .o_tx_ready (w_tx_ready)
    );

    // Command parser state machine
    typedef enum logic [3:0] {
        CMD_IDLE,
        CMD_READ_CMD,
        CMD_READ_ADDR,
        CMD_READ_DATA,
        CMD_EXECUTE,
        CMD_AXIL_WRITE_ADDR,
        CMD_AXIL_WRITE_DATA,
        CMD_AXIL_WRITE_RESP,
        CMD_AXIL_READ_ADDR,
        CMD_AXIL_READ_DATA,
        CMD_SEND_RESPONSE
    } cmd_state_t;

    cmd_state_t r_cmd_state, w_cmd_state_next;

    localparam logic [1:0] AXI_RESP_OKAY = 2'b00;

    // Calculate maximum hex digits needed for address and data
    localparam int ADDR_HEX_DIGITS = (AXIL_ADDR_WIDTH + 3) / 4;  // Round up to nibbles
    localparam int DATA_HEX_DIGITS = (AXIL_DATA_WIDTH + 3) / 4;  // Round up to nibbles
    // "0x" + hex digits + "\n", but never shorter than the 4-character
    // "ERR\n" error response below.
    localparam int RESP_OK_LEN  = 2 + DATA_HEX_DIGITS + 1;
    localparam int RESP_ERR_LEN = 4;                             // "ERR\n"
    localparam int MAX_RESPONSE_LEN =
        (RESP_OK_LEN > RESP_ERR_LEN) ? RESP_OK_LEN : RESP_ERR_LEN;
    localparam int RESPONSE_INDEX_WIDTH = $clog2(MAX_RESPONSE_LEN + 1);  // Width for index

    // Command buffer (parameterized for data width)
    logic [7:0]  r_cmd_type;
    // Width follows the parameter. It was hardcoded [31:0] while the
    // shift and awaddr assignment indexed [AXIL_ADDR_WIDTH-5:0] -- an
    // out-of-range select for any width above 32, so the parameter
    // advertised support the module did not have.
    logic [AXIL_ADDR_WIDTH-1:0] r_cmd_addr;
    logic [AXIL_DATA_WIDTH-1:0] r_cmd_data;  // Data width parameterized
    logic [AXIL_DATA_WIDTH-1:0] r_resp_data; // Response data parameterized
    logic [4:0]  r_nibble_count;  // Increased to handle 64-bit (16 nibbles)
    logic [7:0]  r_response_buffer [MAX_RESPONSE_LEN-1:0];  // Dynamic response size
    logic [RESPONSE_INDEX_WIDTH-1:0]  r_response_index;  // Parameterized index width
    logic [RESPONSE_INDEX_WIDTH-1:0]  r_response_length; // Parameterized length width

    // Helper function to convert hex char to value
    function automatic logic [3:0] hex_to_val(input logic [7:0] c);
        logic [7:0] temp;
        if (c >= "0" && c <= "9") begin
            temp = c - 8'd48;  // '0' = 48
            return temp[3:0];
        end else if (c >= "a" && c <= "f") begin
            temp = c - 8'd87;  // 'a' - 10 = 97 - 10 = 87
            return temp[3:0];
        end else if (c >= "A" && c <= "F") begin
            temp = c - 8'd55;  // 'A' - 10 = 65 - 10 = 55
            return temp[3:0];
        end else begin
            return 4'h0;
        end
    endfunction

    // Helper function to convert value to hex char
    function automatic logic [7:0] val_to_hex(input logic [3:0] v);
        logic [7:0] v_extended;
        v_extended = 8'(v);
        if (v < 4'd10)
            return 8'd48 + v_extended;  // '0' = 48
        else
            return 8'd55 + v_extended;  // 'A' - 10 = 65 - 10 = 55
    endfunction

    // State machine registers
    `ALWAYS_FF_RST(aclk, w_aresetn,
        if (`RST_ASSERTED(w_aresetn)) begin
            r_cmd_state <= CMD_IDLE;
            r_cmd_type <= '0;
            r_cmd_addr <= '0;
            r_cmd_data <= AXIL_DATA_WIDTH'('0);  // Explicitly sized for parameterization
            r_resp_data <= AXIL_DATA_WIDTH'('0); // Explicitly sized for parameterization
            r_nibble_count <= '0;
            r_response_index <= '0;
            r_response_length <= '0;
        end else begin
            r_cmd_state <= w_cmd_state_next;

            case (r_cmd_state)
                CMD_IDLE: begin
                    if (w_rx_valid && w_rx_ready) begin
                        r_cmd_type <= w_rx_data;
                        r_nibble_count <= '0;
                        r_cmd_addr <= '0;
                        r_cmd_data <= AXIL_DATA_WIDTH'('0);  // Explicitly sized
                    end
                end

                CMD_READ_ADDR: begin
                    if (w_rx_valid && w_rx_ready) begin
                        if (w_rx_data != " " && w_rx_data != "\n" && w_rx_data != "\r") begin
                            r_cmd_addr <= {r_cmd_addr[AXIL_ADDR_WIDTH-5:0], hex_to_val(w_rx_data)};
                            r_nibble_count <= r_nibble_count + 1'b1;
                        end
                    end
                end

                CMD_READ_DATA: begin
                    if (w_rx_valid && w_rx_ready) begin
                        if (w_rx_data != " " && w_rx_data != "\n" && w_rx_data != "\r") begin
                            r_cmd_data <= {r_cmd_data[AXIL_DATA_WIDTH-5:0], hex_to_val(w_rx_data)};
                            r_nibble_count <= r_nibble_count + 1'b1;
                        end
                    end
                end

                CMD_AXIL_READ_DATA: begin
                    if (w_fub_rvalid && w_fub_rready) begin
                        r_resp_data <= w_fub_rdata;
                        if (w_fub_rresp != AXI_RESP_OKAY) begin
                            // SLVERR/DECERR: say so. Returning "0x" plus
                            // whatever sat on rdata reports a failed read as a
                            // successful one, and the host cannot tell.
                            r_response_buffer[0] <= "E";
                            r_response_buffer[1] <= "R";
                            r_response_buffer[2] <= "R";
                            r_response_buffer[3] <= "\n";
                            r_response_index  <= '0;
                            r_response_length <= RESPONSE_INDEX_WIDTH'(RESP_ERR_LEN);
                        end else begin
                            // Prepare response: "0x<DATA_HEX_DIGITS>\n"
                            // Dynamic formatting based on AXIL_DATA_WIDTH
                            r_response_buffer[0] <= "0";
                            r_response_buffer[1] <= "x";
                            // Generate hex digits from MSB to LSB
                            for (int i = 0; i < DATA_HEX_DIGITS; i++) begin
                                r_response_buffer[2 + i] <= val_to_hex(
                                    w_fub_rdata[(AXIL_DATA_WIDTH - 1) - (i * 4) -: 4]
                                );
                            end
                            r_response_buffer[2 + DATA_HEX_DIGITS] <= "\n";
                            r_response_index <= '0;
                            r_response_length <= RESPONSE_INDEX_WIDTH'(RESP_OK_LEN);
                        end
                    end
                end

                CMD_AXIL_WRITE_RESP: begin
                    if (w_fub_bvalid && w_fub_bready) begin
                        if (w_fub_bresp != AXI_RESP_OKAY) begin
                            // SLVERR/DECERR: answering "OK" to a write that
                            // failed is the one answer a host cannot recover
                            // from, because it looks exactly like success.
                            r_response_buffer[0] <= "E";
                            r_response_buffer[1] <= "R";
                            r_response_buffer[2] <= "R";
                            r_response_buffer[3] <= "\n";
                            r_response_index  <= '0;
                            r_response_length <= RESPONSE_INDEX_WIDTH'(RESP_ERR_LEN);
                        end else begin
                            // Prepare "OK\n" response
                            r_response_buffer[0] <= "O";
                            r_response_buffer[1] <= "K";
                            r_response_buffer[2] <= "\n";
                            r_response_index <= '0;
                            r_response_length <= RESPONSE_INDEX_WIDTH'(3);  // "OK\n"
                        end
                    end
                end

                CMD_SEND_RESPONSE: begin
                    if (w_tx_valid && w_tx_ready) begin
                        r_response_index <= r_response_index + 1'b1;
                    end
                end

                default: begin
                    // Maintain values
                end
            endcase
        end
    )

    // State machine transitions
    always_comb begin
        w_cmd_state_next = r_cmd_state;

        case (r_cmd_state)
            CMD_IDLE: begin
                if (w_rx_valid && w_rx_ready) begin
                    if (w_rx_data == "W" || w_rx_data == "w")
                        w_cmd_state_next = CMD_READ_ADDR;
                    else if (w_rx_data == "R" || w_rx_data == "r")
                        w_cmd_state_next = CMD_READ_ADDR;
                end
            end

            CMD_READ_ADDR: begin
                if (w_rx_valid && w_rx_ready) begin
                    if (w_rx_data == " ") begin
                        // Only transition if we've accumulated nibbles (skip leading whitespace)
                        if (r_nibble_count > 0) begin
                            if (r_cmd_type == "W" || r_cmd_type == "w")
                                w_cmd_state_next = CMD_READ_DATA;
                            else
                                w_cmd_state_next = CMD_EXECUTE;
                        end
                        // else: stay in CMD_READ_ADDR, skip whitespace
                    end else if (w_rx_data == "\n" || w_rx_data == "\r") begin
                        w_cmd_state_next = CMD_EXECUTE;
                    end
                end
            end

            CMD_READ_DATA: begin
                if (w_rx_valid && w_rx_ready) begin
                    if (w_rx_data == " ") begin
                        // Skip spaces between address and data (already transitioned)
                    end else if (w_rx_data == "\n" || w_rx_data == "\r") begin
                        w_cmd_state_next = CMD_EXECUTE;
                    end
                end
            end

            CMD_EXECUTE: begin
                if (r_cmd_type == "W" || r_cmd_type == "w")
                    w_cmd_state_next = CMD_AXIL_WRITE_ADDR;
                else if (r_cmd_type == "R" || r_cmd_type == "r")
                    w_cmd_state_next = CMD_AXIL_READ_ADDR;
                else
                    w_cmd_state_next = CMD_IDLE;
            end

            CMD_AXIL_WRITE_ADDR: begin
                if (w_fub_awvalid && w_fub_awready)
                    w_cmd_state_next = CMD_AXIL_WRITE_DATA;
            end

            CMD_AXIL_WRITE_DATA: begin
                if (w_fub_wvalid && w_fub_wready)
                    w_cmd_state_next = CMD_AXIL_WRITE_RESP;
            end

            CMD_AXIL_WRITE_RESP: begin
                if (w_fub_bvalid && w_fub_bready)
                    w_cmd_state_next = CMD_SEND_RESPONSE;
            end

            CMD_AXIL_READ_ADDR: begin
                if (w_fub_arvalid && w_fub_arready)
                    w_cmd_state_next = CMD_AXIL_READ_DATA;
            end

            CMD_AXIL_READ_DATA: begin
                if (w_fub_rvalid && w_fub_rready)
                    w_cmd_state_next = CMD_SEND_RESPONSE;
            end

            CMD_SEND_RESPONSE: begin
                if (w_tx_valid && w_tx_ready) begin
                    if (r_response_index >= (r_response_length - 1))
                        w_cmd_state_next = CMD_IDLE;
                end
            end

            default: w_cmd_state_next = CMD_IDLE;
        endcase
    end

    // Output assignments
    assign w_rx_ready = (r_cmd_state == CMD_IDLE) ||
                        (r_cmd_state == CMD_READ_ADDR) ||
                        (r_cmd_state == CMD_READ_DATA);

    assign w_tx_valid = (r_cmd_state == CMD_SEND_RESPONSE);
    assign w_tx_data = r_response_buffer[r_response_index];

    // Internal AXI4-Lite signal assignments (to timing isolation modules)
    // Write path
    assign w_fub_awaddr  = r_cmd_addr[AXIL_ADDR_WIDTH-1:0];
    assign w_fub_awprot  = 3'b000;  // Unprivileged, secure, data access
    assign w_fub_awvalid = (r_cmd_state == CMD_AXIL_WRITE_ADDR);

    assign w_fub_wdata  = r_cmd_data[AXIL_DATA_WIDTH-1:0];
    assign w_fub_wstrb  = {(AXIL_DATA_WIDTH/8){1'b1}};  // All bytes valid
    assign w_fub_wvalid = (r_cmd_state == CMD_AXIL_WRITE_DATA);

    assign w_fub_bready = (r_cmd_state == CMD_AXIL_WRITE_RESP);

    // Read path
    assign w_fub_araddr  = r_cmd_addr[AXIL_ADDR_WIDTH-1:0];
    assign w_fub_arprot  = 3'b000;  // Unprivileged, secure, data access
    assign w_fub_arvalid = (r_cmd_state == CMD_AXIL_READ_ADDR);

    assign w_fub_rready = (r_cmd_state == CMD_AXIL_READ_DATA);

    // AXI4-Lite Write Timing Isolation
    axil4_master_wr #(
        .AXIL_ADDR_WIDTH (AXIL_ADDR_WIDTH),
        .AXIL_DATA_WIDTH (AXIL_DATA_WIDTH),
        .SKID_DEPTH_AW   (SKID_DEPTH_AW),
        .SKID_DEPTH_W    (SKID_DEPTH_W),
        .SKID_DEPTH_B    (SKID_DEPTH_B)
    ) u_axil_wr_timing (
        .aclk    (aclk),
        .aresetn (w_aresetn),

        // FUB side (from command parser)
        .fub_awaddr  (w_fub_awaddr),
        .fub_awprot  (w_fub_awprot),
        .fub_awvalid (w_fub_awvalid),
        .fub_awready (w_fub_awready),

        .fub_wdata  (w_fub_wdata),
        .fub_wstrb  (w_fub_wstrb),
        .fub_wvalid (w_fub_wvalid),
        .fub_wready (w_fub_wready),

        .fub_bresp  (w_fub_bresp),
        .fub_bvalid (w_fub_bvalid),
        .fub_bready (w_fub_bready),

        // Master side (external AXI4-Lite bus)
        .m_axil_awaddr  (m_axil_awaddr),
        .m_axil_awprot  (m_axil_awprot),
        .m_axil_awvalid (m_axil_awvalid),
        .m_axil_awready (m_axil_awready),

        .m_axil_wdata  (m_axil_wdata),
        .m_axil_wstrb  (m_axil_wstrb),
        .m_axil_wvalid (m_axil_wvalid),
        .m_axil_wready (m_axil_wready),

        .m_axil_bresp  (m_axil_bresp),
        .m_axil_bvalid (m_axil_bvalid),
        .m_axil_bready (m_axil_bready),

        .busy ()
    );

    // AXI4-Lite Read Timing Isolation
    axil4_master_rd #(
        .AXIL_ADDR_WIDTH (AXIL_ADDR_WIDTH),
        .AXIL_DATA_WIDTH (AXIL_DATA_WIDTH),
        .SKID_DEPTH_AR   (SKID_DEPTH_AR),
        .SKID_DEPTH_R    (SKID_DEPTH_R)
    ) u_axil_rd_timing (
        .aclk    (aclk),
        .aresetn (w_aresetn),

        // FUB side (from command parser)
        .fub_araddr  (w_fub_araddr),
        .fub_arprot  (w_fub_arprot),
        .fub_arvalid (w_fub_arvalid),
        .fub_arready (w_fub_arready),

        .fub_rdata  (w_fub_rdata),
        .fub_rresp  (w_fub_rresp),
        .fub_rvalid (w_fub_rvalid),
        .fub_rready (w_fub_rready),

        // Master side (external AXI4-Lite bus)
        .m_axil_araddr  (m_axil_araddr),
        .m_axil_arprot  (m_axil_arprot),
        .m_axil_arvalid (m_axil_arvalid),
        .m_axil_arready (m_axil_arready),

        .m_axil_rdata  (m_axil_rdata),
        .m_axil_rresp  (m_axil_rresp),
        .m_axil_rvalid (m_axil_rvalid),
        .m_axil_rready (m_axil_rready),

        .busy ()
    );

endmodule : uart_axil_bridge

