//
//==============================================================================
// Description:
//   wb4_slave (Wishbone bus to command/response queues)
//   -> wb4_to_axil4_core (queues to the five AXI4-Lite channels, merging the
//      two response channels back into one in-order termination stream)
//   -> axil4_master_wr + axil4_master_rd (channels to the bus).
//
//   The mirror of axil4_to_wb4. Same address and data width on both sides.
//
//------------------------------------------------------------------------------
// Parameters:
//------------------------------------------------------------------------------
//   ADDR_WIDTH, DATA_WIDTH
//   CMD_DEPTH, RSP_DEPTH, MAX_OUTSTANDING - the wb4_slave's queues and bound
//   CLASSIC          - 0 = B4 pipelined, 1 = B4 standard; match the master
//   OUTSTANDING      - commands in flight through the core (1 = serialised)
//   SKID_DEPTH_*     - the AXI4-Lite masters' channel skids
//   AXIL_PROT        - AWPROT/ARPROT driven on every command
//
//------------------------------------------------------------------------------
// Test:
//------------------------------------------------------------------------------
//   Location: projects/components/utility-ip/converters/dv/tests/test_wb4_to_axil4.py
//==============================================================================

`timescale 1ns / 1ps

module wb4_to_axil4
    import wb4_pkg::*;
#(
    parameter int ADDR_WIDTH      = 32,
    parameter int DATA_WIDTH      = 32,
    parameter int CMD_DEPTH       = 2,
    parameter int RSP_DEPTH       = 2,
    parameter int MAX_OUTSTANDING = 16,
    parameter int CLASSIC         = 0,
    parameter int OUTSTANDING     = 1,
    parameter int SKID_DEPTH_AW   = 2,
    parameter int SKID_DEPTH_W    = 2,
    parameter int SKID_DEPTH_B    = 2,
    parameter int SKID_DEPTH_AR   = 2,
    parameter int SKID_DEPTH_R    = 2,
    parameter logic [2:0] AXIL_PROT = 3'b000,
    // Short params
    parameter int AW  = ADDR_WIDTH,
    parameter int DW  = DATA_WIDTH,
    parameter int SW  = DW/8,
    parameter int CTW = WB4_CTI_WIDTH,
    parameter int BTW = WB4_BTE_WIDTH
)
(
    input  logic              aclk,
    input  logic              aresetn,

    // Wishbone B4 slave
    input  logic              s_wb_CYC,
    input  logic              s_wb_STB,
    input  logic              s_wb_WE,
    input  logic [AW-1:0]     s_wb_ADR,
    input  logic [DW-1:0]     s_wb_DAT_W,
    input  logic [SW-1:0]     s_wb_SEL,
    input  logic [CTW-1:0]    s_wb_CTI,
    input  logic [BTW-1:0]    s_wb_BTE,
    output logic              s_wb_STALL,
    output logic              s_wb_ACK,
    output logic              s_wb_ERR,
    output logic              s_wb_RTY,
    output logic [DW-1:0]     s_wb_DAT_R,

    // AXI4-Lite master
    output logic [AW-1:0]     m_axil_awaddr,
    output logic [2:0]        m_axil_awprot,
    output logic              m_axil_awvalid,
    input  logic              m_axil_awready,
    output logic [DW-1:0]     m_axil_wdata,
    output logic [SW-1:0]     m_axil_wstrb,
    output logic              m_axil_wvalid,
    input  logic              m_axil_wready,
    input  logic [1:0]        m_axil_bresp,
    input  logic              m_axil_bvalid,
    output logic              m_axil_bready,
    output logic [AW-1:0]     m_axil_araddr,
    output logic [2:0]        m_axil_arprot,
    output logic              m_axil_arvalid,
    input  logic              m_axil_arready,
    input  logic [DW-1:0]     m_axil_rdata,
    input  logic [1:0]        m_axil_rresp,
    input  logic              m_axil_rvalid,
    output logic              m_axil_rready,

    output logic              busy
);

    //==========================================================================
    // Boundary reset synchronization
    //==========================================================================
    // Boundary reset synchronizer (block input reset is async-assert,
    // synchronized internally; complete closure)
    //
    // The port aresetn is treated as an asynchronous-assert input of unknown
    // deassert quality: an N=3 reset_sync (rtl/cdc, formally proven) produces
    // the internal reset every block below sees.
    logic w_aresetn;
    reset_sync #(
        .N             (3),
        .KEEP_ATTRS    (1'b1),
        .IN_ACTIVE_LOW (1'b1),
        .OUT_ACTIVE_LOW(1'b1),
        .ASYNC_ASSERT  (1'b1)
    ) u_reset_sync (
        .clk        (aclk),
        .rst_n      (aresetn),
        .sync_rst_n (w_aresetn)
    );

    // wb4_slave FUB side
    logic          w_cmd_valid, w_cmd_ready, w_cmd_we;
    logic [AW-1:0] w_cmd_adr;
    logic [DW-1:0] w_cmd_dat, w_rsp_dat;
    logic [SW-1:0] w_cmd_sel;
    logic [CTW-1:0] w_cmd_cti;
    logic [BTW-1:0] w_cmd_bte;
    logic          w_rsp_valid, w_rsp_ready;
    logic [1:0]    w_rsp_status;

    // core <-> axil masters
    logic [AW-1:0] w_awaddr, w_araddr;
    logic [2:0]    w_awprot, w_arprot;
    logic          w_awvalid, w_awready, w_wvalid, w_wready;
    logic          w_bvalid, w_bready, w_arvalid, w_arready, w_rvalid, w_rready;
    logic [DW-1:0] w_wdata, w_rdata;
    logic [SW-1:0] w_wstrb;
    logic [1:0]    w_bresp, w_rresp;
    logic          w_busy_wr, w_busy_rd;

    wb4_slave #(
        .ADDR_WIDTH      (AW),
        .DATA_WIDTH      (DW),
        .CMD_DEPTH       (CMD_DEPTH),
        .RSP_DEPTH       (RSP_DEPTH),
        .MAX_OUTSTANDING (MAX_OUTSTANDING),
        .CLASSIC         (CLASSIC)
    ) u_wb_slave (
        .clk        (aclk),
        .aresetn    (w_aresetn),
        .s_wb_CYC   (s_wb_CYC),
        .s_wb_STB   (s_wb_STB),
        .s_wb_WE    (s_wb_WE),
        .s_wb_ADR   (s_wb_ADR),
        .s_wb_DAT_W (s_wb_DAT_W),
        .s_wb_SEL   (s_wb_SEL),
        .s_wb_CTI   (s_wb_CTI),
        .s_wb_BTE   (s_wb_BTE),
        .s_wb_STALL (s_wb_STALL),
        .s_wb_ACK   (s_wb_ACK),
        .s_wb_ERR   (s_wb_ERR),
        .s_wb_RTY   (s_wb_RTY),
        .s_wb_DAT_R (s_wb_DAT_R),
        .cmd_valid  (w_cmd_valid),
        .cmd_ready  (w_cmd_ready),
        .cmd_we     (w_cmd_we),
        .cmd_adr    (w_cmd_adr),
        .cmd_dat    (w_cmd_dat),
        .cmd_sel    (w_cmd_sel),
        .cmd_cti    (w_cmd_cti),
        .cmd_bte    (w_cmd_bte),
        .rsp_valid  (w_rsp_valid),
        .rsp_ready  (w_rsp_ready),
        .rsp_status (w_rsp_status),
        .rsp_dat    (w_rsp_dat)
    );

    // The burst hints stop here: AXI4-Lite is single-beat and has no field to
    // carry them. A burst-aware target behind AXI4-Lite is a contradiction.
    /* verilator lint_off UNUSEDSIGNAL */
    logic w_unused_hints;
    assign w_unused_hints = ^{w_cmd_cti, w_cmd_bte};
    /* verilator lint_on UNUSEDSIGNAL */

    wb4_to_axil4_core #(
        .ADDR_WIDTH  (AW),
        .DATA_WIDTH  (DW),
        .OUTSTANDING (OUTSTANDING),
        .AXIL_PROT   (AXIL_PROT)
    ) u_core (
        .aclk        (aclk),
        .aresetn     (w_aresetn),
        .cmd_valid   (w_cmd_valid),
        .cmd_ready   (w_cmd_ready),
        .cmd_we      (w_cmd_we),
        .cmd_adr     (w_cmd_adr),
        .cmd_dat     (w_cmd_dat),
        .cmd_sel     (w_cmd_sel),
        .rsp_valid   (w_rsp_valid),
        .rsp_ready   (w_rsp_ready),
        .rsp_status  (w_rsp_status),
        .rsp_dat     (w_rsp_dat),
        .fub_awaddr  (w_awaddr),
        .fub_awprot  (w_awprot),
        .fub_awvalid (w_awvalid),
        .fub_awready (w_awready),
        .fub_wdata   (w_wdata),
        .fub_wstrb   (w_wstrb),
        .fub_wvalid  (w_wvalid),
        .fub_wready  (w_wready),
        .fub_bresp   (w_bresp),
        .fub_bvalid  (w_bvalid),
        .fub_bready  (w_bready),
        .fub_araddr  (w_araddr),
        .fub_arprot  (w_arprot),
        .fub_arvalid (w_arvalid),
        .fub_arready (w_arready),
        .fub_rdata   (w_rdata),
        .fub_rresp   (w_rresp),
        .fub_rvalid  (w_rvalid),
        .fub_rready  (w_rready)
    );

    axil4_master_wr #(
        .AXIL_ADDR_WIDTH (AW),
        .AXIL_DATA_WIDTH (DW),
        .SKID_DEPTH_AW   (SKID_DEPTH_AW),
        .SKID_DEPTH_W    (SKID_DEPTH_W),
        .SKID_DEPTH_B    (SKID_DEPTH_B)
    ) u_axil_wr (
        .aclk           (aclk),
        .aresetn        (w_aresetn),
        .fub_awaddr     (w_awaddr),
        .fub_awprot     (w_awprot),
        .fub_awvalid    (w_awvalid),
        .fub_awready    (w_awready),
        .fub_wdata      (w_wdata),
        .fub_wstrb      (w_wstrb),
        .fub_wvalid     (w_wvalid),
        .fub_wready     (w_wready),
        .fub_bresp      (w_bresp),
        .fub_bvalid     (w_bvalid),
        .fub_bready     (w_bready),
        .m_axil_awaddr  (m_axil_awaddr),
        .m_axil_awprot  (m_axil_awprot),
        .m_axil_awvalid (m_axil_awvalid),
        .m_axil_awready (m_axil_awready),
        .m_axil_wdata   (m_axil_wdata),
        .m_axil_wstrb   (m_axil_wstrb),
        .m_axil_wvalid  (m_axil_wvalid),
        .m_axil_wready  (m_axil_wready),
        .m_axil_bresp   (m_axil_bresp),
        .m_axil_bvalid  (m_axil_bvalid),
        .m_axil_bready  (m_axil_bready),
        .busy           (w_busy_wr)
    );

    axil4_master_rd #(
        .AXIL_ADDR_WIDTH (AW),
        .AXIL_DATA_WIDTH (DW),
        .SKID_DEPTH_AR   (SKID_DEPTH_AR),
        .SKID_DEPTH_R    (SKID_DEPTH_R)
    ) u_axil_rd (
        .aclk           (aclk),
        .aresetn        (w_aresetn),
        .fub_araddr     (w_araddr),
        .fub_arprot     (w_arprot),
        .fub_arvalid    (w_arvalid),
        .fub_arready    (w_arready),
        .fub_rdata      (w_rdata),
        .fub_rresp      (w_rresp),
        .fub_rvalid     (w_rvalid),
        .fub_rready     (w_rready),
        .m_axil_araddr  (m_axil_araddr),
        .m_axil_arprot  (m_axil_arprot),
        .m_axil_arvalid (m_axil_arvalid),
        .m_axil_arready (m_axil_arready),
        .m_axil_rdata   (m_axil_rdata),
        .m_axil_rresp   (m_axil_rresp),
        .m_axil_rvalid  (m_axil_rvalid),
        .m_axil_rready  (m_axil_rready),
        .busy           (w_busy_rd)
    );

    assign busy = w_busy_wr || w_busy_rd || s_wb_CYC;

endmodule : wb4_to_axil4

`ifndef __DOUBLE_FLOP_SYNCHRONZER_V__
`define __DOUBLE_FLOP_SYNCHRONZER_V__

/**
 * Use this module only for clock domain crossing or for creating a synchronous
 * input from an asynchronous input signal (into a chip). For regular double delays
 * via a register, `double_delay_register.v` should be used.
 */
module double_flop_synchronizer #(
    parameter integer AT_POSEDGE_RST = 1
) (
    input clk,
    input rst,

    input enable,

    input in,
    output reg out
);

    // Prefixed and suffixed with __ to make sure the structural simulation in QuestaSim
    // can handle the clock-domain crossing.
    reg __intermediate__;

    // Unfortunately, the approach below is the only way to create synthesizable
    // Verilog code. It is not possible to only generate the always @ (...) part.
    generate
        if (AT_POSEDGE_RST == 1) begin : gen_if_at_posedge_rst
            always @(posedge clk, posedge rst) begin
                if (rst) begin
                    __intermediate__ <= 1'b0;
                    out <= 1'b0;
                end else if (enable) begin
                    __intermediate__ <= in;
                    out <= __intermediate__;
                end
            end
        end else begin : gen_if_regular_rst
            always @(posedge clk) begin
                if (rst) begin
                    __intermediate__ <= 1'b0;
                    out <= 1'b0;
                end else if (enable) begin
                    __intermediate__ <= in;
                    out <= __intermediate__;
                end
            end
        end
    endgenerate

endmodule

`endif

module high_speed_in_bus (
    input clk,
    input rst,

    input  data_required,
    output data_available, // If data_available is high and rst is low, then you can read the data from the in_data bus.

    input request,
    output reg acknowledge
);
    wire request_sync;

    double_flop_synchronizer double_flop_synchronizer_request (
        .clk(clk),
        .rst(rst),
        .enable(1'b1),
        .in(request),
        .out(request_sync)
    );

    assign data_available = ~acknowledge & request_sync & data_required;

    // Acknowledge logic. We assume that when acknowledge is high, the data is read from the in_data bus by another component
    // in the same clock cycle. Therefore, we can set acknowledge to low in the next clock cycle.
    always @(posedge clk, posedge rst) begin
        if (rst) acknowledge <= 1'b0;
        else if (data_available) acknowledge <= 1'b1;
        else if (acknowledge && !request_sync) acknowledge <= 1'b0;
    end

endmodule

module high_speed_out_bus #(
    parameter integer HIGH_SPEED_OUT_PINS = 8,
    parameter integer SENT_COUNTER_BIT_WIDTH = 4
) (
    input clk,
    input rst,

    input in_idle,
    input sending,
    input will_stop_sending, // next_state != `SENDING

    input data_ready_for_sending,

    input [SENT_COUNTER_BIT_WIDTH-1:0] num_sends,

    input [HIGH_SPEED_OUT_PINS-1:0] in,

    output reg request,
    input acknowledge,

    output reg [HIGH_SPEED_OUT_PINS-1:0] out,
    output reg [SENT_COUNTER_BIT_WIDTH-1:0] sent_counter,

    output done_sending
);
    wire acknowledge_sync;

    double_flop_synchronizer double_flop_synchronizer_acknowledge (
        .clk(clk),
        .rst(rst),
        .enable(1'b1),
        .in(acknowledge),
        .out(acknowledge_sync)
    );

    assign done_sending = acknowledge_sync & !request & (sent_counter == num_sends);

    always @(posedge clk) begin
        // TODO: is a reset every idle cycle really necessary?
        if (in_idle) begin
            request <= 1'b0;
            out <= 0;
            sent_counter <= 0;
        end else if (sending && will_stop_sending) begin
            request <= 1'b0;
            sent_counter <= 0;
        end else if (sending && (sent_counter <= num_sends)) begin
            if (!acknowledge_sync && !request) begin
                if (data_ready_for_sending) begin
                    request <= 1'b1;
                    out <= in;
                end
            end else if (acknowledge_sync && request) begin
                request <= 1'b0;
                sent_counter <= sent_counter + 1;
            end
        end
    end
endmodule

/**
 * We do not use an enable signal for the SPI client, as that enable signal would be clocked on the
 * internal clock domain, causing issues with the logic that is clocked on the external SPI clock.
 * Instead what we do is, send out a in_idle signal via a separate wire. When this signal is high,
 * the SPI server knows that the SPI client will respond. When this signal is low, the SPI server
 * should not drive the external clock nor the MOSI line.
 */
module spi_client #(
    parameter integer MESSAGE_BIT_WIDTH = 32,
    parameter integer CODE_BIT_WIDTH = 4,
    parameter integer START_ADDRESS_BIT_WIDTH = 16,
    localparam integer NumTransactionsBitWidth = MESSAGE_BIT_WIDTH - CODE_BIT_WIDTH - START_ADDRESS_BIT_WIDTH - 1
) (
    input rst_async,

    input  SCK,
    output MISO,
    input  MOSI,

    input clk,
    input rst,

    input enable_configuration,

    output [CODE_BIT_WIDTH-1:0] code,
    output reg [START_ADDRESS_BIT_WIDTH-1:0] current_address,

    input [MESSAGE_BIT_WIDTH-1:0] MISO_data,
    output reg [MESSAGE_BIT_WIDTH-1:0] MOSI_data,

    output config_data_ready,
    output [START_ADDRESS_BIT_WIDTH-1:0] current_config_address,
    output [MESSAGE_BIT_WIDTH-1:0] config_data,

    output write_new,
    output read_sync
);

    // Local parameters ---------------------------------------------------------------------------

    localparam integer WithinMessageCounterBitWidth = $clog2(MESSAGE_BIT_WIDTH);
    localparam integer SpiCounterBitWidth = NumTransactionsBitWidth + WithinMessageCounterBitWidth;

    // Check parameters ---------------------------------------------------------------------------

    if (NumTransactionsBitWidth < 0) begin
        $fatal(1, "ERROR: MESSAGE_BIT_WIDTH must be at least CODE_BIT_WIDTH + START_ADDRESS_BIT_WIDTH + 1");
    end else if (2 ** $clog2(MESSAGE_BIT_WIDTH) != MESSAGE_BIT_WIDTH) begin
        $fatal(1, "ERROR: MESSAGE_BIT_WIDTH must be a power of two");
    end else if (NumTransactionsBitWidth > START_ADDRESS_BIT_WIDTH) begin
        $fatal(1, "ERROR: NumTransactionsBitWidth must be less than or equal to START_ADDRESS_BIT_WIDTH");
    end

    // Registers ----------------------------------------------------------------------------------

    reg [SpiCounterBitWidth-1:0] spi_counter;  // TODO: why not START_ADDRESS_BIT_WIDTH-1?
    reg [MESSAGE_BIT_WIDTH-1:0] spi_shift_reg_out, spi_shift_reg_in;
    reg [MESSAGE_BIT_WIDTH-1:0] instruction_message;  // Format of the message: read(1)/write(0) | code | start_address | num_transactionss

    reg MOSI_data_ready;
    reg load_MISO_data;

    // Wires for combinational logic --------------------------------------------------------------

    wire [WithinMessageCounterBitWidth-1:0] within_message_counter;
    wire [NumTransactionsBitWidth-1:0] transaction_counter;

    wire message_complete;
    wire received_instruction_message;
    wire [NumTransactionsBitWidth-1:0] num_transactions, num_transactions_from_message;
    wire at_least_one_data_message;  // At least one complete message with data has been received
    wire [MESSAGE_BIT_WIDTH-1:0] new_shift_reg_out;
    wire within_message_counter_zero;

    wire [START_ADDRESS_BIT_WIDTH-1:0] start_address;
    wire read;
    wire write;

    // Combinational logic ------------------------------------------------------------------------

    assign {transaction_counter, within_message_counter} = spi_counter;

    assign {read, code, start_address, num_transactions_from_message} = instruction_message;
    assign write = ~read;

    assign message_complete = &within_message_counter;  // If the last WithinMessageCounterBitWidth bits are all 1, then the message is completely written
    assign received_instruction_message = spi_counter == MESSAGE_BIT_WIDTH - 1;
    assign num_transactions = received_instruction_message ? spi_shift_reg_in[NumTransactionsBitWidth-1:0] : num_transactions_from_message;
    assign at_least_one_data_message = |transaction_counter;
    assign new_shift_reg_out = {spi_shift_reg_out[MESSAGE_BIT_WIDTH-2:0], 1'b0};
    assign within_message_counter_zero = ~|within_message_counter;

    // Internal modules ---------------------------------------------------------------------------

    spi_clock_barrier_crossing spi_clock_barrier_crossing_inst (
        .clk(clk),
        .rst(rst),

        .enable_configuration(enable_configuration),
        .MOSI_data_ready(MOSI_data_ready),
        .load_MISO_data(load_MISO_data),

        .write_new(write_new),
        .read_sync(read_sync)
    );

    // Sequential logic ---------------------------------------------------------------------------

    // SPI counter
    always @(negedge SCK, posedge rst_async) begin
        if (rst_async) begin
            spi_counter <= 0;
            // If 32 SPI clockcycles have passed and the total number of words has been written
        end else if (message_complete && (transaction_counter >= num_transactions)) begin
            spi_counter <= 0;
        end else begin
            spi_counter <= spi_counter + 1;
        end
    end

    // Write message to local register if full message ready
    always @(negedge SCK, posedge rst_async) begin
        if (rst_async) begin
            instruction_message <= 0;
        end else if (received_instruction_message) begin
            instruction_message <= spi_shift_reg_in;
        end
    end

    always @(posedge SCK) begin
        spi_shift_reg_in <= {spi_shift_reg_in[MESSAGE_BIT_WIDTH-2:0], MOSI};
    end

    always @(negedge SCK, posedge rst_async) begin
        if (rst_async) begin
            spi_shift_reg_out <= 0;

            load_MISO_data <= 0;
            MOSI_data_ready <= 0;
            // If the main has sent one complete data message, write the data to the output register
        end else if (write && message_complete && at_least_one_data_message) begin
            spi_shift_reg_out <= 0;
            current_address <= start_address + transaction_counter - 1;
            MOSI_data <= spi_shift_reg_in;

            MOSI_data_ready <= 1;
            // If we have just received a new read instruction
        end else if (spi_shift_reg_in[MESSAGE_BIT_WIDTH-1] && received_instruction_message) begin
            spi_shift_reg_out <= new_shift_reg_out;
            current_address <= spi_shift_reg_in[START_ADDRESS_BIT_WIDTH+NumTransactionsBitWidth-1:NumTransactionsBitWidth];

            load_MISO_data <= 1;
            // If the main just received a complete data message and we stil have more transactions to do
        end else if (read && message_complete && at_least_one_data_message && (transaction_counter < num_transactions)) begin
            current_address <= start_address + transaction_counter;

            load_MISO_data <= 1;
            // If we are in the first clockcycle after receiving the complete instruction message and we are reading from client to main
        end else if (read && within_message_counter_zero && at_least_one_data_message) begin
            spi_shift_reg_out <= MISO_data << 1;

            load_MISO_data <= 0;
            MOSI_data_ready <= 0;
        end else if (within_message_counter_zero) begin
            MOSI_data_ready <= 0;
        end else begin
            spi_shift_reg_out <= new_shift_reg_out;
        end
    end

    assign MISO = (read && within_message_counter_zero && at_least_one_data_message) ? MISO_data[MESSAGE_BIT_WIDTH-1] : spi_shift_reg_out[MESSAGE_BIT_WIDTH-1];

    // We continuously assign these signals for the config memory, as we want the config module to write data to its
    // internal registers on the posedge of the clock. This because, at the point MOSI_data_ready is high, 
    // MESSAGE_BIT_WIDTH clockcycles have passed and so there will never be a positive or negative edge anymore to
    // trigger the config memory to write the data into its internal registers.
    assign config_data_ready = write && (code == 0) && message_complete && at_least_one_data_message;
    assign current_config_address = start_address + transaction_counter - 1;
    assign config_data = {spi_shift_reg_in[MESSAGE_BIT_WIDTH-2:0], MOSI};

endmodule

module spi_clock_barrier_crossing (
    input clk,
    input rst,

    input enable_configuration,

    input MOSI_data_ready,
    input load_MISO_data,

    output write_new,
    output read_sync
);

    // Read barrier -------------------------------------------------------------------------------

    double_flop_synchronizer double_flop_synchronizer_read (
        .clk(clk),
        .rst(rst),
        .enable(enable_configuration),
        .in(load_MISO_data),
        .out(read_sync)
    );

    // Write barrier ------------------------------------------------------------------------------

    // Below text considers the wires inside of the
    // _sync_intermediate is the first register of the double sampling barrier,
    // _sync is the second (which you can use in the clk clock domain without
    // risking metastability). However, it stays high for more than a cycle in
    // the clk clock domain. I therefore add a third register (_delete) and
    // compare when _sync goes high and _delete is not yet high. _new is thus
    // high only for one clock cycle per SPI transaction, which I use to
    // trigger a write to the SRAM.

    triple_flop_toggle_synchronizer triple_flop_toggle_synchronizer_write (
        .clk(clk),
        .rst(rst),
        .enable(enable_configuration),
        .in(MOSI_data_ready),
        .out(write_new)
    );

endmodule

`ifndef __TRIPLE_FLOP_TOGGLE_SYNCHRONIZER_V__
`define __TRIPLE_FLOP_TOGGLE_SYNCHRONIZER_V__

module triple_flop_toggle_synchronizer #(
    parameter integer AT_POSEDGE_RST = 1
) (
    input clk,
    input rst,

    input enable,

    input  in,
    output out
);

    wire in_sync;

    double_flop_synchronizer #(
        .AT_POSEDGE_RST(AT_POSEDGE_RST)
    ) double_flop_synchronizer_inst (
        .clk(clk),
        .rst(rst),
        .enable(enable),
        .in(in),
        .out(in_sync)
    );

    reg in_delete;

    // Unfortunately, the approach below is the only way to create synthesizable
    // Verilog code. It is not possible to only generate the always @ (...) part.
    generate
        if (AT_POSEDGE_RST == 1) begin : gen_if_at_posedge_rst
            always @(posedge clk, posedge rst) begin
                if (rst) begin
                    in_delete <= 0;
                end else if (enable) begin
                    in_delete <= in_sync;
                end
            end
        end else begin : gen_if_regular_rst
            always @(posedge clk) begin
                if (rst) begin
                    in_delete <= 0;
                end else if (enable) begin
                    in_delete <= in_sync;
                end
            end
        end
    endgenerate

    assign out = in_sync & ~in_delete;

endmodule

`endif

// cdc_bit.sv — N-Stage Single-Bit Synchronizer
// Fundamental CDC building block: shift register of SYNC_STAGES flip-flops
// with ASYNC_REG attribute for proper FPGA placement.

`include "cdc_config.svh"

module cdc_bit #(
    parameter int   SYNC_STAGES = 2,
    parameter logic RESET_VALUE = 1'b0
) (
    input  logic i_clk,
    input  logic i_rst_n,
    input  logic i_async_in,
    output logic o_sync_out
);

    `ifndef CDC_ASYNC_RESET
    (* ASYNC_REG = "TRUE" *)
    `endif
    logic [SYNC_STAGES-1:0] sync_chain;

    `ifndef CDC_ASYNC_RESET
    initial begin
        sync_chain = {SYNC_STAGES{RESET_VALUE}};
    end
    `endif

    `ifdef CDC_ASYNC_RESET
    always_ff @(posedge i_clk or negedge i_rst_n) begin
    `else
    always_ff @(posedge i_clk) begin
    `endif
        if (!i_rst_n)
            sync_chain <= {SYNC_STAGES{RESET_VALUE}};
        else
            sync_chain <= {sync_chain[SYNC_STAGES-2:0], i_async_in};
    end

    assign o_sync_out = sync_chain[SYNC_STAGES-1];

endmodule

//-----------------------------------------------------------------------------
// Module : cdc_counter
// Purpose: Self-contained CDC-safe binary counter. Owns the binary counter in
//          the source domain, registers the Gray code on the same clock edge,
//          then synchronizes to the destination domain via cdc_gray_sync.
//          Reusable primitive for credit counters, sequence numbers, etc.
// Author : <author>
// Date   : <date>
//-----------------------------------------------------------------------------
`default_nettype none
`include "cdc_config.svh"

module cdc_counter #(
    parameter int unsigned WIDTH       = 4,
    parameter int unsigned SYNC_STAGES = 2
) (
    // Source clock domain
    input  logic                i_src_clk,
    input  logic                i_src_rst_n,
    input  logic                i_count_up,
    input  logic                i_count_down,
    output logic [WIDTH-1:0]    o_src_count,   // binary count in source domain

    // Destination clock domain
    input  logic                i_dst_clk,
    input  logic                i_dst_rst_n,
    output logic [WIDTH-1:0]    o_dst_gray,    // synchronized Gray in dst domain
    output logic [WIDTH-1:0]    o_dst_count    // synchronized binary in dst domain
);

    // -------------------------------------------------------------------------
    // Source domain: binary counter and Gray registration
    // -------------------------------------------------------------------------
    logic [WIDTH-1:0] count_r;
    logic [WIDTH-1:0] count_nxt;
    logic [WIDTH-1:0] gray_r;

    always_comb begin
        if      (i_count_up   && !i_count_down) count_nxt = count_r + 1'b1;
        else if (i_count_down && !i_count_up)   count_nxt = count_r - 1'b1;
        else                                    count_nxt = count_r;
    end

    // Register binary and its Gray code in the same clock cycle — no extra
    // latency, and gray_r is always a stable FF output for the synchronizer.
    `ifdef CDC_ASYNC_RESET
    always_ff @(posedge i_src_clk or negedge i_src_rst_n) begin
    `else
    always_ff @(posedge i_src_clk) begin
    `endif
        if (!i_src_rst_n) begin
            count_r <= '0;
            gray_r  <= '0;
        end else begin
            count_r <= count_nxt;
            gray_r  <= count_nxt ^ (count_nxt >> 1);
        end
    end

    assign o_src_count = count_r;

    // -------------------------------------------------------------------------
    // Synchronize registered Gray to destination domain
    // -------------------------------------------------------------------------
    cdc_gray_sync #(
        .WIDTH       (WIDTH),
        .SYNC_STAGES (SYNC_STAGES)
    ) u_gray_sync (
        .i_clk   (i_dst_clk),
        .i_rst_n (i_dst_rst_n),
        .i_gray  (gray_r),
        .o_gray  (o_dst_gray)
    );

    // Gray-to-binary for callers that need a binary value in the dst domain
    cdc_gray_conv #(.WIDTH(WIDTH)) u_gray2bin (
        .i_binary ('0),
        .o_gray   (),
        .i_gray   (o_dst_gray),
        .o_binary (o_dst_count)
    );

endmodule

`default_nettype wire

//-----------------------------------------------------------------------------
// Module : cdc_fifo
// Purpose: Async FIFO with Gray-code pointer synchronization.
//          Binary pointer and its Gray code are registered together in the
//          source domain on the same clock edge, so the synchronizer input is
//          always a stable FF output — no combinational glitches at CDC boundary.
//
// Reference: Clifford E. Cummings, "Simulation and Synthesis Techniques for
//            Asynchronous FIFO Design", SNUG 2002.
//            Available at: http://www.sunburst-design.com/papers/CummingsSNUG2002SJ_FIFO1.pdf
//
//            Key techniques adopted from this work:
//              - Gray-code pointers for metastability-safe CDC
//              - Extra pointer MSB (PTR_WIDTH = addr_bits + 1) for
//                unambiguous full/empty detection
//              - Two-MSB-different rule for full flag generation
//              - Registering binary and Gray together in the source domain
// Author : <author>
// Date   : <date>
//-----------------------------------------------------------------------------
`default_nettype none
`include "cdc_config.svh"

module cdc_fifo #(
    parameter int WIDTH       = 8,
    parameter int DEPTH       = 4,
    parameter int SYNC_STAGES = 2,
    // Derived
    parameter int ADDR_WIDTH  = $clog2(DEPTH)
) (
    // Write domain
    input  logic                i_wr_clk,
    input  logic                i_wr_rst_n,
    input  logic                i_wr_en,
    input  logic [WIDTH-1:0]    i_wr_data,
    output logic                o_full,

    // Read domain
    input  logic                i_rd_clk,
    input  logic                i_rd_rst_n,
    input  logic                i_rd_en,
    output logic [WIDTH-1:0]    o_rd_data,
    output logic                o_empty
);

    localparam int PTR_WIDTH = ADDR_WIDTH + 1;

    // -------------------------------------------------------------------------
    // All signal declarations up front — iverilog requires declaration before use
    // -------------------------------------------------------------------------
    logic [WIDTH-1:0]    mem [0:DEPTH-1];

    // Write domain
    logic [PTR_WIDTH-1:0] wr_ptr_r;
    logic [PTR_WIDTH-1:0] wr_ptr_nxt;
    logic [PTR_WIDTH-1:0] wr_ptr_gray_r;    // registered Gray of wr_ptr (wr_clk)
    logic [PTR_WIDTH-1:0] rd_ptr_gray_sync; // synchronized rd Gray (in wr_clk domain)

    // Read domain
    logic [PTR_WIDTH-1:0] rd_ptr_r;
    logic [PTR_WIDTH-1:0] rd_ptr_nxt;
    logic [PTR_WIDTH-1:0] rd_ptr_gray_r;    // registered Gray of rd_ptr (rd_clk)
    logic [PTR_WIDTH-1:0] wr_ptr_gray_sync; // synchronized wr Gray (in rd_clk domain)

    `ifndef CDC_ASYNC_RESET
    initial begin
        wr_ptr_r      = '0;
        wr_ptr_gray_r = '0;
        rd_ptr_r      = '0;
        rd_ptr_gray_r = '0;
    end
    `endif

    // -------------------------------------------------------------------------
    // Write domain — pointer and Gray registration
    // -------------------------------------------------------------------------
    assign wr_ptr_nxt = (i_wr_en && !o_full) ? wr_ptr_r + 1'b1 : wr_ptr_r;

    // Binary and Gray advance together — Gray is always in sync with binary,
    // and wr_ptr_gray_r is a stable FF output ready for the CDC synchronizer.
    `ifdef CDC_ASYNC_RESET
    always_ff @(posedge i_wr_clk or negedge i_wr_rst_n) begin
    `else
    always_ff @(posedge i_wr_clk) begin
    `endif
        if (!i_wr_rst_n) begin
            wr_ptr_r      <= '0;
            wr_ptr_gray_r <= '0;
        end else begin
            wr_ptr_r      <= wr_ptr_nxt;
            wr_ptr_gray_r <= wr_ptr_nxt ^ (wr_ptr_nxt >> 1);
        end
    end

    always_ff @(posedge i_wr_clk) begin
        if (i_wr_en && !o_full)
            mem[wr_ptr_r[ADDR_WIDTH-1:0]] <= i_wr_data;
    end

    // Synchronize rd_ptr_gray_r (rd_clk domain) into wr_clk domain
    cdc_gray_sync #(
        .WIDTH       (PTR_WIDTH),
        .SYNC_STAGES (SYNC_STAGES)
    ) u_rd_ptr_sync (
        .i_clk   (i_wr_clk),
        .i_rst_n (i_wr_rst_n),
        .i_gray  (rd_ptr_gray_r),
        .o_gray  (rd_ptr_gray_sync)
    );

    // Full: top two MSBs of local and synced Gray differ; remaining bits match.
    // Requires PTR_WIDTH >= 3 (DEPTH >= 4).
    assign o_full = (wr_ptr_gray_r[PTR_WIDTH-1]   != rd_ptr_gray_sync[PTR_WIDTH-1]) &&
                   (wr_ptr_gray_r[PTR_WIDTH-2]   != rd_ptr_gray_sync[PTR_WIDTH-2]) &&
                   (wr_ptr_gray_r[PTR_WIDTH-3:0] == rd_ptr_gray_sync[PTR_WIDTH-3:0]);

    // -------------------------------------------------------------------------
    // Read domain — pointer and Gray registration
    // -------------------------------------------------------------------------
    assign rd_ptr_nxt = (i_rd_en && !o_empty) ? rd_ptr_r + 1'b1 : rd_ptr_r;

    `ifdef CDC_ASYNC_RESET
    always_ff @(posedge i_rd_clk or negedge i_rd_rst_n) begin
    `else
    always_ff @(posedge i_rd_clk) begin
    `endif
        if (!i_rd_rst_n) begin
            rd_ptr_r      <= '0;
            rd_ptr_gray_r <= '0;
        end else begin
            rd_ptr_r      <= rd_ptr_nxt;
            rd_ptr_gray_r <= rd_ptr_nxt ^ (rd_ptr_nxt >> 1);
        end
    end

    // Combinational read — data available the cycle rd_ptr_r is valid
    assign o_rd_data = mem[rd_ptr_r[ADDR_WIDTH-1:0]];

    // Synchronize wr_ptr_gray_r (wr_clk domain) into rd_clk domain
    cdc_gray_sync #(
        .WIDTH       (PTR_WIDTH),
        .SYNC_STAGES (SYNC_STAGES)
    ) u_wr_ptr_sync (
        .i_clk   (i_rd_clk),
        .i_rst_n (i_rd_rst_n),
        .i_gray  (wr_ptr_gray_r),
        .o_gray  (wr_ptr_gray_sync)
    );

    // Empty: local rd Gray equals synchronized wr Gray
    assign o_empty = (rd_ptr_gray_r == wr_ptr_gray_sync);

endmodule

`default_nettype wire

//-----------------------------------------------------------------------------
// Module : cdc_gray_sync
// Purpose: Bit-parallel synchronizer for a pre-registered Gray-code bus.
//          Instantiates one cdc_bit per bit, all clocked by the destination
//          clock. Caller must ensure i_gray is a registered flip-flop output
//          from the source clock domain — this module does not register it.
// Author : <author>
// Date   : <date>
//-----------------------------------------------------------------------------
`default_nettype none
`include "cdc_config.svh"

module cdc_gray_sync #(
    parameter int unsigned WIDTH       = 4,
    parameter int unsigned SYNC_STAGES = 2
) (
    // Destination clock domain
    input  logic                i_clk,
    input  logic                i_rst_n,

    // Data — i_gray must be a registered output from the source domain
    input  logic [WIDTH-1:0]    i_gray,
    output logic [WIDTH-1:0]    o_gray
);

    for (genvar i = 0; i < WIDTH; i++) begin : gen_sync_bits
        cdc_bit #(
            .SYNC_STAGES (SYNC_STAGES),
            .RESET_VALUE (1'b0)
        ) u_sync (
            .i_clk      (i_clk),
            .i_rst_n    (i_rst_n),
            .i_async_in (i_gray[i]),
            .o_sync_out (o_gray[i])
        );
    end

endmodule

`default_nettype wire

// cdc_handshake.sv — Handshake-Based Bus Synchronizer
// Four-phase toggle handshake for safe multi-bit data transfer across
// clock domains. Data is held stable in a holding register while
// req/ack toggles cross domains via cdc_bit.

`include "cdc_config.svh"

module cdc_handshake #(
    parameter int WIDTH       = 8,
    parameter int SYNC_STAGES = 2
) (
    // Source domain
    input  logic               i_src_clk,
    input  logic               i_src_rst_n,
    input  logic [WIDTH-1:0]   i_src_data,
    input  logic               i_src_valid,
    output logic               o_src_ready,

    // Destination domain
    input  logic               i_dst_clk,
    input  logic               i_dst_rst_n,
    output logic [WIDTH-1:0]   o_dst_data,
    output logic               o_dst_valid
);

    // All signal declarations up front (iverilog requires declaration before use)
    // Source domain signals
    logic               req_toggle;
    logic               ack_sync;
    logic [WIDTH-1:0]   data_hold;
    logic               busy;

    // Destination domain signals
    logic               req_sync;
    logic               ack_toggle;
    logic               req_sync_prev;

    `ifndef CDC_ASYNC_RESET
    initial begin
        req_toggle    = 1'b0;
        data_hold     = '0;
        busy          = 1'b0;
        ack_toggle    = 1'b0;
        req_sync_prev = 1'b0;
        o_dst_data    = '0;
        o_dst_valid   = 1'b0;
    end
    `endif

    // --- Source domain ---

    // Synchronize ack back to source domain
    cdc_bit #(
        .SYNC_STAGES (SYNC_STAGES),
        .RESET_VALUE (1'b0)
    ) u_sync_ack (
        .i_clk      (i_src_clk),
        .i_rst_n    (i_src_rst_n),
        .i_async_in (ack_toggle),
        .o_sync_out (ack_sync)
    );

    // Source logic: capture data and toggle req on accepted transfer
    `ifdef CDC_ASYNC_RESET
    always_ff @(posedge i_src_clk or negedge i_src_rst_n) begin
    `else
    always_ff @(posedge i_src_clk) begin
    `endif
        if (!i_src_rst_n) begin
            req_toggle <= 1'b0;
            data_hold  <= '0;
            busy       <= 1'b0;
        end else begin
            if (i_src_valid && o_src_ready) begin
                data_hold  <= i_src_data;
                req_toggle <= ~req_toggle;
                busy       <= 1'b1;
            end else if (busy && (ack_sync == req_toggle)) begin
                busy <= 1'b0;
            end
        end
    end

    // o_src_ready is combinational: high whenever not busy
    assign o_src_ready = ~busy;


    // --- Destination domain ---

    // Synchronize req to destination domain
    cdc_bit #(
        .SYNC_STAGES (SYNC_STAGES),
        .RESET_VALUE (1'b0)
    ) u_sync_req (
        .i_clk      (i_dst_clk),
        .i_rst_n    (i_dst_rst_n),
        .i_async_in (req_toggle),
        .o_sync_out (req_sync)
    );

    // Destination logic: detect req change, capture data, ack
    `ifdef CDC_ASYNC_RESET
    always_ff @(posedge i_dst_clk or negedge i_dst_rst_n) begin
    `else
    always_ff @(posedge i_dst_clk) begin
    `endif
        if (!i_dst_rst_n) begin
            ack_toggle    <= 1'b0;
            req_sync_prev <= 1'b0;
            o_dst_data    <= '0;
            o_dst_valid   <= 1'b0;
        end else begin
            o_dst_valid   <= 1'b0;
            req_sync_prev <= req_sync;

            if (req_sync != req_sync_prev) begin
                o_dst_data  <= data_hold;
                o_dst_valid <= 1'b1;
                ack_toggle  <= req_sync;
            end
        end
    end

endmodule

// cdc_pulse.sv — Pulse Synchronizer
// Two modes selectable via MODE parameter:
//   MODE=0 (TOGGLE): Toggle-based — i_src_pulse toggles a FF, level crosses via
//                     cdc_bit, edge detect in dst produces single-cycle pulse.
//                     Lightweight, but back-to-back pulses must be spaced apart.
//   MODE=1 (COUNTER): Counter-based — delegates to cdc_counter which owns the
//                      pulse count in the src domain and synchronizes it to dst.
//                      dst generates pulses to match. Guarantees N-in = N-out.

`include "cdc_config.svh"

module cdc_pulse_toggle #(
    parameter int SYNC_STAGES = 2
) (
    input  logic i_src_clk,
    input  logic i_src_rst_n,
    input  logic i_src_pulse,
    input  logic i_dst_clk,
    input  logic i_dst_rst_n,
    output logic o_dst_pulse
);

    logic toggle_src;
    logic toggle_dst;
    logic toggle_dst_prev;

    `ifndef CDC_ASYNC_RESET
    initial begin
        toggle_src      = 1'b0;
        toggle_dst_prev = 1'b0;
    end
    `endif

    `ifdef CDC_ASYNC_RESET
    always_ff @(posedge i_src_clk or negedge i_src_rst_n) begin
    `else
    always_ff @(posedge i_src_clk) begin
    `endif
        if (!i_src_rst_n)
            toggle_src <= 1'b0;
        else if (i_src_pulse)
            toggle_src <= ~toggle_src;
    end

    cdc_bit #(
        .SYNC_STAGES (SYNC_STAGES),
        .RESET_VALUE (1'b0)
    ) u_sync_toggle (
        .i_clk      (i_dst_clk),
        .i_rst_n    (i_dst_rst_n),
        .i_async_in (toggle_src),
        .o_sync_out (toggle_dst)
    );

    `ifdef CDC_ASYNC_RESET
    always_ff @(posedge i_dst_clk or negedge i_dst_rst_n) begin
    `else
    always_ff @(posedge i_dst_clk) begin
    `endif
        if (!i_dst_rst_n)
            toggle_dst_prev <= 1'b0;
        else
            toggle_dst_prev <= toggle_dst;
    end

    assign o_dst_pulse = toggle_dst ^ toggle_dst_prev;

endmodule


module cdc_pulse_counter #(
    parameter int SYNC_STAGES = 2,
    parameter int CTR_WIDTH   = 4
) (
    input  logic i_src_clk,
    input  logic i_src_rst_n,
    input  logic i_src_pulse,
    input  logic i_dst_clk,
    input  logic i_dst_rst_n,
    output logic o_dst_pulse
);

    logic [CTR_WIDTH-1:0] dst_count_sync;
    logic [CTR_WIDTH-1:0] dst_count_local;
    logic                 dst_pulse_r;

    `ifndef CDC_ASYNC_RESET
    initial begin
        dst_count_local = '0;
        dst_pulse_r     = 1'b0;
    end
    `endif

    // cdc_counter owns the src-domain pulse count and synchronizes it to dst.
    cdc_counter #(
        .WIDTH       (CTR_WIDTH),
        .SYNC_STAGES (SYNC_STAGES)
    ) u_sync_count (
        .i_src_clk    (i_src_clk),
        .i_src_rst_n  (i_src_rst_n),
        .i_count_up   (i_src_pulse),
        .i_count_down (1'b0),
        .o_src_count  (),
        .i_dst_clk    (i_dst_clk),
        .i_dst_rst_n  (i_dst_rst_n),
        .o_dst_gray   (),
        .o_dst_count  (dst_count_sync)
    );

    // Generate one pulse per count difference: exactly 1 dst_clk wide,
    // mandatory 1-cycle gap between consecutive pulses (self-gating via dst_pulse_r).
    `ifdef CDC_ASYNC_RESET
    always_ff @(posedge i_dst_clk or negedge i_dst_rst_n) begin
    `else
    always_ff @(posedge i_dst_clk) begin
    `endif
        if (!i_dst_rst_n) begin
            dst_count_local <= '0;
            dst_pulse_r     <= 1'b0;
        end else begin
            dst_pulse_r <= 1'b0;
            if (!dst_pulse_r && (dst_count_local != dst_count_sync)) begin
                dst_pulse_r     <= 1'b1;
                dst_count_local <= dst_count_local + 1'b1;
            end
        end
    end

    assign o_dst_pulse = dst_pulse_r;

endmodule


// Top-level wrapper — instantiates one mode based on MODE parameter
module cdc_pulse #(
    parameter int SYNC_STAGES = 2,
    parameter int MODE        = 0,       // 0 = toggle, 1 = counter
    parameter int CTR_WIDTH   = 4        // Counter width for MODE=1
) (
    input  logic i_src_clk,
    input  logic i_src_rst_n,
    input  logic i_src_pulse,
    input  logic i_dst_clk,
    input  logic i_dst_rst_n,
    output logic o_dst_pulse
);

generate
    if (MODE == 0) begin : gen_toggle
        cdc_pulse_toggle #(
            .SYNC_STAGES (SYNC_STAGES)
        ) u_impl (
            .i_src_clk    (i_src_clk),
            .i_src_rst_n  (i_src_rst_n),
            .i_src_pulse  (i_src_pulse),
            .i_dst_clk    (i_dst_clk),
            .i_dst_rst_n  (i_dst_rst_n),
            .o_dst_pulse  (o_dst_pulse)
        );
    end else begin : gen_counter
        cdc_pulse_counter #(
            .SYNC_STAGES (SYNC_STAGES),
            .CTR_WIDTH   (CTR_WIDTH)
        ) u_impl (
            .i_src_clk    (i_src_clk),
            .i_src_rst_n  (i_src_rst_n),
            .i_src_pulse  (i_src_pulse),
            .i_dst_clk    (i_dst_clk),
            .i_dst_rst_n  (i_dst_rst_n),
            .o_dst_pulse  (o_dst_pulse)
        );
    end
endgenerate

endmodule

// cdc_qualifier.sv — Valid-Qualified Data Bus Synchronizer
// Synchronizes a level-held i_valid into the destination clock domain via
// cdc_bit, then uses the synchronized valid as a load-enable to capture
// i_data into a destination-domain register. Caller must hold both i_data
// and i_valid stable for at least SYNC_STAGES+1 i_clk cycles — long enough
// for the valid synchronizer to settle before data is sampled.
//
// o_data lags o_valid by one extra i_clk cycle: o_valid is itself a
// registered output of cdc_bit, so the load-enable it drives is only
// visible to this module's always_ff one cycle after o_valid appears to
// assert. Total latency from i_valid asserting to o_data updating is
// SYNC_STAGES+1 i_clk cycles.

`include "cdc_config.svh"

module cdc_qualifier #(
    parameter int unsigned WIDTH       = 8,
    parameter int unsigned SYNC_STAGES = 2
) (
    // Destination clock domain
    input  logic                i_clk,
    input  logic                i_rst_n,

    // Source domain — i_data must remain stable while i_valid is held high
    input  logic [WIDTH-1:0]    i_data,
    input  logic                i_valid,

    // Destination domain
    output logic [WIDTH-1:0]    o_data,
    output logic                o_valid
);

    // Level-held valid crosses the CDC boundary through the standard
    // single-bit synchronizer.
    cdc_bit #(
        .SYNC_STAGES (SYNC_STAGES),
        .RESET_VALUE (1'b0)
    ) u_sync_valid (
        .i_clk      (i_clk),
        .i_rst_n    (i_rst_n),
        .i_async_in (i_valid),
        .o_sync_out (o_valid)
    );

    `ifndef CDC_ASYNC_RESET
    initial begin
        o_data = '0;
    end
    `endif

    // Capture i_data directly while the synchronized valid is asserted.
    // Safe because i_data is required to be stable for the whole window
    // o_valid is high, not just at a single edge.
    `ifdef CDC_ASYNC_RESET
    always_ff @(posedge i_clk or negedge i_rst_n) begin
    `else
    always_ff @(posedge i_clk) begin
    `endif
        if (!i_rst_n) begin
            o_data <= '0;
        end else if (o_valid) begin
            o_data <= i_data;
        end
    end

endmodule

// cdc_reset.sv — Reset Synchronizer
// Async assert, synchronous deassert reset synchronizer.
// This is the one valid use of async reset in FPGA design.
// Active-low reset: i_async_rst_n=0 asserts instantly, deasserts after SYNC_STAGES clocks.

`include "cdc_config.svh"

module cdc_reset #(
    parameter int SYNC_STAGES = 2
) (
    input  logic i_clk,
    input  logic i_async_rst_n,    // Active-low async reset input
    output logic o_sync_rst_n      // Active-low synchronized reset output
);

    (* ASYNC_REG = "TRUE" *)
    logic [SYNC_STAGES-1:0] rst_chain;

    initial begin
        rst_chain = {SYNC_STAGES{1'b0}};  // Power-up in reset
    end

    // Async assert (immediate on rst_n=0), sync deassert (after SYNC_STAGES clocks)
    always_ff @(posedge i_clk or negedge i_async_rst_n) begin
        if (!i_async_rst_n)
            rst_chain <= {SYNC_STAGES{1'b0}};
        else
            rst_chain <= {rst_chain[SYNC_STAGES-2:0], 1'b1};
    end

    assign o_sync_rst_n = rst_chain[SYNC_STAGES-1];

endmodule

// =============================================================================
// Module  : cdc_pulse_sync
// Language: SystemVerilog
//
// Description:
//   Pulse synchronizer for crossing a single-cycle pulse from the source
//   clock domain to the destination clock domain.
//
// CDC Principle (Toggle-Based Pulse Synchronization):
//   A single-cycle pulse may be shorter than one destination clock period and
//   could be invisible to a simple synchronizer. This module uses a three-step
//   toggle-based approach:
//
//   Step 1 – Pulse-to-Toggle (source domain):
//     A flip-flop toggles on each input pulse, converting the short pulse to
//     a persistent level change that cannot be missed by the synchronizer.
//
//   Step 2 – 2-Stage Synchronization:
//     The toggle signal is synchronized to the destination domain using a
//     standard 2-stage flip-flop chain, eliminating metastability.
//
//   Step 3 – Toggle-to-Pulse (destination domain):
//     An XOR of the current and previous synchronized toggle detects each
//     toggle edge and regenerates a single-cycle pulse in the destination domain.
//
// Safety:
//   - Safe because only a persistent toggle (not the original pulse) crosses
//     the clock boundary.
//   - Pulses must be separated by at least the round-trip synchronization
//     latency: approximately 4 destination clock cycles (2 sync + 1 edge
//     detect + 1 margin) to prevent pulse merging.
//
// Use Cases:
//   - Crossing a single-cycle strobe or trigger between clock domains
//   - Interrupt signals between clock domains
//   - Event notification across clock domain boundaries
//
// Limitations:
//   - Minimum inter-pulse spacing: ~4 destination clock cycles; pulses closer
//     together may be lost.
//   - 2–3 destination clock cycles of latency.
//   - Does not detect pulse loss (no overflow flag).
//
// Timing Assumptions:
//   - One pulse in = one pulse out, assuming minimum spacing is met.
//   - Does not preserve data associated with the pulse (use cdc_data_sync for
//     data transfer).
//
// Example Instantiation:
//   cdc_pulse_sync u_pulse_sync (
//       .clk_src   (clk_src),
//       .rst_src_n (rst_src_n),
//       .pulse_src (strobe_src),
//       .clk_dst   (clk_dst),
//       .rst_dst_n (rst_dst_n),
//       .pulse_dst (strobe_dst)
//   );
// =============================================================================

module cdc_pulse_sync (
    // Source domain
    input  logic clk_src,    // Source domain clock
    input  logic rst_src_n,  // Source domain reset (active low)
    input  logic pulse_src,  // Single-cycle input pulse in source domain

    // Destination domain
    input  logic clk_dst,    // Destination domain clock
    input  logic rst_dst_n,  // Destination domain reset (active low)
    output logic pulse_dst   // Single-cycle output pulse in destination domain
);

    // --------------------------------------------------------------------------
    // Step 1: Convert pulse to toggle in the source domain.
    // The toggle persists between pulses so it cannot be missed.
    // --------------------------------------------------------------------------
    logic toggle_src;

    always_ff @(posedge clk_src or negedge rst_src_n) begin
        if (!rst_src_n)
            toggle_src <= 1'b0;
        else if (pulse_src)
            toggle_src <= ~toggle_src;
    end

    // --------------------------------------------------------------------------
    // Step 2: 2-stage synchronizer to move toggle into destination domain.
    // --------------------------------------------------------------------------
    (* ASYNC_REG = "TRUE" *) logic [1:0] sync_ff;

    // --------------------------------------------------------------------------
    // Step 3: Edge detection to regenerate a single-cycle pulse.
    // --------------------------------------------------------------------------
    logic toggle_dst_prev;

    always_ff @(posedge clk_dst or negedge rst_dst_n) begin
        if (!rst_dst_n) begin
            sync_ff          <= 2'b00;
            toggle_dst_prev  <= 1'b0;
        end else begin
            sync_ff          <= {sync_ff[0], toggle_src};
            toggle_dst_prev  <= sync_ff[1];
        end
    end

    // Pulse output: high for exactly one destination clock cycle per event.
    assign pulse_dst = sync_ff[1] ^ toggle_dst_prev;

endmodule

// =============================================================================
// Module  : cdc_reset_sync
// Language: SystemVerilog
//
// Description:
//   Reset synchronizer with asynchronous assertion and synchronous deassertion.
//   Generates a clean, glitch-free reset in a target clock domain from an
//   asynchronous reset source.
//
// CDC Principle (Async Assert / Sync Deassert):
//   This is a well-established technique for distributing resets across clock
//   domains safely:
//
//   Assertion (immediate):
//     When rst_async_n goes low, the output rst_sync_n is immediately driven
//     low (asynchronous), ensuring that all downstream flip-flops enter reset
//     without waiting for a clock edge. This prevents "reset race" conditions.
//
//   Deassertion (synchronized):
//     When rst_async_n goes high, the release is NOT immediate. Instead, it
//     must propagate through a chain of SYNC_STAGES flip-flops clocked by
//     clk. All flip-flops in the chain are preset to '1' asynchronously and
//     only release rst_sync_n after SYNC_STAGES clean clock edges, ensuring
//     the local reset deasserts synchronously with clk. This prevents
//     metastability on the reset release edge.
//
// Safety:
//   - Async assert ensures no combinatorial reset propagation delay.
//   - Sync deassert eliminates metastability when reset is released.
//   - All flip-flops driven by rst_sync_n will exit reset at the same clock edge.
//
// Use Cases:
//   - Generating domain-local resets from a global asynchronous reset source
//   - Power-on reset distribution to multiple clock domains
//   - Generating reset for logic after a PLL lock signal
//
// Limitations:
//   - Clock must be running during reset deassertion for synchronous release.
//   - SYNC_STAGES >= 2 is required (default 2).
//   - The metastability window is very small for the assertion path (since the
//     reset release goes through synchronizer FFs), but assertion itself is
//     asynchronous and purely combinatorial.
//
// Timing Assumptions:
//   - rst_async_n is assumed to meet hold/recovery time on the clock edge it
//     is released on. If not, the SYNC_STAGES chain provides sufficient
//     resolution time.
//
// Example Instantiation:
//   cdc_reset_sync #(.SYNC_STAGES(2)) u_rst_sync (
//       .clk         (clk),
//       .rst_async_n (por_rst_n),
//       .rst_sync_n  (local_rst_n)
//   );
// =============================================================================

module cdc_reset_sync #(
    parameter int SYNC_STAGES = 2  // Number of synchronizer stages (>= 2)
) (
    input  logic clk,          // Target clock domain clock
    input  logic rst_async_n,  // Asynchronous reset input (active low)
    output logic rst_sync_n    // Synchronized reset output (active low)
);

    // Synchronizer chain: all FFs are asynchronously cleared and preset to 1.
    // When rst_async_n goes low:  entire chain goes to 0 (async clear).
    // When rst_async_n goes high: chain shifts in 1s from the LSB.
    (* ASYNC_REG = "TRUE" *) logic [SYNC_STAGES-1:0] sync_chain;

    always_ff @(posedge clk or negedge rst_async_n) begin
        if (!rst_async_n)
            // Asynchronous assertion: immediately drive all stages to 0
            sync_chain <= '0;
        else
            // Synchronous deassertion: shift a 1 from LSB toward MSB
            sync_chain <= {sync_chain[SYNC_STAGES-2:0], 1'b1};
    end

    // Reset output is active until the chain is fully loaded with 1s
    assign rst_sync_n = sync_chain[SYNC_STAGES-1];

endmodule

// =============================================================================
// Module  : cdc_sync2
// Language: SystemVerilog
//
// Description:
//   2-stage flip-flop synchronizer for single-bit clock domain crossing (CDC).
//
// CDC Principle:
//   When a signal crosses clock domains, the capturing flip-flop may enter a
//   metastable state. By chaining two flip-flops in the destination domain,
//   the probability that metastability propagates to downstream logic is reduced
//   exponentially (by roughly e^(Tresolution/tau) per stage). For most designs
//   below a few hundred MHz, 2 stages provide sufficient MTBF.
//
// Safety:
//   - Safe ONLY for single-bit signals.
//   - The input must be quasi-static (stable for at least one destination clock
//     cycle) or use cdc_pulse_sync / cdc_toggle_sync for pulsed signals.
//   - Multi-bit signals require special handling (Gray code or handshake).
//   - Apply ASYNC_REG / keep_hierarchy constraints in the synthesis tool to
//     prevent the optimizer from merging or moving synchronizer FFs.
//
// Use Cases:
//   - Control/status bits crossing clock domains
//   - Enable, valid, or flag signals
//   - Building block for cdc_pulse_sync, cdc_toggle_sync, cdc_reset_sync
//
// Limitations:
//   - 2-cycle latency in the destination domain
//   - Not suitable for fast-changing signals or multi-bit buses
//
// Timing Assumptions:
//   - The signal must remain stable for at least 2 destination clock cycles
//     between transitions (quasi-static) unless a toggle/pulse synchronizer
//     is used upstream.
//
// Example Instantiation:
//   cdc_sync2 #(.RESET_VAL(1'b0)) u_sync (
//       .clk_dst   (clk_dst),
//       .rst_dst_n (rst_dst_n),
//       .data_src  (flag_src),
//       .data_dst  (flag_dst)
//   );
// =============================================================================

module cdc_sync2 #(
    parameter bit RESET_VAL = 1'b0  // Reset value for synchronizer flip-flops
) (
    input  logic clk_dst,    // Destination domain clock
    input  logic rst_dst_n,  // Destination domain asynchronous reset (active low)
    input  logic data_src,   // Single-bit input from source clock domain
    output logic data_dst    // Single-bit output synchronized to destination domain
);

    // Two-stage synchronizer chain.
    // ASYNC_REG attribute prevents optimization across flip-flop stages and
    // guides place-and-route tools to co-locate the FFs for minimal routing
    // delay, reducing the probability of metastability propagation.
    (* ASYNC_REG = "TRUE" *) logic [1:0] sync_ff;

    always_ff @(posedge clk_dst or negedge rst_dst_n) begin
        if (!rst_dst_n)
            sync_ff <= {2{RESET_VAL}};
        else
            sync_ff <= {sync_ff[0], data_src};
    end

    assign data_dst = sync_ff[1];

endmodule

// =============================================================================
// Module  : cdc_sync3
// Language: SystemVerilog
//
// Description:
//   3-stage flip-flop synchronizer for single-bit CDC. Provides higher MTBF
//   than the 2-stage synchronizer.
//
// CDC Principle:
//   Same principle as cdc_sync2 but with a third synchronizer flip-flop.
//   Each additional stage reduces the metastability probability by roughly
//   e^(Tresolution/tau) relative to the previous stage. Use 3 stages when:
//     - Operating at high clock frequencies (>500 MHz), where the destination
//       clock period may not allow sufficient metastability resolution time
//       between the first and second FF.
//     - The application demands very high MTBF (e.g., safety-critical systems).
//
// Safety:
//   - Safe ONLY for single-bit signals.
//   - Same input stability requirements as cdc_sync2.
//   - Apply ASYNC_REG / keep_hierarchy constraints in synthesis tools.
//
// Use Cases:
//   - High-frequency designs (>500 MHz)
//   - Safety-critical applications requiring very high MTBF
//   - When 2-stage does not provide enough resolution time at the target frequency
//
// Limitations:
//   - 3-cycle latency in the destination domain (one more cycle than cdc_sync2)
//   - Not suitable for fast-changing or multi-bit signals
//
// Timing Assumptions:
//   - Destination clock period must be long enough for the first FF to resolve
//     metastability before its output is sampled by the second FF.
//
// Example Instantiation:
//   cdc_sync3 #(.RESET_VAL(1'b0)) u_sync3 (
//       .clk_dst   (clk_dst),
//       .rst_dst_n (rst_dst_n),
//       .data_src  (flag_src),
//       .data_dst  (flag_dst)
//   );
// =============================================================================

module cdc_sync3 #(
    parameter bit RESET_VAL = 1'b0  // Reset value for synchronizer flip-flops
) (
    input  logic clk_dst,    // Destination domain clock
    input  logic rst_dst_n,  // Destination domain asynchronous reset (active low)
    input  logic data_src,   // Single-bit input from source clock domain
    output logic data_dst    // Single-bit output synchronized to destination domain
);

    // Three-stage synchronizer chain.
    // ASYNC_REG attribute prevents optimization across stages and guides
    // place-and-route to co-locate the FFs for minimum routing delay.
    (* ASYNC_REG = "TRUE" *) logic [2:0] sync_ff;

    always_ff @(posedge clk_dst or negedge rst_dst_n) begin
        if (!rst_dst_n)
            sync_ff <= {3{RESET_VAL}};
        else
            sync_ff <= {sync_ff[1:0], data_src};
    end

    assign data_dst = sync_ff[2];

endmodule

// =============================================================================
// Module  : cdc_toggle_sync
// Language: SystemVerilog
//
// Description:
//   Toggle-event synchronizer. Synchronizes a toggle signal from the source
//   clock domain to the destination domain and generates a single-cycle pulse
//   on each toggle edge.
//
// CDC Principle:
//   Instead of sending a short pulse (which might be missed if shorter than
//   one destination clock period), the source toggles a persistent signal each
//   time an event occurs. The toggle is synchronized with a 2-stage FF chain.
//   An XOR of the synchronized toggle with its previous value detects each
//   edge and generates a single-cycle output pulse in the destination domain.
//
// Safety:
//   - Safe for CDC because the toggle is persistent (does not need to be
//     captured within a specific clock window).
//   - The 2FF chain handles metastability on the toggle crossing.
//   - Events must be separated by at least 3 destination clock cycles for
//     reliable detection (2 sync cycles + 1 cycle for edge detection).
//
// Use Cases:
//   - Signaling infrequent events across clock domains
//   - When the source already provides a toggle signal
//   - Building block for cdc_pulse_sync (which adds the src toggle generation)
//
// Limitations:
//   - Consecutive events must be separated by >= 3 destination clock cycles.
//   - Back-to-back high-frequency events may be missed if spacing is too short.
//
// Timing Assumptions:
//   - toggle_src must be stable for at least one destination clock cycle before
//     each new transition.
//
// Example Instantiation:
//   cdc_toggle_sync u_tog_sync (
//       .clk_dst    (clk_dst),
//       .rst_dst_n  (rst_dst_n),
//       .toggle_src (my_toggle),
//       .toggle_dst (toggle_synced),
//       .pulse_dst  (event_pulse)
//   );
// =============================================================================

module cdc_toggle_sync (
    // Destination domain
    input  logic clk_dst,     // Destination domain clock
    input  logic rst_dst_n,   // Destination domain reset (active low)
    // Cross-domain input
    input  logic toggle_src,  // Toggle signal from source clock domain
    // Destination domain outputs
    output logic toggle_dst,  // Synchronized toggle in destination domain
    output logic pulse_dst    // One-cycle pulse on each toggle transition
);

    // Two-stage synchronizer for the toggle signal.
    (* ASYNC_REG = "TRUE" *) logic [1:0] sync_ff;

    // Previous value of synchronized toggle (for edge detection).
    logic toggle_dst_prev;

    always_ff @(posedge clk_dst or negedge rst_dst_n) begin
        if (!rst_dst_n) begin
            sync_ff          <= 2'b00;
            toggle_dst_prev  <= 1'b0;
        end else begin
            sync_ff          <= {sync_ff[0], toggle_src};
            toggle_dst_prev  <= sync_ff[1];
        end
    end

    // Synchronized toggle output
    assign toggle_dst = sync_ff[1];

    // Single-cycle pulse on any toggle edge (rising or falling)
    assign pulse_dst = sync_ff[1] ^ toggle_dst_prev;

endmodule

// =============================================================================
// Example: cdc_handshake instantiation
// =============================================================================
// This example shows a 4-phase handshake between a 50 MHz "processor" domain
// that initiates DMA transfers and a 200 MHz "DMA engine" domain that executes
// them.
//
// The processor asserts dma_req and waits for dma_ack. The DMA engine sees the
// synchronized request, starts the DMA, and asserts its ack when done.
// =============================================================================

module example_handshake (
    // Processor domain (50 MHz)
    input  logic clk_cpu,
    input  logic rst_cpu_n,
    input  logic start_dma,     // CPU requests a DMA transfer
    output logic dma_done,      // High when DMA engine has acknowledged

    // DMA engine domain (200 MHz)
    input  logic clk_dma,
    input  logic rst_dma_n,
    output logic dma_req_dma,   // Synchronized DMA request in engine domain
    input  logic dma_ack_dma    // DMA engine asserts when transfer complete
);

    // Handshake signals
    logic cpu_req;   // Level-high while DMA is pending (CPU side)
    logic cpu_ack;   // Level-high when DMA engine has acknowledged

    // Simple state: set req when start_dma arrives, clear when ack is received.
    always_ff @(posedge clk_cpu or negedge rst_cpu_n) begin
        if (!rst_cpu_n)
            cpu_req <= 1'b0;
        else if (start_dma && !cpu_req)
            cpu_req <= 1'b1;          // Start new transfer
        else if (cpu_ack)
            cpu_req <= 1'b0;          // Transfer acknowledged; release request
    end

    assign dma_done = cpu_ack;

    // 4-phase handshake synchronizer
    cdc_handshake u_dma_hs (
        .clk_src   (clk_cpu),
        .rst_src_n (rst_cpu_n),
        .src_req_i (cpu_req),
        .src_ack_o (cpu_ack),
        .clk_dst   (clk_dma),
        .rst_dst_n (rst_dma_n),
        .dst_req_o (dma_req_dma),
        .dst_ack_i (dma_ack_dma)
    );

endmodule

// =============================================================================
// Example: cdc_pulse_sync instantiation
// =============================================================================
// This example crosses a single-cycle interrupt strobe from a 125 MHz CPU
// clock domain to a 50 MHz peripheral clock domain.
//
// The pulse synchronizer uses toggle-based encoding so the pulse cannot be
// missed, even if the source clock is faster than the destination clock.
//
// Limitation: consecutive pulses must be separated by at least ~4 destination
// clock cycles (80 ns at 50 MHz). For bursts, use a FIFO instead.
// =============================================================================

module example_pulse_sync (
    input  logic clk_cpu,      // 125 MHz CPU clock
    input  logic rst_cpu_n,
    input  logic irq_pulse,    // 1-cycle interrupt pulse in CPU domain

    input  logic clk_periph,   // 50 MHz peripheral clock
    input  logic rst_periph_n,
    output logic irq_periph    // 1-cycle interrupt pulse in peripheral domain
);

    cdc_pulse_sync u_irq_sync (
        .clk_src   (clk_cpu),
        .rst_src_n (rst_cpu_n),
        .pulse_src (irq_pulse),
        .clk_dst   (clk_periph),
        .rst_dst_n (rst_periph_n),
        .pulse_dst (irq_periph)
    );

endmodule

// =============================================================================
// Example: cdc_reset_sync instantiation
// =============================================================================
// This example distributes a single power-on reset (POR) to three independent
// clock domains. Each domain gets its own reset synchronizer so that each
// domain's flip-flops exit reset synchronously with their own clock.
//
// Without reset synchronizers, each domain's FFs may come out of reset at
// unpredictable times, leading to glitches or X-propagation during simulation.
// =============================================================================

module example_reset_sync (
    input  logic por_rst_n,     // Asynchronous power-on reset (active low)

    input  logic clk_100m,      // 100 MHz clock domain
    output logic rst_100m_n,    // Synchronized reset for 100 MHz domain

    input  logic clk_200m,      // 200 MHz clock domain
    output logic rst_200m_n,    // Synchronized reset for 200 MHz domain

    input  logic clk_50m,       // 50 MHz clock domain
    output logic rst_50m_n      // Synchronized reset for 50 MHz domain
);

    // 100 MHz domain reset synchronizer (2 stages)
    cdc_reset_sync #(.SYNC_STAGES(2)) u_rst_100m (
        .clk         (clk_100m),
        .rst_async_n (por_rst_n),
        .rst_sync_n  (rst_100m_n)
    );

    // 200 MHz domain reset synchronizer (3 stages for extra metastability margin)
    cdc_reset_sync #(.SYNC_STAGES(3)) u_rst_200m (
        .clk         (clk_200m),
        .rst_async_n (por_rst_n),
        .rst_sync_n  (rst_200m_n)
    );

    // 50 MHz domain reset synchronizer (2 stages)
    cdc_reset_sync #(.SYNC_STAGES(2)) u_rst_50m (
        .clk         (clk_50m),
        .rst_async_n (por_rst_n),
        .rst_sync_n  (rst_50m_n)
    );

endmodule

// =============================================================================
// Example: cdc_sync2 instantiation
// =============================================================================
// This example shows how to use the 2-stage flip-flop synchronizer to cross
// a single-bit control flag from a 100 MHz source domain to a 200 MHz
// destination domain.
//
// Key rule: flag_src must be quasi-static (stable for >> 1 dst clock cycle).
//           For pulsed signals, use cdc_pulse_sync instead.
// =============================================================================

module example_sync2 (
    input  logic clk_100m,    // 100 MHz source clock
    input  logic rst_100m_n,  // Source domain reset
    input  logic flag_src,    // Flag generated in 100 MHz domain

    input  logic clk_200m,    // 200 MHz destination clock
    input  logic rst_200m_n,  // Destination domain reset
    output logic flag_dst     // Flag synchronized to 200 MHz domain
);

    // Instantiate the 2-stage synchronizer.
    // RESET_VAL = 0 means the synchronized flag initializes to 0 after reset.
    cdc_sync2 #(
        .RESET_VAL (1'b0)
    ) u_flag_sync (
        .clk_dst   (clk_200m),
        .rst_dst_n (rst_200m_n),
        .data_src  (flag_src),
        .data_dst  (flag_dst)
    );

endmodule

// =============================================================================
// Example: cdc_sync3 instantiation
// =============================================================================
// This example shows the 3-stage synchronizer for a high-frequency (500 MHz)
// design where additional metastability resolution time is needed.
//
// The extra FF stage provides ~e^(Tclk/tau) more metastability rejection
// compared to cdc_sync2, at the cost of one additional cycle of latency.
// =============================================================================

module example_sync3 (
    input  logic clk_src,    // Source clock (e.g., 250 MHz)
    input  logic rst_src_n,
    input  logic status_src, // Slow-moving status bit in source domain

    input  logic clk_500m,   // 500 MHz destination clock
    input  logic rst_500m_n,
    output logic status_dst  // Status synchronized to 500 MHz domain
);

    // Use 3-stage synchronizer for high-frequency destination clock.
    cdc_sync3 #(
        .RESET_VAL (1'b0)
    ) u_status_sync (
        .clk_dst   (clk_500m),
        .rst_dst_n (rst_500m_n),
        .data_src  (status_src),
        .data_dst  (status_dst)
    );

endmodule

// =============================================================================
// Example: cdc_toggle_sync instantiation
// =============================================================================
// This example uses the toggle synchronizer to signal a "packet received"
// event from a 25 MHz MAC clock domain to a 100 MHz CPU clock domain.
//
// The MAC toggles rx_event_toggle once per received packet. The toggle
// synchronizer detects each edge and generates a single-cycle pulse in the
// CPU domain to trigger processing.
// =============================================================================

module example_toggle_sync (
    input  logic clk_mac,        // 25 MHz MAC clock
    input  logic rst_mac_n,
    input  logic rx_event_toggle, // Toggled in MAC domain on each packet received

    input  logic clk_cpu,         // 100 MHz CPU clock
    input  logic rst_cpu_n,
    output logic rx_toggle_sync,  // Synchronized toggle output
    output logic rx_pulse_cpu     // 1-cycle pulse in CPU domain per packet
);

    cdc_toggle_sync u_rx_sync (
        .clk_dst    (clk_cpu),
        .rst_dst_n  (rst_cpu_n),
        .toggle_src (rx_event_toggle),
        .toggle_dst (rx_toggle_sync),
        .pulse_dst  (rx_pulse_cpu)
    );

endmodule

